window.CCAF_KO = {"348831":["새 세션 2개를 시작하기. 월요일 분석은 이미 낡았고, 낡은 컨텍스트를 포크하면 문제가 두 배가 되기 때문임."],"671445":["500달러가 넘는 process_refund 호출을 막고 에스컬레이션 워크플로로 넘기는 가로채기 훅(interception hook)."],"754589":["둘 다 동적 분해(dynamic decomposition)임. 어느 팀도 실행을 시작하기 전에는 개별 항목에 뭐가 들어갈지 모르기 때문임."],"1360236":["이미 가져온 데이터를 다시 요청하지 말고, 대화에서 실제로 본 내용만 근거로 추론하라는 지시를 프롬프트에 넣기."],"2593570":["도구 결과(tool result)를 읽을 때 \"관련 있는 필드에만 집중해\"라고 에이전트한테 지시하기"],"3027386":["창고 API가 응답할 때까지 도구가 내부에서 무한정 재시도하게 만들어서, 에이전트는 타임아웃을 아예 못 보게 하기"],"3239522":["확실할 때만 policy number를 말하라는 system-prompt 문구를 추가하기"],"8318631":["요약을 더 자주 해서 요약 한 번이 다루는 분량을 줄이고, 한 번 지날 때마다 잃는 정보도 줄이기"],"11146730":["Glob으로 파일 위치를 다시 찾은 뒤, 같은 기준점으로 Edit을 재시도하기."],"12645228":["놓쳤을 때 비용이 큰 카테고리에서만 블로킹하고, 나머지는 조언성 코멘트로 올라가게 해서, 블로킹할 만한 가치가 있는 곳에만 블로킹 여력을 쓰게 하기."],"13385522":["일시적 타임아웃은 상위로 보고하기 전에 로컬에서 두 번 재시도하기."],"13906558":["정산일(settlement date)이 없는 것은 실패가 아니라 그냥 정보가 없는 것으로 처리하기. 날짜 없이 확인서를 먼저 보내고, provider가 나중에 날짜를 주면 그때 follow-up하기"],"13996775":["src/web/api/client.ts"],"15217600":["결측값(missing-value) 케이스 세 가지는 따로 유지하되 각각에 회귀 테스트(regression test)를 추가해서, 문제가 다시 생기는 순간 바로 찾아낼 수 있게 하기"],"15814890":["유지되는 파일 읽기 내용을 실제로 참조된 범위로 줄이기. 그러면 전체 파일이 context에 절대 쌓이지 않음."],"15903953":["도구는 하나로 유지하고, 답할 수 있는 것을 전부 나열한 네 문장 이상으로 설명을 늘리기"],"17505531":["리서치 coordinator에게 \"우리 데이터 보존(data-retention) 관행이 새 규제를 충족하는지 평가해줘\"라는 요청이 들어옴. 어떤 시스템이 개인정보를 저장하는지는 아직 아무도 모름.","coordinator는 첫날 12개 항목짜리 서브태스크(subtask) 목록을 작성하고 \"감사 추적(audit trail)을 깨끗하게 유지하려고\" 여기에 어떤 변경도 금지함. 3일째가 되자, subagent들이 목록에 없는 문서화되지 않은 데이터 저장소 두 곳을 발견했음.","무엇이 잘못됐고, 해결책은 무엇인가?"],"17804775":["통합 방식 두 가지가 모두 타당한, 파일 45개짜리 라이브러리 마이그레이션."],"18312728":["모델이 전보다 확인 질문을 더 많이 함."],"19130975":["이름이 지정된 세션(named session) 하나에 300개 파일로 이뤄진 서비스의 전체 의존성 분석(dependency analysis)이 담겨 있음.","밤사이 자동 포매터(formatter)가 저장소(repository)의 모든 파일을 다시 썼는데, 공백과 import 순서만 바꿨을 뿐 로직은 전혀 건드리지 않았음.","오늘 아침 최소한의 토큰(token) 사용으로 이 분석을 이어가야 함.","이 세션이 낡은 것인지 아닌지를 두고 팀원 둘의 의견이 갈렸음.","올바른 판단은 무엇인가?"],"19449047":["(a) 이전 결론을 구조화해 요약한 것을 들고 새 세션을 시작하기. (b) --resume으로 이어가면서 어떤 이름이 어떻게 바뀌었는지 알려줘서 그 부분만 다시 분석하게 하기. (c) 공통 기준점에서 fork_session으로 두 갈래를 만들기."],"21235625":["서버가 성공할 때까지 내부적으로 재시도하게 해서, 에이전트는 실패를 아예 보지 못하게 하기"],"23104645":["Grep으로 몇 번 나오는지 세고, 나온 횟수만큼 Edit을 한 번씩 실행하기"],"23177096":["찾아낸 후보 세 개의 이름을 대고, 각각에 무엇이 의존하는지 말한 다음, 무언가 건드리기 전에 \"old auth code\"가 그중 어느 것을 뜻하는지 물어보기."],"24119951":["두 소스가 서로 다르면, 에이전트가 더 최근에 업데이트된 정책 문서를 우선하게 하기"],"24689647":["이름 패턴으로 파일 찾기 → Grep. 파일 시스템을 훑어 주기 때문임."],"27684182":["partner한테는 보고서에서 가장 먼저 나오는 발견 사항 8개를 주기. 그것이 클라이언트가 나머지를 읽는 방식을 결정하기 때문임."],"28656461":["형식 지시를 프롬프트 맨 앞과 맨 뒤에 둘 다 반복해서 넣기."],"29031668":["bot의 출력을 post-process(후처리)해서, 파일 경로에 \"test\"가 들어가는 발견 사항은 다 걸러내기."],"29625976":["봇을 2주 동안 꺼둬서 개발자들이 쌓인 반감 없이 다시 쓰게 하기"],"29658599":["(i) 그 확장자(suffix)를 어떤 깊이에서든 매칭하는 패턴을 가진 규칙 파일임. (ii) 규칙 파일이나 폴더 단위 memory 파일임. 경계가 폴더이기 때문임. (iii) 둘 다 아님. 아직 매칭을 트리거할 것이 존재하지 않기 때문임. 이건 항상 존재하거나 명시적으로 호출되는 곳에 들어가야 함. (iv) 커밋된 deny 규칙임. 컨벤션 문서는 쓰기를 거부할 수 없기 때문임."],"32909502":["1차 출력을 다시 정규화하는 2차 모델 패스를 돌리기"],"32995099":["모델이 모든 지적에 근거 설명과 신뢰도를 같이 달게 해서 리뷰어가 몇 초 만에 분류할 수 있게 하기. 신뢰도가 낮은 것은 훑고 높은 것은 파고드는 식임. 이러면 아무것도 감추지 않는다는 원칙을 지키면서 진짜 병목을 건드릴 수 있음."],"33232655":["secrets 디렉터리를 project memory 파일에 접근 금지로 기록해두면, subprocess를 포함해서 모델이 거기 갈 수 있는 모든 경로가 다 막힘."],"33814308":["구조화된 에러보다 토큰을 더 많이 소모함."],"37509828":["출력이 유효한 쪽으로 수렴하게, 루프가 재시도할 때마다 temperature를 낮춰야 함."],"38167277":["네 출처 검증용 subagent(하위 에이전트)는 \"신뢰도 낮은 출처(low-credibility sources)\"를 배제 대상으로 표시함.","지난 한 달 동안 분석가들이 이 배제 판정의 63%를 뒤집었음(대부분 프리프린트(preprint)와 정부 워킹페이퍼였음). 반면 클라이언트 산출물(client deliverable)에 결국 인용된 벤더 후원 블로그 글 두 개는 그대로 남겨뒀음.","지시문에는 이렇게 적혀 있음: \"보수적으로 판단하고 품질 좋고 신뢰할 수 있는 출처만 포함하세요.\" 올바른 수정 방법은 무엇인가?"],"39985207":["여러 도구가 다 맞아 보일 때 \"신중히 고르라\"고 모델에게 일러 주는 문구."],"41142291":["두 가지 문제 모두 하나의 지식 공백에서 비롯됨.","생성기(generator)가 프로덕션 핸들러에 console.log 호출을 써넣음.","리뷰 봇은 눈에 보이는 console.log를 전부 플래그로 거는데, 팀이 디버깅하면서 일부러 쓰는 테스트 파일 속 console.log도 예외가 아님.","지난달 리뷰어들이 그런 발견 사항을 60건이나 기각했음.","정확히 겨냥한 해결책은 무엇인가?"],"42436028":["편집이 전혀 일어나지 않는 상태로 조사해서 접근 방식을 확정하고, 그 작성된 접근 방식을 결제 그룹이 서명할 산출물로 넘긴 다음, 그제서야 일반 작업 세션에서 합의된 설계를 실행하기"],"43038437":["프롬프트(prompt)는 그대로 두고, 로더(loader)가 파싱(parsing)하기 전에 가장 바깥쪽 중괄호(braces) 사이의 텍스트만 남기게 하기."],"43454823":[".claude/skills/에 있는 팀 skill을 직접 수정하기. 네 취향은 남들도 반길 만한 개선이기 때문임."],"43522158":["서브에이전트(subagent)의 야간 실행이 로컬 재시도 2번 후 03:12에 도구 타임아웃(tool timeout)으로 실패했음.","온콜(on-call) 엔지니어는 전체 실행 로그와 실패한 도구 호출(tool call)을 갖고 있고, 그 도구의 인자 처리(argument handling)에 있는 알려진 버그에 대한 한 줄짜리 수정도 이미 준비해뒀음.","가장 적절하지 않은 행동은 무엇인가?"],"43527852":["이것을 skill로 패키징하기. 호출되기 전까지는 비용이 전혀 들지 않기 때문임. 그리고 체크아웃과 정산 엔지니어들에게는 그 트리를 건드리는 세션을 시작할 때마다 이것을 호출하도록 알리기"],"43820040":["릴리스 노트(release-notes) 절차를 필요할 때 호출되는 skill로 패키징하고, frontmatter를 포크된 컨텍스트(forked context)에서 돌아가게 설정해서 로그 분석이 작업 대화(working conversation)에는 절대 남지 않게 하기"],"44494897":["allowed-tools. 도구를 제한하면 출력 길이가 줄어들기 때문임."],"44890351":["요약 프롬프트를 \"요약할 때 수치는 절대 잃지 말 것\"으로 다시 쓰기"],"45825652":["확실하지 않을 때 에이전트가 합의된 금액을 고객한테 다시 물어보게 하기"],"45986543":["coordinator가 \"새 국경 간 데이터 규정에 대한 우리의 노출도를 평가하라\"는 작업을 시작한 지 6시간째임. 지금까지 킥오프 때 아무도 언급하지 않은 사업부 세 곳을 찾아냈는데, 그중 두 곳은 애초에 범위에 없던 벤더를 쓰고 있음.","다음 실행을 위해 변경 사항 네 가지가 제안됐음.","이런 유형의 작업에 가장 도움이 안 되는 것은 무엇인가?"],"46080619":["판정을 내리는 세션에게, rating을 산출하기 전에 자신의 추론을 더 비판적으로 다시 검토하라고 지시하기."],"46178189":["루프에 커버리지 충분성 기준과 중단 기준을 주기. 표적 재검색을 해도 새 출처가 더 안 나오면 그 종합 결과를 받아들이고, 빈약한 부분을 표시한 커버리지 주석을 달아서 내보내기."],"50295958":["환불 상태 질문이 환불 도구가 아니라 주문 조회로 라우팅되는 예시를 두세 개 추가하기"],"51804192":["대화 턴마다 Task를 하나씩만 호출하고, 결과가 나온 다음에 그다음 것을 실행하기"],"54452204":["에스컬레이션하기. 그 특정 요청에 대해 정책이 침묵하거나 모호하면 그것은 에스컬레이션 신호임. 에이전트가 어느 방향으로든 정책을 즉흥적으로 지어내면 안 됨."],"55369812":["hooks, plugins, project context 탐색을 건너뛰는 플래그를 추가해서 모든 러너가 동일한 상태에서 시작하게 하고 push에 대한 deny 규칙을 추가하고 산문(prose) 출력은 유지하되 리뷰 프롬프트 문구는 고정해서 대시보드 패턴이 더 이상 흔들리지 않게 하기."],"58024318":["파일 16개짜리 PR 리뷰에서 서로 모순되는 발견 항목이 나옴. 어떤 패턴을 payments.ts에선 문제로 잡고, orders.ts에선 똑같은 형태인데 통과시킴. 게다가 절반의 파일은 얕게만 훑고 지나감.","팀이 내놓은 안은 이러함. (A) 컨텍스트가 더 큰 모델, (B) PR 전체를 중복으로 세 번 돌린 뒤 다수결, (C) 파일별 패스에 파일 간 통합 패스를 더하기, (D) 리뷰어한테 \"일관되게 해\"라고 지시하기. 근본 원인을 고치는 제안은 무엇인가?"],"58060697":["lookup_order 호출 한 번마다 필드가 40개 넘게 돌아옴. 창고 코드, 내부 SKU, 배송사 메타데이터 같은 것들인데, 반품 처리 에이전트한테 필요한 건 5개뿐임.","몇 번 조회하고 나면 컨텍스트가 상관없는 필드로 가득 차고, 에이전트는 앞선 대화 턴의 세부 사항을 놓치기 시작함.","수정은 어디에 들어가야 하는가?"],"59154279":["데이터베이스 조회 도구를 추가해서 잊어버린 수치를 다시 가져올 수 있게 하기"],"59506159":["tool_choice: \"auto\" 는 그대로 두고, 각 도구 설명에 \"항상 메타데이터를 먼저 추출할 것\" 을 덧붙이기."],"59810465":["정책이 실제로 보장하는 5일치 바우처는 발급하고, 나머지 초과 일수와 의류 환급 건은 정책이 상한을 두는 부분과 아예 다루지 않는 부분을 구분해서 명시한 구조화된 요약과 함께 사람에게 escalate하기."],"61541752":["assistant 턴을 예상 출력의 시작 부분으로 프리필(prefill)하기. 이 모델 세대는 이 기능을 지원하고, preamble이 들어갈 자리를 아예 남기지 않음."],"62342004":["매 단계마다 Claude한테 \"remember the constraints from earlier\"(앞에서 나온 제약을 기억하라)고 부탁하기."],"64168745":["정의를 그대로 .mcp.json으로 옮기고, 어차피 비공개 저장소니까 하드코딩된 토큰도 그냥 두기"],"64180033":["모델이 작동 방식을 이해하도록 도구의 내부 구현 전체를 넣기."],"64341975":["같은 세션 리뷰 프롬프트에 \"앞서 한 작업을 새로운 눈과 최대한의 의심으로 검토할 것\"을 추가하기"],"65154988":["Claude에게 대안 구현 3개를 만들게 한 다음, 가장 튼튼해 보이는 것을 고르기"],"66154924":["enum을 자유 텍스트로 바꿔서 어떤 조항 유형이든 표현할 수 있게 하기."],"69262663":["네 코디네이터는 market-data subagent에게서 {\"status\": \"no_data\"}를 받는데, 완전히 다른 두 상황에서 똑같은 값을 받음. 데이터 API가 죽었을 때랑, 정상적인 질의인데 진짜로 맞는 레코드가 하나도 없을 때임.","최근에는 장애 중인데도 코디네이터가 재시도를 건너뛰어서, 한 섹션이 통째로 빠진 보고서가 나갔음.","어떻게 고쳐야 하는가?"],"71330757":["출력을 후처리해서 짧은 테스트를 지우기. 보통 가치가 낮기 때문임."],"73478489":["어제 하던 분석 세션을 재개하기 전, 밤사이 팀이 모듈 두 개를 리팩터링했다고 언급함.","팀원은 대수롭지 않게 넘김. \"굳이 세션에 말할 필요 없음. Claude는 필요할 때 파일을 다시 읽으니 알아서 변경을 알아챌 것임.\" 이 논리의 허점은 무엇인가?"],"73641342":["각 결과를 환불 관련 필드만 남기게 다듬고 날짜 형식을 정규화하는 PostToolUse hook임. 모델이 그 결과를 처리하기도 전에 이 작업이 이루어짐."],"73894720":["모든 컨벤션을 더 안정적으로 로드되는 사용자 레벨 CLAUDE.md로 옮기기"],"75019348":["그 제안을 물리치고, 대신 종합 에이전트가 애초에 검증을 필요로 하는 일이 없도록 금지하기"],"75413795":["지시를 산문으로 아무리 자세히 써도 Claude 출력 형식이 실행할 때마다 달라짐.","가장 효과적인 해결책은 무엇인가?"],"75573676":["두 도구를 order_info 하나로 합치기. 같은 도메인을 건드리는 도구가 둘이면 모델은 언제나 헷갈리기 때문임."],"75702026":["탐색은 건건이 Explore subagent에 위임하기. 장황한 탐색 출력을 따로 격리하고 간결한 요약만 메인 대화로 돌려줌."],"75845010":["두 작업 모두에 adaptive subtask generation(적응형 하위 작업 생성)을 쓰기. 계획을 수정할 수 있는 coordinator는 그럴 수 없는 coordinator보다 절대 나쁘지 않기 때문임."],"76042413":["도구 결과를 구조화된 형태 그대로 대화에 추가하기. 토큰 비용이 정말 부담되면 추가하기 전에 관련 필드만 남기고 잘라내기. 데이터를 산문 소감으로 바꿔치기하지 않기."],"77930220":["실패하는 문서 형태들을 다루는 작은 레이블링된 세트(labeled set)를 각각의 정답과 함께 만들고, 그 형태들을 예시(worked example)로 지시문에 녹여 넣고, 바꿀 때마다 그 세트로 다시 측정해서 한 형태는 나아지고 다른 형태는 나빠지는 것이 눈에 보이게 하기."],"78736176":["표준은 위키에 두고, 개발자들에게 필요할 때 관련 부분을 프롬프트에 붙여넣으라고 안내하기"],"79413533":["티켓 카탈로그(catalogue)를 도구로 노출해서, 에이전트가 대화 시작할 때마다 호출해 어떤 티켓 유형이 있는지 확인하게 하기"],"80513347":["계약서 추출기의 스키마는 counterparty_signatory(상대방 측 서명자)를 필수로 요구함.","서명자가 아예 없는 미서명 초안 계약서에서는, 모델이 레터헤드에서 가져온 그럴듯한 임원 이름을 지어냄.","올바른 해결책은 무엇인가?"],"81143846":["일시적 실패는 감추고, 존재하는 부분 결과만 성공으로 표시해서 돌려주기"],"81190036":["종합(synthesis) 에이전트가 “모순”이라고 표시함. 한 결과는 원격근무 도입률이 45%라고 하고, 다른 결과는 28%라고 함.","확인해 보니 앞의 것은 2021년 조사이고 뒤의 것은 2024년 조사임. 그런데 subagent들의 구조화된 출력에 날짜가 없어서 종합 단계에서는 그것을 알 수가 없었음.","구조적인 해결책은 무엇인가?"],"81373224":["(1) auto, (2) any, (3) none."],"81511155":["각 subagent(하위 에이전트)가 진행하면서 자기 결과와 완료 기록을 파일로 계속 써 두게 해서, 코디네이터가 재시작되면 그 기록을 읽고 아직 끝나지 않은 패키지만 다시 배정하게 하기."],"81621136":["\"결제 재시도 모듈 테스트를 작성해줘\"라는 작업을, 파일을 열고, export된 함수를 나열하고, 함수마다 테스트 하나씩 작성하고, 테스트 스위트를 실행하라는 식으로 단계를 하나하나 적은 40줄짜리 프롬프트로 subagent에게 위임함.","그 결과 사소한 getter까지 포함해서 함수마다 테스트를 하나씩 만들었지만, retry exhaustion(재시도 소진)에 대한 테스트는 하나도 없었음.","동료는 단계를 20줄 더 추가하고 싶어 함.","더 나은 선택은 무엇인가?"],"83989928":["시스템 프롬프트(system prompt)를 지난주 버전으로 되돌리고, 감사(audit)가 끝난 뒤에 다시 살펴보기"],"85633109":["기각률을 릴리스마다 하나의 전체 지표로만 추적하기."],"86977605":["src/api/index.ts"],"87398612":["둘 중 어느 수치도 확정값으로 내보내지 않기: 각 수치를 어디서 찾았는지와 함께 둘 다 기록하고, 그 레코드를 conflicting으로 표시해서 자동 경로에서 빠지게 하기. 문서 자체가 서로 모순되고 있고, 파이프라인 안의 어떤 rule도 어느 수치가 진짜인지 결정할 수 없으니까."],"88135238":["리포트와 structured findings만 받고 작성 세션의 reasoning은 전혀 가져오지 않는 별도 인스턴스를 두고, 각 주장(claim)을 그것이 인용한 finding과 대조해서 확인하는 방식임."],"88184680":["검색 Task 호출 세 개를 한 응답에 같이 내보내서 병렬로 돌리기. 그다음 턴에서 세 결과를 프롬프트에 주입해 비교 단계를 호출하고, 이어서 비교 결과를 넣어 요약 단계를 호출하기"],"88316806":["출시 전에는 전체 합산치만 보지 말고 문서 유형별·필드별로 나눠서 정확도를 검증하기","출시 후에는 자동 승인된 추출 건을 층화 무작위 표본으로 뽑아서 오류율을 계속 측정하고 새로운 패턴을 찾아내기"],"88900120":["Majority voting을 쓰면 딱 하나의 instance만 찾아낸 finding들이 버려지는데, 그것이 바로 추가 pass를 돌린 대가로 얻으려던 recall임."],"88942727":["네 리뷰 봇이 이제 독립 인스턴스로 돌면서 괜찮은 지적을 뽑아내는데, 양이 너무 많아서 사람 리뷰어가 못 따라감.","사람 눈이 가장 필요한 지적만 골라서 보내고 싶음.","모범 사례에 맞는 설계는 어느 쪽인가?"],"89073276":["discovery 결과가 쌓이고 나면 세션을 compact하기."],"91268579":["시스템 프롬프트의 위임 표현이 너무 약함. \"모든 요청에 반드시 subagent를 써야 한다\"고 못 박기."],"93333303":["아직 4시간째임.","에이전트는 플랫폼 리드가 손대지 말라고 지정한 세 서비스 중 하나에 legacy billing client를 호출하는 코드가 있다는 것을 발견함.","리드가 말한 롤백 규칙은 수정 중인 서비스에만 적용되기 때문에, 이 경우에는 해당되지 않음.","에이전트는 리드가 작성한 지침을 두 번이나 다시 읽어봤지만, 거기엔 이에 대한 언급이 없음.","에이전트는 어떻게 해야 하는가?"],"95882232":["jitter 설계를 지금 바로 구현해서 pull request를 열기. 결제 그룹은 코드 리뷰에서 승인하는데, 거기서는 설명이 아니라 실제 변경 내용을 보고 판단할 수 있음."],"96675463":["파일 45개 이상에 걸쳐 쓰이는 라이브러리를 마이그레이션하기"],"98678214":["검수자 두 명이 하루 3,000건 중에 60건을 확인할 수 있음.","지금 라우팅은 무작위 표본을 넘겨줌.","어제는 이미 가장 취약한 구간으로 알려진 유형임에도 애매한 스캔 영수증 묶음이 자동 승인을 그냥 통과해 버렸음.","그 60건을 어떻게 배분해야 하는가?"],"99199270":["목록이 더 길었어야 함. 규정에서 한 줄 한 줄 뽑아낸 40개 항목짜리 체크리스트였다면 문서화되지 않은 매장(store)들까지 다 커버했을 것임."],"99481033":["심볼과 호출 그래프까지 이해하는 semantic_search 도구를 가진 코드 인텔리전스 MCP server를 붙임. 단순 텍스트 검색보다 훨씬 강력함.","그런데도 에이전트는 \"processPayment를 호출하는 곳을 전부 찾아 달라\" 같은 질문에 계속 내장 Grep을 씀. 이 MCP 도구의 설명에는 \"Searches code.\"라고만 적혀 있음. 가장 좋은 해결책은 무엇인가?"],"100623026":["필드마다 호출 하나씩, 문서 전체에 걸쳐 60번 호출하기. 그러면 호출마다 대상이 하나뿐이라 두 조항을 헷갈릴 수가 없음."],"101971859":["이 제안이 맞음: memo를 schema 안에 넣어야 두 출력을 한 번의 call로 강제할 수 있고, 섹션 순서와 문구 규칙은 그 필드의 description에 넣으면 됨."],"104167424":["두 값을 모두 넣고 출처, 날짜, 방법론(전수조사 대 추계)을 함께 표기한 다음, 충돌 자체를 위로 올려서 coordinator가 조정하게 하기. 최신이라는 이유만으로 서로 다른 방법론 사이의 우열이 갈리지는 않고, 충돌을 솔직히 드러내는 건 우유부단한 게 아님."],"104775083":["모든 인보이스를 사람 검토로 보내고 세금 ID가 없는 것들만 검토자가 빠르게 승인하게 해서, 세금 ID가 들어 있는 건 어느 것도 빠져나가지 못하게 하기."],"108187521":["(i) 동적 분해(dynamic decomposition); (ii) 고정 순차 파이프라인(fixed sequential pipeline)."],"109810425":["get_customer가 항상 먼저 호출되는 모습을 보여주는 few-shot 예시."],"109849198":["그것이 .claude 폴더 안에 있는지가 판단 기준임. Claude Code가 설정을 찾을 때 훑는 폴더가 바로 거기이기 때문임."],"112737971":["모든 permission 검사를 건너뛰는 모드로 실행을 시작하기. 두 증상이 한 번에 사라지고, 어차피 workspace는 작업 사이마다 다시 만들어지기 때문임."],"114466584":["알려진 오탐 패턴과 일치하는 지적을 걸러내는 시그니처 기반 억제기를 만들기."],"114618451":["구조가 서로 다른 문서에서 제대로 추출하는 모습을 보여주는 few-shot 예시를 추가하기. 본문 인용이 있는 것 하나, 참고문헌 목록이 있는 것 하나, 방법론이 본문에 섞여 있는 것 하나로."],"115102622":["한 엔지니어가 이렇게 제안함. \"종합 에이전트가 소스가 더 필요할 때 검색 에이전트한테 바로 메시지를 보내게 한다. coordinator를 빼면 왕복 한 번을 아낄 수 있다.\" 지금 시스템은 모든 것을 coordinator를 거쳐 라우팅함.","올바른 평가는 무엇인가?"],"115149124":["저장소의 진입점을 읽고 import를 따라가며 사용처를 찾은 다음, 의존성 트리가 펼쳐지는 대로 이름을 바꾸기."],"115606108":["창고 팀에 API 응답을 더 적고 깔끔한 필드로 다시 설계해 달라고 요청하기"],"116499997":["그 contractor(외부 계약자)의 실험용 서버를 자기만의 user-scoped configuration(사용자 범위 설정)으로 옮겨서, 그 사람한테만 로드되게 하기."],"118505041":["직접 실행 모드를 유지하면서 렌더러만 고쳐 이중 변환을 상쇄하기. 원래 티켓이 다룬 범위가 렌더러뿐이었음."],"119221819":["(3)과 (4)는 프로그램으로 검사하기 쉬우니까 hook으로 두고 (1)과 (2)는 판단이 필요해서 언어 이해가 있어야 하니까 few-shot 예시와 함께 프롬프트에 넣기."],"119952831":["(1)과 (3)은 프로젝트 스킬로 만들어서 필요할 때 불러 쓰고, (2)는 프로젝트 CLAUDE.md에 \"Kim 전용\"이라고 표시해서 넣기"],"120790041":["max_tokens를 늘려서 모델이 답하기 전에 페이지 전체를 충분히 처리할 여유를 갖게 하기."],"124560443":["개발자가 이렇게 입력함: \"오래된 auth 코드 정리할 것.\" 리포지토리에는 사용 중단된(deprecated) auth/ 디렉터리, 살아 있는 엔드포인트 세 개가 여전히 import하는 legacy_auth.py 모듈, 그리고 feature flag로 감춰둔 auth_v2/ 재작성본이 있음.","잘못된 것을 지우면 프로덕션이 멎음.","에이전트는 어떻게 해야 하는가?"],"128438069":["배치 요청 하나로는 요청 도중에 도구를 실행하고 이어서 진행할 수가 없음."],"128581812":["네 최종 리서치 리포트는 뭐든 똑같은 불릿 목록으로만 나옴. 분기 재무 수치, 속보 인용, API 벤치마크 결과가 전부 똑같아 보이고, 검토자들은 재무 부분을 못 읽겠다고 함.","모범 사례는 어떻게 하라고 하는가?"],"129317317":["에이전트가 수정해도 되는 디렉터리 목록."],"129754404":["심각도가 critical인 findings만 사람에게 넘기고 나머지는 자동 승인하기."],"131705091":["합의된 금액, 날짜, 주문 번호, 상태를 뽑아서 영속적인 케이스 사실(case-facts) 블록에 모으기. 이 블록은 요약 대상에서 빼고 모든 프롬프트에 주입하기."],"131911099":["fetch_url은 유지하되 모든 fetch를 로그로 남겨서 주간 보안 검토에 쓰기."],"134195618":["경로 범위를 지정한 .claude/rules/ 파일을 레포에 커밋해서 쓰는 방식."],"135242816":["권한 확인(permission check)을 아예 건너뛰도록 호출을 감싸고(그러면 멈춤 현상이 바로 사라지고, 어차피 실행기는 일회용임), 텍스트 출력은 그대로 둔 채 대시보드의 패턴만 더 엄격하게 다듬기"],"135468579":["intake 단계는 항상 get_customer로 시작해야 함.","팀은 각 대화의 첫 API 호출에서 tool_choice를 get_customer를 지정하는 specific tool 형태로 설정함.","이 변경으로 팀이 기대하면 안 되는 결과는 무엇인가?"],"136089058":["structured outputs(구조화된 출력)를 활성화해서 API가 응답을 스키마(schema)에 맞게 제한하게 하기"],"136184220":["retry 횟수를 늘려서 paywalled(유료 장벽에 걸린)된 경우랑 malformed(형식이 잘못된) 경우도 결국엔 성공하게 하기"],"137247569":["8턴마다 새 세션을 시작하되, 지금까지의 대화 요약은 넘겨주기"],"138363009":["결국 chargeCard()를 호출하는 곳을 전부 찾아야 함.","이 심볼(symbol)은 서로 다른 이름의 wrapper 모듈 두 개, billing.charge와 payments.run을 통해 재수출(re-export)되고 있고, 저장소에는 파일이 2,600개 있음.","다음 단계로 가장 쓸모없는 방법은 무엇인가?"],"138542550":["에러 메시지 문자열의 오타를 고치기"],"139822979":["extraction prompt에 \"could not retrieve document\"가 나오면 에이전트가 멈추고 실패를 보고해야 한다는 문구를 한 줄 추가하기."],"140092706":["-p로 CLI를 호출해서 non-interactive(비대화형) 실행으로 만들고 --output-format json도 함께 써서, 이미 있는 파서(parser)가 출력을 기계적으로 파싱할 수 있게 하기."],"140978302":["(i), (ii), (iii)는 진실 공급원(source of truth)을 하나로 유지하기 위해 루트 메모리 파일(root memory file)에 넣고, (iv)는 diff가 vendored/를 건드리는 빌드는 전부 실패시키는 파이프라인 체크(pipeline check)로 만들기."],"141006390":["(a) --resume 에 \"변경에 주의해\" 라는 메모를 붙이기. (b) 요약을 들고 새 세션 열기. (c) 예전 세션에서 두 전략을 순차로 탐색하기."],"141216646":["에이전트가 더 보수적인 confidence 점수를 하나 더 만들게 하고, 둘 다 기준을 넘어야 하게 만들기"],"142237711":["호출자(caller)가 다르게 대응해야 하는 실패 종류들(document not found, permission denied, upstream timeout)을 한 문장으로 뭉뚱그리지 말고 구분하기"],"144816664":["셋 다 바로 실행으로 넘어가고, (b)만 나중에 꼼꼼히 검토하는 방식임."],"145081610":["세션의 도구 결과(tool result)가 이미 낡았으니까, 어제 나온 핵심 결론을 구조화된 요약으로 넣으면서 새 세션을 시작하기."],"146893711":["그 이름이 지정된 session을 resume(재개)해서 에이전트한테 어떤 identifier(식별자)가 바뀌었는지 알려주면, 영향받은 레코드만 다시 읽기."],"147083079":["tool choice를 설정해서 이번 턴의 첫 호출이 그 특정 도구에 고정되게 하고, 등록(registration)이 끝나면 다음 턴들에서 보강용(enrichment) 도구들이 돌아가게 하기"],"147346604":["리뷰어는 각 pull request에 연결된 issue tracker 티켓의 acceptance criteria(수용 기준)를 인용해야 함.","팀이 그 tracker용 MCP server를 설정했고, 개발자 머신의 interactive session(대화형 세션)에서는 잘 작동함.","그런데 CI에서는 그 인용이 전혀 나타나지 않음.","다음 중 이 문제를 해결하지 못하는 조치는 무엇인가?"],"148034152":["카테고리별 기준: security는 리뷰어가 확신이 없어도 반드시 보고해야 하는 코드 패턴을 구체적으로 명시하고, style은 style 관련 발견을 애초에 제기할 가치가 있는 좁은 조건을 구체적으로 명시하기","confidence를 설명하는 전역 문장 하나로는 정반대인 허용 기준 두 개를 동시에 담을 수 없음."],"148125831":["Job B도 고정된 체인(fixed chain)으로 돌리되, subtask 목록을 훨씬 길게 잡아서 나중에 중요하다고 밝혀지는 영역이 뭐든 이미 커버되게 하기."],"148718965":["다섯 개를 메시지 하나에 하나씩 순차로 보내서 각 수정이 온전히 주목받게 하기"],"148902985":["팀은 반복 가능한 4단계 릴리스 감사(release audit)를 원함. 체인지로그(changelog)를 읽고, 마이그레이션 파일을 diff하고, 버전 매니페스트(version manifest)를 확인하고, 판정을 내리는 것임. 개발자가 명령어를 입력해서 실행하든 CI job이 실행하든 똑같이 동작해야 함.","컴플라이언스(Compliance)는 요구사항을 하나 더 추가함: 이 감사는 아무것도 쓸 수 없어야 함.","한 팀원은 이것을 skill로 패키징하고, skill의 allowed-tools frontmatter에 읽기 도구만 나열하면 \"그렇게 하면 구조적으로 read-only가 됨\"이라며 제안함. 이 제안에서 맞는 부분과 틀린 부분은 무엇인가?"],"149783579":["버그의 스택 트레이스가 문제 줄을 정확히 짚어 주고, 실패하는 회귀 테스트도 이미 있고, 수정도 한 줄이면 끝남.","가장 부적절한 행동은 무엇인가?"],"152163865":["두 필드의 enum에 \"unknown\" 값을 각각 추가해서 모델이 언제나 솔직한 선택지를 갖게 하기"],"152904705":["추출(extraction)을 JSON 스키마(schema)가 있는 도구(tool)로 정의하고 도구 입력(tool input)을 읽어서, 제약이 응답이 시작되는 부분만이 아니라 객체 전체(어떤 키가 있고 각 값의 타입이 뭔지)를 다루게 하기"],"153619233":["세션을 fork해서 분기 쪽에서 이어 가고, 원본은 그대로 두기."],"156801905":["매일 밤 처리하는 문서 4만 건은 Batches API로 옮기고, 웹 폼은 동기(synchronous) 호출 그대로 유지하기. 야간 결과는 주간 마감 때까지 읽히지 않고 완료 시점도 보장되지 않는 반면, 폼에는 2초 예산이 있어서 어떤 배치 처리 시간도 이걸 맞출 수 없음."],"157750450":["탐색용(discovery) 도구 세 개를 describe_archive라는 통합 도구 하나로 바꿔서 탐색에 호출 세 번 대신 한 번만 들게 하기."],"159015668":["세 개 전부 저장소의 메모리 파일(memory file)에 넣고 R2는 굵은 글씨로 명시적인 금지 사항으로 적고 R3는 관련 없을 때 모델이 건너뛸 수 있게 명확히 라벨링된 섹션에 배치하기. 항상 로드되는 단일한 진실 공급원(source of truth) 하나가 세 가지 메커니즘보다 14명이 최신 상태로 유지하기 더 쉬움."],"160102762":["채용 지원(hiring-support) 에이전트가 들어오는 지원서를 심사함.","매 지원서마다 parse_resume를 호출하고 이어서 score_fit을 호출한 다음, 채용 담당자를 위해 한 문단짜리 요약을 작성함.<br><br>3월에 물량이 두 배로 늘면서 채용 담당자들 말로는, 배치(batch) 뒤쪽에서 처리된 지원서의 요약에 그 지원자 이력서 어디에도 없는 스킬이 언급된다고 함.","로그를 보면 parse_resume는 이력서 전체 텍스트를 반환하는데 보통 3,000토큰 이상이고, 파싱된 이력서는 전부 지원서 60건짜리 배치 전체 동안 대화에 남아 있음.<br><br>지원서는 반드시 한 번의 배치 실행(batch run)으로 처리해야 하는데, 채용 담당 툴링이 결과 파일 하나를 폴링(poll)해서 가져오기 때문임.","올바른 해결책은 무엇인가?"],"160669832":["과제는 다음과 같음. \"설정값 MAX_RETRY_DELAY가 어디서 정의되는지, 그리고 그걸 읽는 파일이 전부 어딘지 찾기.\" 코드베이스에는 파일이 1,400개 있음.","올바른 도구 사용 순서는 어떤 것인가?"],"161528369":["각 에이전트의 읽기 노트(reading notes)를 30분마다 갱신되는 rolling digest(누적 요약)로 점진적으로 요약하는 방식임."],"161558370":["plan mode부터 쓰기. 운영 버그에서는 코드를 건드리기 전에 계획을 세우는 것이 안전한 기본값이기 때문임."],"161695366":["각자 자기 사본을 관리하도록 전부 개발자 개인 사용자 레벨로 옮기기."],"163589360":["첫 번째 불만을 조사해보니, 코디네이터(coordinator)의 루프는 이렇게 동작함. 대화를 모델에 보내고, 응답에 텍스트 블록(text block)이 하나라도 있으면 실행이 끝난 것으로 간주함. 그렇지 않으면 요청된 도구들을 실행하고, 성공한 결과만 대화에 추가한 다음, 40회 반복 상한(cap)이 강제로 멈출 때까지 이 과정을 반복함.","폭주하는 실행의 근본 원인을 해결하는 변경은 어느 것인가?"],"163980473":["두 그룹 모두 최대 세 번까지 재시도하기. 일시적인 추출 실패는 대부분 두 번째 시도에서 풀리기 때문임."],"164102274":["모든 결과에 신뢰도(confidence) 값을 붙이기. 그래야 엔지니어들이 의심스러운 결과는 건너뛰고, 재현 안 될 티켓에 시간 쓰는 것을 멈출 수 있음."],"164484630":["후처리 단계에서 이미 올린 코멘트와 문자열을 비교해 중복 코멘트를 걸러내기."],"165211142":["pull request의 티켓 번호로 저장소를 검색해서 그 작업 항목을 참조하는 파일만 리뷰에 들어가게 하기."],"165377399":["모델이 필드 단위 신뢰도 점수를 내게 하고, 라벨이 붙은 검증 셋으로 필드마다 보정한 다음, 핵심 필드가 각자의 보정된 임계값 아래로 떨어지는 문서를 따로 보내기. 문서 평균으로는 개별 필드를 지켜줄 수 없기 때문임."],"166428198":["반드시 보존해야 하는 값들에 대해 필드를 미리 정의하고, 그 블록을 모든 프롬프트에 다시 넣기"],"167251351":["\"어시스턴트 턴(assistant turn)을 프리필(prefill)하는 게 잘 구성된 JSON 객체를 가장 강력하게 보장하는 방법임. 여는 중괄호(opening brace)가 한 번 주어지면 모델이 그 구조에서 벗어날 수 없음.\""],"168001679":["임계값을 50달러로 낮춰서 위반 하나하나의 무게를 줄이기"],"168207705":["계획대로 재개해서 보고서를 요청하기. 모델이 작성하면서 불일치를 알아채고 알아서 바로잡을 것임."],"170003558":["CI 실행(invocation)에서 minimal-startup 플래그를 제거하기. 이것이 지금 MCP server auto-discovery를 건너뛰게 만들고 있음."],"171096881":["첫 번째 조사 결과가 두 번째로, 두 번째 결과가 세 번째로 넘어가는 식으로 chain으로 연결해서 진행하면서 context를 계속 쌓아가기."],"171564801":["이름을 붙여둔 세션 \"checkout-migration\"에 결제 모듈을 깊이 분석해 둔 내용이 들어 있음.","그 뒤로 바뀐 것은 하나뿐임. 6개 파일에 걸쳐 PaymentGateway를 PaymentProvider로 이름 바꾸는 PR을 머지했음.","이제 마이그레이션 계획 짜기를 이어서 하려고 함.","가장 효율적인 접근은 무엇인가?"],"173047803":["hook의 동작은 감사 가능(auditable)함. 요청이 어떻게 표현되든 상관없이 차단된 호출은 전부 동일한 기록을 남기기 때문임."],"173628120":["충돌이 감지될 때마다 종합 단계에서 더 오래된 수치를 버리게 하기."],"174283771":["두 팀 각각 에이전트가 필요함.","Team A는 벤더 계약서 240건을 똑같은 다섯 개 조항에 대해 똑같은 순서로 검토해서, 계약서별 판정을 낸 다음 계약서 전체를 아우르는 요약 하나를 만들어야 함.","Team B는 \"우리 AWS 청구액이 왜 6월에 3배로 뛰었는가?\"라는 질문에 답해야 하는데, 여기서는 뽑아본 지표 하나하나가 다음에 어떤 서비스, 리전, 계정을 열어볼지를 결정함.","Team B를 위한 비용 분석 런북(runbook)은 이미 문서로 마련되어 있음. 분해 전략(decomposition strategy) 배정 중 어느 것이 맞는가?"],"174603630":["시스템 프롬프트에 대응 관계를 나열해 두고 모델이 머릿속으로 변환하게 하기"],"177694429":["새 개발자의 Claude Code 버전이 CLAUDE.md 지원 이전 버전이라 업그레이드가 필요함."],"178236874":["개발자가 리졸버를 수정하기 전에 실행하는 /resolver-rules 슬래시 명령."],"180984354":["리서치 오케스트레이터(orchestrator)가 4시간 동안 서브에이전트(subagent) 5개를 실행함.","종합(synthesis) 단계에서 2019년 수치를 마치 최신인 것처럼 제시하는 보고서, 그리고 서로 다른 두 출처의 수치가 한 문장에 뒤섞이는 보고서가 계속 나오고 있음.","오케스트레이터는 현재 20분마다 각 서브에이전트의 트랜스크립트(transcript)를 500토큰짜리 서술문으로 압축함.","컨텍스트(context) 전략을 어떻게 바꿔야 두 증상을 모두 해결할 수 있는가?"],"181991718":["argument-hint 에서 mode 인자를 필수로 표시해서, 그게 없으면 skill이 실행되지 않게 하기"],"187654896":["핵심 findings 요약을 취합 입력의 맨 앞에 두고, 상세 결과는 명시적인 섹션 헤더로 정리하기. 이러면 lost-in-the-middle 효과를 줄일 수 있음."],"188264941":["단순 호출을 --output-format json으로 바꾸기. 이 플래그 하나로 비대화형(non-interactive) 실행과 구조화된 출력을 둘 다 처리하기 때문임."],"188901424":["검색 도구에 rate limit이 걸려서 모델이 자동으로 재시도하는 상황."],"189070958":["개발자들이 리뷰 봇의 지적을 많이 무시하는데, 어떤 코드 구조가 잘못된 지적을 유발하는지는 알 수가 없음.","오탐(false positive)을 체계적으로 분석하려면 어떻게 설계해야 하는가?"],"190947751":["불만 세 번째는 한 애널리스트의 하루에서 비롯됨: 그녀는 오전 9시부터 계속 같은 세션(session)에서 작업해 왔음.","점심시간 동안 데이터 팀이 그녀의 오전 분석이 기반했던 경쟁사 목록을 교체했음. 파일명은 같지만 내용은 다름.","이제 그녀는 오후 작업을 이어가고 싶어 하고, 동시에 같은 오후 질문을 서로 다르게 프레이밍한 두 버전을 나란히 비교하고 싶어 함.","어떤 처리 방식이 맞는가?"],"191637650":["지금처럼 하나씩 계속 하되, 고칠 때마다 회귀 테스트를 추가하기"],"191854437":["파일 전체를 Read하고, 메모리에서 올바른 위치에만 변경을 적용한 다음, 갱신된 파일을 Write로 다시 쓰기"],"192185561":["3주짜리 리서치 작업이 named session 하나에서 진행됨.","12일째에 클라이언트가 시장 모델을 다시 발표했는데, 3일째에 분석 subagent들이 읽었던 소스 문서 11개 중 6개가 이제 수정된 수치를 담고 있음.","분석가가 named session을 재개해서 최종 보고서를 요청하려는 참임.","대신 어떻게 해야 하는가?"],"194128879":["Jira는 이미 나와 있는 커뮤니티 MCP server를 쓰고, 자체 개발한 승인 시스템에만 커스텀 서버를 만들기."],"194236578":["안전을 위해 반복 10회라는 하드 상한을 주된 종료 조건으로 두기"],"197314556":["40회 iteration cap은 유지하되, 작업 종료를 판단하는 기준이 아니라 폭주를 막는 안전장치(runaway guard)로만 쓰기"],"198526831":["사용처가 하나도 숨지 못하게 코드베이스 전체를 한 번 다 읽기."],"199804713":["네 리서치 시스템은 깊이 있는 리포트는 훌륭하게 뽑아내는데, 단순 사실 질의(\"X의 CEO가 누구인가?\")도 90초 넘게 걸리고 비용도 전체 리포트랑 똑같이 나옴.","로그를 보면 coordinator가 모든 질의마다 다섯 개 subagent(검색, 분석가 둘, 종합, 리포트 작성)를 항상 차례로 전부 호출하고 있음.","subagent 각각의 동작 자체는 문제없음.","무엇을 바꿔야 하는가?"],"200286653":["엄격한 JSON 스키마와 함께 tool_use를 쓰면 무엇을 보장받고, 무엇을 보장받지 못하는가?"],"203371335":["지적 사항마다 세 번 실행한 심각도를 평균 내기"],"204419569":["반복 상한을 올려서 루프가 남은 작업을 끝낼 사이클을 더 갖게 하기"],"204599825":["한 번에 리뷰하려고 컨텍스트 창이 더 큰 모델로 바꾸기."],"204973773":["엔드포인트 스캐폴딩(endpoint-scaffolding) 워크플로가 schema writer, handler writer, test writer, docs writer, 이렇게 subagent 4개를 한 번에 띄움.","handler와 test는 customer_ref를 참조하는데, schema subagent는 자기 실행 도중에 customer_id로 정해버렸음. 그 시점엔 그 이름이 자기 출력에만 있었고, 아직 디스크에는 없었음.","각 subagent는 지시받은 그대로 했음.","문제는 어디에 있는가?"],"206227131":["R1은 모든 컨트리뷰터(contributor)의 개인 메모리 파일(memory file)에 넣어서 그 사람의 모든 프로젝트에 적용되게 하기; R2는 apply가 감지되면 빌드를 실패시키는 파이프라인 체크(pipeline check)에 넣기; R3는 services/ledger/ 안에 두는 메모리 파일에 넣기."],"206694074":["한 팀이 8시간짜리 멀티 에이전트(multi-agent) 문헌 조사를 위해 컨텍스트(context) 전략을 고르고 있음.","산출물은 첫 시간에 읽은 자료에서 나온 정확한 페이지 번호를 인용해야 함.","가장 적절하지 않은 선택지는 어느 것인가?"],"206930473":["야간 마이그레이션 에이전트가 레거시 재고 데이터베이스의 레코드를 새 스키마로 옮겼음.","사람 없이 컨테이너 안에서 무인으로 실행됐음.","오늘 아침 보니 새 데이터베이스에서 supplier_lots 테이블의 8,400개 행이 빠져 있음.","실행 로그에는 verify_batch가 모든 배치에 대해 {\"ok\": true}를 반환한 것으로 나오는데, 쓰기 단계가 타임아웃된 배치 세 개도 포함되어 있었음. 작성자는 대상 데이터베이스에 연결할 수 없을 때도 verify_batch가 ok를 보고하도록 만들었는데, \"연결이 불안정하다고 마이그레이션 전체가 실패하지 않게 하려고\" 그렇게 만든 것임. 컷오버(cutover) 기간이 끝나서 레거시 데이터베이스는 이제 읽기 전용이라, 전체 마이그레이션을 다시 실행할 수는 없음.","정확한 해결책은 무엇인가?"],"208430690":["대리 지표로 쓰던 트리거를 진짜 기준으로 갈아치우기. 고객이 사람을 명시적으로 요청한 경우, 정책 예외나 공백이 있는 경우, 더는 진행할 수 없는 경우를 프롬프트 기준으로 적고 few-shot 예시를 붙이기. 지금 쓰는 세 신호는 어느 것도 사건의 복잡도를 재지 못하기 때문임."],"210346196":["제안을 받아들이기. 프로그램적 강제는 대화 흐름에 너무 뻣뻣하다는 게 실험에서 드러남."],"210722649":["케이스의 12%에서 네 에이전트가 get_customer를 건너뛰고, 고객이 말한 이름만으로 lookup_order를 호출함. 그러다 가끔 계정을 잘못 짚음.","이걸 가장 효과적으로 고치는 방법은 무엇인가?"],"211166636":["자동화 임계값을 낮춰서 전체적으로 더 많은 문서가 사람한테 가게 하기"],"214375882":["search_products와 search_docs는 둘 다 설명이 한 줄뿐이라, 호출의 약 20%에서 서로 혼동됨.","제안 A: 에이전트 앞단에 의도 라우팅 분류기를 붙이자는 것임.","제안 B: 두 설명을 목적, 입력 예시, 그리고 \"언제 쓰고 언제 안 쓰는지\" 경계까지 넣어서 다시 쓰자는 것임.","무엇을 먼저 해야 하고, 이유는 무엇인가?"],"214731625":["Northwind Retail는 22명의 엔지니어가 함께 쓰는 저장소(repository) 하나를 유지함.","체크아웃 코드는 services/checkout/ 아래에, 정산 작업은 pipelines/settlement/ 아래에, React 스토어프론트는 web/ 아래에 있음.","이 팀은 6주 전에 Claude Code를 도입했고, 이번 스프린트에 플랫폼 리드에게 불만 세 건이 접수됐음.","첫째, 아무도 놓치지 않게 하려고 40페이지짜리 결제 컴플라이언스 핸드북을 저장소의 항상 로드되는 지침 파일(instruction file)에 통째로 붙여넣었음.","이제 세션마다 이 내용이 함께 로드되는데 스토어프론트 세션도 예외가 아니며, 결제와는 전혀 상관없는 작업에서도 토큰이 약 11,000개나 쓰이는 것을 팀이 확인했음.","둘째, 한 엔지니어가 사소한 통화 반올림 수정을 요청했는데 어시스턴트가 두 서비스에 걸쳐 파일 19개를 바꿨음. 반올림 로직을 공유 money 헬퍼 하나에 둘지, 아니면 서비스 경계마다 따로 둘지 아무도 합의한 적이 없었기 때문임.","셋째, 야간 풀 리퀘스트 리뷰 작업은 공유 CI 러너에서 사람 없이 돌아감.","지난주엔 오전 9시까지도 이 작업이 살아 있었는데, 마지막 로그 줄이 셸 명령 승인 요청이었고, 결과를 수집하는 대시보드는 산문에서 문장을 긁어내는 방식이라 일주일에 한 번꼴로 망가짐.","컴플라이언스 팀은 확고한 요구사항 하나를 추가했음. 리뷰 단계는 저장소에 절대 써서는 안 된다는 것임.","이번 분기 예산은 고정돼 있고, 플랫폼 리드는 불만 각각을 실제로 해결하는 메커니즘으로 처리하길 원함."],"216613499":["“아주 확신하는 발견만 보고할 것”이라는 지시를 추가하기"],"216924373":["프롬프트 지시를 추가하기. \"유효한 JSON으로만 응답하고 부연 설명은 붙이지 마.\""],"217980891":["탐색이 확실히 끝나도록 에이전트의 최대 반복 횟수를 늘리기."],"218030820":["코디네이터(coordinator)와 작업자들 사이에 전용 분류(triage) subagent를 넣어서 각 인시던트를 먼저 분류하게 하기."],"218439707":["20턴짜리 환불 케이스에서 초반에 정해 둔 정확한 금액과 기한이 자꾸 사라짐.","컨텍스트를 무한정 늘릴 수는 없음.","그 사실을 지켜 주는 메커니즘 두 개는 무엇인가? (2개 선택)"],"219508599":["호스트에 설치된 MCP server는 더 이상 탐지되지 않으므로 이미지 하나에만 있는 서버가 그 이미지의 결과를 바꿀 수 없음."],"223308983":["추출 호출 중에 나는 네트워크 타임아웃."],"223844112":["네 지원 에이전트의 도구들은 어느 백엔드가 응답하느냐에 따라 고객 등급을 \"GOLD\", \"2\"(숫자 코드), \"premium\" 중 하나로 돌려줌.","그래서 에이전트가 여러 결과를 놓고 판단할 때 가끔 엉뚱한 할인 등급을 적용함.","정규화는 어디에서 해야 하는가?"],"224441427":["재시도 루프를 넣어서 잘못된 값이 두 번째 패스에서 교정되게 하기"],"225527940":["초안 답변마다 빠뜨리는 것이 다름. 어떤 것은 정책 인용이 없고, 어떤 것은 일정이 없고, 또 어떤 것은 다음 단계가 없음. 일관된 패턴이 보이지 않음.","few-shot 예시를 다섯 개나 추가했는데도 지표가 거의 움직이지 않았음. 이제 무엇을 해야 하는가?"],"226987102":["깨끗한 세션과, 출력 형태와 견고성(robustness) 요구사항을 담은 훨씬 더 자세한 문서화된 명세(specification)가 필요함. 그래야 혼란스러웠던 이전 라운드의 내용이 하나도 넘어오지 않음."],"227226424":["지원서마다 독립된 context에서 처리해서 한 지원자의 이력서 텍스트가 다른 지원자 요약에 섞여 들어가지 않게 하고, 지원서별 결과는 채용팀 tooling이 기대하는 단일 통합 파일로 모으기"],"230024379":["요청이 코드베이스(codebase)를 언급할 때는 항상 이 도구를 쓰게 강제해서, Grep으로 폴백(fallback)되는 일이 없게 하기."],"231020245":["신원 확인은 백그라운드에서 비동기로 돌리고, 계정 작업은 그와 병렬로 진행하기"],"231597999":["infra/ 아래에서 뭔가를 수정할 때 Terraform 네이밍 규칙을 로드하기"],"232299536":["subagent가 주장과 출처의 대응 관계를 구조화해서 내놓게 하고(주장 + 인용 발췌 + URL + 날짜), synthesis 단계가 그것을 반드시 보존하고 병합하게 하기"],"233085348":["프롬프트를 다시 쓸 때까지 스타일 카테고리는 아예 꺼두고 나머지 카테고리는 다시 읽히게 하기."],"234355598":["평평한 사실 목록을 시간순으로 정렬해서 관련된 사실끼리 자연스럽게 뭉치게 하기"],"235121736":["코디네이터가 요청마다 실제로 어떤 스페셜리스트가 필요한지 판단하게 하고, 독립적인 것들은 한 응답 안에서 Task 호출로 동시에 실행시키고, 진짜로 의존 관계가 있는 단계만 다음 턴으로 남기기"],"235456422":["CI 리뷰 봇이 개발자들이 이전 라운드에서 이미 고친 이슈를 계속 다시 지적함.","팀원 하나가 이전 코멘트의 파일+줄 시그니처와 겹치는 지적을 걸러내는 후처리 필터를 짰음.","왜 다른 방식이 더 나은가, 그리고 그 방식은 무엇인가?"],"236099098":["배송 관련 질문이 track_shipment로 가는 걸 보여주는 few-shot 예시를 시스템 프롬프트에 넣고, 새로운 혼동이 나타날 때마다 예시를 늘려가기"],"236649281":["실패한 테스트를 언급하는 메시지를 달아서 변경을 커밋하기"],"238557397":["민감한 게 절대 커밋되지 않도록 서버 설정 전체를 개발자 각자의 ~/.claude.json으로 옮기기"],"238789816":["파일이 코드와 함께 커밋되니까, 저장소(repository)를 클론하는 모든 팀원에게 전달되는 방식임."],"238892757":["고신뢰 추출 건을 층화 무작위 표본으로 뽑아서, 오류율을 계속 측정하고 새로운 패턴도 찾아내기"],"241201989":["Message Batches API에 적합한 워크로드 두 개는 무엇인가? (두 개 선택)"],"242855959":["보고서를 작성하기 전에 양쪽 거래 건수를 비교하고, 합계가 다르면 전체 대사(reconciliation) 작업을 다시 실행하기."],"243513056":["밤새 돌린 리서치는 계속 \"정상(green)\" 상태였는데, 아침에 나온 경쟁 분석 리포트에는 가격 섹션이 통째로 빠져 있음.","로그를 보면 가격 담당 subagent가 대상 소스 두 곳 모두에서 페이월에 막혔고 {\"results\": [], \"status\": \"ok\"}를 반환했음. 작성자가 \"불안정한 소스 하나 때문에 파이프라인 전체가 실패하지 않게\" 하려고 그렇게 만들어 둔 것임. 코디네이터(coordinator)는 성공으로 보고 그대로 종합 단계로 넘어감.","올바른 수정 방향은 무엇인가?"],"244690099":["규칙 1에는 가로채는 hook이 필요하고, 규칙 2는 결과에 최종 환불 금액이 드러나니까 PostToolUse에 두는 게 맞음."],"245254452":["판단해서 소액이면 매칭을 승인하기. 고객을 붙잡는 것이 그 차액보다 가치 있기 때문임."],"246251880":["한 파트너사가 고정 컬럼(fixed-column) 텍스트 파일을 받아들임. 한 줄에 레코드 하나, 금액은 41열부터 52열까지 오른쪽 정렬, 날짜는 구분자 없이 8자리 숫자로 표기함.","지금 프롬프트는 모델에게 그 줄을 직접 만들어내라고 시키는데, 40줄 중 한 줄꼴로 한 글자씩 어긋남.","한 팀원은 컬럼 레이아웃을 스키마(schema)의 필드 설명(field description)으로 옮겨서 모델에게 정확한 패딩(padding) 방법을 알려주자고 제안함."],"248047510":["print mode의 달러 상한(dollar ceiling)을 추가하기: subagent(하위 에이전트)가 쓰는 비용도 거기 합산되고, 상한(cap)에 도달하면 subagent를 새로 만드는 대신 실행이 멈춤."],"248062147":["중복 결제(duplicate-charge) 사후분석(postmortem)에서 나온 액션 아이템: 결제 게이트웨이 클라이언트의 재시도 백오프(retry backoff)를 바꿔야 함.","설계안은 두 가지 다 타당하고(클라이언트 쪽 지터(jitter) 방식 대 큐 계층의 정책 방식), 변경 범위는 두 서비스에 걸친 파일 9개이며, 결제팀은 코드가 반영되기 전에 승인된 방식이 기록으로 남아 있어야 한다고 요구함. 이 단계를 건너뛴 것이 1,400건의 중복 결제를 만든 원인이었음.","어떤 실행 형태가 맞는가?"],"250236535":["출력이 파싱에 실패하는 subagent가 있으면 coordinator가 최대 세 번까지 다시 물어보게 하기"],"251451923":["그것을 저장소(repository) memory 파일에 커밋(commit)하고, 리뷰 체크리스트가 같은 파일을 참조하게 하기."],"251680128":["shell 허용 권한을 패턴 매칭 파일 찾기 tool로 바꾸기. 파일 일부를 골라내려고 만들어진 전용 tool이고, 세션이 임의 명령을 실행하지 못하게 막아주기 때문임."],"251979811":["보고서 에이전트가 상류에서 온 페이로드를 쓰기 전에 각각 요약하게 하기"],"252525101":["각 조사의 프롬프트는 그 자체로 완결되게 쓰기(질문, 어디서부터 찾아볼지, 원하는 답변 형태까지 포함). 어느 것도 메인 대화를 읽을 수 없기 때문임."],"254141236":["워크플로(workflow)를 저장소 메모리 파일(memory file)로 옮겨서 모든 세션이 그것을 로드하고 따르게 하기"],"254348313":["\"재생에너지 도입(renewable energy adoption)\"을 다루는 리서치 시스템이 태양광만 다룬 보고서를 내놓고 있음.","로그를 보면 코디네이터가 만든 하위 작업은 \"solar panel costs\", \"residential solar trends\", \"solar subsidies\"였음. subagent는 전부 성공했음.","실패 지점은 어디인가?"],"255983803":["custom_id로 실패한 요청을 찾아내고, 크기가 너무 큰 문서는 잘게 나눠서, 실패한 것만 다시 제출하기."],"256871215":["서로 얽힌 문제는 함께 풀어야 하므로, 이슈 5개를 자세한 메시지 하나에 모아서 한꺼번에 제시하기"],"257456748":["불만 둘. 출처 두 개짜리 질문이나 전체 시장 조사나 똑같이 돌아감. 코디네이터가 모든 요청을 스페셜리스트 세 명 전부에게 보내고, 하나가 끝나야 다음 것을 시작하기 때문임.","팀은 짧은 요청은 빨리 끝나면서도 긴 요청의 처리력은 약해지지 않길 바라고, 코디네이터는 모든 트래픽의 중심에 계속 있어야 함.","어떤 재설계가 맞는가?"],"259124672":["실제로 합의된 내용(금액, 기한, 고객에게 한 약속)을 구조화된 요약으로 심어서 새 세션을 열고, 새 레코드를 기준으로 계정을 다시 조회하게 하기."],"261359441":["loader가 매일 밤 레코드 개수를 전날 밤과 비교하게 하고, 유의미한 변화가 있으면 alert를 보내게 하기."],"264600463":["야간 CI 작업이 그날 머지된 변경사항을 리뷰함. 보통 billing-api, notification-worker, shared/utils에 걸쳐 파일 20~40개 정도임.","한 번에 훑는 단일 패스 리뷰라서 어떤 파일에선 뻔한 버그를 놓치고, 똑같은 패턴을 두고 서로 모순되는 판정을 내림.","팀이 재설계안 네 가지를 놓고 논쟁 중임.","어떤 게 가장 나은가?"],"265194605":["한 저장소에 필요한 게 두 가지 있음. (1) infra/ 아래 파일을 편집할 때마다 Terraform 스타일 규칙이 항상 적용돼야 함. (2) 새 API 엔드포인트를 스캐폴딩하는 예제는 엔드포인트를 만들 때만 필요하고, 같은 디렉터리에서 버그를 고치는 동안에는 방해만 됨.","각각에 맞는 메커니즘을 고를 것."],"265865333":["서로 독립적인 세 조회를 한 번의 응답에서 모두 요청하도록 에이전트에 프롬프트를 주기. 병렬 도구 호출(parallel tool calls)은 새 도구가 필요 없고, 왕복 횟수를 줄여 주며, 앞으로 어떤 조합의 조회가 와도 통함."],"267882795":["네 CI 리뷰어의 출력은 merge-queue bot이 파싱하는 3줄짜리 요약 블록으로 항상 끝나야 함. 무엇이 바뀌었든 모든 pull request에서 예외는 없음.","한 팀원이 frontmatter에서 repository의 모든 파일에 매칭되는 path 패턴을 선언하는 rule 파일을 제안하면서, 이러면 모든 컨벤션을 한곳에 일관되게 모아둘 수 있다고 주장함.","그게 왜 문제고, 무엇이 맞는 방법인가?"],"267975445":["원본 청구서는 날짜를 \"3/4/25\", \"April 3, 2025\", \"2025-04-03\"처럼 제각각 적고, 금액도 \"1.234,56 €\" 아니면 \"$1,234.56\"처럼 적음.","네 스키마는 날짜를 ISO 8601로, 금액을 USD로 정규화한 숫자 값으로 저장함.","추출 결과는 구조상으로는 유효한데 값의 정규화가 들쭉날쭉함.","가이드는 무엇을 하라고 하는가?"],"270526076":["카테고리 enum에 \"unclear\"와 \"other\"를 추가하고, 상세 내용을 담을 문자열 필드도 하나 넣기."],"271411871":["재시도 상한을 3회에서 8회로 늘려서 티켓 필드가 결국은 제대로 나오게 하기."],"271915503":["코디네이터가 \"Analyze the documents relevant to our research.\"라는 프롬프트로 문서 분석 subagent를 띄움. 그랬더니 subagent가 어떤 문서를 말하는 것이냐고 되물음.","정작 코디네이터 자기 히스토리에는 검색 단계에서 나온 URL 12개 목록이 전부 들어 있음.","근본 원인은 무엇인가?"],"273060280":["기존 개발자 세 명은 매 세션마다 팀의 네이밍 컨벤션이 적용됨. 그런데 새로 합류한 네 번째 개발자는 같은 저장소를 클론했는데도 적용이 안 됨.","가장 그럴듯한 원인과 해결책은 무엇인가?"],"273203072":["응답이 끝날 때마다 텍스트에서 \"task complete\" 같은 문구를 찾아보는 것을 두 번째 완료 확인으로 쓰기."],"273252144":["Glob으로 **/*config* 파일을 찾아 하나씩 읽고, import를 보고 누가 읽을지 추측하기"],"273313693":["세션 요약을 더 자주, 더 공격적으로 해서 처음 30분 동안 내려진 결정들이 매번 갱신되는 요약(running summary)에 계속 반영되게 하기"],"274429357":["발췌문(excerpt) 안의 콜론, 따옴표, 그 밖의 문장부호를 허용하도록 정규표현식(regular expression)을 더 견고하게 만들기."],"275448627":["저장소와 함께 백업되도록 프로젝트의 .claude/commands/에 /my-commit으로 두기."],"281664222":["각 심각도 등급을 명시적인 기준과 구체적인 코드 예시로 정의하기(예: 하드코딩된 자격증명은 critical, 샘플 코드까지 함께). 그래야 똑같은 이슈가 똑같이 분류되기 때문임."],"284558441":["세금 ID(tax ID)가 발견된 송장은 무조건 escalate하라고 에이전트에게 지시하는 system-prompt 규칙을 추가하기"],"285349429":["B2B 케이스가 9일째 진행 중이며, 에이전트가 합의된 내용을 기억하도록 지정 세션(named session)을 그대로 유지하고 있음.","6일째에 계정이 새 청구 플랫폼(billing platform)으로 이전됨. 모든 주문, 인보이스, 자격(entitlement) 레코드가 새 식별자로 다시 생성됐고, 예전 ID로 조회하면 이제 not-found가 뜸.","세션에 저장된 도구 결과(tool result)는 예전 레코드에 대한 내용임.","7일째에는 어떻게 해야 하는가?"],"286609812":["주문 조회 도구가 지금은 어떤 문제가 나든 \"failed\"라는 문자열만 돌려줌.","구조화된 에러 응답에 어떤 필드 두 개를 넣어야 에이전트가 올바른 복구 판단을 할 수 있는가? (두 개 선택)"],"287104346":["src/api/v2/handlers/payment.ts"],"290924765":["그 절차는 필요할 때마다 호출되므로, 같은 prompt 텍스트를 담은 project slash command."],"291473004":["자동 코드 리뷰가 미묘한 문제까지 안정적으로 잡게 만드는 실천 둘은 무엇인가? (두 가지를 선택할 것)"],"292871706":["정확성을 위해 매일 아침 새 세션을 시작하고 코드베이스 전체 분석을 다시 돌리기."],"293017508":["안전하게 가려고 자동 승인 임계값을 0.9에서 0.95로 올리기."],"293284424":["둘 다, 원래 prompt를 새 세션에서 다시 실행하기. 식별자를 따로 관리할 필요도 없고, 애초에 실행 비용이 저렴했던 리뷰를 그대로 재현할 수 있음."],"293915720":["다시 초안을 쓰기 전에, 모델이 클라이언트의 stakeholder한테 대상 독자, 내려야 할 결정, 반드시 빼야 할 내용에 대해 인터뷰하게 하기"],"294442824":["종합 에이전트가 상충하는 수치를 발견할 때마다 웹에서 날짜를 검색하도록 지시하기"],"294911537":["authentication 예시 개수를 12개에서 30개로 늘려서 의도한 패턴이 다른 모듈로 새어 나가지 않을 만큼 정확하게 보여지게 하기"],"295076558":["무언가 없을 때는 null이 정직한 값이니까, 셋 다 필수로 두되 broker_reference와 insurance_certificate_id는 nullable로 하기"],"297362943":["형용사 표현을 명시된 조건으로 바꾸기: 고객이 손실이나 우리 쪽 과실을 언급할 때만 공감 문장 하나, 해결책은 첫 두 문장 안에, 상태 질문에는 사과를 아예 넣지 않는 식으로"],"299463902":["로그를 보면 문서 분석 subagent가 분석 도중에 \"빈틈을 메우려고\" 가끔 웹 검색 도구를 호출함. 그 바람에 검색 에이전트의 품질 필터를 우회한, 추적되지 않는 소스가 생김.","이 분석 에이전트는 검색 도구 일습을 포함해 도구 11개에 접근할 수 있음.","올바른 해결책은 무엇인가?"],"299749418":["도구 설명이 망가졌으니 둘 다 처음부터 새로 쓰기"],"302463300":["레포 어디에 있든 이름이 *.test.tsx 에 맞는 파일을 전부 찾기 → Glob."],"303578069":["네 추출(extraction) 로직은 이미 JSON schema로 tool을 호출하고 있는데, 그런데도 loader가 300개 중 1개꼴로 payload를 거부함. 필수 필드가 빠졌거나 integer가 string으로 들어오는 식임.","팀은 최신 모델을 쓰고 있고 요청 과정을 처음부터 끝까지 직접 통제함.","제안이 두 가지 나왔음. tool에 schema-validation 보장 기능을 켜거나, tool wrapper를 아예 빼고 응답 자체를 schema에 맞는 JSON으로 취급하는 방법임.","둘을 정직하게 비교하면 어떻게 되는가?"],"304272611":["대신 기준을 모든 티켓에 대해 0.95로 올리고, 평균 CSAT가 4.8에 도달하면 그때 낮추기."],"304850791":["line item들의 합이 명시된 invoice 총액과 일치하는지 확인하고, 일치하지 않으면 해당 레코드를 flag하는 것."],"305830955":["Task 호출 5개를 한 응답에 전부 내보내기. 병렬성을 최대로 끌어올리면 전체 지연이 가장 짧아지기 때문임."],"306135021":["그대로 받아들이되 직접 주고받은 메시지를 로그로 남겨서 관측 가능성은 유지하기."],"307690692":["각 shell 명령을 검사해서 허용되지 않은 도메인이 나오면 거부를 반환하는 PreToolUse hook을 등록하기. 이 hook은 모든 tool 호출에서 permission 판단보다 먼저 실행되기 때문임."],"307801605":["쓰기 작업(write operation) 전에 이전 대화를 다시 읽으라고 에이전트한테 지시하는 줄을 시스템 프롬프트에 추가하기"],"307918757":["먼저 할 것: 검증 세트 크기를 두 배로 늘리기.","그다음 할 것: 같은 검증 세트를 분기마다 다시 돌리기."],"307965561":["두 번째 불만 사항에 집중함.","합계 금액 추출 실패와 주소 뒤바뀜 문제는 특정 레이아웃에서만 나타나며, 브리핑에는 그 파일들을 직접 열어 보는 사람이라면 두 값 모두 읽어낼 수 있다고 적혀 있음.","한 팀원은 스키마(schema)에서 total과 billing_address를 필수(required)로 지정해 모델이 더 이상 null을 반환하지 못하고 반드시 값을 찾아내게 하자고 제안함.","대신 무엇을 적용해야 하는가?"],"308807754":["세 개의 gap에 대해 실패하는 테스트(failing test)를 작성하고, 전부 통과할 때까지 반복하기"],"310672975":["block에는 갈 곳이 없음. 거부(refusal)가 일어나면 hook이 케이스 정보를 첨부해서 사람 에스컬레이션(escalation) 경로로 보내야 대화가 막다른 곳에서 끊기지 않고 어딘가로 이어짐."],"313518426":["공유된 고객 컨텍스트를 활용해서 서로 다른 이슈들을 병렬로 조사하고, 그다음 하나로 통합된 해결안으로 종합하기"],"313825566":["1번과 2번은 순차로 하되 사이에 회귀 테스트를 하나 넣고, 3번부터 5번까지는 정리용 메시지 하나로 묶기."],"315338716":["매일 자정에 배치를 하나씩 제출하기. 처리에 24시간이 걸려도 30시간 안에는 들어오기 때문임."],"317053768":["Call 1은 파싱 실패 시 재시도하는 format instruction을 씀. 이게 더 저렴하고, 루프만 갖춰지면 신뢰도도 똑같이 나옴."],"317081480":["적용(apply) 기능을 아예 지워서 파괴적인 동작이 하나도 못 돌게 하기."],"318093802":["커밋마다 하지 말고 머지할 때만 리뷰하기. 그러면 다시 지적할 이전 라운드가 아예 없기 때문임."],"318507433":["critical 라벨의 기준을 높여서 해당되는 발견을 줄이기. 정밀도(precision) 88%면 여덟 개 중 하나꼴로 부당한 차단이 섞여 있는 셈인데, 라벨 기준을 조이면 그것들이 없어짐."],"318986556":["에이전트가 가진 도구를 그 역할에 실제로 필요한 작은 집합으로 줄이고, 나머지는 위임된 subagent 뒤로 넘기기. 선택지가 늘어날수록 선택 신뢰도가 떨어지기 때문임."],"319769229":["/migration-create와 /migration-apply라는 별개 스킬 두 개로 쪼개기"],"320597716":["모든 턴마다 특정 도구 하나를 강제해서 에이전트가 절대 잘못 고를 수 없게 하기"],"321538160":["모든 실패를 즉시 코디네이터에게 올리기. 판단에 필요한 컨텍스트는 코디네이터가 더 많이 갖고 있기 때문임."],"323526700":["엄격 스키마 모드를 켜기. 지어낸 값, 잘못된 카테고리, 형식이 깨진 날짜를 API 수준에서 거부해 주기 때문임."],"324014193":["스키마에서 모든 필드를 필수로 만들어서 모델이 값을 반드시 찾아내게 하기"],"324058226":["이미 실패하는 테스트가 붙어 있는 함수 하나에 검증 체크를 한 개 추가하기."],"325241449":["\"enum 값은 대소문자 구분 없이 비교하라: 반환된 값이 스키마 값과 대소문자만 다를 수 있음.\""],"326085811":["이 주장이 맞음. 검증 실패(validation failure)는 똑같은 호출이 똑같이 실패한다는 뜻이므로, 다시 시도가 의미 있으려면 그 전에 seat_count가 바뀌어야 함."],"327118615":["PM 말대로 하기. 최신 데이터가 이전 데이터를 대체하고, 깔끔한 숫자 하나가 있어야 의사결정자가 리포트를 바로 활용할 수 있기 때문임."],"327772758":["subagent가 웹 검색 실패를 코디네이터(coordinator)에게 보고할 때, 다음 중 안티패턴은 무엇인가?"],"329954596":["search_wiki가 페이지 전문 대신 일치하는 발췌문과 페이지 제목, 링크만 반환하도록 바꿔서, 가져온 내용이 세션 앞부분에서 이미 정리된 내용을 밀어내지 않게 하기"],"330083510":["에이전트의 allowedTools에서 Grep을 빼서 semantic_search만 검색 수단으로 남게 하기."],"331022844":["주 단위로 두 API를 번갈아 쓰면서 청구서를 비교하기."],"333796402":["허용되는 패턴만 예시로 주기. 그래야 모델이 빈 catch를 건너뛰도록 배움."],"339246631":["각 조회의 출력이 다음 조회의 입력으로 들어가니까 호출을 순차로 유지하기."],"339597382":["창이 닫힌(closed-window) 경우는 정책상의 결과일 뿐 시스템 실패가 아니니까, 빈 결과를 담은 성공 호출로 반환하기"],"340054751":["설계상 user 레벨 파일이 항상 프로젝트 파일을 덮어쓰므로, 팀 표준을 개발자 각자의 user 레벨로 옮기기."],"340198742":["세션을 resume하고 어떤 파일 4개가 바뀌었는지 명시적으로 알려줘서 그 파일들만 다시 읽게 하기. 그다음 갱신된 세션을 설계안마다 하나씩 두 갈래로 fork하기"],"340895786":["\"Be conservative and only report issues you are highly confident about.\" 즉 보수적으로 판단하고 아주 확신하는 이슈만 보고하라고 지시하기."],"342906941":["프롬프트 지시는 유지하되 temperature를 0으로 설정해서 출력이 결정적(deterministic)이게 하기"],"344356282":["문제는 Claude Code가 이전에 분석한 파일을 잠가 버려서, 밤새 들어온 변경이 애초에 반영될 수 없었다는 점임."],"345389610":["페이로드(payload) 형태는 유지하되 각 원인마다 자세한 설명 문장을 적어서, 재시도할지 말지는 에이전트가 그 문구를 보고 스스로 판단하게 하기."],"345509073":["규제 대상 고객사가 다음 두 분기 동안 이전 세대 Claude 모델에 고정된 온프레미스(on-prem) 게이트웨이를 운영하는데, 이 게이트웨이는 나가는 모든 요청에서 tools 필드를 제거함.","이 회사의 분류기(classifier)에는 결함이 정확히 하나 있는데, 응답의 약 7%가 \"Sure!","Here is the classification:\"로 시작한 다음 JSON이 오는 방식이라, 엄격한 파서(parser)가 깨짐.","이번 분기에는 모델이나 게이트웨이를 바꾸는 건 범위 밖임.","이들이 쓸 수 있는 가장 직접적인 해결책은 무엇인가?"],"346283315":["JSON schema로 structured outputs를 활성화해서 API가 응답을 제약하게 하기"],"346352449":["어시스턴트가 뭘 만들어내기 전에 형식에 대해 스스로 확인 질문을 하게 하는 것임."],"346727414":["모드는 작업을 시작하기 전에 정해야 하므로, 지금 세션을 버리고 plan mode로 새 세션을 열기"],"353949495":["2주 뒤에 다시 켜기. 개발자들이 나쁜 경험을 잊기에 충분한 시간이기 때문임."],"354466237":["자기 비평 단계. 에이전트가 자기 초안을 검토해서 놓친 걸 찾아냄."],"355299254":["import 규칙은 프로젝트 memory 파일에 넣기. 누가 물어볼 때만이 아니라 모든 세션에서 항상 유지돼야 하기 때문임."],"356279250":["세션이 진행될수록 응답이 짧아짐."],"356928392":["일반적인 버그 탐지력을 키우려고, 관련 없는 실제 버그 예시를 더 넣기."],"357613880":["고객지원 코디네이터(coordinator)는 들어오는 티켓마다 주문 이력, 결제, 배송 조회, 정책 조회라는 네 개의 subagent로 나눠 보내고, 돌아온 결과를 합침.","트래픽 분석 결과, 티켓의 61%는 단순히 \"내 주문이 어디 있나요\" 질문이고, 배송 조회만 있으면 되는 것이었음.","이런 티켓 하나에 38초, subagent 실행 4회가 걸리고, 매일 오후마다 대기열이 밀림.","가이드가 가리키는 재구성 방향은 무엇인가?"],"358576378":["너의 시스템 프롬프트(system prompt)는 에이전트한테 공감하고 전문적으로, 그리고 간결하게 답하라고 지시함.","QA가 답변 400건을 채점했는데, 23%가 답에 도달하기 전에 세 문단짜리 사과로 시작했고, 고객들은 길이에 대해 불만을 제기하고 있음.","QA 팀장은 문구를 다시 한번 더 강하게 다듬고 싶어 함.","실제로 수치를 움직이는 것은 무엇인가?"],"358658461":["루프를 25번 반복으로 제한하고, 그 한도에 도달하는 것을 리서치 실행이 끝나는 정상적인 방식으로 취급하기."],"358791200":["모델의 temperature가 너무 낮아서 똑같은 출력만 반복하는 것임."],"358830138":["같은 세션에 답하기 전 더 큰 thinking budget을 줘서 자체 점검(self-check)을 확장하기"],"359060961":["모델이 앞서 찾아낸 구체적인 클래스와 함수 대신 \"전형적인 패턴\"을 언급하기 시작함."],"360265536":["분석 에이전트에서 도구를 전부 없애고 모든 작업을 coordinator를 거쳐 처리하기"],"361692077":["짧은 한 문장으로 끝내기. 설명이 길면 요청마다 토큰을 낭비하기 때문임."],"362122123":["단계 목록은 그대로 두고, 빠졌던 경우를 41번 단계로 추가하기. 이번 실행에서 실제로 드러난 빈틈이 바로 그것임."],"362222625":["루트 CLAUDE.md 에 Terraform 규약, React 스타일 규칙, SQL 마이그레이션 정책, API 설계 표준까지 다 들어가서 1,100줄이 됐음.","React 컴포넌트 하나만 고치는 개발자한테도 그게 전부 로드되고, Claude가 가끔 Terraform용 조언을 React 코드에 적용함.","어떻게 재구성하는 것이 가장 좋은가?"],"362527759":["아무 시도도 하지 말고 바로 에스컬레이션하기. 고객이 사람을 명시적으로 요구했기 때문임."],"362938432":["보고서를 깔끔하게 유지하려고, 실패한 것은 언급하지 않고 확보된 출처 세 개만으로 종합하기."],"363834513":["항상 가운데에만 오는 섹션이 없도록 매 실행마다 섹션 순서를 무작위로 섞기"],"367347144":["쓰기 단계 주변에 retry-with-backoff를 추가해서 타임아웃난 배치가 성공할 때까지 재시도되게 하고, 마이그레이션을 다시 실행하기."],"368076653":["조회를 세 번 할 때마다 /compact를 실행해서 컨텍스트를 줄이기"],"369073155":["allowed-tools 하나면 충분함. 도구를 제한하면 출력도 격리되고 기본 인자까지 정할 수 있기 때문임."],"371131383":["저장소 전체를 먼저 컨텍스트에 읽어 들인 다음 수동으로 검색하기 → Read."],"371258280":["structured state object임. 턴이 아무리 쌓여도 context 크기에 상한을 두기 때문임."],"374809085":["추출 작업을 JSON 스키마를 가진 도구(tool)로 정의하기. 필요하면 엄격한 스키마 검증(strict schema validation)까지 붙이고, 구조화된 도구 입력(tool input)을 읽기. 그러면 그냥 요청만 하는 것이 아니라 객체 전체가 제약을 받게 됨."],"374992419":["추출 파이프라인이 전체 정확도 97%라고 보고했고, 팀은 신뢰도가 높은 항목에 대해서는 사람 검토를 빼고 싶어 함.","자동화하기 전에 반드시 무엇이 이뤄져야 하는가?"],"378763916":["세션 A에는 progressive summarization을 적용해서 6개월치 히스토리에서 아무것도 사라지지 않게 하기"],"380530403":["Glob으로 모든 파일을 나열한 다음, 하나씩 순서대로 요약하기"],"380630409":["문서 목록이 subagent의 컨텍스트 한도를 넘어서 조용히 버려진 것임."],"382841203":["각 분석가가 복사해 쓰는 user-scoped skill임. 다들 자기 archive 목록을 알아서 조정할 수 있게 하는 것임."],"382917997":["더 최근 출처를 기준으로 진행하고, 그렇게 골랐다는 것을 각주에 밝히기."],"387936162":["둘 다 도움이 안 됨. 스키마는 이미 있었으니까 남은 실패는 semantic한 문제일 수밖에 없고, 해결책은 더 강한 enforcement가 아니라 validation loop임."],"388466720":["리뷰 범위에서 테스트 디렉터리와 TODO가 들어간 파일을 빼고, 그다음 원래 프롬프트로 되돌리기."],"389687765":["기계가 읽을 수 있는 코드와 재시도 가능 여부를 담은 structured error를 반환하기. 그러면 에이전트가 다시 시도하는 것이 도움이 될지 추측하지 않아도 됨."],"390327174":["이런 부류의 버그는 사람 리뷰어만 찾아낼 수 있음. 수동 감사 일정을 잡기."],"391073739":["고정 파이프라인(pipeline)을 그대로 유지하기. dynamic decomposition(동적 분해)은 코드 관련 작업에만 적합하기 때문임."],"391629849":["메인 에이전트의 전체 대화를 각 subagent에 넘겨서, 진짜 원하는 게 뭔지 스스로 파악하게 하기."],"394305156":["CLI를 -p 옵션으로 호출하고, 코멘트 파서(comment parser)가 산문(prose) 형태 출력도 받아들이도록 수정하기"],"394493628":["할인이 고객한테 닿기 전에 바로잡아 주는 최종 출력 필터 안에서."],"394629580":["두 번째 불만.","반올림(rounding) 관련 요청이 checkout과 settlement에 걸쳐 파일 19개짜리 작업으로 불어났는데, 두 설계안 다 나름 타당해서 어느 쪽도 선택되지 않았기 때문임.","결제(payments) 담당자는 이제 파일이 하나라도 바뀌기 전에 선택된 접근 방식을 문서로 남기고 승인(sign off)받아야 한다고 요구함.","그 요건을 만족하는 실행 방식은 무엇인가?"],"397634492":["전부 파일로 로그를 남겼다가, 크래시 뒤에 로그 전체를 새 세션에 붙여넣기"],"397707635":["Grep과 Read 패턴은 그대로 두고, 대화가 길어질 때마다 /compact를 실행하기. 그러면 다음 sweep을 위한 여유 공간이 항상 남음."],"399499136":["시스템 프롬프트 규칙 하나. \"500달러가 넘는 환불은 항상 에스컬레이션할 것.\""],"399833097":["그 변형은 프로젝트의 .claude/commands/에 /review-strict로 추가해서 저장소와 함께 백업되게 하기"],"402121645":["새 API 엔드포인트를 스캐폴딩하는 팀 스킬을 만들고 있음. 템플릿으로 파일을 생성해야 하고(쓰기 작업 필요), 셸 명령은 절대 실행하면 안 되고, 개발자들이 자꾸 빠뜨리는 엔드포인트 이름을 반드시 받아야 함.","SKILL.md 프론트매터를 어떻게 설정하는 게 맞는가?"],"402147295":["(C). 파일 16개에 주의가 분산되면서 두 증상이 다 생기는 것임. 파일별로 나눠서 훑으면 깊이가 고르게 나오고, 통합 패스가 파일 간 일관성을 맡아줌."],"402239892":["지난 분기 코드 생성(code-generation) 저장소(repo)에서 사고가 두 건 있었음.","(1) 어떤 세션이 rebase를 정리하다가 공유 main 브랜치에 force push를 실행했음. contributor guide는 2023년부터 force push를 금지해 왔음.","(2) 생성된 마이그레이션(migration)이 짝이 되는 down-migration 없이 올라가는 경우가 다섯 번 중 한 번꼴로 있는데, project memory 파일은 그걸 요구하고 있는데도 그러함.","각 사고가 실제로 필요로 하는 걸 해결하는 변경 두 가지는 무엇인가? (두 개를 고르시오.)"],"402800132":["문서 파이프라인에 도구가 네 개 있음. extract_metadata, enrich_entities, classify_topic, store_result임.","제대로 보강(enrichment)하려면 메타데이터가 먼저 추출돼야 하는데, 실행의 9%에서 모델이 enrich_entities부터 시작해서 손상된 레코드를 만듦.","extract_metadata가 먼저 실행되도록 보장해 주는 구성은 무엇인가?"],"402892796":["생성된 코드를 리뷰할 때, 그 코드를 만든 세션보다 별도의 Claude 인스턴스가 더 나은 이유는 무엇인가?"],"404018403":["동작이 검증된 credential을 커밋되는 설정 파일에 그대로 넣어서, 모든 엔지니어가 작동이 확인된 값으로 연결하게 하기."],"405697055":["첫 응답에는 자연어 인사말이 아니라 get_customer 호출이 들어갈 것임."],"407499232":["쓰기 성격의 셸 명령(shell command)에 대한 거부 규칙(deny rule)을 저장소 설정 파일(settings file)에 커밋해서, 모든 모드에 적용되게 하기."],"407733727":["예시들을 없애고 문서화된 기준으로 돌아가기. 치우친 예시 집합은 아예 없는 것보다 더 해롭기 때문임."],"408971424":["src/api/v2/handlers/payment.test.ts"],"410908624":["여기서 하위 작업(subtask)은 처음부터 다 나열할 수 있는 게 아니라 진행하면서 발견되는 것들이라, 계획은 매장이 발견될 때마다 하위 작업이 늘어나는 살아있는 문서(living document)여야 함. 그리고 감사 추적(audit trail)은 목록을 고정해서가 아니라 각 수정 내용을 기록해서 보존하는 것임."],"412368071":["도구는 하나로 유지하되, 백엔드가 의도를 추론할 수 있게 사용자의 원래 요청을 그대로 덧붙이기"],"412498472":["둘 다 커뮤니티 서버를 쓰기. 승인 시스템용 서버쯤은 누군가 이미 만들어 놓았을 것임."],"412714633":["“글로벌 AI 규제” 주제로 돌린 실행을 검토함. 코디네이터가 이를 “EU AI Act 의무사항”, “EU AI Act 시행 일정”, “EU AI Act 벌칙”으로 나눔. 검색 에이전트와 분석 에이전트가 각각 거의 똑같은 EU 자료를 가져오는 바람에 토큰 지출이 3배가 되었고, 보고서는 미국과 중국, 국제 표준화 기구를 아예 다루지 않음.","가장 좋은 교정 방법은 무엇인가?"],"412960871":["(i)와 (ii)는 경로 범위 규칙 파일(path-scoped rule files)로 두고, (iii)과 (iv)는 둘 다 특정 폴더 하나에 묶여 있지 않으므로 루트 메모리 파일(root memory file)의 섹션으로 두기."],"414099218":["모니터링을 붙여서 승인하기. 배치를 한 시간마다 폴링하고, 새벽 6시에도 아직 돌고 있으면 팀에 알리기."],"414201777":["/migration 스킬 하나가 SQL 마이그레이션 파일 생성과 DB 적용을 둘 다 하고, 도구 권한도 넓게 열려 있음.","초안만 원했는데 마이그레이션을 실제로 적용해버린 일이 두 번 있었음.","argument-hint로 \"create|apply\"를 물어보긴 하는데 사용자들이 그냥 건너뜀.","확실한 해결책은 무엇인가?"],"414540905":["subagent 4개 전부에 완전히 똑같은 prompt를 줘서 결과가 서로 비교 가능하게 하기."],"414674964":["서브태스크(subtask) 목록 전체를 미리 작성해서 고정하기. 그러면 리드가 안정된 범위를 승인할 수 있고 진행 상황도 측정 가능하게 유지됨."],"417126874":["트레이딩 데스크 컴플라이언스 에이전트(compliance agent)는 거래일마다 하나의 연속 세션(session)을 돌림.","언제든 고객 ID(client ID), 상품(instrument), 명목금액(notional), 한도위반 플래그(limit-breach flags), 승인자(approver), 타임스탬프(timestamps)까지 9개 필드의 정확한 값을 보고해야 하는데, 이 값들은 전부 하루가 시작되기 전에 이미 고정되어 알려져 있음.","세션은 300턴 넘게 이어지고, 토큰(token) 사용량은 이미 예산 한도에 도달해 있음.","지금 팀은 매시간 가장 오래된 200턴을 요약하고 있는데, 지난주 보고서에서는 실제 장부상 수치가 4,182,500이었는데도 명목금액(notional)을 \"대략 400만\"이라고 적었음.","어떤 컨텍스트(context) 전략이 맞는가?"],"420933895":["프로젝트 폴더 안에 있으므로 .claude/settings.local.json."],"421007015":["Bash에서 sed를 써서 파일 전체의 패턴을 치환하기"],"422858323":["모든 문서에 도구 3개를 전부 돌리고, 검증을 통과하는 출력만 남기기"],"424163262":["planning은 절대 해가 되지 않고 의도(intent)의 기록도 남기니까, 셋 다 먼저 planning 단계를 거치기."],"424319150":["실패하면 빈 페이지 목록을 반환해서 추출 경로를 일정하게 유지하고 레코드는 그냥 null 값으로 돌아오게 하기."],"425364430":["repository 서버를 먼저 만들기. 파일 접근을 표준화하면 에이전트가 임의의(arbitrary) 셸 명령을 실행할 위험이 줄어들기 때문임."],"425705777":["6시간짜리 멀티 에이전트(multi-agent) 리서치 실행에는 리서치 리드가 정한 절대 타협 불가 규칙이 하나 있는데, 최종 보고서의 모든 주장은 첫 시간에 읽은 문장까지 포함해서 그 주장을 만들어낸 정확한 문장과 출처 URL로 추적할 수 있어야 함.","그 규칙과 가장 맞지 않는(LEAST compatible) 컨텍스트 전략은 어느 것인가?"],"426695967":["트리 전체에 stream edit을 돌려서 모든 사례를 다 바꾼 다음, fixture 파일 세 개는 손으로 되돌리기."],"428524149":["월요일 작업 큐는 다음과 같음. (a) 스택 트레이스가 payment.ts의 한 줄을 정확히 가리키는 널 포인터 크래시 고치기. (b) 60개 넘는 파일에서 쓰는 ORM 라이브러리 마이그레이션. (c) 인프라 비용이 서로 다른 세 가지 방식으로 만들 만한 기능 추가하기.","모드 배정으로 맞는 것은 어떤 것인가?"],"431408694":["그 3%는 버리기. 배치 작업이면 97% 완료율로도 받아들일 만함."],"431898206":["선택적 보존(selective retention)을 쓰기: 통화 금액이 들어있는 턴은 전부 그대로 남기고 나머지는 버리기"],"435526870":["해당 expense에 대해 검증 결과가 기록되어 있지 않으면 submit_report를 막는 PreToolUse hook을 추가하기"],"441604341":["signing_date는 enum에 \"unknown\"을 추가하고, jurisdiction은 nullable로."],"441769535":["선행 조건 게이트(prerequisite gate)가 작동하긴 하지만 너무 곧이곧대로임. 게이트가 걸린 호출마다 바로 직전에 get_customer 확인을 새로 요구해서, 계정 작업이 세 번 있는 대화에서는 같은 고객을 세 번이나 확인하게 됨.","불만이 늘자 한 엔지니어가 \"게이트가 실제 대화에 맞지 않는 게 분명하니\" 프롬프트 기반 순서 지정으로 되돌리자고 제안함. 올바른 대응은 무엇인가?"],"441934283":["end_turn이 아닌 stop_reason은 전부 재시도 가능한 에러로 보고, 똑같은 요청을 그대로 다시 보내기."],"441943427":["추출기가 문서당 신뢰도 점수(confidence score)를 하나씩만 내놓고, 평균 0.93 이상인 문서는 자동 승인됨.","재무팀이 방금 찾아냈는데, 자동 승인된 인보이스의 18%에서 tax_registration_number가 틀렸음. 나머지 아홉 개 필드는 거의 완벽해서 문서 평균은 높게 유지됐고, 그러는 사이 가장 약한 필드가 검토도 없이 그냥 통과함.","어떻게 다시 설계하는 것이 맞는가?"],"442997066":["요약(summarization) 과정에서 아무것도 유실되지 않고 엔지니어가 추론 과정(reasoning)을 전부 읽을 수 있도록, 전체 review transcript를 ticket에 첨부하기"],"444646420":["tool_choice: \"auto\"는 도구를 쓸지 말지 모델이 정하는 방식임."],"445257642":["숫자 토큰이 비용이 더 커서, 요약이 예산을 아끼려고 그것을 빼 버리기 때문임."],"445375772":["지금까지 찾은 내용을 에이전트가 다시 읽을 수 있는 파일에 적어두고, 남은 질문은 각각 검색을 수행하고 결론만 돌려주는 subagent한테 보내기."],"446590878":["팀 채팅에 고정해 둔 메시지를 각자 수동으로 적용하기."],"447268284":["API 문서 전체를 그대로 붙여 넣어서 어떤 세부사항도 빠지지 않게 하기."],"448293655":["synthesis agent에게 발행일은 항상 명시하고 서로 다른 출처의 수치는 절대 합치지 말라고 지시하기."],"449282087":["배치 요청은 24시간으로 제한되어 있어서 반복적인 파일 분석에는 너무 짧음."],"450366007":["추출된 이름 중에 레터헤드에도 같이 나오는 것은 걸러내기"],"451580608":["나중에 나온 amendment를 원래 읽었던 소스로 착각하지 않도록, extraction이 실행된 문서의 version과 revision identifier를 저장하는 방법임."],"452059768":["경로 필터(path filter) 없는 룰 파일(rule file)로 커밋해서 그 저장소의 모든 세션에서 컨텍스트(context)에 들어가게 하기"],"452140118":["브레인스토밍 skill이 길고 탐색적인 출력을 쏟아내서 메인 대화를 어지럽히고 있음.","이를 격리해 주는 frontmatter 옵션은 무엇인가?"],"452466474":["어제 세션이 checkout 모듈을 분석하다가 중간에 API 에러로 죽었음. 파일 60개까지는 끝난 상태임.","밤사이에 팀원이 그 파일 중 3개에 변경 사항을 머지했음.","오늘 아침에는 토큰을 최소한만 써서 이어가야 함.","어떻게 해야 하는가?"],"453597072":["네 에스컬레이션 설정은 자동 트리거 세 개를 씀. sentiment_score < -0.5, self_confidence < 0.6, turn_count > 8임.","운영 데이터를 보면 다음과 같음. 클릭 한 번이면 끝날 문제인데 몹시 화가 난 고객은 사람에게 넘어가서 상담팀을 성가시게 하고, 차분하지만 정책에 아예 언급도 없는 걸 요청한 고객은 지어낸 조건으로 자신 있게 자동 \"해결\" 처리되고, 그냥 질문이 많은 꼼꼼한 고객은 턴 수 제한에 걸림.","올바른 재설계는 무엇인가?"],"453660911":["첫 번째 불만에 집중할 것.","야간 처리 경로(nightly path)는 사람 검토 없이 finance database에 바로 기록하는데, 문서 몇백 건 중 한 번 꼴로 JSON 주변에 엉뚱한 문장이 끼어들어서 loader가 그 행 전체를 거부함.","팀은 이 야간 처리 경로가 출력 형식을 어떻게 강제할지 고민 중임.","이 경로에 맞는 선택지는 무엇인가?"],"454672738":["그날 머지된 변경을 검토하고 아침에 보고서를 올려 주는 야간 감사 작업."],"456865093":["모델이 값을 지어내거나 억지로 끼워 맞추는 것을 막아 주는 스키마 설계 두 가지는 무엇인가? (2개 고르기)"],"456913557":["프레임워크는 유지하되 임계값을 조정하기. 한 달치 프로덕션 데이터를 근거로 감성 점수 < -0.7, 신뢰도 < 0.4, 턴 수 > 12로 맞추는 것임."],"459422008":["네 내부 MCP server가 tool을 하나 제공하는데 이름은 codebase_query고, 설명은 \"Query the codebase.\"라고만 돼 있음. 자유 텍스트로 된 질문 인자(argument)에 따라 심볼 조회, 의존성 질문, 소유권 질문에 답을 줌.","Claude Code가 이 tool을 계속 쓰는데 쓸 만한 답이 나오는 건 절반 정도고, 나머지 절반은 tool이 답할 수 없는 걸 물어봐서 Grep으로 다시 넘어감.","제대로 된 해결책은 무엇인가?"],"460796578":["루프 진행 여부를 응답의 stop reason으로 판정하기: tool_use면 계속 돌리고, end_turn이면 멈추기."],"461066387":["처음부터 끝까지 편집 불가능한 계획 모드(planning mode)를 유지해서 모든 단계가 검토 가능하게 하고, 결제팀이 마지막에 누적된 계획을 승인하게 하기."],"461485180":["의존성 감사(dependency-audit) skill을 만드는 중임. (a) 스캔 출력이 엄청 장황해서 메인 대화를 오염시키면 안 되고, (b) 파일을 절대 수정하거나 삭제하면 안 되는 읽기 전용 분석이고, (c) 대상 디렉터리를 반드시 받아야 하는데 개발자들이 자꾸 그것을 빼먹음.","frontmatter를 어떻게 설정하는 것이 맞는가?"],"462655038":["handoff를 input schema에서 amount 필드가 null을 가질 수 있게 하고 required 목록에서는 빼는 tool로 정의하면, \"금액이 논의되지 않았다\"는 상태에도 모델이 실제로 반환할 수 있는 값이 생김."],"462979835":["독립된 인스턴스는 기본 temperature가 더 높아서 더 비판적으로 굴기 때문임."],"464352658":["subagent의 보고 방식을 바꿔서, 접근 실패는 실패 유형과 재시도에 필요한 정보를 함께 담아 정상적인 빈 결과와 구분하기. 그래야 코디네이터가 장애는 재시도하고, 진짜로 비어 있는 결과는 그대로 받아들일 수 있음."],"465009021":["게이트는 지금 그대로 두고, 반복되는 확인 절차에 대한 사과 템플릿만 추가하기."],"466827369":["push 명령에 대한 거부 규칙(deny rule)을 추가하고 턴 한도(turn limit)를 올려서 리뷰가 더 깊이 들어가게 한 다음, 어떤 문장을 발견 사항(finding)으로 칠지 더 엄격하게 대시보드의 패턴을 다시 쓰기"],"469276398":["도구 쪽에서 에러를 제대로 분류하기. 검증 에러(입력이 잘못된 경우)는 isRetryable: false로 돌려주면서 입력을 고치라고 안내하는 설명을 같이 주고, 일시적 에러는 isRetryable: true로 남기기. 같은 플래그 하나로 두 경우를 다 감당할 수는 없음."],"469656672":["입력의 맨 앞에 두고, 중요한 항목은 끝에서 한 번 더 반복하며, 전체에 걸쳐 명시적인 섹션 헤더를 붙이기. 모델이 긴 입력의 앞과 끝은 안정적으로 처리하지만 중간은 흘리는 경향이 있기 때문임."],"470797804":["시나리오: 매일 밤 실행되는 보안 검토(security-review) 시스템이 coordinator(코디네이터) 하나와 서브에이전트(subagent) 세 개(dependency_scan, secrets_scan, config_scan)를 돌려서 보안 채널에 통합 보고서 하나를 올림.<br>상황: 각 서브에이전트가 자기 섹션을 작성하고 coordinator가 그것들을 이어 붙임.<br>증상: 지난 목요일 secrets_scan의 provider(제공자)가 레이트 리밋(rate limit)에 걸렸고, 그 서브에이전트는 \"no secrets found\"라고 적힌 빈 섹션을 반환함. 보고서는 정상(green)으로 나감.","이틀 뒤 저장소(repository)에서 실제로 살아있는 크리덴셜(credential)이 발견됨.","6주치 보고서를 다시 살펴보니 서브에이전트의 provider에 연결할 수 없었는데도 보고서가 그대로 정상(green)으로 나간 밤이 네 번 더 있었음.<br>제약: 보고서는 매일 밤 반드시 나가야 함. 보안 팀은 보고서 누락을 통제 실패(failed control)로 간주함.<br>질문: 재발을 막는 데 가장 효과가 없는(LEAST effective) 변경은 어느 것인가?"],"471361836":["Bash. 디렉터리 트리부터 나열하기"],"472523068":["plugin과 subagent는 자동으로 탐색되지 않으므로, 이미지 간의 오래된 plugin 차이가 사라짐."],"473404874":["에이전트가 스스로 보고하는 해결 확신도(resolution confidence)가 0.9를 넘으면 티켓이 자동으로 닫히는데, 이게 전체 물량의 71%이고, 이 케이스들의 평균 CSAT는 5점 만점에 4.6임.","운영 리드(ops lead)는 다음 달에 기준을 0.75로 낮추고 싶어 함.","지난달 샘플 점검(spot check) 결과, 스페인어 티켓(전체 물량의 9%) 중에서 0.9 이상으로 닫힌 케이스가 19%는 틀렸던 것으로 나타남.","먼저 와야 하는 단계 두 가지는 무엇인가? (두 개 선택)"],"473821186":["push 명령에 대한 거부 규칙(deny rule)을 추가하고, 리뷰가 더 깊이 들어가도록 턴 제한(turn limit)을 늘리고, 어떤 문장을 발견 사항(finding)으로 칠지 대시보드 패턴을 더 엄격하게 다시 쓰기"],"473951024":["프롬프트에서 모델에게 자기 신뢰도를 더 솔직하게 밝히라고 요청하기"],"475272175":["파일 2,300개짜리 저장소에 네 가지가 자리 잡을 곳이 필요함. (i) 마이그레이션 컨벤션(마이그레이션 파일은 .sql로 끝나고 서로 다른 디렉터리 6곳에 흩어져 있음), (ii) billing/ 안의 무엇이든 편집할 때 적용되는 PCI 체크리스트(billing/은 파일 90개짜리 폴더 하나임), (iii) 아직 존재하지 않고 다음 스프린트에 수작업으로 만들어질 feature-flag 파일의 네이밍 컨벤션, (iv) vendored/ 트리는 절대 편집하지 않는다는 강제 요구사항(지난달 두 번이나 덮어써진 뒤로 생긴 규칙임).","어떤 매핑이 맞는가?"],"475668369":["어시스턴트가 shared-helper 버전을 곧바로 구현하게 하고, 그 접근 방식은 pull request 본문에 설명하기. 결제 담당자(payments owner)는 코드 리뷰(code review) 중에 승인함."],"476614232":["체크리스트는 고정해두고, 체크에서 실패하는 티켓은 전부 사람이 처리하는 큐(queue)로 보내기"],"476796229":["예약 에이전트(booking agent)의 결제 도구가 {\"isError\": true, \"errorCategory\": \"validation\", \"isRetryable\": false, \"message\": \"seat_count must be a positive integer; received 0\"}를 반환함.","에이전트의 다음 행동은 같은 도구를 동일한 인자로 여섯 번 더 호출하는 것이었음.","그 도구 결과(tool result)는 실제로 에이전트에게 무엇을 하라고 말해주는가?"],"476937289":["코디네이터(coordinator)가 선언된 데이터 공백(data gap)을 일반 빈 섹션이 아니라 리포트 헤더에 반드시 나타나야 하는 차단 조건(blocking condition)으로 다루게 하기."],"479582005":["리뷰 카테고리는 두 개인데 프롬프트는 하나임.","Security 카테고리는 SQL 문에 들어가는 문자열 연결(string concatenation)을 절대 놓쳐서는 안 되고, 팀은 이 카테고리에서는 노이즈를 명확히 감수하겠다고 함.","반면 Style 항목은 열에 아홉은 기각되고, 개발자들은 거의 확실한 경우가 아니면 아예 나오지 않길 원함.","프롬프트는 지금 \"보수적으로 판단하고, 확신하는 이슈만 보고할 것\"이라는 전역 한 줄로 끝남. 이걸 무엇으로 바꿔야 하는가?"],"481451658":["1,100줄 전부를 path-scoped rule 파일들로 옮기면, 패턴에 맞는 파일을 편집할 때가 아니면 아예 아무것도 로드되지 않음."],"481525884":["그 구간이 나아질 때까지 스캔한 영수증만 리뷰하고 나머지는 무시하기"],"481863587":["이 실패 유형(failure class)에서 재시도가 애초에 의미가 있는지 판단하기 전에, 도구 결과(tool result)의 retryable 플래그부터 확인하기"],"481887808":["analyze_document를 설명은 똑같고 이름만 다른 사본 세 개로 만들기."],"482186816":["네 자동 리뷰 봇(review bot)이 모든 pull request에 코멘트를 남김.","오탐(false positive)이 40%에 달하고, 개발자들은 이제 코멘트를 아예 무시하기 시작했음.","팀 제약 조건: 사람이 확인하기 전까지는 발견 사항(finding)을 절대 숨기면 안 됨.","올바른 변경 사항은 무엇인가?"],"483150632":["개인 취향은 팀원한테 하는 주석으로 감싸 두기. \"Kim이 아니면 무시할 것\" 같은 식으로"],"483188518":["추출(extraction) 과정은 문서 id에 대한 페이지 이미지를 가져오는 내부 MCP server를 호출함.","가져오기(fetch)가 실패하면 서버는 \"문서를 가져올 수 없음\"이라는 문자열을 반환함. 실패했을 때 에이전트의 동작은 제각각임: 어떨 땐 열한 번이나 재시도하고, 어떨 땐 필드 값을 지어내고, 어떨 땐 로더(loader)가 아무렇지 않게 받아들이는 빈 레코드를 만듦.","서버의 에러 응답(error response)을 어떻게 두 가지로 바꾸면 이 문제가 해결되는가? (두 개를 선택하시오.)"],"484143343":["환불 에이전트에 규칙이 두 개 있음. (1) lookup_order가 돌려주는 데이터에 Unix epoch와 ISO 8601 타임스탬프가 섞여 있어서, 모델이 환불 기한을 따지기 전에 형식을 통일해야 함. (2) 1,000달러가 넘는 환불은 절대 자동으로 실행되면 안 됨.","어떤 엔지니어가 두 규칙을 PostToolUse 훅 하나에 몰아서 구현하자고 제안함.","올바른 판단은 무엇인가?"],"485557396":["네 리포트 생성 에이전트는 컨텍스트 예산이 빠듯한데, 상위 subagent들이 findings와 함께 추론 과정 전체까지 통째로 돌려줌. \"X를 검색했고, Y를 고려했고, 그다음...\" 같은 것이 수천 토큰임.","그 탓에 뒤늦게 도착한 findings가 리포트에서 빠지고 있음.","구조적인 해결책은 무엇인가?"],"486301790":["에이전트가 적절한 복구 전략을 고를 수 없음. 재시도할 수 있는 실패인지, 정책 위반인지, 잘못된 입력인지 구분하지 못하기 때문임."],"488793881":["--json을 --strict와 같이 쓰기"],"490769990":["단일 패스는 그대로 두되 세 번 돌리고 그중 최소 두 번에 나온 지적만 올리기."],"490844292":["system prompt에 \"어떤 서두(preamble)도 넣지 말 것\"을 추가하고, 파싱에 실패하는 응답은 재시도하기"],"491685483":["enum은 버리고 자유 텍스트(free text)를 받기. 그 분류 체계(taxonomy)가 일주일 새 두 번이나 불완전하다는 게 드러났기 때문임."],"491782640":["extractor한테 필요한 것은 다 delegating prompt(위임 프롬프트)에 넣기. schema, 그 문서 종류의 특이한 점, 그리고 문서 자체까지. subagent는 coordinator의 history(이력)를 하나도 없이 시작하기 때문임."],"492791835":["각 스캔 subagent의 프롬프트는 그 자체로 완결되게 쓰기(조사 질문, 배정된 관할 구역(jurisdiction), 범위에 드는 출처 유형, 기대하는 출력 형태까지 포함). 어느 subagent도 코디네이터(coordinator)의 히스토리를 볼 수 없기 때문임."],"493110912":["엔지니어 14명 중 9명이 최근 두 분기 안에 합류했고, 계약직 두 명은 매달 교체됨.","새 모듈 네이밍 규칙(module-naming convention)은 개인별 설정 없이 현재와 미래의 모든 기여자에게 전달돼야 함.","아래 보기 중 하나만 빼고 전부 그것을 달성할 수 있음.","어느 것이 예외인가?"],"493127209":["첫 요청에서는 tool_choice: {\"type\": \"tool\", \"name\": \"extract_metadata\"}로 그 도구를 강제하고 이후 단계는 다음 턴들에서 처리하기."],"495066602":["(a)를 넣고 (b)에서는 더 최근 값을 넣기. (c)는 보고서가 깔끔하게 읽히도록 빼기"],"496397860":["모듈을 바꾸기 전에 Explore subagent를 먼저 돌려서 그 모듈의 의존성을 파악하기."],"498243733":["후속 질문은 가장 최근 대화를 이어서 하고, 그다음 두 개의 remediation 경로를 위해 두 번 더 이어가기. 그러면 이어간 대화 하나하나가 자연스럽게 별도의 스레드(thread)가 됨."],"498393382":["고정 파이프라인(fixed pipeline)을 유지하기. 단계 목록과 그 분기(branch)는 실행 전에 이미 다 알려져 있으므로, 중간 탐색(intermediate discovery)으로 결정되는 것은 아무것도 없음. 동적 분해(dynamic decomposition)는 능력은 더해주지 않으면서 비결정성(nondeterminism)만 더할 뿐이고, 진짜 예외 상황은 에스컬레이션 경로(escalation path)에서 다뤄야 함."],"498480457":["배송 문서 추출기(extractor)에 대한 스키마 리뷰임.","필드 세 개를 두고 의견이 갈림. container_number는 파이프라인이 받아들이는 모든 문서에 나타남. broker_reference는 그중 3분의 1 정도에만 나타나는데, 없을 때는 다운스트림 시스템이 '문서를 확인했지만 값이 없었다'는 걸 기록해야 함. insurance_certificate_id는 특정 플랜의 고객에 대해서만 팀이 수집하는 필드인데, 범위 밖일 때는 레코드에 그 키 자체가 아예 없어야 함.","이 세 필드는 어떻게 선언해야 하는가?"],"500278236":["일시적 실패, 검증 실패, 권한 실패를 구분해 주는 errorCategory."],"502952181":["잘못된 것은 없음. 두 스토어(store)는 범위 밖(out of scope)으로 기록하고 후속 작업(follow-up engagement)에서 처리하면 됨."],"503144982":["응답의 max_tokens를 올려서 지적 사항이 더 온전히 서술되게 하기"],"503478853":["스킬(skill)의 프론트매터(frontmatter)에 호출 가능한 도구를 선언해서 파괴적인 호출 자체가 아예 불가능하게 하기"],"505000095":["세션의 검증 상태가 설정되어 있지 않으면 process_refund를 막아주는 PreToolUse hook."],"505681153":["(i) 고정 순차 파이프라인(fixed sequential pipeline), (ii) 동적 분해(dynamic decomposition)."],"507453319":["\"프리필(prefill)된 마지막 assistant 턴을 여전히 담고 있는 요청은, 프리필을 조용히 무시하는 대신 400 에러로 실패함.\""],"508085535":["일이 안 끝나는 건 반복 상한 때문이고, 호출이 반복되는 건 API 레이트 리밋 때문임. 반복 사이에 지수 백오프를 넣기."],"509396784":["\"타임존 동작을 보존\"이 정확히 뭘 뜻하는지 보여 주는 구체적인 입출력 테스트 케이스를 2~3개 제시하기. 서머타임(DST) 경계 엣지 케이스도 반드시 포함해서."],"509472875":["A의 경우, 트리 전체에서 이름 패턴(name pattern)으로 파일을 매칭하기."],"513024148":["가져오기 기능을 아예 없애고 문서를 프롬프트에 직접 붙여넣기"],"514669426":["파트너는 리서치 보고서가 클라이언트에게 나가기 전, 보고서마다 담긴 약 200개 findings 중 8개를 직접 읽음.","지금 그 8개는 synthesis agent가 \"most important\"라고 라벨을 붙인 것들임. 지난 분기에는 클라이언트에게까지 노출된 오류가 두 건 있었는데, 하나는 search agent 스스로 불확실하다고 표시했던 출처에서 나온 수치였고, 다른 하나는 블로그 글 하나에만 근거한 주장인데도 단정적으로 제시돼 있었음.","그 8개 슬롯은 어떻게 써야 하는가?"],"514983965":["규칙 하나. “이 프로젝트에서는 비어 있는 catch 블록을 절대 지적하지 말 것.”"],"516915980":["섹션 헤더만 분명하면 위치는 상관없음. 구조가 배치를 대신해 주기 때문임."],"517877668":["support-agent 저장소에 올라오는 모든 pull request가 녹화된 고객 대화 40개를 재생하고, 회귀가 있으면 전부 PR 코멘트로 남기길 원함.","주니어 엔지니어가 처음 만든 workflow는 runner를 30분 동안 멈춰 있게 하다가 결국 job이 timeout됨.","runner 로그의 마지막 줄은 에이전트의 첫 인사말임.","무슨 일이 일어난 것이고, 어떻게 고쳐야 하는가?"],"517978940":["같은 문장이 두 위치 모두에 있을 때 각각 올바른 판정과, 위치가 결정 요인이 되는 이유까지 보여주는 짝 예시(paired example)를 추가하기"],"518813857":["지금 코디네이터(coordinator)가 검색 subagent에게 주는 프롬프트는 대본처럼 읽힘. \"먼저 X를 질의하고, 그다음 Y를 질의하고, 결과가 5개 미만이면 Z를 질의할 것...\" 같은 식임. 처음 보는 주제에서는 그 대본이 명백히 안 맞는데도 에이전트가 그대로 따라감.","그럼 코디네이터 프롬프트는 어떻게 설계하는 게 맞는가?"],"519171969":["hook을 용도에 맞게 고를 것. (1) 금액이 500달러를 넘으면 언제든 process_refund를 차단하고, (2) 모델이 결과를 두고 추론하기 전에 세 백엔드의 제각각인 날짜 형식을 정규화할 것."],"519945137":["파생값(derived value)마다 그 파생에 어떤 입력이 쓰였는지 저장해두는 방식임. 그래야 합산해서 나온 합계와 페이지에 그냥 인쇄된 합계를 구별할 수 있음."],"521181302":["CI 리뷰어에게 프로젝트 맥락을 주려고, 리뷰 기준·테스트 표준·fixture 문서를 어디에 둬야 대화형 세션과 -p 파이프라인 실행이 둘 다 일관되게 읽어 가는지 팀에서 논의 중임.","어디에 두는 것이 맞는가?"],"522290663":["스택 트레이스가 이미 문제 줄을 정확히 짚어 준, 한 줄짜리 가드 절 수정."],"522405711":["context: fork. skill이 격리된 sub-agent 컨텍스트에서 돌아가는 설정임."],"522507394":["두 값을 평균 낸 26%를 써서, 종합 단계가 다룰 숫자를 하나로 만들기."],"524675905":["vat_status는 standard, reduced, zero_rated로 구성된 enum임.","같은 주에 두 가지 문제가 나타나는데, 국내 공급업체에서 온 인보이스 묶음은 VAT를 아예 언급하지 않고, 자선단체 고객에게서 온 묶음은 실제로 VAT 면제 대상임.","둘 다 지금은 standard로 처리되고 있음.","재무팀 말로는 이 둘이 서로 다른 후속 처리로 이어져야 함. 하나는 데이터 품질 후속조치이고, 다른 하나는 정당한 회계 처리임.","옳은 스키마 변경은 무엇인가?"],"526782011":["탐색 호출을 한 번에 전부 실행하는 explore_everything 도구를 하나 더 만들기"],"526900153":["고객 한 명이 한 세션에서 미해결 이슈 세 건을 갖고 있음. 주문 #A-1042 환불(89달러), #A-1077 교환, #A-1103 청구 분쟁(312달러)임.","20턴쯤 지나서 에이전트가 \"주문 #A-1042 건 312달러 환불\"이라고 안내함. 3번 이슈의 금액을 1번 이슈의 주문에 갖다 붙인 것임.","케이스 사실(case-facts) 블록이 있지만, 언급된 숫자를 전부 한 줄로 늘어놓은 평면 목록임.","올바른 해결책은 무엇인가?"],"527167490":["배치를 4시간마다 제출하고, custom_id로 실패 건을 찾아내서 문제를 고친 뒤(예: 너무 큰 문서는 쪼개기) 바로 재제출하기. 6시간의 여유는 제출이 잦을 때만 재제출 한 사이클을 감당할 수 있기 때문임."],"527565533":["베스트 프랙티스 기준으로 정당한 에스컬레이션 조건이 되는 상황은 무엇인가?"],"528062678":["기대하는 출력 형식을 정확히 보여 주는 구체적인 예시를 2~3개 주기."],"529892189":["자동 추출에서 tax_registration_number를 빼고, 그 필드는 재무팀이 직접 입력하게 하기."],"531743037":["필수 필드에 환각 값이 들어가는 것을 막아 주기 때문임."],"535051555":["\"provision a new tenant\" 워크플로(workflow)는 한 달에 두 번 정도 실행됨.","이 워크플로는 개발자들이 작업 대화에 원치 않는 수천 줄짜리 인벤토리(inventory)를 출력하고, 새 tenant 디렉터리 밖은 절대 건드리면 안 되는데도 6월 실행에서 이웃 tenant 소유의 설정(config) 파일을 지워버린 적이 있음.","그 두 문제를 발생 지점에서 해결하는 변경 두 가지는 무엇인가? (두 개 선택)"],"535593223":["subagent와 다를 게 없음. coordinator도 모든 청구 목록을 고객 본인의 계정 요약과 대조해서, 안 맞으면 escalate(상급 처리로 넘김)해야 함."],"535712403":["대화형 호출(interactive invocation)은 그대로 두되 CI 작업의 wall-clock 타임아웃을 늘려서 밤새 멈춰 있는 상황은 결국엔 강제 종료되게 하고, 리뷰 프롬프트(prompt)에는 어시스턴트가 파일을 절대 쓰면 안 되고 반드시 JSON으로만 답해야 한다는 줄을 추가하기"],"536352290":["모델이 항상 올바른 추출 도구를 고르도록 보장함."],"537397755":["그건 항상 로드되는 instruction 파일에 그대로 두되, 맨 끝으로 옮기고 그 위에 지금 하는 작업이 결제(payments) 관련이 아니면 이 섹션은 건너뛰라고 알려주는 heading을 달기"],"538979968":["고정 반복 상한에 도달하면 멈추기. 단, stop_reason과 함께 쓰는 보조 안전장치로만 사용하기"],"539110918":["이전 리뷰의 findings를 실행에 넘기고, 새로 생겼거나 아직 해결 안 된 이슈만 보고하라고 지시하기."],"539524516":["파이프라인의 coordinator는 의존성 감사(dependency audit), 커버리지 점검(coverage pass), 라이선스 스캔(license scan)을 위임함.","지난 목요일 라이선스 스캐너의 데이터 소스가 다운됐고, 그 서브에이전트는 \"unable to complete license scan\"이라고 반환했음. coordinator의 보고서는 \"No issues found - 3 checks passed\"로 나갔고, 허용되지 않는 라이선스를 가진 패키지가 그대로 배포됐음.","다음 중 올바른 해결책에 속하지 않는 것은 무엇인가?"],"540379861":["조사와 설계 단계는 plan mode로 하고, 계획한 방식을 구현할 때는 직접 실행으로 전환하기"],"541403836":["감정 분석 점수가 불만 임계값을 넘을 때."],"542503705":["단순한 질의는 코디네이터를 아예 건너뛰고, 이미 간결하고 잘 다듬어진 답을 잘 만드는 종합(synthesis) 에이전트로 바로 보내기"],"543295219":["\"고객 메시지의 모든 부분에 빠짐없이 답할 것\"이라는 지시를 시스템 프롬프트에 추가하기."],"544708043":["네 CI 리뷰 단계는 사람이 붙지 않은 채로 돌아가야 하고, 기계가 파싱할 수 있는 출력을 내야 함.","실제로 되는 명령은 무엇인가?"],"544714659":["리뷰 봇에 대한 개발자 신뢰가 완전히 사라졌음. \"코드 중복\" 카테고리의 오탐률이 85%나 되고(관용적인 테스트 셋업까지 중복으로 잡음), 이제는 정확한 보안 지적까지 무시당함.","올바른 회복 순서는 무엇인가?"],"545357778":["사람 리뷰를 자동화로 걷어내기 전에, 집계 정확도 97%라는 수치가 왜 오해를 부를 수 있는가?"],"548568620":["그냥 그대로 재개해서 설계 비교를 시작하기. 모델이 바뀐 파일을 건드릴 때 알아서 알아챌 것이기 때문임."],"549426000":["이 사람은 자기만의 variant(변형)를 다른 이름으로 자기 user-scoped skills 디렉터리에 두고, 다른 모두를 위한 공유 skill은 그대로 건드리지 않음."],"551261729":["리뷰 단계는 다른 팀들도 같이 쓰는 공유 빌드 호스트에서 돌아감.","이번 스프린트 증상은 두 가지임. 실행 두 건이 승인 요청 상태로 멈춰 있다가 60분짜리 job timeout에 걸려 종료됐고, 실행 한 건은 아무도 요청하지 않은 브랜치를 만들었음.","보안팀은 이 정도 규모의 호스트에서는 검사를 건너뛰는 모드를 허용할 수 없다고 함.","어떤 설정이 맞는가?"],"551472360":["리뷰 봇은 pull request마다 style 지적을 40개 정도 남김.","개발자들은 두 달 전부터 그것을 읽지 않게 됐고, 지난주에는 목록 속에 묻힌 채 읽히지도 않았지만, 거기엔 정확히 찾아낸 진짜 SQL injection이 있었음.","프롬프트는 \"꼼꼼히 리뷰하고 이상해 보이는 건 뭐든 보고해\"라고 되어 있음. 한 동료는 \"적어도 80% 확신하는 것만 보고해\"를 제안함. 실제로 효과가 있는 것은 무엇인가?"],"553804950":["재시작할 때, 코드베이스가 이제 익숙해졌으니 더 빠르게 진행하라는 지시와 함께 모든 subagent를 다시 생성하기"],"554443351":["한 줄짜리 수정을 바로 적용하기"],"554675099":["claude \"Review this diff for security issues\" --output-format json"],"556879772":["이 변형본은 사용자 스코프(user scope, ~/.claude/commands/)에 /review-strict 같은 다른 이름으로 넣고, 저장소의 커맨드는 그대로 두기"],"558055146":["세션 하나당 이슈 하나로 제한하고, 용건이 여러 개인 고객에게는 대화를 따로 열어 달라고 하기"],"558728991":["맞음. 에스컬레이션은 복잡한 사례를 위한 장치인데, 이는 그중에서도 가장 단순한 사례이기 때문임."],"559699510":["너는 두 페이지짜리 명세서(spec)를 보고 속도 제한기(rate limiter)를 만들고 있음.","1라운드는 시스템 시계(system clock)가 갑자기 바뀔 때 무슨 일이 일어나는지를 무시했음.","2라운드는 제한에 걸린 클라이언트가 실제로 뭘 돌려받는지에 대한 답이 없었음.","3라운드는 제한이 API 키 단위인지 IP 단위인지를 불분명하게 남겨뒀음.","각 버전 다 동작은 했지만, 매번 빠진 부분은 네가 미처 적어두지 않은 것이었음.","4라운드는 어떻게 해야 하는가?"],"561621803":["수정이 제대로 됐는지 확인하려고 기존에 실패하던 테스트를 실행하기"],"564854294":["각 서브에이전트(subagent)를 마지막 30턴에 대한 슬라이딩 윈도우(sliding window) 방식으로 옮기기. 이러면 남겨둔 텍스트가 그대로 보존됨."],"566134715":["밤에 돌려놓고 다음 날 아침에 결과를 읽는 기술 부채 분석임."],"566663929":["(1)은 시스템 프롬프트 규칙으로, (2)는 PostToolUse로 두는 방식임. 정책은 지시문에, 변환은 hook에 두는 것임."],"567046929":["같은 형식 설명을 prompt 맨 위와 맨 아래에 한 번씩 다시 적어서 두 번 보이게 하기"],"567428724":["response-as-JSON 방식만 쓰기. 도구의 schema는 모델이 벗어날 수도 있는 가이드일 뿐이지만, response formatting은 API가 강제하는 것이기 때문임."],"568462849":["매일 밤 도는 현지화 QA. 모든 지원 문서가 용어 검사, 톤 검사, 깨진 링크 검사를 똑같은 순서로 거침."],"568853618":["지원 에이전트가 사람에게 넘길 정당한 사유 두 가지는 무엇인가? (두 개 고르기.)"],"570188533":["CI 테스트 생성 작업이 가치 낮은 테스트(단순 getter 같은 것)를 잔뜩 만들고, 기존 스위트가 이미 커버하는 시나리오도 중복으로 만듦.","베스트 프랙티스에 맞는 수정 조합은 무엇인가?"],"571474546":["coordinator가 실패한 check를 성공할 때까지 재시도하게 해서, 보고서가 항상 완료된 check 세 개로부터만 만들어지게 하기."],"573058749":["\"결과는 우리가 제출한 custom_id로 요청과 매칭되니까, 부분 실패가 있어도 전체 작업(job)을 다시 실행하지 않고 그 부분만 식별해서 재제출할 수 있음.\""],"575339097":["동시에 열린 채팅 두 개임. (a) 대문자와 협박까지 써 가며 격분한 고객인데, 용건은 에이전트가 한 단계로 처리할 수 있는 일반적인 주소 변경임. (b) 차분하고 정중한 고객인데, 정책 어디에도 언급이 없는 보증 연장을 요청함.","어느 쪽 처리 방식이 맞는가?"],"576575669":["모델이 두 가지 결함 유형을 스스로 고치도록 검증 피드백을 주는 재시도 루프를 추가하기"],"579893704":["subagent를 단순하게 유지하려고 일시적인 타임아웃을 전부 중앙에서 처리하는 방식."],"580264834":["모든 인보이스를 사람 검토로 보내고, 세금 ID(tax ID)가 없는 것들은 검토자가 빠르게 승인하게 해서 처리량이 괜찮은 수준을 유지하게 하기"],"581439613":["리뷰를 파일별 local logic 체크용 pass와, 파일 간 일치 여부만 확인하는 별도 pass로 나누기"],"581889447":["모놀리스를 마이크로서비스로 재구성하기. 파급 범위가 넓은 아키텍처 결정임."],"583165842":["9일짜리 세션을 fork해서, 한 브랜치는 비교용으로 migration 이전 분석을 계속 남겨두고, 다른 브랜치는 새 레코드 작업을 진행하게 하기"],"583934993":["subagent들이 스캔 결과와 실행 결과를 분리한 구조화된(structured) result를 반환하게 하기. 그러면 \"실행할 수 없었음\"이 \"발견 사항 없음\"으로 표현될 수 없음."],"583999817":["원문(source text)이 손상된 것처럼 보이면 extractor가 아무것도 반환하지 않도록 지시하는 프롬프트 지시문을 추가하기."],"584519232":["데이터 완전성을 위해 모든 필드를 required로 유지하되, 프롬프트에 \"값을 절대 지어내지 말 것, 카테고리를 절대 억지로 끼워 맞추지 말 것, 날짜는 항상 ISO 형식으로 쓸 것\"이라는 경고를 넣기"],"587564304":["그 문서 유형에서는 renewal_term_months를 스키마에서 아예 빼기. 원본에 값이 없는 필드는 아예 출력하면 안 되기 때문임."],"587793735":["80% confidence threshold를 채택하기. 이러면 모델이 가장 확신이 없는 nit들을 걸러낼 수 있음."],"589426198":["개발자가 머지하기 전에 결과를 기다려야 하는 머지 전 검사."],"590149329":["답답한 마음을 먼저 인정해 주고 문제가 간단하니까 클릭 한 번으로 바로 복구해 주겠다고 제안하기. 그래도 고객이 사람과 이야기하고 싶다고 다시 말하면 즉시 사람에게 넘기기."],"591495574":["환불 확인서(refund confirmation)는 금액, 카드 뒷자리 4자리, 예상 정산일(settlement date)을 표기함.","지난달 감사 결과. (a) 확인서의 4%에서 표기된 금액이 실제로 process_refund에 전달된 금액과 달랐고, (b) 2%에서는 payments 도구가 한 번도 반환한 적 없는 정산일이 표시됐음. 그 도구는 provider가 아직 지급을 대기열에 넣어둔 상태에서는 해당 필드에 아무 값도 반환하지 않는데, 재시도 세 번을 해도 값이 나오지 않았음.","이 문제들을 발생 지점 수준에서 해결하는 변경 두 가지는 무엇인가? (두 개를 고를 것.)"],"592372669":["-p로 CLI를 호출하고, comment parser(코멘트 파서)를 확장해서 prose(산문형) 출력도 받아들이게 하기"],"592508463":["에이전트가 이미 잘 처리하는, 가장 흔하고 명확한 케이스들."],"594162340":["검색 subagent 수를 두 배로 늘려서 더 많은 지역을 커버하기."],"594476322":["\"문서 전체를 꼼꼼히 읽고 필드를 하나도 놓치지 마\"를 프롬프트에 추가하고, temperature를 낮춰서 추출이 더 신중하게 이뤄지게 하기"],"594527730":["audit 지적 사항이 다시 발생하지 않도록, 각 도구 호출(tool call) 후에 실행되면서 transcript에서 비밀번호 형태의 문자열을 지워주는 hook을 추가하기"],"594758824":["리뷰가 충분한 깊이에 도달하려면 extended thinking을 켜기."],"595519487":["고정 시퀀스는 모든 단계가 앞 단계를 기다려야 해서 모델 주도 루프보다 느림."],"595527921":["synthesis 에이전트가 보고서를 쓴 다음, 같은 session 안에서 \"네가 방금 한 주장을 전부 의심해 봐\"라는 지시를 받은 self-check(자체 검토)를 실행함. 보고서 30건에 걸쳐 이 self-check는 문장 두 개만 고쳤고, 나중에 고객이 발견한 attribution error(귀속 오류) 네 건 중 단 하나도 잡아내지 못했음.","model pass를 정확히 한 번 더 돌릴 예산만 남아 있음.","그것을 어디에 써야 하는가?"],"596080150":["이렇게 무거운 테스트 스위트를 pull request에 넣는 것은 맞지 않음. 야간 스케줄 작업(nightly scheduled job)으로 옮겨서 PR이 절대 막히지 않게 하기."],"597173889":["특정 문서 유형이나 필드에서의 저조한 성능을 가려 버릴 수 있음. 어떤 구간은 평균보다 한참 아래일 수도 있음."],"598065744":["마이그레이션 코디네이터(migration coordinator)가 180개 파일에 걸쳐 패키지마다 subagent(하위 에이전트)를 하나씩 생성함.","3시간째에 인프라 재시작(infrastructure restart)으로 코디네이터 프로세스가 죽었음.","subagent마다의 결과는 코디네이터 대화(conversation)로 반환된 텍스트로만 존재했기 때문에, 재실행 때 이미 끝난 패키지 11개 분석을 다시 반복했음.","다음 실행은 어떻게 설계해야 하는가?"],"598280830":["시스템 프롬프트에 \"내부 문서 URL만 가져올 것\"이라는 규칙을 추가하기."],"599226606":["도구 호출 실행 시간이 점점 길어지기 시작함."],"599566331":["\"Claude가 세션 시작할 때 이걸 로드하는가?\"가 기준임. 자동으로 로드되므로 모두에게 적용되는 것임."],"600341659":["순차로 조사하면서 이슈가 하나씩 해결될 때마다 고객에게 부분 답변을 보내기."],"602553418":["클라이언트가 \"경영진이 바로 볼 수 있는 배터리 재활용 시장 개요\"를 요청했는데, 초안 세 개가 완전히 다른 형태로 돌아왔음: 다섯 페이지짜리 서술형 보고서, 벤더 표, 리스크 메모.","브리프는 산문 한 문단짜리임.","해결책 네 가지가 테이블 위에 올라와 있음.","결과물을 수렴시키는 데 가장 도움이 안 될 것 같은 것은 무엇인가?"],"602971103":["B의 경우, src/ 아래 모든 파일을 나열하고 의존성 순서(dependency order)대로 읽어서 호출이 전부 파악될 때까지 계속하기"],"603105886":["모놀리스를 마이크로서비스로 재구성하는 작업."],"604156923":["매일 밤 저장소 전체를 훑는 리뷰가 사람 개입 없이 돌아감.","지난주 실행 한 번에 61달러가 들었는데, 실행 기록(transcript)을 보면 subagent 9개가 생성됐고 그중 몇 개는 같은 패키지 트리를 서너 번씩 훑었음.","재무 담당자는 실행 한 번이 쓸 수 있는 금액에 확실한 상한선을 원함.","플랫폼 담당자는 agentic turn 수를 제한하는 것만으로 이미 충분하고, 두 번째 제한을 추가하는 건 중복이라고 반박함.","재무 담당자의 요구사항을 실제로 충족시키는 변경은 무엇인가?"],"604538799":["(a) 일치하는 항목이 여러 개 나올 때마다 사람에게 넘기기. (b) 정책이 허용하지 않으니까 요청을 거절하기."],"605548494":["종합 프롬프트에 이 문장을 추가하기. \"발견 내용을 요약할 때 출처 URL을 항상 남겨.\""],"609905693":["시스템 프롬프트에 규칙을 추가하기. \"결과가 비어 있으면 데이터베이스가 죽었을 가능성도 고려해\"라고 적는 것임."],"614823969":["심각도를 왜 그렇게 골랐는지 모델한테 설명하게 시키기. 그러면 분류를 더 신중하게 하게 됨."],"616021103":["시스템 프롬프트가 두 요구사항을 절대적 제약으로 명시하면 두 규칙 다 hook은 필요 없음."],"616762735":["그냥 받아들이기. 홉이 적으면 언제나 지연이 나아지고, 에이전트끼리 peer-to-peer로도 잘 협업함."],"618094460":["#799는, 몇 개 파일만 resume해서 재분석하는 게 context를 처음부터 다시 만드는 것보다 항상 비용이 덜 드니까, run을 resume하고 어떤 파일이 바뀌었는지 알려주기."],"619094257":["header total은 confidence 값을 낮게 붙여서 그대로 출력하고, 사람이 실제로 보게 될지는 downstream threshold가 결정하게 두기"],"622621752":["별도 인스턴스는 기본적으로 더 새로운 모델 버전에서 돌아감."],"623830870":["stop_reason으로 루프를 진행할지 판단하기. \"tool_use\"면 계속 가고 \"end_turn\"이면 멈추는 방식임. 그리고 실패까지 포함해 모든 도구 결과(tool result)를 구조화된 도구 결과로 대화에 추가하기. 그래야 실패한 호출이 조용히 반복되지 않음."],"625945547":["둘 다 PreToolUse. hook은 파이프라인에서 항상 최대한 이른 시점에 작동해야 하기 때문임."],"627331786":["실패 유형 세 가지를 설명하는 규칙을 시스템 프롬프트에 넣어서, 어떤 실패가 일어났는지 에이전트가 추측하게 하기"],"627878110":["낯선 레거시 코드베이스를 파악해서 포괄적인 테스트를 추가하는 작업임. 의존성은 진행하면서 하나씩 발견하게 되는 상황임."],"628175604":["tool_choice: 둘 중 더 흔한 쪽을 강제하면 모델이 더 이상 선택할 필요가 없어지므로 모호함(ambiguity)이 애초에 생기지 않음."],"628225659":["Job A에는 이미 알려진 섹션 5개에 대한 고정된 순차 체인(sequential chain)을 주고, Job B에는 범위를 잡는(scoping) 패스로 시작해서 발견 내용이 질문을 좁혀갈 때마다 서브태스크가 늘어나는 계획을 주기. 두 작업의 차이는 증거가 들어오기 전에 서브태스크를 미리 나열할 수 있는지 여부임."],"628409320":["정책 위키(wiki) 전체를 대화 시작마다 시스템 프롬프트(system prompt)에 붙여넣어서 따로 조회할 필요가 없게 하기."],"629106427":["도구가 tools 배열에 등장하는 순서."],"629637363":["거의 알지 못하는 도메인의 캐싱 레이어를 Claude에게 구현해 달라고 맡김.","예전에도 돌아가는 코드는 나왔지만, 나중에 예상 못 한 방식으로 터짐. 낡은 캐시 무효화나 thundering herd 같은 문제였음.","이를 가장 잘 막아 주는 상호작용 패턴은 무엇인가?"],"629861612":["문서 단위 자동 승인 기준을 0.93에서 0.97로 올려서, 평균 아래에 숨을 수 있는 오류의 양을 줄이기"],"631098192":["감정 분석이 고객이 매우 화가 났다고 감지한 경우."],"631743085":["각 필드 값 옆에 모델의 신뢰도(confidence) 값을 함께 저장하기. 그래야 감사자(auditor)가 추출 결과가 얼마나 확실했는지 볼 수 있음."],"632123431":["리뷰어가 패키지 트리를 아예 순회하지 못하게 도구 목록을 좁히기. 그러면 비용이 많이 드는 동작을 근본에서 없앨 수 있음."],"632362179":["요청마다 tool_choice로 맞는 도구를 강제해서 선택이 설명에 절대 좌우되지 않게 하기."],"632460867":["두 설명을 모두 고쳐서 겹치는 부분을 없애고 경계를 규정하는 문구를 넣기. 어떤 질의 유형이 어느 도구에 속하는지를 예시 질의와 함께 적고, \"이럴 땐 대신 X를 써\" 같은 문장도 명시하기"],"632519955":["헷갈릴 경계를 줄이려고 minor 등급을 없애기."],"632734448":["\"관리자 계정이 만든 건가?\" 팀 전체 설정은 상위 권한이 있어야 함."],"633542177":["고객지원 운영팀(support operations)은 전날 종료된 티켓(약 1,200건)을 대상으로 매일 밤 실행되는 작업(nightly job)을 원함.","티켓마다: (i) 후속 조치 날짜(follow-up date)가 기록됐는지, (ii) 인용된 정책 조항이 제시된 해결 내용과 일치하는지, (iii) 고객의 종결 감정(closing sentiment)이 부정적이었는지를 확인해야 함.","컴플라이언스(Compliance)가 3월에 이 세 가지 점검을 모두 승인했고, 모든 티켓이 세 가지를 다 받아야 하며, 결과는 주 단위로 비교 가능해야 함.","이 중 가장 적절하지 않은 접근법은 어느 것인가?"],"633806514":["팀은 \"내 소포가 어디 있는가\"라는 문장이 track_shipment로 연결되기를 원함.","제안이 네 개 올라와 있음.","그중 원인을 우회하는 것이 아니라 원인 자체를 없애는 것은 어느 것인가?"],"636032934":["감사 작업에 훨씬 큰 컨텍스트 창을 하나 줘서 끊김 없이 한 번에 끝나게 하기."],"639196694":["넷 다 path pattern이 있는 rule file로 만들기. path scoping이 범용 조건부 로더(conditional loader)이므로 (iv)는 그냥 vendored/를 포함하는 pattern을 붙이고 (iii)은 flag 파일이 나중에 위치할 디렉터리를 포함하는 pattern을 붙이면 됨."],"641046308":["temperature를 올려서 생성되는 테스트가 더 다양해지고 중복이 줄게 하기"],"642082227":["오후용으로 새 세션(session)을 시작해서 오전의 원본 노트를 붙여넣고, 새 세션에서 두 프레이밍(framing)을 차례로 실행하기."],"642120809":["반복을 아예 없애려고, PR이 처음 열릴 때 딱 한 번만 리뷰하기."],"643402861":["스캐폴딩 하네스(scaffolding harness)가 Claude를 돌려 서비스 모듈을 생성함.","루프는 응답 텍스트에 \"All done.\"이라는 문구가 있으면 멈추는데, 지난주에 프롬프트 템플릿 문구가 바뀌면서 Claude가 \"Everything is complete.\"로 마무리하기 시작했고, 그 이후 22번 실행 중 18번이 40회 반복 상한(40-iteration cap)까지 갔음.","별개로, 3번의 실행은 함수 중간에서 파일이 잘린 채 끝났고, 그 응답들은 stop_reason 값이 max_tokens였음.","수정안에 포함되면 안 되는 변경은 무엇인가?"],"643555798":["프로젝트 범위의 .mcp.json 안에."],"643723696":["신원 판단은 사람 상담원에게 넘기기."],"644140897":["타임아웃이 일시적인 것인지 알려진 버그 때문인지 확인하기도 전에, 앞으로의 모든 실행에서 그 도구를 우회하도록 coordinator를 다시 작성하기"],"644708546":["/migration-create와 /migration-apply로 쪼개고 allowed-tools 범위를 각각 따로 잡기(create는 파일 도구만, apply는 DB 실행). 그리고 인자가 빠졌을 때는 SKILL.md가 확인을 요청하게 만들기. argument-hint는 화면에 보여주는 힌트일 뿐이지 강제 수단이 아니기 때문임."],"645217931":["팬아웃(fan-out) 구조는 그대로 두고, subagent(하위 에이전트)가 해당 티켓이 자기 담당이 아니라고 판단하면 빈 결과를 반환하게 하기"],"647085412":["구조화된 출력에 발행일이나 데이터 수집일을 반드시 넣게 해서 시점 차이를 모순으로 잘못 읽지 않게 하기."],"647353687":["(a) 최근 주문이 대화 주제와 가장 잘 맞는 고객을 고르기. (b) 호의를 지키려고 합리적인 선에서 가장 작은 할인을 제시하기"],"647728147":["Claude Code를 재시작해서 지시 캐시를 비우기. 삭제된 규칙이 몇 주씩 메모리에 남아 있을 수 있음."],"647958348":["추출하기 전에 모든 논문을 하나의 정규화된 형식으로 전처리하기."],"649043725":["verify_batch가 매 배치 뒤 source와 target 사이 row 개수를 비교하게 하고, 첫 번째 불일치(mismatch)가 나오면 마이그레이션(migration)을 중단하기."],"649178752":["hook이나 skill은 자동으로 발견되지 않으니까, 한 runner에 남겨진 게 그 runner의 리뷰를 몰래 바꿀 수는 없음."],"649740558":["모델이 스스로 보고한 신뢰도 점수로 지금 당장 라우팅을 시작하고 감사는 나중에 하기"],"650187434":["세션 히스토리에는 옛날 코드를 근거로 만든 결론과 분석이 그대로 남아 있음. 에이전트는 바탕이 되는 파일을 다시 읽지 않은 채 그 기록된 결론에서 추론하는 경우가 많음. 명시적으로 알려줘야 필요한 부분만 겨냥해 다시 분석하게 됨."],"653368445":["가장 최근 턴들에 대해 슬라이딩 윈도우(sliding window)를 유지하기. 이렇게 하면 남겨둔 텍스트가 바이트 단위로 그대로 보존되고 추가 모델 호출 비용도 들지 않음."],"655219985":["9일치 전체를 발급하고 사후 검토(post-hoc review)를 위해 바우처에 플래그를 걸어서, 승객이 사람을 기다리지 않게 하기"],"656028000":["2단계가 끝날 때 /compact를 한 번 실행해서 의존성 덤프를 줄이기"],"658752239":["성공한 결과만 계속 추가하고, coordinator에 소스가 이미 충분해지면 도구 호출을 멈추라고 알려주는 system prompt 지시를 추가하기"],"659173666":["contractor가 공유 프로젝트 설정(project configuration)에 서버를 그대로 두게 하되, 팀원들에게 활성화하지 말라고 부탁하는 주석을 추가하기"],"659979056":["추출된 값은 스키마로 제약하기(금액은 숫자로, 날짜는 날짜 타입 문자열로). 그리고 고정 컬럼(fixed-column) 줄 자체는 파이프라인 코드가 직접 만들게 하기. 컬럼 패딩(padding)은 결정적인(deterministic) 포매팅 작업이므로 그것을 모델에 맡기면 스키마가 없애려던 변동성이 다시 들어옴."],"660932509":["두 도구를 mode 파라미터가 있는 검색 도구 하나로 합치기."],"662222717":["harness가 매칭하는 completion 문자열 목록에 새 문구를 추가하고, 프롬프트가 바뀔 때마다 그 목록을 계속 최신 상태로 유지하기"],"662373126":["부분적으로만 맞음. 변경을 처리하면서 동시에 사람에게 넘길 건을 대기열에 올려야 함."],"664174923":["고객지원 엔지니어 11명이 각자 개인 설정(personal configuration)에서 ticketing MCP server를 손으로 직접 연결함.","그중 세 명은 만료된 자격 증명(credential)을 쓰고 있어서, 에이전트가 티켓 상태를 조용히 추측하는 쪽으로 넘어감.","한편, 누군가 결제 제공업체의 공개 API(public API)를 감싸는 사내(in-house) MCP server를 따로 만들었는데, 이미 유지 관리되고 있는 커뮤니티 서버(community server)와 겹치는 반면, 이 팀만의 고유한 환불 승인(refund-approval) 워크플로에는 여전히 서버가 없음.","맞는 변경 사항 두 가지는 무엇인가? (두 가지를 선택할 것)"],"665055761":["규칙끼리 서로 덮어쓰는 우선순위."],"665748720":["재시도는 아예 건너뛰고, 세 가지 실패를 검증기(validator) 출력과 함께 개발자에게 그대로 보여주기"],"667088974":["각 팀이 자기 패키지의 표준을 각자의 personal memory 파일에 두게 하기. 어차피 그 패키지에서 작업하는 건 그 팀뿐이기 때문임."],"667612141":["CI workflow 파일에 넣고 호출 시점에 prompt에 덧붙여서 merge bot만 신경 쓰는 규칙이 대화형(interactive) 세션에는 부담이 되지 않게 하기."],"670818305":["plan mode로 작업하고 세션에 더 큰 context budget을 줘서 전체 매핑이 한군데 다 들어가게 하기."],"672602231":["기본 설정은 그대로 두고 프롬프트 규칙만 하나 추가하기. \"쿠폰이 두 번 실패하면 고객에게 코드를 다시 확인해 달라고 요청할 것.\""],"672806442":["내용에 validateCoupon이 언급된 파일을 전부 찾기 → Grep."],"673021542":["오래된 대화 기록을 압축해서 컨텍스트 공간을 되찾는 야간 유지보수 작업."],"675245249":["일시적인 실패는 위로 전파하기 전에 그 자리에서 횟수를 제한해 몇 번 재시도해 보기."],"675938353":["네 추출 파이프라인은 전체 필드 정확도를 96%로 보고함.","고신뢰 추출 건을 자동 승인하기 시작한 지 한 달 뒤, 재무팀이 손글씨 주석 달린 청구서의 오류율이 61%라는 걸 발견함. 전체 물량의 4%인데, 집계 수치에서는 전혀 안 보였던 것임.","출시 전과 출시 후에 이걸 찾아낼 수 있었던 실천 두 가지는 무엇인가?"],"676310781":["도구 18개를 전부 남겨두되, tools 배열 안에서 사용 빈도순으로 정렬하기"],"676407998":["한 번 실행할 때 넘기는 findings 개수를 줄여서 종합 에이전트가 출처를 더 쉽게 추적하게 하기"],"678647129":["네 저장소는 모두가 쓰는 scaffold-service skill을 포함하고 있음.","한 엔지니어는 자기 버전에서 Terraform stub도 함께 생성되길 원하는데, 나머지 팀원들은 그게 자기들 출력에 들어가는 걸 명확히 원하지 않음.","그는 공유 skill 파일을 로컬에서 계속 수정해왔고, 커밋할 때마다 매번 그걸 un-stage 해야 함.","올바른 구성은 무엇인가?"],"678650436":["하나로 확정하기 전에 세션을 fork해서 후보 수정안 두 개를 비교하기"],"678664524":["매칭을 느슨하게 해서 Edit이 처음 찾은 곳에 적용되게 하기."],"679302897":["둘을 type enum이 있는 addresses 배열 하나로 합쳐서, 모델이 어느 슬롯을 채울지 더 이상 고민하지 않게 하기."],"682234240":["애널리스트가 브리프에 유료 데이터 구매 전에는 꼭 자신에게 먼저 물어봐 달라고 적어놨는데, 다음 단계가 바로 그런 구매를 필요로 함."],"682828143":["(a)는 재시도로 해결하지 못함. 원본에 그 정보 자체가 없으니 null을 허용하거나 사람 입력으로 넘기기. (b)는 자기 교정 설계가 필요함. stated_total과 함께 calculated_total도 추출해서 차이가 나면 표시하기"],"684623545":["Call 2는 명시적인 형식 지시와 함께, disclaimer(고지 문구)와 네 개 section이 있는지 확인하는 체크를 쓰고, 없으면 retry하기. 필수 문구는 JSON Schema가 강제할 수 있는 형태가 아니기 때문임."],"685132004":["코디네이터 응답 하나에 Task 도구 호출을 세 개 담아서 subagent들이 병렬로 돌게 하기."],"685807639":["--output-format json 을 --json-schema 와 함께 쓰기."],"685981729":["사람 상담원에게 넘기는 handoff에는 고객 ID, 이슈 요약, 에이전트가 이미 시도한 것, 그리고 해당하는 경우에 한해 논의 중인 환불 금액이 담겨야 함.","지금은 에이전트가 문단 형태로 써서 넘기는데, handoff의 12%는 금액이 전혀 언급되지 않은 사례에서도 환불 금액을 명시하고 있음.","이런 종류의 오류를 없애는 스키마 설계는 무엇인가?"],"686298499":["세 경우 전부 구조화된 요약을 들고 새 세션으로 시작하기. 파일이 하나라도 바뀌면 그 세션의 도구 결과(tool result)는 무효가 됨."],"687102391":["명시된 제약 조건(stated constraints)을 지속적인 구조화 블록(persistent structured block)으로 뽑아내서, 모든 프롬프트(prompt)에 다시 포함시키고 요약(summarization) 대상에서는 제외하기."],"687558269":["코디네이터가 취합하기 전에 각 서브에이전트의 실행 결과를 확인하게 하고 스캔이 실행되지 않았을 때는 통제(control)를 명시적으로 실패 처리하기. 다만 보고서는 그대로 내보내기."],"688197617":["너의 scaffolding 파이프라인(pipeline)은 Claude한테 생성한 내용에 대한 JSON manifest(경로(path), 목적(purpose), 짝이 되는 테스트 파일)를 출력하라고 요청함.","실패 유형은 두 가지임. (a) manifest의 약 6%가 실제로는 만들어지지 않은 테스트 파일을 나열함. (b) manifest에는 모델이 접근할 수 없는 tracker에만 존재하는 ticket_id가 담기는데, 대략 열 번 중 한 번꼴로 값을 지어내고, 자동 재시도 세 번을 해도 정확한 값이 한 번도 나오지 않았음.","어떤 두 가지 변경이 맞는가? (두 개를 선택할 것.)"],"690988615":["\"이 낯선 결제 서비스를 파악하고 개선안을 제안해\" 같은 일. 탐색하는 과정에서 범위가 잡히는 경우임."],"691155951":["승인 기준(acceptance check)부터 먼저 쓰기(어떤 섹션이 있어야 하는지, 문서가 어떤 질문에 답해야 하는지). 그리고 실패한 기준을 피드백으로 넣으면서 반복하기."],"692914759":["\"인보이스 렌더러의 타임존 버그\"를 고치려고 바로 실행(direct execution)으로 시작함. 파일 하나만 건드리면 되는 명확한 작업이었음.","10분쯤 지났을 때 Claude가 진짜 원인을 알려줌. 서비스 세 개가 각자 타임존 변환을 하고 있고, 가끔은 이중 변환까지 일어남. 제대로 고치려면 변환을 어디서 할지 정하고 파일 20개쯤을 손봐야 함.","타당하다고 볼 만한 설계안이 최소 두 가지는 있음.","어떻게 해야 하는가?"],"693231196":["search_wiki가 반환하는 매치 수를 9개에서 3개로 줄여서 대화에 들어오는 페이지 수 자체를 줄이기."],"696481040":["도구 출력이 들어갈 자리를 만들려고 대화 전체를 더 공격적으로 요약하기."],"697030614":["주소 정규화기(address normaliser) 작업을 세 번째 라운드까지 진행한 상황임.","1라운드: 출력 형태를 두 문단으로 설명했더니 실행할 때마다 키 순서가 달라졌음.","2라운드: \"더 견고하게 만들어줘\"라고 했더니 관련 없는 지오코딩(geocoding) 모듈을 리팩터링해버렸음.","3라운드: 실패 세 가지를 하나씩 보고했음: 빈 문자열, 리터럴 \"N/A\", 그리고 null. 그런데 하나를 고치면 다른 하나가 다시 나타났고, 셋 다 같은 형변환(coercion) 헬퍼를 거침.","4라운드는 무엇으로 구성해야 하는가?"],"697059784":["어제 세션을 fork해서 그 브랜치에서 이어서 작업하기."],"698712879":["subagent가 실패를 구조화된 에러 맥락(실패 유형(접근 불가/페이월), 무엇을 시도했는지, 부분 결과, 대안(캐시본, 대체 출처))으로 보고하게 하기. 그래야 coordinator가 다른 방식으로 재시도할지, 대체할지, 커버리지 주석을 달고 내보낼지 고를 수 있음."],"698726606":["merge gate가 미완료된 체크를 통과가 아니라 통과 실패로 취급하게 만들어서, 장애가 나도 게이트가 열리지 않게 하기"],"699351452":["(1)과 (3)은 repository의 memory 파일에 두고, (2)는 database workflow가 실행되는 동안 사용 가능한 도구를 frontmatter로 제한하는 skill이 처리하게 하기."],"699538742":["프롬프트에 지시를 하나 넣기. \"답하기 전에 각 금액이 어느 주문에 속하는지 항상 다시 확인할 것.\""],"700846822":["더 이상 쓰지 않는 import 경로 @corp/logger-v1을 74개 파일에서 @corp/logger로 바꿔야 함.","제약이 두 가지 있음: 그중 3개 파일은 test fixture 안에 @corp/logger-v1이라는 문자열이 그대로 들어 있는데 이는 손대지 말고 그대로 둬야 하고, 수정한 파일은 전부 repo의 formatter가 만드는 형식 그대로 맞춰야 함.","어떤 접근 방식이 맞는가?"],"701341973":["앞으로 나올 유형까지 커버하려고 enum을 미리 60개 카테고리로 늘리기"],"701993637":["새 세션을 시작해서 모듈을 처음부터 다시 분석하기. 크래시가 났고 외부 변경도 있었으니 어제 컨텍스트는 믿을 수 없음."],"702087771":["정책상 100달러를 넘는 환불은 처리하기 전에 반드시 검증된 영수증(verified receipt)이 있어야 함.","시스템 프롬프트를 두 번 강화하고 few-shot 예시도 넣었더니 위반율이 9%에서 5%로 떨어졌는데, 0%까지는 내려가지 않음.","그런데 컴플라이언스 쪽은 0%를 요구함.","이 상황이 알려주는 것은 무엇이고, 해결책은 무엇인가?"],"702114661":["DevOps 팀이 파이프라인의 프롬프트 문자열에 하드코딩해 두기"],"702888694":["어떤 규칙이 지금 팀원과 앞으로 합류할 팀원 모두에게 자동으로 적용돼야 함. 사람마다 따로 설정하는 일 없이.","파일을 어디에 둬야 하는지 확실하게 알려주는 단 하나의 기준은 무엇인가?"],"703351992":["이미 자리 잡은 15개 카테고리는 enum으로 유지하고, 새로운 조항을 설명하는 필수 상세 문자열이 딸린 \"other\"를 추가하고, 진짜 애매한 것은 \"unclear\"로 받기. 그리고 \"other\"로 들어온 값들을 매달 검토해서 분류 체계를 넓혀 가기"],"706455259":["두 호출의 올바른 순서를 보여주는 퓨샷 예시를 추가하기"],"706581358":["네 저장소(repository)에는 팀의 모든 엔지니어가 사용하는 공유 /review 슬래시 명령(slash command)이 들어 있음.","너는 팀원들이 /review를 실행할 때 받는 결과는 그대로 두면서, 네가 실행할 때만 더 엄격한 보안 체크리스트와 다른 출력 형식을 쓰고 싶음.","어떻게 해야 하는가?"],"707014023":["아무것도 잃지 않도록 중간 결과를 전부 coordinator의 대화 히스토리에 남겨 두기"],"708154243":["간결하게 하라는 지시를 system prompt 끝에도 한 번 더 넣어서, 모델이 고객 메시지 보기 직전에 마지막으로 읽는 내용이 되게 하기."],"708414556":["97%는 자동화 업계 표준에 못 미치기 때문임."],"708707723":["한 인보이스의 헤더 합계(header total)는 48,200이고, 항목별 금액을 다 더하면 48,020임.","추출(extraction) 결과는 total_amount 하나만 내놔야 하고, 문서에는 다른 합계가 없음.","이 고객사 계약에 따르면, 파이프라인이 50,000 미만으로 내놓는 값은 사람이 보지 않고 자동으로 지급됨.","추출 로직은 어떻게 해야 하는가?"],"709538605":["한 번의 큰 패스로 전부 생성해서 모든 엔티티가 컨텍스트를 공유하게 하기"],"709618693":["18만 줄짜리 서비스를 물려받았는데, ENABLE_LEGACY_PRICING이라는 폐기 예정 스위치(switch)가 아직 적용되는 곳을 전부 찾아야 함.","TypeScript, 배포 매니페스트(deployment manifest), 셸 스크립트 하나, 로그 메시지에 등장한다는 건 아는데, 어느 파일인지는 모름.","파일을 하나씩 여는 식으로 시도했던 이전 방법은 끝내기도 전에 컨텍스트 창(context window)을 다 써버렸음.","어떤 순서로 하면 되는가?"],"711746632":["에이전트가 \"7년 된 레거시 코드베이스에 포괄적인 테스트를 추가\"해야 함. 엔지니어 두 명의 의견이 갈림. Dana는 Claude가 메인 모듈 테스트를 당장 생성하기 시작하길 원함(\"직접 해 보면서 구조를 익힌다\"는 입장임). Raj는 완결된 고정 계획을 미리 다 써 놓고 정확히 그대로 따르길 원함(\"계획을 세워야 낭비를 막는다\"는 입장임).","모범 사례가 실제로 권하는 것은 무엇인가?"],"711903837":["타임아웃일 때만 isError를 돌려주고, 나머지 둘은 경고를 붙인 성공으로 처리하기"],"713551170":["순수 무작위 표본을 그대로 유지하기. 편향 없는 배분은 그것뿐이기 때문임."],"714168421":["전역 문구는 그대로 두고 \"확신이 높은 이슈만 보고해\"로 강화하기. 가장 짧은 변경이면서 기각률을 직접 공략하는 방법이기 때문임."],"715260040":["주소 정규화기(address normaliser) 작업이 세 라운드째임.","1라운드: 출력 형태를 두 문단으로 설명했더니 실행할 때마다 키 순서가 다르게 나왔음.","2라운드: \"더 견고하게 만들 것\"이라는 지시가 관계없는 지오코딩(geocoding) 모듈의 리팩터링(refactor)을 낳았음.","3라운드: 빈 문자열, 문자 그대로의 \"N/A\", null, 이렇게 세 가지 실패가 하나씩 보고됐는데 고칠 때마다 다른 실패 중 하나가 다시 나타났음. 셋 다 같은 강제 변환 헬퍼(coercion helper)를 거쳐감.","4라운드는 무엇으로 구성해야 하는가?"],"719082236":["탐색하는 동안 Claude에게 \"응답을 짧게 유지할 것\"이라고 요청해서 노이즈를 줄이기."],"722263738":["보정된 신뢰도가 낮은 추출, 그리고 출처가 모호하거나 상충하는 문서를 우선하기. 고신뢰 추출 중에서도 소수의 층화 표본은 남겨서 상시 모니터링에 쓰기"],"722278407":["Read로 파일 전체를 읽고, 메모리에서 변경을 적용한 뒤, Write로 다시 쓰는 방식으로 넘어가기. 고유 앵커 지정이 실패했을 때 문서에 나온 대체 방법임. 그다음 필요하면 Grep으로 확인하면 됨."],"722407217":["B. 위임하기 전에 리서치 범위를 나눠두면 중복 작업 자체가 안 생김. 수집한 뒤에 중복을 제거하면 토큰 비용은 이미 두 배로 나갔고, 낭비된 작업 때문에 밀려난 커버리지도 되살릴 수 없음."],"722738448":["subagent들의 system prompt에 항상 필드 라벨(field label)이 일관된 유효한 마크다운(markdown)을 출력하라고 지시하기"],"723038613":["세 번째 출처를 가져와 최종 판단 근거로 삼고, 셋 중 둘이 일치하는 값을 보고하기"],"725422344":["긴 코드 탐색 세션에서 컨텍스트가 망가지고 있다는 결정적인 신호는 무엇인가?"],"725983150":["리뷰 프롬프트를 어떤 상황에서도 어시스턴트가 아무것도 수정하면 안 된다는 단호한 지시로 시작하기"],"727045501":["같은 CI 리뷰어에 대한 불만 두 개가 같은 회고(retro)에서 나왔음.","(1) 팀의 error-envelope 컨벤션(convention)을 절대 언급하지 않는데, 이 컨벤션은 pull request 템플릿에 링크된 위키 페이지에 있음.","(2) lockfile을 다시 쓰는 스크립트를 두 번이나 실행했는데, 릴리스 엔지니어(release engineer)에 따르면 CI에서 이런 일이 절대 일어나면 안 됨.","어떤 메커니즘 조합이 맞는가?"],"728360550":["팀은 이번 주에 분류기(classifier)를 내보내야 하는데, 조건이 두 가지 딱 걸려 있음. 프록시가 모든 요청에서 tools 필드를 벗겨내고, 이번 분기 동안은 pre-4.6 Claude 모델에 고정돼 있다는 것임.","실패 유형은 두 가지임. 라벨 앞에 서론(preamble) 텍스트가 붙는 것, 그리고 가끔 허용된 집합 밖의 라벨이 나오는 것.","실제로 이들이 쓸 수 있으면서 이 실패들을 해결하는 조치 두 가지는 무엇인가? (두 가지를 선택할 것)"],"728722395":["허용된 라벨을 프롬프트에 명시적으로 나열하고, 라벨이 그 집합을 벗어나는 응답은 거부하고 다시 시도하기."],"729497491":["고객이 한 메시지 안에서 이중 청구와 누락된 적립금을 신고하고, 반품 배송까지 물어봄.","지금 에이전트는 첫 번째 문제만 답하고 대화를 닫음.","문제를 쪼개는 것 말고, 가이드가 조사 단계에 권하는 실행 패턴은 무엇인가?"],"729554039":["검증(verification)이 실제로 끝나기 전에는 대화 뒷부분에서 에이전트가 process_refund에 도달하지 못하게 막아 줌."],"729603596":["문장 하나로는 에이전트가 매번 문구에서 실패 유형과 retry 여부를 다시 추론해야 하고, 그 문구는 다른 팀 소관임. 같은 실패라도 category와 retryable 플래그가 필드로 명시된 채 와야 함."],"730500240":["모든 도구 결과(tool result)를 구조화된 tool_result 블록으로 대화에 추가하기. 실패한 것까지 전부."],"732723865":["각 도구의 내부 구현 코드."],"734944645":["넷 다 경로 패턴(path pattern)을 쓴 규칙 파일(rule file)로 처리하기. 경로 스코핑(path scoping)이 범용 조건부 로더이므로, (iv)에는 vendored/를 포괄하는 패턴을 주고 (iii)에는 플래그 파일이 놓일 위치를 포괄하는 패턴을 주기"],"735371998":["Call 1은 schema-constrained 경로로 가기. loader가 사람 개입 없이 바로 파싱하므로, 그 경직성(rigidity)이 보장받을 가치가 있음."],"735848487":["실패 유형과 함께 실제로 시도한 쿼리를 그대로 포함하기."],"736435441":["소스를 가져온 순서."],"736645530":["두 그룹 다 사람 검토로 바로 넘기기. 추출 실패야말로 검토자가 있는 이유임."],"737091878":["출력의 문법적 정확성과 의미적 정확성을 둘 다 보장해 줌."],"738883191":["세 수치 다 너무 낮아서 믿을 수 없음. 아무것도 결정하기 전에 심어 둔 버그를 늘려서 실험을 다시 돌리기"],"739907402":["종합 출력에서 콘텐츠 유형에 맞게 렌더링하기. 전부 한 형식으로 바꾸지 말고, 금융 데이터는 표로, 뉴스는 산문으로, 기술적 발견은 구조화된 목록으로 내보내는 것임."],"740773257":["플랫폼 팀은 리포지토리에 대해 read_file, search_files, list_files를 제공하는 MCP server를 만들자고 제안하면서 \"에이전트가 코드를 다루는 방식을 표준화할 것\"이라고 주장함. 같은 팀은 또 에이전트가 회사 자체 개발한 릴리스 승인 시스템(release-approval system)에 티켓을 올리게도 해야 하는데, 이 시스템은 HTTP API는 있지만 공개 클라이언트(public client)는 없음.","구축 작업은 어디에 써야 하는가?"],"741178032":["이것을 forked 컨텍스트에서 실행되고 예상 인자(argument)를 선언하는 버전 관리되는 skill로 패키징하기. 이 제안은 타이밍에서 실패함. 그 절차가 필요한 시점에는 대상 디렉터리가 아직 만들어지지 않아서 어떤 경로 패턴도 매칭될 것이 없고, 반대로 그 파일들이 이미 존재하는 세션에서는 평범한 버그 수정에 9단계짜리 잡음을 끼얹게 됨."],"743051696":["각 실패를 category와 retry가 도움이 되는지 여부(transient, permission, validation), 그리고 이미 시도한 내용과 함께 반환해서 coordinator가 timeout은 재시도하고 나머지 둘은 다른 곳으로 보내게 하기."],"744252227":["--resume으로 \"checkout-migration\"을 이어가면서, 그 6개 파일에서 PaymentGateway가 PaymentProvider로 이름이 바뀌었다고 알려주기. 그러면 영향받은 부분만 다시 분석하기."],"744343113":["추출 호출의 temperature를 낮춰서 모델이 갱신 기간을 지어내지 않게 하기"],"745837212":["~/.claude/skills/ 아래에 다른 이름으로 개인용 변형을 만들고, 팀 skill은 그대로 두기"],"746302774":["에이전트가 티켓마다 세 가지 점검 중 무엇을 돌릴 가치가 있는지 스스로 판단하게 하기. 그래야 위험해 보이는 티켓에 예산이 쓰임."],"746412591":["중복 카테고리를 영구히 삭제하고, 그만큼 보안 카테고리를 넓히기"],"747463281":["루트 CLAUDE.md 안에 \"Resolver conventions\"라는 제목으로 넣은 섹션임."],"748305530":["소스 실패를 치명적 오류로 처리하기. 가져오기가 하나라도 실패하면 사람이 원인을 조사할 때까지 파이프라인을 멈추는 것임."],"750587923":["코디네이터(coordinator)가 하나로 합친 판정 대신 점검별(per-check) 상태를 보고하게 하기. 그래야 병합 게이트(merge gate)가 읽는 출력에서 빠진 점검이 눈에 보임."],"751347781":["예시 자체는 괜찮은데 라벨이 잘못 붙었음. 각각에 \"difficulty: easy\" 태그를 명시해 주면 모델이 기준을 잡는 데 도움이 됨."],"751811474":["봇의 출력을 개발자가 선택적으로 참여(opt-in)할 수 있는 별도 채널로 옮겨서, pull-request 댓글은 깔끔하게 유지하기"],"752177732":["자동화가 실수해도 뒷단에서 발견되도록 사람 검토 팀을 먼저 두 배로 늘리기"],"753198334":["분석을 밤마다 도는 독립 작업으로 쪼개서, 죽더라도 하룻밤치만 날아가게 하기"],"754701607":["에이전틱 턴(agentic turns)에 상한을 두고 CI 작업 타임아웃(timeout)을 늘려서 느린 밤에 작업이 중간에 끊기지 않게 하기. 승인 지연(approval stall)과 스크래핑 문제는 별개 사안이므로 나중 스프린트로 미루기"],"757934463":["tax_id 신뢰도 점수(confidence score)가 0.90 밑으로 떨어질 때마다 그 인보이스(invoice)를 사람 검토로 보내기. 신뢰할 수 없는 필드가 실제로 컴플라이언스 위험(compliance risk)을 만들어내는 원인이기 때문임."],"760007859":["그 변형(variant)을 같은 이름 /review로 user scope에 두기. 그러면 해당 실행에서만 팀 버전을 깔끔하게 오버라이드(override)하게 됨."],"760040501":["parse_resume가 300토큰으로 잘라낸 발췌본을 반환하게 해서, 이력서 60개 전부가 대화 하나 안에 여유 있게 들어가게 하기."],"762708310":["실패를 위로 전달할 때 어떤 쿼리를 시도했는지 같이 보고하기."],"762942532":["개발자들이 온보딩 기간에 코드베이스 관련 질문을 에이전트한테 물어봄.","질문마다 Grep/Read 탐색이 대규모로 일어나서 그 원본 출력이 대화를 가득 채우고, 다섯 번째 질문쯤 되면 에이전트가 앞에서 알아낸 것들을 잊어버림.","알맞은 아키텍처는 무엇인가?"],"763838094":["스킬은 하나로 두되, 지시문에 \"적용하기 전에 항상 확인할 것\"을 추가하기."],"764098056":["list_policy_categories와 open_policy_page를 하나의 list_policy_tree 도구로 합쳐서, 같은 탐색(discovery)을 네 번이 아니라 한 번의 호출로 끝내기"],"765482123":["뒷받침 증거가 가장 약한 발견 내용(출처가 하나뿐이거나, 스스로 불확실하다고 표시했거나, 다른 곳과 모순되는 것들)을 보내고, 시스템이 확실하다고 평가한 발견 내용 중에서도 한두 자리는 스팟 체크(spot check)용으로 남겨서 오판정(miscalibration)을 찾아내기"],"766314365":["84개 파일을 21개씩 4번의 pass로 나눠서 처리하고 결과(finding)를 합치기"],"767709976":["\"formatCurrency\"만 Grep하기. 래퍼는 어차피 호출자로 같이 잡히기 때문임."],"768215076":["여행 지원 에이전트가 \"항공편 재예약하고 호텔 날짜도 맞춰 달라\" 같은 요청을 처리함. 필요한 도구와 그 순서는 케이스마다 달라짐.","팀원 한 명이 모든 요청에 고정된 순서 하나(search_flights → book_flight → search_hotels → book_hotel)를 하드코딩하자고 제안함.","여기에 반대하는 가장 강한 근거는 무엇인가?"],"768703133":["발견된 세 가지 gap을 spec에 추가하고, 업데이트된 버전으로 다시 생성하기"],"769049078":["백오프(backoff)를 두고 기다렸다가 재시도하기. 결제 서비스가 일시적으로 이용 불가능한 상태일 수 있고, 나중에 다시 시도하면 성공할 수도 있음."],"770784803":["coordinator가 subagent의 finding이 도착할 때마다 자기 running notes에 바로 반영하게 해서, subagent가 끝났을 때 아무것도 사라지지 않게 하기"],"770842475":["모델이 확신하는 추출 결과는 자동 승인하고, 나머지는 검토자에게 넘기고 싶음.","모델은 필드마다 신뢰도 점수(confidence score)를 내놓음.","파일럿 결과, 신뢰도 0.9 이상으로 표시된 필드가 실제로 맞은 경우는 78%뿐이었음.","신뢰도 기반 라우팅을 실제 운영에 올리기 전에 무엇이 먼저 이뤄져야 하는가?"],"771139749":["그 폴더의 템플릿을 실제로 편집하는 동안에만 적용되는 추가 컨벤션."],"774482696":["질문 형태로 되어 있는 것은 무엇이든 coordinator를 거치지 않고 search subagent가 직접 답하게 하기"],"775410387":["중복을 피하도록 기존 테스트 파일을 컨텍스트에 넣어 주고, 테스트 표준과 가치 있는 테스트의 기준, 그리고 쓸 수 있는 fixture를 CLAUDE.md에 문서로 남기기."],"775856030":["세 번의 호출을 하나로 묶는 run_all_discovery 도구를 만들기"],"776708581":["리서치 coordinator가 감당을 못 하고 있음. 일시적인 검색 타임아웃, 단일 출처 충돌, 빈 결과까지 전부 coordinator를 거쳐 왕복하고, 이제 분류 작업이 컨텍스트 대부분을 잡아먹음.","책임 배분을 어떻게 다시 설계해야 하는가?"],"776877383":["대화 기록이 너무 길어서 오래된 메시지가 잘려 나가고 있음."],"777785967":["Grep. 파일 내용에서 그 패턴을 찾아줌."],"778083194":["lookup_order는 몇 달 동안 안정적으로 라우팅됐음.","지난주에 팀이 track_shipment(\"주문의 배송·배달 정보를 제공\")를 추가했고, 그 뒤로 \"배송 상태를 포함한 주문 상세를 조회\"라고 설명된 lookup_order가 배송 관련 질문의 절반을 받아가고 있음. 반대로 track_shipment는 환불 관련 주문 질의를 가져갈 때도 있음.","두 도구 다 코드는 바뀐 게 없음.","가장 효과적인 첫 단계는 무엇인가?"],"778263816":["너의 문서 분석(document-analysis) 서브에이전트(subagent)는 enrichment 도구가 문서를 건드리기 전에 register_source(URL, 발행처, 발행일을 기록함)를 반드시 호출해야 함.","문서 400건을 감사(audit)했더니 61건에서 register_source를 건너뛰었고, 그 61건 전부 출처 표기(attribution) 없이 보고서까지 그대로 올라갔음.","시스템 프롬프트는 이미 먼저 등록하라고 지시하고 있음.","가장 신뢰할 수 있는 해결책은 무엇인가?"],"778279676":["잘 고른 도구 이름. 모델은 설명 텍스트보다 이름에 훨씬 큰 비중을 두기 때문임."],"778304278":[".claude/rules/ 파일의 YAML frontmatter에 있는 paths 필드는 무엇을 제어하는가?"],"779196766":["코디네이터와 subagent로 이루어진 리서치 시스템에서, 코디네이터의 책임에 해당하는 것 2개는 무엇인가? (2개 고를 것.)"],"783220530":["모델이 그 줄을 계속 만들게 두고, column 체크에서 실패하는 줄은 뭐든 다시 요청하는 validation-and-retry loop를 추가하기."],"783463453":["60명 규모 platform org가 자기네 repository CLAUDE.md에 무엇을 담을지 정하는 중임.","그 안에 들어가면 안 되는 항목은 어느 것인가?"],"783831336":["frontmatter에 paths: [\"src/api/*.ts\"] 를 넣어서 .claude/rules/api-conventions.md 를 만들었음.","src/api/index.ts 를 편집할 때는 잘 작동하지만, 정작 API 코드 대부분이 있는 src/api/v2/handlers/payment.ts 나 src/api/middleware/auth/verify.ts 에서는 이 규약이 전혀 로드되지 않음.","규칙 파일 내용 자체는 제대로 적혀 있음.","무엇이 잘못된 것인가?"],"784764790":["영속 계층을 이슈 단위로 다시 짜기. 열려 있는 이슈마다 자기 구조화 레코드(주문 ID, 금액, 상태, 합의된 조치)를 갖게 하면, 동시에 진행되는 스레드끼리 사실이 섞여 오염될 수가 없음."],"784947627":["\"no_data\"를 치명적 오류로 보고, 보고서 생성을 멈춘 뒤 원인을 조사하기"],"785562069":["subagent들이 스캔 결과와 실행 결과를 분리한 구조화된(structured) result를 반환하게 하기. 그러면 \"실행할 수 없었음\"이 \"아무것도 못 찾음\"으로 표현될 수 없음."],"785868899":["멈추고 플랫폼 리드(platform lead)에게 구체적인 충돌 내용, 이미 확인한 것, 지금까지 확인된 호출 지점들, 그리고 보이는 선택지들을 함께 전달하며 에스컬레이션하기. 지시사항에 공백이 있고, 그걸 메울 수 있는 건 리드뿐임."],"786409136":["Ji-woo: stop_reason이 \"tool_use\"인 동안 계속 돌면서 요청된 도구를 실행하고, 도구 에러까지 포함해 모든 결과를 구조화된 도구 결과(tool result)로 대화에 추가하기. \"end_turn\"이 나오면 종료하기"],"787140402":["3단계 코드베이스 분석(구조 파악 → 의존성 추적 → 리팩터링 제안)이 자꾸 3단계에서 실패함. 2단계가 쏟아낸 장황한 의존성 덤프로 컨텍스트가 꽉 차서, 제안이 1단계에서 발견한 제약을 무시해 버림.","어떤 재구성이 가장 좋은가?"],"787478668":["리뷰어가 품질을 직접 걸러낼 수 있게, 한 번 실행할 때 테스트를 5개까지만 생성하도록 제한하기"],"788275458":["frontmatter는 메타데이터 전용이니까, 요구사항 3개를 스킬 프롬프트 본문에 지시문으로 적기"],"788735977":["이탈할 여지가 줄어들도록 max_tokens를 낮추기"],"789295553":["나머지 카테고리에 대한 신뢰를 되찾으려면 중복 카테고리를 일시적으로 끄기. 명시적 기준과 대조 예시(관용적인 설정 코드 대 진짜 중복)로 그 프롬프트를 개선하고, 라벨링된 테스트 세트를 통과한 뒤에만 다시 켜기"],"790338649":["실행 전체를 재시도 루프로 감싸서, 실패하면 분석을 처음부터 다시 돌리게 하기."],"792469919":["팀원들에게 영향이 가지 않게 하려면 개인용 실험 MCP server를 어디에 설정해야 하는가?"],"793704182":["fetch_url을 제약이 걸린 load_document 도구로 바꾸기. 가져오기 전에 URL이 내부 문서 도메인에 속하는지 검증해 주기 때문임."],"794316656":["어떤 컨벤션이 지금 팀원과 앞으로 합류할 팀원 모두에게 자동으로 전달돼야 함.","그것을 만족하는 위치 두 곳은 어디인가? (두 개 선택.)"],"795579625":["더 많은 주제 유형을 다루는 긴 스크립트를 써서, 처음 보는 경우까지 미리 대비하기"],"795954205":["등록 순서(registration order) 문제임. 더 자주 필요한 도구(tool)를 먼저 등록해두면 선택이 그쪽으로 쏠리면서 에러율이 줄어듦."],"797079195":["위키 구조는 서버가 탐색 가능한 콘텐츠로 노출하는 MCP resource로 게시하고, search_policy는 실제 조회를 수행하는 도구(tool)로 그대로 두기."],"797300701":["둘 다 괜찮음. 최종 리포트도 같고 총비용도 같기 때문임."],"797889091":["프롬프트에 \"어떤 경우에도 서명자를 추측하지 말 것\"이라는 경고를 넣기"],"798557971":["B임. 모델이 도구를 고를 때 쓰는 주된 근거가 설명이므로, 설명을 풍부하게 하면 새 구성요소를 하나도 늘리지 않고 근본 원인을 고칠 수 있음. 분류기를 두는 것은 설명으로 풀어야 할 문제를 우회하려고 새로운 실패 지점을 하나 더 만드는 셈임."],"798624745":["낯선 레이아웃을 만나면 모델이 경고를 출력하도록 요구하기."],"799012745":["MCP는 건너뛰고 두 API를 직접 호출할 수 있게 에이전트에게 raw HTTP 도구를 주기."],"799557433":["독자가 원본을 직접 확인할 수 있게 원시 소스 파일을 첨부하기"],"801654834":["세션을 다시 시작하고, 더 신중하라는 지시를 붙여서 분석을 다시 하기"],"801761996":["메인 에이전트가 조사를 직접 돌리게 해서 핸드오프(handoff) 과정에서 아무것도 안 놓치게 하기."],"804219347":["두 rewrite 모두 세션 하나로 진행해서 비교가 한 대화 안에서 이뤄지게 하고, 목요일에는 안전하게 새로 시작하기."],"806204678":["야간 의존성 감사(dependency-audit) 작업이 공유 러너(runner)에서 Claude Code를 호출함.","실패 양상이 두 가지 번갈아 나타나는데, 어떤 밤엔 오전 9시가 돼도 작업이 아무것도 만들어내지 못한 채 살아 있고 러너 로그의 마지막 줄은 셸 명령 승인 요청이고, 또 어떤 밤엔 작업은 끝나지만 38달러가 청구되고 트랜스크립트(transcript)를 보면 같은 파일 3개를 11번이나 다시 읽은 게 보임.","결과는 원래 대시보드로 들어가야 하는데, 지금은 대시보드가 정규식(regex)으로 텍스트를 긁어오는 방식임.","세 가지 증상을 다 해결하는 수정안은 무엇인가?"],"806869206":["대화가 열 턴을 넘어가는 것."],"807383419":["고객 질문에 답하는 대화형 챗봇."],"808338535":["context: fork 하나면 됨. 격리만 해두면 셸 실행도 막히고 인자 누락도 안 생기기 때문임."],"811140293":["repository server는 건너뛰기. 그 세 가지 작업은 이미 에이전트의 내장 file 도구로 커버되기 때문임. 그리고 다른 어떤 것도 접근할 수 없는 release-approval system(릴리스 승인 시스템)용 서버를 만들기."],"813347149":["단계별 목록 대신 목표와 통과 기준을 주기. 어떤 동작들을 반드시 커버해야 하는지(retry exhaustion, backoff 타이밍, idempotency를 포함해서) 그리고 무엇을 완료로 칠지를 명시하고, 서브에이전트가 작업의 근거로 삼을 module findings도 포함하기."],"815466240":["fetch 헬퍼가 non-200 응답을 구조화된 실패(structured failure)로 드러내게 하고, job이 불일치 0건이라고 보고하는 대신 읽지 못한 페이지를 명시하면서 보고서를 partial로 표시해서 발행하게 하기"],"815722902":["두 호출 다 예상 출력의 시작 부분으로 assistant 턴을 prefill하는데, 이게 JSON에서든 산문에서든 똑같이 통하는 유일한 기법임."],"815820554":["memory 파일의 그 줄을 \"NEVER force-push: this is a hard rule(절대 force-push 금지, 이건 무조건 지켜야 할 규칙)\"으로 다시 쓰고, 파일 맨 위, 가장 먼저 읽히는 자리로 옮기기."],"815927786":["매칭을 느슨하게 하려고 \"retry(\" 처럼 더 짧은 앵커 문자열로 Edit를 다시 시도하기"],"815932705":["process_refund는 세 가지로 실패할 수 있음. 결제 서비스가 타임아웃 나거나, 환불액이 주문 금액을 넘거나(잘못된 입력), 주문이 반품 기한을 지났거나(정책) 하는 경우임.","지금은 세 경우 모두 {\"isError\": true, \"message\": \"refund failed\"} 를 돌려줌.","에이전트가 각 상황에 맞게 대응하게 하려면 어떻게 재설계해야 하는가?"],"816828491":["어떤 케이스가 중요한지 확신이 안 설 때마다 subagent가 멈추고 coordinator에 물어보게 하기"],"817570512":["팀이 공유하는 /commit 명령을 자신의 메시지 스타일로 바꾼 개인용 변형을 만들고자 함. 다른 사람에게는 전혀 영향을 주지 않으면서.","어디에 두고, 이름은 무엇으로 해야 하는가?"],"817908751":["-p를 --output-format json으로 바꾸기. 플래그 하나로 비대화형 실행과 구조화된 출력을 둘 다 처리해 주기 때문임."],"818089564":["그 판단에 등장할 만한 단어(push, email, channel)로 파일 내용을 검색해서 어떤 파일이 걸리는지 보기"],"820628276":["릴리스 파이프라인이 열려 있는 pull request마다 하나씩 무인 리뷰 실행 세 개를 동시에 돌리고, 각 실행의 JSON 페이로드(payload)를 저장함.","다음날 아침 후속 조치가 두 가지 필요함.","PR #812라면 발견 사항(findings) 중 하나에 대해 확인 질문을 함.","PR #799라면 그 발견 사항에 따라 조치해야 하는데, 그 사이 해당 브랜치가 모듈 배치를 바꿔놓은 release 브랜치 위로 리베이스(rebase)됐고, 리뷰 대상이었던 14개 파일 중 11개가 다시 작성됐음.","맞는 처리 방법 두 가지는 무엇인가? (두 개 선택)"],"820735426":["추출을 JSON 스키마를 사용하는 tool use 방식으로 옮기기. 이게 지금 쓸 수 있는 가장 신뢰할 만한 구조화된 출력(structured output) 메커니즘이기 때문임."],"820864245":["작성(drafting) subagent(하위 에이전트)의 system prompt에 앞선 조사 단계의 세부사항을 계속 염두에 두라는 문구를 한 줄 추가하기"],"821877932":["최종 리서치 보고서가 출처도 없이 \"연구에 따르면...\" 이라고만 씀.","로그를 보면 subagent들은 분명히 URL을 돌려주었음. synthesis 에이전트가 요약하면서 그것을 날려버린 것임.","오래 가는 해결책은 무엇인가?"],"823716523":["tools 배열에서 extract_metadata가 맨 앞에 오도록 도구 목록 순서를 바꾸기."],"825089172":["거절(refusal) 응답은 실행 후에 평범해 보이는 tool result로 다시 구성해서, 모델이 원문 그대로의 거절을 읽는 대신 따뜻하게 풀어서 말할 수 있게 하기."],"825186548":["두 증상 모두 25회 반복 제한 때문임. 100회로 올리면 조기 종료와 중복 호출이 다 해결됨."],"825429209":["대조 쌍 만들기. 프로젝트에서 허용하는 패턴 예시에는 \"do not flag\"를, 진짜 버그인 빈 catch에는 \"flag\"를 붙여 나란히 두고, 둘을 가르는 근거까지 같이 적기."],"827246255":["묻지 않고 edit(수정)을 받아들이는 모드로 실행을 시작하고, review prompt 맨 앞에 리뷰어가 branch를 만들지 못하게 금지하는 줄을 넣기"],"828344647":["문서 추출(document-extraction) 서비스는 사람의 검토 없이 매일 밤 PDF 3만 개를 데이터 웨어하우스(warehouse)의 행(row)으로 변환함.","현재 설계는 프롬프트(prompt) 끝에 \"이 11개 키만 담은 JSON 객체만 반환할 것\"이라는 문구를 넣고 텍스트 응답을 파싱(parse)하는 방식인데, 밤 중 2.3%는 형식이 잘못된 출력 때문에 실패함.","팀은 최신 모델(current models)을 사용하고 있고, 요청 과정을 처음부터 끝까지 직접 제어함.","어떤 대안이 맞는가?"],"828360477":["6주 전에 금액이 500달러를 넘으면 언제든 process_refund를 막는 인터셉션 hook(interception hook)을 추가했음.","컴플라이언스 위반(compliance violation)은 0건이 됐음.","그런데 이 케이스들의 CSAT는 2.1까지 떨어졌고, 대화 기록(transcript)을 보면 패턴이 보임: hook이 거절을 반환하면 모델이 그걸 그대로 읽고, \"I'm not able to help with that\"라는 말로 끝나는 대화가 300건 넘게 나왔는데 고객한테 다음 단계는 전혀 없었음.","이 설계에서 빠진 것은 무엇인가?"],"829231307":["강조하려고 프롬프트에 형식 지시를 두 번 반복해서 넣기."],"830174964":["캐싱 레이어를 만든 그 세션이 자기 코드를 리뷰하고 \"eviction 로직은 문제없음\"이라고 결론 냈음. 그런데 프로덕션에서는 아니라는 게 드러났음.","반면 지난주에는 자기 비평(self-critique) 패스가 미완성 답변 문제를 진짜로 고쳐 줬음.","왜 결과가 갈렸고, 캐시 버그는 이제 어떻게 해야 하는가?"],"831234794":["리서치 팀 속도를 늦추는 문제가 두 가지 있음.","첫째, 세션이 시작될 때마다 에이전트가 내부 아카이브 서버(archive server)에 무엇이 있는지 알아내려고 list_collections, describe_collection, sample_documents를 호출하는데, 그 아카이브 구조는 분기에 한 번꼴로 바뀜.","둘째, 한 계약직 직원이 실험용 스크래핑(scraping) 서버를 리포지토리의 공유 설정(shared configuration)에 계속 추가하는데, 그때마다 분석가 두 명의 세션이 깨짐.","어떤 변경 두 가지가 맞는가? (두 개 선택)"],"833196247":["모든 업로드를 Batches API로 보내고, 배치(batch) 결과가 2초 예산 안에 도착하지 않을 때마다 동기(synchronous) 호출로 폴백(fall back)하기"],"835401376":["서브에이전트가 각 실패를 설명하는, 사람이 읽을 수 있는 문장을 쓰게 해서 coordinator가 그것을 읽고 판단할 수 있게 하기."],"836570476":["무언가에 답하기 전에 에이전트는 위키 구조를 다시 파악하려고 list_policy_categories와 open_policy_page를 호출하면서 턴(turn) 서너 개를 소모함.","구조 자체는 한 달에 한 번 정도 바뀜.","MCP server 자체 기능에 가장 잘 맞는 변경은 무엇인가?"],"836843098":["기존 test 파일들을 이번 run의 context에 넣어서, 추가 제안을 하기 전에 이미 커버된 시나리오가 무엇인지 먼저 보게 하기"],"836870336":["처리에 최대 24시간까지 걸릴 수 있고 지연 시간 SLA도 없음."],"837522309":["10분보다 오래된 것은 전부 점진적으로 요약(progressive summarization)해서, 스트림의 어떤 부분도 통째로 사라지는 일이 없게 하기."],"837618525":["코디네이터(coordinator)가 취합하기 전에 각 서브에이전트(subagent)의 실행 결과를 확인하게 하고, 예측 결과는 부분(partial)으로 표시하되(실행되지 않은 섹션 이름을 명시하면서) 결과물은 그대로 내보내기."],"839271368":["A. 결정적 라우터가 확률적 선택보다 낫고, 신뢰성 요구사항 앞에서는 언제나 결정적인 쪽이 유리하기 때문임."],"840176847":["리서치 플랫폼은 반복되는 업무 두 가지를 담당함.","Job A는 매달 나가는 경쟁사 브리핑으로, 같은 8개 회사를 대상으로 가격·자금 조달·채용·제품 출시·특허 출원이라는 같은 5개 섹션을 매달 똑같이 다룸.","Job B는 \"우리 엔터프라이즈 갱신이 EMEA에서 왜 줄었는지 알아내라\"는 과제인데, 어떤 시장·계약·지원 이슈가 중요한지는 아직 아무도 모름.","한 아키텍트는 두 작업에 똑같은 엔진 하나를 쓰자고 제안하는데, coordinator가 매 실행(run) 시작 시점에 하위 작업(subtask) 목록을 짜고 이후 절대 수정하지 않는 방식임.","어떤 설계가 맞는가?"],"840256685":["낯선 저장소에서 엔지니어가 두 가지를 해야 함. (a) 이름이 .config.ts로 끝나는 파일을 전부 찾기, (b) 상수 MAX_RETRIES가 실제로 참조되는 곳을 전부 찾기임.","어떤 조합이 맞는가?"],"840826228":["코디네이터의 대화 이력 전체를 종합 에이전트한테 넘겨서, 출처를 정리할 컨텍스트를 최대한 많이 주기."],"843253965":["checkout 모듈에 버그 리포트가 다섯 개 들어옴. #1과 #2는 둘 다 공유 CartState 캐시와 얽혀 있고, 지난 스프린트에는 하나를 고치니 다른 하나가 깨졌음. #3은 에러 메시지 오타, #4는 영수증의 날짜 포매터 고장, #5는 관련 없는 유틸리티의 누락된 null 체크임.","이를 Claude Code에 어떻게 넘겨야 하는가?"],"846553227":["요청 유형마다 관련 있는 도구만 활성화해 주는 라우팅 분류기."],"848042305":["가로채기 훅(interception hook)은 500달러가 넘는 process_refund 호출을 제대로 막고, {\"isError\": true, \"message\": \"blocked by policy\"}를 돌려줌.","운영 로그를 보면 에이전트가 똑같은 호출을 세 번 재시도한 다음 고객에게 \"이건 처리할 수 없습니다\"라고 말함. 사람에게 넘기는 에스컬레이션은 아예 일어나지 않고 있음.","설계를 완성하려면 무엇이 더 필요한가?"],"848697332":["(1) none, (2) auto, (3) any."],"849530212":["PostToolUse hook 안에서. 모델이 결과를 처리하기 전에 모든 등급 표현을 하나의 표준 형식으로 매핑해 주는 방식임."],"849734567":["subagent가 일상적인 복구를 자기 선에서 처리하게 하기. 일시적 실패는 재시도하고 충돌은 자기 출력에 표시해 두고, 스스로 못 푸는 것만 위로 올리는 것임. 코디네이터는 작업 설계, 위임, 종합을 계속 맡음."],"850478815":["고객 메시지에 요청이 두 개 들어 있음. (a) 주문 #B-2210 환불인데 반품 정책으로 전부 커버되는 건이고, (b) \"정신적 피해(emotional distress)\" 보상인데 정책에는 아예 언급조차 없는 내용임.","올바른 처리는 무엇인가?"],"851228186":["주장과 출처를 이어주는 정보. 어떤 진술이 어떤 출처에서 나왔는지를 URL이나 문서 이름과 함께 담은 것."],"851326683":["여기서 few-shot은 한계에 부딪힘. 애매한 회색지대 사례는 라벨링된 티켓으로 파인튜닝한 분류기가 필요함."],"851893959":["정확도를 문서 유형별·필드 구간별로 쪼개고, 확신도 높은 추출 건에 대해 층화 무작위 표본을 돌리기. 전체 수치는 정답률이 떨어지는 구간(예를 들면 71%짜리 손글씨 인보이스)을 가릴 수 있고, 자동화는 그걸 조용히 그대로 내보냄."],"853391102":["tool_choice를 제일 많이 쓰는 추출 도구로 고정해서 애초에 망설일 선택지 자체를 없애기"],"853707315":["이미 모든 subagent 결과를 본 coordinator가 직접 그 체크를 하게 하기."],"855011310":["생성한 쪽 세션은 컨텍스트 창이 너무 꽉 차서 제대로 리뷰할 수 없음."],"855065160":["그 예시 묶음은 모델이 이미 잘하는 것만 가르치고 있음. 그러니까 애매한 사례 2~4개로 바꾸되, 그럴듯한 다른 선택지를 제치고 왜 그 행동이 나은지 그 이유까지 넣기. 처음 보는 회색지대 메시지에까지 일반화되는 건 바로 그것임."],"855138589":["다음 작업 중에서 동적 적응형 분해 대신 고정된 순차 파이프라인(prompt chaining)을 써야 하는 것은 무엇인가?"],"855453480":["오류 보고를 억눌러서 subagent가 언제나 최선의 결과를 반환하게 하고 coordinator는 깔끔하게 유지하기"],"855870989":["리서치 목표와 품질 기준(커버리지, 출처 다양성, 최신성)을 정해주고, 접근 방식은 subagent가 발견한 내용에 맞춰 스스로 조정하게 두기."],"858862299":["없을 수도 있는 필드는 optional/nullable로 두고, enum에는 \"other\"와 상세 문자열, 그리고 \"unclear\" 값을 추가하기. 거기에 스키마와 나란히 프롬프트에도 형식 정규화 규칙을 명시적으로 넣기"],"859631182":["시나리오: CI 작업이 모든 풀 리퀘스트(pull request)마다 Claude Code를 실행하고 리뷰 코멘트를 올림.<br>상황: 이 작업은 TTY가 없는 GitHub Actions 컨테이너 안에서 돌아감.","CLI를 호출하고 리뷰를 기다렸다가 돌아온 텍스트를 그대로 올림.<br>증상: 실행의 3분의 2가 CLI가 여전히 대화형(interactive) 프롬프트에 멈춰 있는 채로 끝나고, 코멘트 본문이 비어 있음.","끝까지 완료되는 실행은 자유 형식(free-form) 텍스트를 올리는데, 코멘트 파서(parser)가 이걸 조용히 버림.<br>제약: 이 파서는 다른 팀 소유이고 엄격한 JSON만 받아들이며, 이번 분기에는 바뀌지 않을 것임.<br>질문: 두 증상을 한 번에 해결하는 단 하나의 변경은 무엇인가?"],"859757293":["\"여는 중괄호(opening brace)를 프리필(prefill)해서 JSON을 강제하던 서비스는 구조화된 출력(structured outputs)이나 JSON 스키마가 있는 도구로 옮겨가야 함.\""],"860684319":["응답을 기다리는 대신 프로세스가 완료되고 종료되도록 호출하기. 짧은 사전 승인 목록 밖의 건 전부 자동으로 거부(auto-deny)하는 모드로 시작해서 아무것도 멈추지 않게 하기. agentic 턴 수와 이번 실행이 쓸 수 있는 금액 둘 다 상한을 걸기. 그리고 스키마 검증(schema-validated)된 JSON을 내보내서 대시보드가 문장 대신 필드를 읽게 하기."],"861453005":["분기마다 원래 검증 세트를 다시 돌려서 모델이 여전히 통과하는지 확인하기"],"861632364":["메시지와 함께 실패 카테고리(category)와 retryable 플래그도 반환하기. timeout은 retryable로, 금액 초과(oversized amount)는 문제 필드 이름을 명시하고 retryable 아님으로, 마감된 창(closed window)은 에이전트가 고객에게 그대로 읽어줄 수 있는 문구와 함께 retryable 아님으로 처리하기."],"863477860":["claude --batch review-requests.txt --output json --no-interactive"],"865319102":["디스커버리 호출 결과를 시스템 프롬프트에 캐싱해 두고, 프롬프트는 매달 손으로 갱신하기"],"865528281":["(D). 동일한 패턴에는 동일한 판단을 내려야 한다는 걸 모델에게 다시 일러줘야 하기 때문임."],"865813967":["모든 extractor에게 네 가지 schema를 전부 주고 스스로 고르게 하기. 이러면 coordinator의 classification에 대한 의존을 완전히 없앨 수 있음."],"866452326":["새로 온 엔지니어가 알림 서비스(notification service)가 이메일을 보낼지 push 메시지를 보낼지 어떻게 정하는지 알아내야 함.","이 repo에는 파일이 1,100개 있고, 이 엔지니어는 아직 한 번도 열어본 적이 없음.","첫 행동으로 네 가지가 제안됨.","가장 쓸모없는 첫 행동은 어느 것인가?"],"867340425":["이메일 도메인이 일치하는 레코드를 고르기. 이메일이 지역번호보다 강한 신호이기 때문임."],"867876316":["결과가 실망스러울 때마다 코디네이터가 작업 도중에 스크립트를 고치게 하기."],"867952474":["서술형 메모는 그대로 두되 더 길고 구조적으로 만들기. 결과마다 불릿 요약을 붙이는 식으로 해서 토큰은 아끼면서 정보 손실은 줄이기."],"872802090":["시스템 프롬프트에 \"For anything involving documents, analyze thoroughly before answering\"라는 문장을 넣은 뒤로, 에이전트가 웹페이지 관련 질문을 extract_web_results가 아니라 analyze_document로 보내기 시작했음. 두 도구 다 설명은 충실히 적혀 있는데도 그러함.","가장 그럴듯한 원인과 해결책은 무엇인가?"],"873054070":["에러 피드백을 주면서 재시도하는 루프로 고칠 수 있는 실패 유형은 무엇인가?"],"873303009":["개발자 6명이 Jira MCP server를 함께 쓰고, 각자 개인 API 토큰을 갖고 있음.","팀원 한 명이 자기 토큰을 그대로 적어 넣은 .mcp.json을 커밋해버렸음. 그 토큰이 지금 git 히스토리에 남아 있음.","앞으로는 어떻게 설정하는 것이 맞는가?"],"873550889":["세션을 재개하고, 저장소 전체 포매팅(formatting) 작업이 공백과 import 순서만 바꿨다고 에이전트에게 말해줘서, 정확한 줄 참조가 중요한 곳에서만 파일을 다시 읽게 하기."],"873981062":["같은 리뷰를 세 번 돌려서 다수결로 정하기."],"875267660":["context: fork 하나면 충분함. 격리만 해도 파일 수정이 자동으로 막히고 누락된 인자도 알아서 처리되기 때문임."],"875889130":["진행되는 대로 매 turn을 판단해서, 인용문·수치·날짜가 담긴 turn은 원문 그대로 남기고 나머지는 버리기. 무엇을 남겨야 하는지 목록은 실행이 시작되기 전에는 쓸 수가 없기 때문임."],"877577889":["각자 다른 계약(contract)을 가진 도구들(find_symbol_definition, list_dependents, get_file_owner)로 나누기. 이때 각 도구는 자기만의 입력값과, 어떤 요청을 처리하고 어떤 요청은 처리하지 않는지 밝히는 설명을 갖추기."],"879721225":["신뢰도 기반 라우팅을 버리고 대신 무작위로 20%를 검토하기."],"879911558":["subagent 하나한테 문서 세 개를 순서대로 다 분석하라고 시키기"],"880747828":["이번 주에 운영 사고가 두 건 났음. (a) get_customer가 \"J. Kim\"이라는 고객을 3명 돌려줬는데 에이전트가 가장 최근에 활동한 사람을 골랐고, 그것은 틀린 선택이었음. (b) 고객이 경쟁사 가격에 맞춰달라고 요청했는데, 정책은 자사 사이트의 가격 인하만 다룸. 그런데도 에이전트가 10% 호의 할인을 지어냈음.","올바른 행동 조합은 무엇인가?"],"881808071":["스키마 위에 semantic check를 추가하기. confidence가 허용 범위 안에 있는지, 모든 claim이 source 목록에 실재하는 source id를 갖고 있는지 확인하는 식으로. 스키마를 만족시키면서도 말이 안 되는 값이 있을 수 있기 때문임."],"882237816":["법무팀은 네 계약서 추출기가 조항을 분류해 주길 원함.","변호사들이 새로운 조항 유형을 계속 만나서 조항 분류 체계(taxonomy)가 매달 바뀜.","지금 enum은 고정값이 15개뿐이라, 처음 보는 조항을 가장 비슷한 기존 범주로 잘못 분류함.","계속 바뀌는 분류 체계를 감당하려면 스키마를 어떻게 설계해야 하는가?"],"882314125":["고객의 첫 메시지임. \"당신네 앱이 내 플레이리스트를 지웠어요.","사람 바꿔줘요.","당장요.\" 플레이리스트 복구는 클릭 한 번으로 되는 작업이라 에이전트 능력 범위 안에 충분히 들어옴.","올바른 행동은 무엇인가?"],"882781638":["개발자들이 봇 판단에 동의하지 않을 때 심각도를 투표로 정하게 하기."],"883130644":["둘 다 skill로 만들기. 개발자가 필요할 때 /terraform-style이나 /new-endpoint를 직접 호출하는 것임."],"884833948":["프로젝트의 rules 폴더 아래에 두는 규칙 파일(rule file)로, frontmatter에 그 두 디렉터리 트리에 대한 패턴을 적어 두면 그런 파일을 편집할 때만 핸드북이 컨텍스트(context)에 들어오고 다른 세션은 전혀 이를 갖고 있지 않게 됨."],"885109645":["떠오르는 캐싱 관련 고려사항을 전부 나열한 더 긴 프롬프트를 주기."],"885115093":["반복 개선 루프(iterative refinement loop)를 하나 붙였음.","\"아프리카의 양자 네트워킹 스타트업\"이라는 주제에서 코디네이터(coordinator)가 지금까지 개선 사이클을 여섯 번 돌렸음. 타깃 재검색은 계속 똑같이 빈약한 소스 세 개만 돌려주고 재종합 결과도 거의 바뀌지 않음.","비용은 계속 불어나는 중임.","올바른 설계 대응은 무엇인가?"],"886295980":["모델의 컨텍스트 창이 숫자부터 먼저 잘라내기 때문임."],"886479548":["요약 주기를 매시간에서 15분마다로 줄이기"],"887452216":["hook의 에러 메시지를 더 친절한 표현으로 고쳐 써서 에이전트가 고객에게 그대로 전달할 수 있게 하기."],"888159005":["새 개발자가 저장소를 클론하고 Claude Code를 실행했는데, 팀이 쓰는 GitHub MCP 도구가 하나도 보이지 않음. 다른 사람들은 다 갖고 있음.","팀 리드가 확인해 보니, 자신의 컴퓨터에서는 서버가 잘 돌아가고, 저장소의 .mcp.json에는 그 서버 이야기가 아예 없으며, 자신의 ~/.claude.json 안에는 토큰이 하드코딩된 서버 정의가 통째로 들어 있음.","무슨 일이 벌어진 것이고, 올바른 해결책은 무엇인가?"],"888524894":["정신적 피해 주장에 대해 소액의 호의 크레딧을 제안해서 한 번의 접촉으로 두 건을 다 마무리하기."],"889171354":["환불을 전부 로그로 남기고 위반 건은 주 단위로 감사하기"],"889540575":["allowedTools에서 WebSearch를 빼서 코디네이터(coordinator)가 위임할 수밖에 없게 만들기"],"889925521":["한 번 답하고 종료하도록 호출하고, 프로젝트 컨텍스트(context) discovery를 건너뛰는 플래그를 추가해서 모든 runner가 동일한 상태에서 시작하게 하고, agentic 턴 수에 상한을 둬서 밤새 돌아가는 일이 없게 하기."],"889930536":["stop_reason이 \"end_turn\"이고 코디네이터가 최종 종합(synthesis)을 만들어냈을 때 멈추기"],"891080625":["핵심 발견과 제약을 찾는 대로 스크래치패드 파일에 기록해 두고 이후 프롬프트에서 그것을 참조하기. 다음 단계로 넘어갈 때는 먼저 발견 내용을 요약하고, 장황한 탐색 출력을 비우려면 /compact도 고려해 보기"],"891088335":["보내기 전에 모델이 답변이 공감되는지, 전문적인지, 간결한지 스스로 묻는 self-review 단계를 추가하기"],"891415259":["배치를 쓰되 늦어지는 문서는 \"processing\"으로 표시하기. 고객이 24시간 전에 확인하는 경우는 드물기 때문임."],"891707067":["고객지원 운영 에이전트는 '내 주문이 아예 안 왔어요' 티켓을 처리함.","모든 티켓은 똑같은 네 단계를 거침. 주문 확인, 배송사 상태 조회, 환불/재발송 정책 적용, 고객 답변 작성 순이고, 정책 단계의 분기 표(branch table)는 런북(runbook)에 전부 적혀 있음.","신입 엔지니어가 '특이한 티켓에도 대응할 수 있게' 이것을 동적 분해(dynamic-decomposition) 에이전트로 다시 만들자고 제안함. 가장 타당한 반응은 무엇인가?"],"891899146":["재고 도구가 상품에 정말 재고 기록이 없을 때도, 데이터베이스가 타임아웃될 때도 똑같이 []를 반환함.","그래서 DB 장애 중에 에이전트가 고객한테 \"재고 없음\"이라고 말해 버리는 일이 생김.","고쳐야 할 지점은 어디인가?"],"891949719":["추출 단계는 반드시 구조화된 데이터를 돌려줘야 하고 일반 대화체 텍스트는 절대 안 됨. 다만 추출 도구 세 개 중 어느 것을 쓰든 상관없음.","어떤 tool_choice 설정이 맞는가?"],"893845908":["allowed-tools는 파일 쓰기/읽기 작업으로만 제한하고(Bash는 제외), 엔드포인트 이름을 위한 argument-hint를 붙이기. 스캐폴드 출력이 작으므로 context: fork는 선택 사항임."],"895180881":["Bash로 sed 명령을 돌려서 네 군데를 한 번에 치환하기"],"895312130":["작업 전체 동안 편집 불가능한 계획 모드를 유지해서 모든 단계가 검토 가능하게 하고, 승인은 마지막에 받기"],"898386843":["작업량을 문서 5,000건짜리 배치 네 개로 쪼개서 승인하기. 배치가 작을수록 그만큼 비례해서 빨리 끝나기 때문임."],"898678295":["예상 밖의 문자열을 edit distance(편집 거리) 기준으로 넷 중 가장 가까운 것에 매핑하는 후처리(post-processing)를 적용하기."],"899207391":["에이전트에게 \"온보딩 퍼널이 3단계에서 40% 떨어지는 이유를 찾아내고 고칠 것\"이라는 지시가 내려졌음. 엔지니어링 리드는 코드를 변경하기 전에 반드시 문서화된 계획을 요구함.","원인은 현재 알 수 없는 상태임.","이 작업의 성격에 맞는 계획 수립 방식은 무엇인가?"],"899824709":["Plan mode는 계획이 승인될 때까지 편집을 붙잡아두는데, 새벽 3시에는 승인해줄 사람이 없음. 이 단계는 설계상 그대로 멈춰버림.","대신 사람 없이 돌아가면서 제안된 변경을 검토 가능한 산출물(artifact)로 만들어내는 단계와, 사람이 승인한 뒤에만 그걸 적용하는 후속 단계로 나누기."],"900044595":["정책 문서가 그 고객의 구체적인 요청에 대해서는 아무 말도 없음."],"900722137":["가장 최근 턴(turn)들에 대한 슬라이딩 윈도(sliding window): 그보다 오래된 건 전부 그냥 버리고, 남겨두는 알림 텍스트는 그대로 정확히 유지하고, 이걸 유지하기 위해 별도로 돌아가는 건 없음."],"900868986":["아무것도 건너뛸 수 없게, 필수 섹션 헤더가 있는 응답 템플릿을 강제하기"],"901137436":["diff에 lockfile이나 handler 파일이 나타날 때마다 로드되는 path-scoped rule 파일 하나로 둘 다 표현하기"],"903924690":["완성된 scaffold를 생성 과정의 추론을 전혀 본 적 없는 새 instance에 넘기고, 코드만 보고 리뷰하게 하기"],"904740577":["프로젝트 레벨임. 저장소에 커밋되는 .claude/CLAUDE.md나 루트 CLAUDE.md임."],"904933507":["개발자가 머지하기 전에 기다리는 머지 전 PR 검사임."],"905281466":["라벨이 달린 데이터 집합(labelled set)을 채점해서 0.9라고 말한 값이 실제로 90% 정답률을 의미했는지 확인하기. calibration이 안 된 self-report는 threshold의 근거가 될 수 없음."],"905968806":["argument-hint에서 그 인자를 필수로 표시해서, 모드를 명시하지 않으면 skill이 실행되지 못하게 하기."],"906130065":["셋 다 프로젝트 CLAUDE.md에 넣기. command와 skill을 같이 쓰는 것보다 움직이는 부품이 적기 때문임."],"908433740":["세션을 재개하되 competitor 목록이 교체됐다는 사실과 오전 결론 중 어느 것이 그 목록에 근거하는지 명시적으로 말하기. 그래야 에이전트가 그 파일을 다시 읽고 영향받은 분석을 다시 하게 됨. 그런 다음 재개한 세션을 두 브랜치로 fork해서 공유된 기준선(baseline) 하나에서 두 프레이밍(framing)을 비교하기."],"908690117":["tool_choice: \"any\"로 설정해서 모델이 추출 도구 중 하나를 반드시 부르게 하기. 산문 응답을 말리는 게 아니라 구조적으로 아예 못 나오게 막는 것임."],"908963178":["코디네이터가 통합 리포트를 초록색(green)으로 올리는 대신, 실행되지 않은 스캔의 이름을 밝히면서 부분(partial) 상태로 표시하게 하기"],"909145048":["모든 초안을 내보내기 전에 독립된 두 번째 Claude 인스턴스로 보내서 리뷰받기."],"909329571":["그 개발자 쪽 프로젝트 CLAUDE.md가 손상됐으니 다시 클론해야 함."],"910340083":["휴리스틱으로 분기하기. 따옴표로 묶인 문자열은 find_text, 나머지는 전부 search_code."],"911189352":["포맷 설명을 출력이 만족해야 하는 소수의 어서션(assertion) 집합으로 바꾸고, 통과할 때까지 반복(iterate)하기."],"911461766":["뭔가 보고하기 전에 isError 결과가 나오면 에이전트가 두 번 재시도하게 하기. 이러면 카테고리 없이도 타임아웃(timeout)까지 다 커버됨."],"911835086":["추출 파이프라인이 구조가 제각각인 연구 논문을 처리함. 어떤 논문은 본문 안에 인용을 달고 어떤 논문은 참고문헌 목록을 쓰며, 어떤 논문은 방법론 섹션이 따로 있고 어떤 논문은 방법을 결과 안에 섞어 놓았음.","문서 안에 정보가 분명히 있는데도 필수 필드가 null로 돌아오는 일이 잦음.","가장 좋은 해결책은 무엇인가?"],"911871921":["그 상수에 디버거 중단점을 걸어 두고 Bash로 앱을 실행하기."],"913652043":["둘 다 이런 종류의 실패를 없애주는데, 하나는 tool의 이름과 입력을 schema에 맞춰 보장하고, 다른 하나는 응답 내용 자체를 제한함. 어느 쪽을 고를지는 그 호출이 개념적으로 tool invocation(도구 호출)인지에 달려 있음.","둘 다 형식은 맞지만 값 자체가 틀린 경우는 건드리지 못함."],"913795935":["CI 자동화용으로 Claude Code가 기계가 파싱할 수 있고 스키마를 지키는 출력을 내게 하려면, 어떤 플래그 조합을 써야 하는가?"],"914708535":["glob 패턴 src/api/*.ts는 src/api/ 바로 아래 파일만 매칭하고 중첩된 하위 디렉터리는 매칭하지 못함. src/api/**/*.ts로 바꿔서 어느 깊이에서든 규칙이 걸리게 하기."],"915272725":["별도의 분해 모델임. 에이전트가 보기 전에 용건을 쪼개 두면 그 실패 양상 자체가 사라지기 때문임."],"916238340":["에이전트가 특정 실패에 과적합하지 않도록 무작위로 만든 에러 코드."],"919666873":["공유 skill에 flag를 추가해서, 요청받았을 때만 Terraform stub을 생성하게 하기"],"920128308":["현재 15개 범주에 없는 조항이 들어간 문서는 거부하기."],"920486948":["먼저 파일별로 요약하고, 그 요약만 놓고 리뷰를 한 번에 돌려서 전부 집중된 한 패스에 담기"],"921465566":["process_refund는 서로 다른 세 가지 방식으로 실패함: 결제 타임아웃, 주문 총액을 초과하는 금액, 마감된 반품 기한. 이렇게 셋 다 똑같은 isError payload로 돌아옴.","에이전트가 각각에 맞게 제대로 대응하게 하려면 어떻게 재설계해야 하는가?"],"923298026":["프롬프트를 \"JSON만 반환할 것.","서두 설명 없이, 코드 펜스(code fence) 없이, 뒤에 부연 설명도 없이.\"라는 식으로 더 명확하게 다듬고 파싱에 실패하는 응답은 재시도하기"],"923955914":["1번과 2번은 한 메시지에 자세히 같이 담아서 공유 상태가 얽힌 부분을 한꺼번에 풀기. 3번, 4번, 5번은 서로 독립적이니 순차적으로 따로 고치기."],"924884797":["결제 모듈 내부를 다룬 400줄짜리 walkthrough인데, 그걸 만지는 엔지니어 두 명한테만 필요함."],"925344880":["coordinator는 요청이 들어올 때마다 웹 검색, 문서 분석, synthesis, 보고서 생성으로 이루어진 전체 파이프라인(pipeline)을 매번 다 돌림.","요청 2,000건을 대상으로 한 텔레메트리(telemetry)를 보면, 46%가 \"Acme의 2024년 직원 수는?\" 같은 단일 사실 조회(single-fact lookup)였고, 건당 평균 41초에 subagent 호출 4번이 들었음.","Product 팀은 진짜 리서치 브리프의 깊이는 잃지 않으면서 5초 이내 조회를 원함. 무엇을 바꿔야 하는가?"],"925605773":["첫 번째 형태만 재시도하되, 구체적인 validation 에러와 문제가 된 값을 덧붙여서 수정할 근거를 주고, 시도 횟수는 제한하기. 두 번째 형태는 어떤 재시도로도 고칠 수 없는 콘텐츠 결함으로 보고, 그 finding들은 대신 폐기하거나 라우팅하기."],"925887623":["코드를 생성한 그 session이 테스트도 같이 생성하게 하기. 자기가 무엇을 썼고 무엇이 테스트되지 않았는지 이미 알고 있기 때문임."],"926940197":["subagent 응답 길이에 상한을 둬서 narration이 잘리게 하기"],"927643566":["CI 리뷰어는 자격증명처럼 생긴 리터럴(literal)을 발견할 때마다 온콜(on-call) 보안 엔지니어에게 티켓을 엶.","엔지니어들은 이 티켓이 쓸모없다고 함. 각 티켓에는 finding 문장 하나와 파이프라인 실행 링크만 있는데, 누가 보러 갈 때쯤이면 그 실행의 로그는 이미 만료되어 있음.","최근 9건 중 3건은 \"cannot reproduce\"로 닫혔음. 인계(handoff)에는 무엇이 담겨야 하는가?"],"927675367":["컨벤션 묶음을 각각 슬래시 명령으로 바꿔서, 개발자가 편집 전에 실행하게 하기"],"928910448":["Batches API는 도구 정의가 들어간 요청을 전부 거부함."],"929022030":["다음 단계를 시작하기 전에 각 단계의 핵심 결과를 요약하고, 그 요약을 다음 단계의 초기 컨텍스트에 넣어주기. 그리고 출력이 장황한 추적 작업은 구조화된 결과만 돌려주는 subagent에 맡기기."],"931378566":["nightly run을 다시 동기 호출(synchronous call) 방식으로 되돌리기. 순서 보장이 할인보다 더 가치 있기 때문임."],"931657994":["한 번 답하고 종료하도록 실행하고 러너(runner)가 일회용이니까 권한 검사(permission checking)는 아예 꺼버리고 산문(prose) 출력은 그대로 두면서 dashboard의 패턴만 더 엄격하게 만들기."],"932109056":["이름 변경은 굳이 언급하지 말고 세션을 재개하기. 에이전트가 다음에 파일을 읽을 때 알아서 변화를 알아챌 것임."],"933721680":["이름이 완전히 똑같은 개인 skill을 만들어서 팀 skill을 덮어쓰기"],"934052497":["네 subagent의 문서 가져오기 도구가 타임아웃으로 간헐적으로 실패함.","팀은 복구 로직을 어디에 둘지를 놓고 논쟁 중임.","베스트 프랙티스대로면 subagent는 어떻게 해야 하는가?"],"935282804":["(a)와 (c)는 저장소 메모리 파일에 넣고, (b)는 새 서비스가 결국 위치할 경로로 범위를 한정한 규칙 파일(rule file)에 넣기"],"936758103":["provider의 raw stack trace를 메시지에 그대로 붙여서, 에이전트가 뭐가 잘못됐는지에 대해 얻을 수 있는 정보를 최대한 갖게 하기"],"936861164":["파일 84개짜리 pull request를 금요일 전까지 리뷰해야 함.","84개 파일 전체를 한 번에 훑었더니 findings가 대략 20번째 파일을 넘어가면서 확 줄어들었고, 파일 3에서 이름이 바뀐 helper가 파일 61에서는 여전히 옛 이름으로 호출되고 있는 것을 놓쳤음.","어떤 분해(decomposition) 방식이 맞는가?"],"939497752":["최근 N턴을 대상으로 하는 슬라이딩 윈도우(sliding window) 방식임. 창 밖으로 벗어난 턴은 통째로 버려지고 창 안에 있는 턴은 한 글자도 안 틀리고(byte-for-byte) 그대로 남으며 이것을 유지하려고 따로 도는 것도 없음."],"940196713":["\"prompt 수준의 형식 지시는 JSON schema로는 표현할 수 없는 형식까지 다룰 수 있어서 가장 유연한 방법이지만, 확실한 보장은 없음.\""],"941380825":["원본 결과 전체가 항상 들어가도록 컨텍스트 창 예산을 늘리고, 비용이 진짜 문제가 될 때만 압축을 다시 검토하기"],"942044992":["여러 단계로 나뉜 작업임. 먼저 큰 코드베이스를 탐색하고, 그다음에 수정안을 설계하고 구현해야 함. 탐색 단계에서는 파일 목록과 검색 결과가 수천 줄씩 쏟아짐.","지난번 시도에서는 구현을 시작할 때쯤 메인 대화가 탐색 노이즈로 가득 차서 Claude가 설계를 놓쳐버렸음.","구조적으로 가장 나은 해법은 무엇인가?"],"943697201":["네 에이전트가 똑같은 인자로 같은 검색 도구를 계속 호출하면서 전혀 진행되지 않음.","로그를 보니 도구 결과(tool result)를 대화에 추가하지 않고 실행 뒤에 그냥 버리고 있음.","이게 왜 무한 루프를 만드는가?"],"944276288":["형태를 문장에서 유추하지 않아도 되도록 실제로 채워 넣은 전/후(before-and-after) 예시를 두세 개 주고 정확히 실패한 입력을 실제로 나온 결과 및 나왔어야 할 결과와 함께 명시하고 값 누락 세 가지 케이스는 같은 헬퍼에서 만나는 문제이므로 한 묶음으로 전달하기."],"944309573":["마이그레이션 디렉터리마다 CLAUDE.md 파일을 하나씩 두기."],"945012513":["프롬프트 지시는 확률적으로 따라지는 거라, 지시 문구를 어떻게 쓰든 검증을 건너뛰는 호출이 0보다 큰 비율로 나옴."],"947377178":["Team A → 고정된 순차 파이프라인(fixed sequential pipeline, 계약별 처리 + 계약 간 교차 처리), Team B → 동적 분해(dynamic decomposition)."],"947852294":["월요일 세션을 그대로 두 갈래로 포크하고, 각 갈래에 파일 변경 사항을 따로 알려 주기"],"948621014":["bot이 반드시 보고해야 하는 카테고리(correctness, security, data loss)를 나열하고, 반드시 건너뛰어야 하는 카테고리도 나열하기. 그중에 formatting도 포함시켜서."],"948713176":["둘 다, 저장소(repository) 전체를 버퍼 하나로 이어붙이는 shell 명령을 실행해서 스캔하기"],"950074011":["프리필(prefill)은 유지하되 assistant 메시지를 대화 앞쪽으로 옮겨서, 마지막 턴 제약을 피해 가기"],"950967613":["notification 디렉터리 아래 파일들을 이름 패턴으로 나열해서 서비스가 어떻게 구성돼 있는지 보기."],"952381013":["루트 CLAUDE.md는 그대로 두되, Claude가 어느 절을 적용할지 알 수 있게 더 명확한 섹션 제목을 붙이기."],"952999275":["lookup_order는 호출 한 번에 44개 필드를 돌려줌(창고 코드, 배송사 내부 값, 감사 메타데이터 등). 그중 환불 판단에 의미가 있는 건 6개 정도임. 게다가 날짜는 백엔드마다 서로 다른 세 가지 형식으로 들어옴.","이런 결과가 쌓이면서 긴 대화의 품질이 떨어지고, 에이전트가 가끔 날짜를 잘못 비교함.","두 문제를 한 번에 잡으려면 어디를 손보는 게 맞는가?"],"953209037":["플랫폼 팀은 \"새 마이크로서비스(microservice) 만들기\" 절차를 한 달에 두 번 정도 실행함. 아홉 단계, 파라미터 네 개로 이루어져 있고, 아직 존재하지 않는 디렉터리에 파일 약 40개를 만들며, 작업 대화창에는 아무도 원하지 않는 템플릿 목록을 수천 줄씩 출력함.","개발자들은 대상 서비스 이름을 넣는 것을 늘 깜빡함.","한 팀원은 paths: [\"services/**\"]로 범위를 지정한 규칙 파일(rule file)을 제안해서, 누구든 services 트리에서 작업할 때마다 절차가 자동으로 로드되게 하자고 함.","올바른 메커니즘은 무엇이고, 이 제안의 문제는 무엇인가?"],"954730762":["문구를 \"be extremely conservative and exclude anything you are not fully confident about.\"로 더 엄격하게 다듬기"],"955381701":[".ts와 .yaml 파일을 이름 패턴으로 전부 나열한 다음 그 switch가 더 이상 나오지 않을 때까지 순서대로 읽어보기. 확장자를 보면 설정이 어디에 있을 수 있는지 알 수 있음."],"957764827":["그것을 저장소 루트(repository root)에 있는 메모리 파일에 커밋하기"],"959113051":["둘 다 만들지 말고 릴리스 승인 시스템은 그 HTTP API에 대고 셸 명령(shell command)으로 직접 다루기."],"960455501":["회사는 Claude 기반으로 사내 문서 서비스를 운영하며, 두 경로가 하나의 추출 프롬프트(extraction prompt)를 공유함.","야간 경로(nightly path)는 밤 11시까지 도착이 끝나는 스캔된 공급업체 송장과 계약서 약 4만 건을 받아 각각에서 14개 필드를 추출하고, 중간에 사람 검토 없이 그 행들을 바로 재무 데이터베이스에 적재함.","재무팀은 주간 마감 때 그 행들을 대조하므로 야간 적재가 하루 종일 걸려도 괜찮고, 문서 한 건당 처리 시간을 누구에게도 약속한 적이 없음.","대화형 경로(interactive path)는 직원이 문서 한 건을 직접 업로드하는 웹 폼으로, 페이지가 대기하는 동안 추출된 필드를 봐야 하며 제품 예산상 2초 이내여야 함.","이번 달에 불만이 세 건 들어왔음.","첫째, 야간 응답의 약 0.5퍼센트가 JSON을 설명 문장으로 감싼 채로 왔는데, 로더(loader)는 그 엉뚱한 문장이 아니라 행 전체를 거부했음.","둘째, 총액을 항목별 표(line-item table) 대신 페이지 하단(footer)에 인쇄한 송장은 total 값이 null로 돌아오고, 두 공급업체의 송장은 배송 주소를 청구 주소(billing address) 필드에 집어넣는데, 그 파일을 여는 사람이라면 누구나 두 값을 다 읽을 수 있는데도 그러함.","셋째, 재무팀장은 다음 주까지 아무도 결과물을 열어보지 않는데 야간 실행(nightly run)의 문서당 비용이 왜 대화형 실행과 같은지 알고 싶어 함.","모델, 14개 필드, 그리고 2초짜리 대화형 예산은 이번 분기 동안 전부 고정임."],"961332322":["subagent가 되물었다는 것은 그 시스템 프롬프트에 자율적으로 판단하라는 지시가 빠져 있다는 뜻임."],"961358789":["에이전트가 고객에게 뭐라고 말하기 전에 실패한 환불을 3번 재시도하게 하기."],"961720986":["네 사용자 스코프(~/.claude/commands/)에 /my-commit 같은 다른 이름으로 두기. 이름이 같으면 개인 명령이 너한테만 팀 명령을 가려 버려서 동작을 디버깅하기 헷갈려지기 때문임."],"963082444":["팀은 매달 하는 archive 재스캔(문서 60만 건, 결과는 그다음 주에 확인)을 Message Batches API로 옮기자는 근거를 정리함.","이 정리 내용 중 정확하지 않은 줄은 어느 것인가?"],"964136446":["먼저 payment 모듈을 읽고, export하는 심볼을 전부 나열한 다음, 그 심볼들을 찾으면서 테스트 파일 340개를 하나씩 읽기"],"965520605":["두 값을 모두 담고 각각의 출처를 명시해서 분석을 마무리한 다음, 어느 쪽으로 정할지는 코디네이터가 결정하게 하기. 충돌은 그 자리에서 해결할 오류가 아니라 보존하고 드러내야 할 데이터이기 때문임."],"965528636":["네 파이프라인에는 인보이스, 계약서, 선적 명세서가 섞여 들어오고, 각각 자기 스키마를 가진 추출 도구 세 개(extract_invoice, extract_contract, extract_manifest)가 있음.","요청 시점에는 문서 유형을 알 수 없고, 응답은 항상 구조화된 출력이어야 함. 대화체 텍스트는 절대 안 됨.","어떤 tool_choice 설정이 맞는가?"],"966587965":["-p 플래그로 비대화형(non-interactive) 실행을 하면서 --output-format json도 같이 써서 CLI를 호출하기. 그러면 실행이 절대 입력을 기다리지 않고, 이미 있는 파서로 출력을 파싱할 수 있음."],"968319039":["패키지 9개짜리 모노레포(monorepo).","루트 메모리 파일은 패키지마다 자기 기준을 계속 덧붙이는 바람에 1,100줄까지 늘어났음.","packages/mobile에서 작업하는 세션은 절대 건드리지 않을 Go 서비스 컨벤션(convention)과 Terraform 규칙까지 불러오고, 정작 모바일 팀이 신경 쓰는 규칙 세 개는 940번째 줄 근처에 묻혀서 눈에 안 띔.","올바른 재구성 방법은 무엇인가?"],"969047386":["Claude가 보고된 버그 다섯 개를 하나씩 고쳤는데, 고칠 때마다 앞서 고친 것 중 하나가 깨졌음. 버그들이 같은 모듈에서 상태를 공유하고 있기 때문임.","베스트 프랙티스는 무엇을 권하는가?"],"970145915":["무작위 로테이션. 하룻밤에 관심사 하나씩, 사흘 주기로 돌리기."],"971422846":["헤더 합계(header total)를 출력하기. 명시된 합계는 문서 스스로가 밝힌 주장이지만, 항목별 내역은 그냥 불완전할 수도 있기 때문임."],"971509461":["다섯 개를 한 메시지에 다 넣기. 한 번에 종합적으로 훑으면 빠뜨리는 게 없고 Claude도 전체 맥락을 갖게 됨."],"973319361":["매일 밤 실행되는 작업(job)이 스캔된 구매주문서에서 필드 14개를 추출해서 사람의 검토 없이 곧바로 Postgres에 적재함.","현재 구현은 assistant 턴의 시작 부분을 여는 중괄호와 첫 키로 프리필(prefill)한 뒤, 돌아오는 응답을 파싱함.","이번 달 문제가 두 가지 있었음. (1) 응답의 약 0.4%가 닫는 중괄호 뒤에 문장을 덧붙여서 로더(loader)가 깨졌고, (2) 팀이 이 작업을 Claude 4.6 모델에 고정한 뒤로는 모든 요청이 400 에러로 실패하기 시작했음.","파이프라인(pipeline)은 무엇으로 옮겨가야 하는가?"],"974852970":["어제 세션에서 대형 코드베이스를 분석했음.","밤사이 자동 의존성 업그레이드가 저장소 전반의 많은 파일을 바꿔놓았음.","너는 오늘 그 분석을 이어가야 함.","가장 확실한 방법은 무엇인가?"],"976088423":["/migration skill이 SQL 파일 초안 작성과 데이터베이스 적용을 둘 다 하는데, 초안만 원했는데도 두 번이나 실제로 적용해 버렸음.","이것을 안전하게 만드는 변경 두 가지는 무엇인가? (2개 선택)"],"977324995":["첫 실패가 나면 그 작업을 바로 종료해서 coordinator가 파이프라인 전체를 깔끔하게 다시 시작하게 하기."],"977532125":["항상 같은 데이터 소스 네 개를 집계하는 주간 보고서 생성."],"977960153":["discovery 결과를 system prompt에 붙여넣고, 분기마다 손으로 직접 갱신하기"],"979697521":["사람 상담원은 대기 시간이 길고 봇이 더 빨리 도와줄 수 있다고 설명하기."],"979887799":["원래 심볼을 파일 내용에서 검색해서 정의와 직접 호출부를 찾기."],"980827343":["프로덕션 장애 세 건이 터진 뒤에 하는 스키마 리뷰임.","스키마는 다음과 같음. 모든 필드가 필수(required)고, product_category는 enum [\"electronics\",\"clothing\",\"food\"]이고, 날짜는 자유 형식 문자열임.","장애 내용은 다음과 같음. (1) supplier_tax_id가 아예 없는 문서인데도 값을 지어냄. (2) 틈새 자동차 부품이 \"food\"로 분류됨. (3) 같은 배송 날짜가 문서마다 \"3/4/25\", \"2025-04-03\", \"April 3rd\"로 제각각 추출됨.","이 셋을 한꺼번에 해결하는 스키마 수정은 무엇인가?"],"982506153":["인용(citation)이 달린 문장은 전부 그대로(verbatim) 보존하고, 절차적인 잡담과 tool 응답 확인(acknowledgement)은 버리는 선택적 보존(selective retention)임."],"984616564":["문서 아카이브 전체를 훑는 주간 컴플라이언스 스캔."],"985195768":["퍼널(funnel) 단계 일곱 개를 전부 나열하고, 각각에 대해 순서대로 같은 분석을 돌린 다음 결과를 비교하기"],"986279643":["신입 엔지니어들은 사내 온보딩 에이전트에게 스테이징 데이터베이스 신청 방법 같은 질문을 함. 이 에이전트는 도구가 search_wiki 하나뿐인데, 이 도구는 4,000페이지짜리 사내 위키에서 매칭되는 모든 페이지의 전체 텍스트를 반환함.<br><br>첫 달 지표를 보면 전형적인 세션은 14턴 정도 진행됨. 그런데 8턴쯤부터는 에이전트가 같은 세션에서 앞서 가져온 위키 페이지를 인용하는 대신 일반적인 업계 조언(\"보통 팀들은 스테이징 접근을 이렇게 처리한다...\")으로 답하기 시작하고, 세션의 30%는 엔지니어가 원래 질문을 다시 묻는 것으로 끝남.","search_wiki를 한 번 호출할 때마다 전체 페이지 4~9개가 반환되고, 호출당 평균 6,000토큰이 들어감.<br><br>위키의 페이지 구조는 문서 팀이 관리하고 있고, 재구성되지 않을 것임.","가장 효과적인 해결책은 무엇인가?"],"989659643":["그 단계를 plan mode로 돌리되, plan은 항상 승인된다는 지시를 추가해서 기다림 없이도 리뷰라는 형식만 유지하기"],"989660052":["둘 다 동기 API로 옮기기. 비용보다 안정성이 더 중요하기 때문임."],"990144200":["매일 아침 세션을 fork해서 그날 작업을 전날 작업과 분리하기"],"991952986":["검색 에이전트들이 서로의 결과 집합을 직접 볼 수 있게 해서 같은 출처를 또 가져오지 않게 하기"],"992062499":["컨텍스트를 아끼려고 탐색은 건너뛰고, 작업 설명만 보고 바로 구현하기"],"992166534":["pair-programming 세션이 하루 종일 이어지고, context가 도구 결과(tool result)로 가득 참.","아래 조치들은 하나만 빼고 전부 쌓이는 양을 줄여줌.","줄여주지 않는 것은 어느 것인가?"],"993279350":["승인은 하되 제출 시각을 정오로 옮기기. 그러면 마감까지 배치에 21시간이 생기고, 최대 24시간 안에 여유 있게 들어옴."],"994768288":["19개 다 유지하되, run_shell의 설명만 최후의 수단(last resort)이라고 다시 쓰기"],"995707934":["금액을 필수로 유지하고, 모델이 직접 보지 못한 금액은 절대 추측하지 말라는 프롬프트 문구를 추가하기"],"997935395":["타임아웃을 실패 유형과 재시도 가치 여부를 담은 구조화된 tool result(도구 결과)로 대화에 추가해서 에이전트가 이것을 성공한 호출과 구별할 수 있게 하기."],"998213509":["#812 건은 디렉터리에서 가장 최근인 대화를 아무거나 집어드는 대신 저장된 페이로드(payload)에 이미 기록된 세션 식별자(session identifier)로 그 실행을 특정해서 처리하기."],"998990750":["호출 지점마다 tool_choice를 맞출 것. (1) 추출 단계는 항상 도구를 통해 구조화된 출력을 내야 하고 산문은 절대 안 됨. (2) 사용자에게 보여 줄 최종 요약은 산문이어야 하고 도구 호출은 절대 안 됨. (3) 일반 대화 단계는 모델이 알아서 정하게 둠."],"1000557084":["프로젝트 파일을 짧게 만들려고 규칙을 전부 사용자 수준의 ~/.claude/CLAUDE.md로 옮기기."],"1001280380":["tool_choice를 \"auto\"로 두고, 항상 도구를 쓰라는 지시를 프롬프트에 넣기"],"1001786722":["frontmatter에 항목을 여러 개 넣기. paths는 패턴 하나당 디렉터리 한 단계만 받으므로 하위 디렉터리를 전부 따로 적어야 함."],"1001829350":["각 subagent가 finding, 근거가 된 파일들, 그리고 판단하지 못한 부분까지 고정된 형태로 답만 돌려주게 하고, 검색 과정 서술은 남기지 않게 하기"],"1005664023":["롤백(rollback) 규칙을 유추(analogy)해서 보호된(protected) 서비스에 적용하기. 리드가 준 규칙 중 가장 가깝기 때문임. 그리고 그 가정을 보고서에 기록하기."],"1007119118":["먼저 래퍼 모듈들에서 그 함수가 export되는 이름을 전부 찾아내고, 그다음 각 이름을 코드베이스 전체에서 Grep으로 검색하기"],"1007185674":["타임아웃 전에 받아둔 부분 결과 두 개를 같이 첨부하기"],"1008217516":["체크별 출력 형태를 고정해서, 하룻밤 수치를 지난주 수치와 나란히 비교할 수 있게 하기"],"1008894705":["타임아웃을 감지한 다음 성공으로 표시된 빈 결과 집합을 돌려주는 것임."],"1009520335":["코디네이터의 allowedTools에 \"Task\"가 빠져 있음. Task 도구가 없으면 프롬프트에서 위임을 아무리 잘 설명해도 subagent를 띄울 수단 자체가 없음."],"1010091019":["매일 전체 추출 결과 중에서 무작위로 고정 5%를 검토하기"],"1011006031":["각 엔지니어에게 커밋(commit)하기 전에 diff를 읽으라고 요청하고, pull request 템플릿에 리마인더 줄을 추가하기"],"1011375461":["18% 대 71%라는 격차는 프롬프트 품질 문제가 아니라 구조에서 오는 것임. 코드를 만든 세션은 자기 추론 맥락을 그대로 갖고 있어서 자기 결정을 방어하고, 그 맥락 안에서 더 깊이 생각해 봐야 대개 자기 합리화만 깊어짐.","독립 인스턴스 방식으로 가기"],"1013773906":["결제 재시도 경로(payment retry path)를 실제로 실행하는 테스트 파일 목록이 필요함.","저장소의 테스트 디렉터리 아래에는 약 340개 파일이 있는데 이름 규칙이 없음. 어떤 건 .spec.ts로 끝나고, 어떤 건 .test.ts, 어떤 건 그냥 tests/feature-name.ts 형태임.","지난번 시도는 340개를 전부 읽다가 컨텍스트 창을 초과했음.","어떤 순서로 접근해야 하는가?"],"1014953029":["계약서 추출 스키마에 문제 필드가 둘 있음. signing_date는 실제로 날짜가 안 적힌 계약서가 많고, jurisdiction은 enum 목록 밖의 지역이 문서에 자주 나옴.","어떤 수정 조합이 맞는가?"],"1015108586":["표준을 리뷰 프롬프트(review prompt)에 붙여넣고, 어시스턴트가 JSON으로만 답하고 그 외에는 아무것도 답하지 않도록 지시한 다음, 이 단계에 금액 상한(dollar cap)을 둬서 비용이 큰 실행이 반복될 수 없게 하기"],"1015989803":["main agent는 코드베이스 audit을 조율하면서 조사를 subagent들에게 위임함.","이번 주 로그에는 문제가 두 가지 있음. subagent들은 자신이 검색한 모든 것을 8,000토큰짜리 서술로 계속 돌려주고, \"billing 모듈을 살펴보라\"는 요청을 받은 subagent 하나는 main agent가 실제로 필요로 했던 의존성 답변 대신 폴더 구조 요약을 돌려줌.","어떤 두 가지 변경이 적합한가? (Select TWO.)"],"1016345773":["동료가 \"토큰 아끼기\"라며 루프를 바꿨음. 요청된 도구를 실행한 뒤 원본 결과를 붙이는 대신, \"(주문 데이터 가져옴, 정상으로 보임)\" 같은 한 줄 설명만 붙이게 했음.","그 뒤로 에이전트는 이미 실행한 조회를 다시 요청하고, 어제는 실제 주문 데이터 어디에도 없는 배송일을 그대로 말해버렸음.","올바른 해결책은 무엇인가?"],"1016655164":["한 엔지니어가 extraction 팀의 schema-design 체크리스트를 검토용으로 돌림.","옳지 않아서(NOT correct) 삭제해야 하는 줄은 어느 줄인가?"],"1020169677":[".claude/rules/ 파일 하나에 paths: [\"**/migrations/**/*.sql\"]를 넣어서, 마이그레이션 SQL 파일이 어디에 있든 잡히게 하기"],"1020857331":["지금 pull-request 리뷰 단계는 권한 검사(permission checks)를 꺼둔 공유 러너(runner)에서 어시스턴트를 돌리고 있음.","이번 스프린트에 불만이 세 가지 들어왔는데, 리뷰가 리포지토리에 문서화된 에러 처리·로깅 표준을 무시한다는 것, findings를 받아들이는 metrics dashboard가 그 산문(prose) 텍스트를 패턴 매칭하다가 거의 매주 깨진다는 것, 그리고 지난 화요일엔 이 단계가 브랜치를 push해버렸다는 것, 이렇게 세 가지임.","세 가지를 전부 해결하는 수정안은 무엇인가?"],"1021548770":["네 가지를 전부 시스템 프롬프트에 넣고 (1)과 (2) 앞에는 \"CRITICAL:\"을 붙이기. 모델은 강하게 강조된 지시를 평범한 지시보다 훨씬 잘 따르기 때문임."],"1021723028":["이번 주에 상황 세 가지가 생겼음. (a) 밤사이 자동 의존성 업그레이드가 어제 분석한 저장소 전체의 import를 다시 써버렸음. (b) 지난 세션 이후로 클래스 하나의 이름을 파일 5개에 걸쳐 바꿨음. (c) 이미 끝낸 분석 위에서, 서로 경쟁하는 캐싱 전략 두 가지를 나란히 놓고 평가해보고 싶음.","각 상황에 맞는 메커니즘은 무엇인가?"],"1023664001":["frontmatter에서 격리된 forked context로 실행되도록 하고, 쓸 수 있는 도구를 제한하고, 기대하는 인자를 선언해둬서 topic이 빠지면 추측하는 대신 다시 요청하게 만드는 project skill임."],"1023754616":["새 tenant 디렉터리 안에만 머물고 다른 곳의 파일은 절대 지우지 말라는 문장을 skill의 지침(instructions)에 추가하기."],"1024979087":["자동 리팩터링 도중에 에이전트가 utils/orders.ts에서 \"return retry(fetchOrder);\" 줄을 Edit하려 했는데 실패했음. 똑같은 텍스트가 그 파일 안에 네 군데나 있음.","에이전트는 fetchWithBackoff 함수 안에 있는 것만 바꿔야 함.","다음 단계로 가장 확실한 것은 무엇인가?"],"1025725293":["두 주소를 비교하는 검증 규칙(validation rule)을 추가해서 똑같이 나올 때마다 재시도하게 하기. 중복된 값은 모델이 헷갈렸음을 보여주는 신호니까."],"1026091449":["작업을 세션 세 개로 나누기. 탐색용 하나, 설계용 하나, 구현용 하나."],"1026634882":["관련 있는 필드에만 집중하고 모든 날짜를 머릿속에서 하나의 형식으로 맞추라고 지시하는 시스템 프롬프트."],"1026740190":["few-shot 예시를 두 배로 늘려서 더 많은 누락 유형을 다루는 예시 10개로 만들기"],"1028459452":["메시지를 쪼개서 처리하기. 환불은 정책 범위 안이므로 에이전트가 알아서 해결하고, 보상 요구는 정책에 아무 언급이 없으므로 구조화된 요약과 함께 사람에게 넘기기"],"1028598411":["재시도 상한(retry ceiling)을 5에서 10으로 올리기. 실패가 간헐적이므로 재시도 단계를 늘리면 대부분 해결될 것임."],"1029730760":["리포트마다 주된 콘텐츠 유형을 보고 모델이 형식 하나를 고르게 하기."],"1029932221":["지시를 더 강하게 쓰기. \"절대 텍스트로 답하지 마.","반드시 도구를 호출해야 함.","이는 매우 중요함.\""],"1033545463":["exempt를 실제 category 값으로 추가하고, \"문서에 명시돼 있지 않다\"는 상태는 따로 표현하기. unclear 값이든 허용된 null이든. 이 둘 중 하나는 거래에 관한 사실이고, 다른 하나는 문서에 관한 사실이기 때문임."],"1034461950":["팀의 프로젝트 레벨 /commit을 직접 수정하기. 이 개선이 모두에게 도움이 될 것이기 때문임."],"1035756051":["형식 지시(format instructions)를 담은 프롬프트 하나로 둘 다 만들어내기. 같은 서비스 안에서 강제되는 경로와 강제되지 않는 경로를 둘 다 운영하는 건 얻는 것보다 유지 비용이 더 큼."],"1037162229":["월요일 아침 내내 Claude에게 200개 파일짜리 빌링 서비스를 매핑시켰음. 모듈 경계, 결제 제공업체(payment provider) 세 곳, 재시도 설계까지 포함함.","이제 할 일이 두 가지임: 그 매핑을 바탕으로 큐 기반(queue-based) 재작성과 인라인 재시도(inline-retry) 재작성을 비교하는 것, 그리고 목요일에 팀원이 같은 서비스에 커밋 30개를 병합한 뒤 그 작업을 이어서 하는 것.","세션 컨트롤(session controls)을 어떻게 쓰는 것이 맞는가?"],"1037931628":["저장소 어디에서도 console.log를 금지하는 규칙을 memory file에 추가하기."],"1038348323":["같은 작업을 여는 두 가지 조회(lookup)가 있음.","(A) \"Jest setup 파일이 어떤 것들이지?\": jest.setup.* 라는 이름 패턴을 따른다는 것은 알지만, 트리 어디에 있는지는 모름.","(B) \"chargeCard()를 호출하는 모듈이 뭐지?\": 심볼(symbol)은 알지만 파일명은 모름.","A와 B 각각에 맞는 첫 단계로 옳은 것 두 가지는 무엇인가? (Select TWO.)"],"1038654041":["시작하기 전에 Claude에게 그 형식을 확인했다고 답하게 하기"],"1045692087":["네 추출 서비스는 문서 업로드 후 12시간 안에 결과를 준다고 약속했음.","너는 Batches API로 비용을 아끼려 함. 처리에는 최대 24시간이 걸림.","계산해 보면 어떤 결론이 나오는가?"],"1046138379":["야간 작업 로그의 7번째 반복임. 응답의 stop_reason이 \"max_tokens\"이고, tool_use 블록이 잘린 채 일부만 들어 있음.","네 루프는 stop_reason이 tool_use가 아니면 전부 완료로 처리해서, 50%만 진행된 작업을 끝난 걸로 표시했음.","올바른 수정은 무엇인가?"],"1046626423":["가격 담당 subagent가 출처를 2곳 대신 5곳을 보게 해서 보통 최소 한 곳은 성공하게 하고, \"ok\" 동작은 복원력 장치로 그대로 두기"],"1046958153":["모든 PR을 보안, 커버리지, 컨벤션이라는 똑같이 고정된 체크리스트로 검토하는 일."],"1048120797":["코디네이터(coordinator)는 planning을 아예 건너뛰고 서브에이전트(subagent)들이 자유롭게 탐색하게 둔 다음, 마지막에 그 결과를 합쳤어야 했음."],"1048956502":["지적 사항을 고정 20% 샘플링 비율로 무작위로 사람한테 넘기기"],"1049320908":["리포트가 나가기 전에 사람 편집자가 주장마다 출처를 다시 붙이게 하기."],"1049735079":["기여자(contributor) 14명이 있는 핀테크 저장소(repo)가 일주일 새 세 가지 요청을 가져옴.","(R1) 금액은 decimal 타입으로 처리해야 하며, float은 절대 쓰면 안 됨. 이는 모든 세션에서 누구에게나 생성되는 코드에 반영돼야 함.","(R2) 어떤 에이전트 세션도 인프라 apply 명령을 실행하면 절대 안 됨. 가이드 문서에 이미 경고 문구가 있는데도 3월에 apply가 실행된 적이 있음.","(R3) 30페이지짜리 정산(reconciliation) 런북(runbook)은 누군가 services/ledger/ 아래 파일을 편집하는 동안에만 작업에 반영되어야 하는데, 지금은 관련 없는 세션에서도 매번 약 9,000토큰을 잡아먹고 있음.","세 가지 조건을 다 만족하는 배치는 무엇인가?"],"1050909169":["하루 수천 건의 추출을 사람 검토자 단 두 명이 감당해야 하는데, 이 인력을 가장 잘 쓰는 라우팅 설계는 무엇인가?"],"1052247050":["라벨링된 검증 세트로 점수를 보정하기. 모델의 원시 신뢰도를 실제 관측된 정확도에 대응시키고, 라우팅 임계값은 보정된 값 위에서 정하기"],"1052958760":["검토 턴(reviewing turn)에게 더 회의적으로 접근하고 코드에 결함이 최소 3개는 있다고 가정하라고 지시하기"],"1054368180":["Claude Code를 다시 설치해서 설정 상태를 초기화하기."],"1054689735":["40턴짜리 분쟁 대화에서 에이전트가 3월 15일까지 312.40달러를 환불해 주기로 합의했음.","20턴 뒤, 요약이 작동하고 나서는 \"적절한 금액을 가능한 한 빨리 환불해 드리겠습니다\"라고 말함. 고객은 단단히 화가 났음.","이 티켓 하나를 넘어서, 재발을 막을 시스템 차원의 해법은 무엇인가?"],"1054783840":["ticket 필드 재시도를 멈추고, 빈 값으로 돌아오게 둔 다음, 파이프라인 안에서 tracker로부터 채워 넣기"],"1055792986":["(a) 원래 분석을 보존하려고 fork_session, (b) 이름 변경은 언급하지 않고 --resume, (c) 전략마다 하나씩 완전히 새 세션 두 개."],"1057152458":["제품 카테고리 필드가 enum: [\"electronics\", \"clothing\", \"food\"]로 되어 있음.","실패 유형이 두 가지임. 틈새 제품이 엉뚱한 카테고리로 억지로 밀려 들어가고, 진짜로 애매한 항목은 실행할 때마다 라벨이 달라짐.","스키마를 어떻게 발전시키는 게 맞는가?"],"1057292979":["CI 워크플로 YAML. 파이프라인 실행 중에만 프롬프트 앞부분으로 주입하기."],"1057686687":["tracker 서버를 자체적으로 만들고, 호출할 때마다 340개 전체 목록을 반환하는 도구로 템플릿을 등록하기"],"1058319689":["고정된 체인임: 알려진 기사 경계에서 나누고, 각 기사에 국한된 프롬프트로 필드를 추출한 다음, 여러 기사에 걸쳐 나타나는 필드를 조정하는 마지막 패스를 돌리기."],"1060001818":["각 값을 읽어온 페이지 번호와 인용된 원문 텍스트를, 추출 스키마 자체의 필드로 저장해 두는 것임."],"1062143383":["각 문서를 더 작은 청크로 쪼개서 그 배치가 더 빨리 끝나게 하기."],"1062520472":["리뷰 지시가 너무 무르니까 \"최소 다섯 개 이슈를 찾아라\"라고 요구하기."],"1062917538":["초기 조사(계측 검토, 퍼널 데이터 수집, 3단계 코드 읽기)로 첫 계획을 만들고, 그 계획을 수정 가능한 것으로 다루기. 발견 사항이 나올 때마다 하위 작업을 추가하거나 빼거나 순서를 바꿀 수 있고, 계획 문서는 진행하면서 계속 업데이트됨."],"1062931894":["시니어 개발자 한 명의 Claude Code만 탭과 세미콜론이 들어간 코드를 만듦. 나머지 사람들 건 팀 표준인 스페이스에 세미콜론 없는 스타일로 나옴.","확인해 보니 팀 표준은 프로젝트의 CLAUDE.md에 있고, 그 시니어 개발자는 ~/.claude/CLAUDE.md에 개인 포매팅 규칙을 따로 두고 있음.","무슨 일이 벌어지고 있고, 뭘 바꿔야 하는가?"],"1063699990":["리뷰어가 실행할 때마다 어떤 파일이 위험해 보이는지 직접 판단하고, 그것만 깊이 있게 리뷰하게 하기"],"1063979981":["사용자에게 상호 의존 관계를 전부 먼저 문서로 정리해 달라고 하고, 그다음에 고정된 계획을 실행하기."],"1064068536":["구체적인 예시 질의를 곁들인, 기대하는 입력 형식."],"1064326528":["같은 시장 규모를 두고 믿을 만한 수치가 둘임. 하나는 2023년 산업협회 전수조사의 42억 달러($4.2B), 다른 하나는 2024년 애널리스트 전망치인 51억 달러($5.1B)임.","PM은 2024년 수치를 써야 한다고 밀어붙임. 더 최신이고, 숫자를 두 개나 내보내면 팀이 우유부단해 보인다는 것이 이유임. 분석 단계는 실제로 어떻게 해야 하는가?"],"1064558275":["종합 단계에서 숫자가 서로 다른 쌍은 전부 모순으로 표시해서 사람 검토로 넘기게 하기"],"1064696632":["두 형태 모두 계속 retry하되, validator의 전체 stack trace를 붙여서 리뷰어가 정확히 뭐가 깨졌는지 보고 다음 시도에서 고칠 수 있게 하기."],"1065066165":["필요한 값마다 필드 하나씩 있는 구조화된 상태 객체(structured state object)를 유지해서 매 턴마다 갱신하고 그대로(verbatim) 이어서 가져가고, 일반 요약(summarization)은 주변 서사만 처리하게 두기"],"1066377761":["제안을 승인하기. 올바른 동작을 보여주는 예시가 많을수록 케이스 난이도와 상관없이 패턴이 강해지기 때문임."],"1066999862":["숫자 금액이 해당 문서 유형에 맞는 그럴듯한 범위 안에 들어가는지 확인하기. 그 경로에서는 range 관련 keyword가 강제되지 않기 때문임."],"1067851528":["팀의 더 깊은 주제별 가이드가 어디 있는지 가리키는 포인터임. 관련이 생기면 세션이 그것을 끌어와 쓸 수 있게 하는 것임."],"1068396313":["두 경우를 구분하기. 타임아웃일 땐 errorCategory를 \"transient\", isRetryable을 true로 해서 isError를 반환하고, 성공한 빈 결과는 질의가 실제로 실행됐는데 일치 항목이 없을 때만 반환하기"],"1068970478":["에이전트가 템플릿(template)으로 저장소 보일러플레이트(boilerplate)를 생성하고, 팀의 linter와 타입 체커(type checker)로 결과를 검증함.","로그에는 세 가지 실패 유형이 나타남. 생성된 파일에 필수 export가 빠진 경우, 에이전트가 추측한 패키지 버전 때문에 생긴 타입 에러, 그리고 템플릿이 서비스를 소유한 팀 이름을 필요로 하는데 그 이름이 저장소에도 요청에도 전혀 없는 경우임.","어떤 retry 정책이 맞는가?"],"1069483575":["추출 작업을 JSON 스키마를 가진 도구(tool)로 정의하고, 구조화된 도구 입력(tool input)을 읽기. 스키마는 앞부분 몇 글자가 아니라 객체 전체를 제약하고, 프리필(prefill) 제약도 없음."],"1069701930":["밤새 돌린 추출 결과임. 312건은 타입 오류로 Pydantic 검증에 실패했음(날짜가 문자열로 들어옴). 89건은 tax_registration_number가 null인데, 감사팀이 확인해 보니 그 값은 별도 등기 문서에만 있음. 23건은 항목 합계가 명시된 총액과 맞지 않음.","올바른 분류 처리는 무엇인가?"],"1070475454":["점진적으로 요약되는 대화에서는 왜 환불 금액과 약속한 날짜가 사라지는가?"],"1070590409":["각 severity 레벨을, 해당되는 경우와 안 되는 경우를 보여주는 짧은 코드 예시로 정의하기"],"1071888950":["지시를 아예 없애기. subagent는 자유도가 최대일 때 제일 잘하기 때문임."],"1072664669":["한 데이터 팀의 CSV-to-report 생성 결과가 실행할 때마다 형태가 다르게 나오는데, 2라운드로 시도할 아이디어가 네 가지 있음.","실행할 때마다 다르게 해석되는 출력을 고치는 데 가장 효과가 적은 것은 어느 것인가?"],"1072923362":["실패한 것은 그대로 다시 돌리기. 배치 실패는 대개 일시적이기 때문임."],"1074087466":["process_refund에 필수 boolean 파라미터를 추가해서, 고객이 실제로 환불을 요청했다는 걸 모델이 확인 표시하도록 반드시 설정하게 하기."],"1075521666":["검수자가 대시보드에서 직접 고른 걸 검토하게 하기"],"1076654063":["각 요청을 나머지 19개 중 맞는 것으로 보내 주는 스무 번째 도구를 추가하기."],"1077706294":["(a) 최신 상태를 유지하려고 매일 아침 전체 분석을 처음부터 다시 돌리기. (b) 더 큰 컨텍스트 창을 쓰기. (c) 실행을 자동 재시작 루프로 감싸기."],"1078976182":["\"EV 배터리 시장\"을 조사한 리서치 subagent 두 개가 똑같은 소스 세 개를 물어 왔음. 토큰의 40%가 중복된 셈임.","제안 A: coordinator가 결과를 다 모은 뒤에 중복을 제거함.","제안 B: coordinator가 위임하기 전에 서로 겹치지 않는 세부 주제와 소스 유형을 나눠서 할당함.","어느 쪽이 맞고, 이유는 무엇인가?"],"1079151502":["이름 붙인 세션을 매일 그대로 재개하고 변경 사항은 언급하지 않기. 하루치 PR은 너무 작아서 영향이 없기 때문임."],"1080362920":["extractor는 강제된 스키마로 동작하고, loader는 몇 주째 payload를 하나도 거부하지 않았음.","그런데 주소가 두 개 인쇄된 인보이스에서는 배송 주소가 자꾸 billing_address에 들어감.","두 필드는 타입이 똑같이 지정돼 있음.","가장 직접적인 해결책은 무엇인가?"],"1081395997":["시나리오: 야간 에이전트가 청구 시스템과 결제 처리업체(payment processor) 사이의 결제 기록을 대조함.<br>상황: 양쪽 데이터를 가져와 비교한 다음, 재무팀이 매일 아침 확인하는 공유 드라이브에 불일치 보고서를 씀.<br>증상: 목요일 보고서에는 불일치가 0건으로 나와 있었음.","금요일에 재무팀이 목요일 거래 중 214건의 불일치 거래를 발견했음.","실행 로그를 보면 처리업체의 API가 40페이지 중 11페이지에서 HTTP 503을 반환했는데, fetch 헬퍼는 200이 아닌 응답을 받으면 빈 페이지 목록을 반환하도록 되어 있음. \"페이지 하나 잘못됐다고 실행 전체가 죽으면 안 되니까\" 그렇게 만든 것임.<br>제약조건: 재무팀은 보고서 누락을 통제 실패로 간주하기 때문에, 보고서는 매일 밤 반드시 생성돼야 함.<br>질문: 정확한 해결책은 무엇인가?"],"1081918906":["frontmatter는 필요 없음. 세 가지 요구사항을 전부 스킬 프롬프트 본문에 분명히 적기."],"1083544470":["어제 세션을 그대로 이어서 쓰기. 히스토리 자체가 값진 컨텍스트이기 때문임."],"1083970090":["네 에이전트는 답하기 전에 어떤 데이터가 있는지 알아내려고 list_tables, describe_table, sample_rows를 부르느라 세션마다 몇 턴씩 낭비함.","이 탐색 오버헤드를 해결해 주는 MCP 기능은 무엇인가?"],"1084496034":["플랫폼 팀이 Claude 4.6으로의 조직 전체 업그레이드에 앞서, 모든 서비스를 프리필(prefill)된 어시스턴트 턴(assistant turn)에서 벗어나게 하는 내부 마이그레이션 가이드를 작성하고 있음.","그 가이드에 들어가면 안 되는 문장은 무엇인가?"],"1084622560":["최근 대화 턴에 대한 슬라이딩 윈도(sliding window)를, 매 프롬프트에 다시 포함되는 추가 전용(append-only) 인용 블록(citations block)과 결합하기."],"1086422128":["온콜(on-call) 트리아지 어시스턴트가 Kubernetes 얼럿(alert) 스트림을 지켜봄.","매 턴마다 지난 1분간의 얼럿을 받아서 \"지금 당장 조치할 게 있는가?\"라는 질문 하나에 답함. 6개월치 트랜스크립트를 보면 10분보다 오래된 얼럿이 답을 바꾼 적은 한 번도 없었음.","턴당 레이턴시(latency) 예산은 800ms이고, 팀의 고정 규칙은 \"요청 경로(request path)에서 모델 호출 추가 금지\"임. 어떤 전략이 가장 잘 맞는가?"],"1086431764":["배치 처리는 제출 → 대기 → 수거 구조임. 요청 도중에 도구 결과(tool result)를 돌려줄 통로가 없어서, 한 요청 안에서 여러 턴짜리 도구 실행 루프는 돌 수 없음.","도구 정의 자체는 받아 줌. 불가능한 것은 루프 쪽임."],"1087028229":["둘 다 \"이번엔 더 신중하게, 숫자를 다시 확인해\"라는 지시를 붙여서 재시도하기"],"1087570128":["종합 에이전트가 숫자 두 개를 합쳐 추세 문장으로 만드는 것을 아예 금지하기."],"1087921063":["coordinator는 subagent 네 개를 한꺼번에 실행해야 함. 독립적인 소스 스캔 세 개(EU filings, US filings, trade press)와, 나머지 셋이 뭘 돌려주든 그걸 요약하는 subagent 하나임.","지금 각각을 생성하는 프롬프트는 \"리서치를 계속하라\"라고만 되어 있음. 이번 배치에는 어떤 두 가지 변경이 필요한가? (Select TWO.)"],"1087960456":["subagent들의 AgentDefinition에 description이 빠져 있어서 coordinator 눈에 안 보이는 것으로 보임."],"1088177640":["요약기에게 더 길고 자세한 요약을 쓰라고 지시하기."],"1088607167":["진입점 파일을 읽고 그 값이 나올 때까지 모든 import 체인을 따라가기"],"1088645973":["추출 실패가 두 가지 반복됨. (a) supplier_tax_id가 비어 있음. 그 값은 네 파이프라인이 아예 받지 않는 별도의 등록 문서에만 나옴. (b) 청구서 항목 합계가 명시된 총액과 안 맞을 때가 있음.","어떻게 처리하는 것이 맞는가?"],"1088787740":["통계적 커버리지를 확보하려고 프로덕션 사례를 무작위로 표본 추출하기"],"1089662239":["(a) 불만에 공감해주고 주소 변경을 즉시 처리하기. (b) 정책에 보증 연장 얘기가 없으니 사람에게 넘기기."],"1091790174":["세 단계를 하나의 연속 실행으로 합쳐서 넘겨줄 것이 아예 없게 만들기."],"1092436212":["세 개를 똑같은 방식으로 제시하기. 구분해서 보여 주면 편집자의 편향이 끼어들기 때문임."],"1095141135":["(i)와 (ii)는 경로 패턴(path pattern)이 있는 규칙 파일(rule file)로, (iii)와 (iv)는 루트 메모리 파일(memory file)의 섹션으로 두기. 둘 다 한 폴더가 아니라 저장소 전체에 걸쳐 적용돼야 하기 때문임."],"1095626092":["축약된 버전 대신, 완전한 finding(주문 ID, 금액, 날짜, 상태)을 그대로 drafting subagent의 prompt에 넣기"],"1096312334":["사람에게 에스컬레이션하기. 도구(tool)가 이 요청을 에이전트로서는 복구 불가능하다고 판정했기 때문임."],"1096852014":["두 설계 다 각각 다른 브랜치에 구현해서 결제(payments) 그룹이 동작하는 코드를 비교할 수 있게 하기. 그런 다음 채택되지 않은 브랜치는 버리기."],"1097942558":["down-migration은 문서 가이드로만 남겨두고, 짝이 되는 파일이 있는지 자동 검사를 merge 조건으로 걸어서 다섯 건 중 한 건꼴로 빠져나가는 것을 반영되기 전에 찾아내기."],"1098800268":["supplier name을 extraction schema에 required 필드로 추가하고, 로드한 뒤 입력 파일과 대조 검사하기"],"1098929588":["기존 세 개 위에 정책 공백 탐지용 트리거를 네 번째로 추가해서 시스템에 다층 방어를 갖추기."],"1099597077":["Northwind Analytics는 Claude Agent SDK로 만든 멀티에이전트(multi-agent) 리서치 시스템을 운영함.","코디네이터(coordinator) 에이전트가 리서치 요청을 하나씩 받아 웹 검색(web search), 문서 분석(document analysis), 종합(synthesis) 이렇게 세 개의 전문 subagent에게 위임하고, 출처가 달린 리포트를 조립함.","모든 subagent 호출은 coordinator를 거쳐가며, subagent끼리는 절대 직접 메시지를 주고받지 않음.","분석가들은 아침에 리서치 세션을 열고 하루 종일 그 세션 안에서 계속 작업하며, 점심 이후에 다시 돌아오는 경우도 많음.","지난 릴리스 이후로 팀은 불만 사항 세 건을 기록했음.","일부 실행(run)은 절대 끝나지 않으며, 운영자가 40회 반복(iteration) 한도에서 강제 종료할 때까지 계속 토큰을 소모함.","출처 두 개짜리 단순한 질문도 전체 시장 조사만큼 시간이 걸리고 비용도 똑같이 듦.","게다가 리포트가 가끔 데이터팀이 며칠 전에 이미 교체한 경쟁사 리스트의 수치를 인용하기도 함.","이 시스템은 4주 후에 유료 고객에게 오픈될 예정임."],"1102137060":["규칙 파일 자체를 어디에 저장해야 하는지."],"1102716950":["실패한 424건 전부를 에러 피드백과 함께 재시도하기. 수작업에 비하면 재시도는 싸게 먹힘."],"1103007068":["synthesis subagent가 소스 하나만 더 필요할 때는 search subagent를 직접 호출하게 해서, 코디네이터를 거치는 불필요한 왕복을 없애기"],"1105692039":["settlement-date 필드를 자유 텍스트도 받을 수 있게 넓혀주면, 날짜가 없을 때 모델이 \"pending\"이라고 쓸 수 있음."],"1106592165":["문서 5,000건짜리 배치 실행에서 3%가 실패했음. 대부분은 컨텍스트 한도를 넘긴 초과 크기 문서임.","올바른 실패 처리 설계는 무엇인가?"],"1107104897":["릴리스 스크립트(release script)가 오픈된 풀 리퀘스트(pull request)마다 하나씩, 총 3개의 무인 리뷰 실행(unattended review run)을 병렬로 돌리고 각 실행의 JSON payload를 저장함.","한 시간 뒤, (a) PR #812를 리뷰한 그 실행에 콕 집어서 후속 질문을 보내야 하고, (b) 감사(audit)를 위해 원본을 잃지 않으면서 같은 대화를 서로 다른 두 개의 수정(remediation) 경로로 갈라 진행해야 함.","어떤 처리 방식이 맞는가?"],"1108624501":["jitter 설계를 곧바로 구현해서 pull request를 열기. 결제 그룹은 코드 리뷰 중에 승인하는데, 승인은 원래 거기서 이루어져야 하고 거기서만 설명이 아니라 실제 변경 내용을 볼 수 있음."],"1109599605":["hook이 구조화된 비즈니스 에러를 반환하게 하기(retriable: false에 설명을 붙여서). 그리고 흐름을 사람에게 넘기는 에스컬레이션 워크플로로 돌리기. 막기만 하고 다른 길로 안 보내면 패턴의 절반만 한 셈임."],"1109615507":["#812의 경우, 그 디렉터리(directory)에서 가장 최근 대화(conversation)를 이어가기. 페이로드(payload) 세 개가 나란히 있으므로, 물어보는 것은 그중 최신 것임."],"1110256684":["장황한 출력을 격리하려고 context: fork, 읽기 전용 도구로만 제한한 allowed-tools, 대상 디렉터리를 물어보는 argument-hint."],"1110395017":["(a) /compact를 돌려서 세션 기억을 정리하고, (b) 원본 출력은 스크래치패드 파일로 받아 두고, (c) 야간 실행을 세 시간씩 두 묶음으로 쪼개기"],"1110400104":["먼저 바로 실행(direct execution)으로 실제 에러를 모으고, 그다음에 plan mode로 그것을 해석하기"],"1112293419":["다섯 개를 전부 순차로 돌리기. 병렬과 순차를 섞으면 에러 처리가 너무 복잡해짐."],"1112724240":["리포트를 그대로 내보내기. 하위 주제 셋 중 둘이면 커버리지로 받아들일 만하기 때문임."],"1113283442":["subagent(하위 에이전트)끼리 서로의 부분 출력(partial output)을 지켜보게 해서 요약기(summarizer)가 일찍 시작할 수 있게 하기."],"1113552411":["어떤 사안이 제일 중요한지 고객에게 물어보고, 이번 세션에서는 그것만 처리하기"],"1113563448":["도구 출력이 대화 컨텍스트에 들어가기 전에 반환에 필요한 필드만 남기고 잘라내서, 관계없는 데이터가 절대 쌓이지 않게 하기."],"1115634812":["두 경우 모두 isError를 돌려주기. 결과가 비어 있는 것도 알릴 만한 실패의 한 종류이기 때문임."],"1118539303":["클레임 파이프라인(claims pipeline)이 모델 호출을 두 번 함.","첫 번째 호출은 스캔된 양식을 타입이 지정된 필드(typed field) 18개로 바꿔서, 사람 개입 없이 곧바로 데이터베이스에 적재함.","두 번째 호출은 손해사정인(adjuster)의 서술을 보험사가 정한 문구로 작성함: 필수 면책 조항 문장 하나와 정해진 순서의 섹션 네 개임.","맞는 선택지는 어느 두 가지인가? (두 개를 선택할 것.)"],"1121573838":["argument-hint만 있으면 됨. 이름만 주어지면 스킬 본문에서 도구 규칙을 강제할 수 있음."],"1122443638":["세션 B는 제약 조건, 상한(cap), 마감일을 전용 필드에 담아 모든 프롬프트에 다시 채워 넣고, 조사 서술(narrative)은 그 주변에서 요약되는 방식임."],"1122999507":["전체 파이프라인은 유지하되 조회 답변을 캐시해서, 반복되는 질문은 빠르게 나오게 하기."],"1123691943":["스테이징을 없애고 그 단계가 직접 수정하게 하기.","pull request 리뷰 자체가 사람이 거치는 게이트인 데다, 변경 내용이 기계적이라 플랜을 추가해도 안전성은 더해지지 않고 단계만 늘어남."],"1124745130":["정책은 다음과 같음. 500달러를 넘는 환불은 항상 사람에게 넘겨야 함.","일반 환불은 자동화된 상태로 두면서 정책 준수를 보장하는 구현은 무엇인가?"],"1125370792":["help-centre 글을 에이전트의 source set(출처 집합)에서 빼서 policy 페이지만 인용될 수 있게 하기"],"1126041742":["도구를 고르기 전에 질의를 분류해 주는 전용 라우팅 계층을 만들 수 있을 때까지 track_shipment를 롤백하기"],"1127469655":["완전히 새 session을 시작해서 3주치 탐색 전체를 다시 돌리기. 낡은 정보가 하나도 남지 않게 하는 것임."],"1129211473":["verify_batch를 고친 상태로 마이그레이션(migration)을 처음부터 다시 실행해서, 모든 배치가 수정된 로직으로 검증되게 하기"],"1130789049":["새 세션에서 다시 시작해서 성능 저하(degradation)를 없애고, 처음부터 다시 탐색하기."],"1131587001":["규정을 지킨 대화들로 커스텀 모델을 파인튜닝해서 그 규칙을 모델에 내재화시키기."],"1132764641":["공용 서비스 토큰 하나를 만들어서 커밋하기. 개인 토큰 여섯 개를 관리하는 것보다 간단하기 때문임."],"1135382761":["tax_id 필드에 값이 채워진 추출 결과는 신뢰도 점수(confidence score)와 상관없이 전부 사람 검토로 보내고, 나머지 모든 인보이스(invoice)는 자동화 경로에 그대로 두는 프로그래밍 방식의 게이트(programmatic gate)임."],"1136425626":["사전 승인되지 않은 것은 전부 자동 거부하는 모드로 실행을 시작하고, 리뷰에 필요한 read와 diff 명령어만 미리 승인하고, branch나 push 형태의 명령어에 대한 거부 규칙(deny rule)은 커밋해 두어서 이후에 수정이 어떤 모드를 고르든 항상 거부되게 하기."],"1136584837":["저장소를 클론하는 모든 개발자에게 지시가 적용되게 하려면 CLAUDE.md를 어디에 두어야 하는가?"],"1136608828":["죽은 세션을 두 갈래로 fork 해서 하나로 정하기 전에 이어서 갈 전략들을 비교하기"],"1138157728":["같은 프롬프트로 subagent를 두 번 실행하고 테스트 파일 두 개를 합쳐서, 한 실행에서 빠진 부분을 다른 실행이 채우게 하기"],"1139880079":["900줄짜리 루트 CLAUDE.md에 팀 코딩 표준과 개발자 한 명의 개인 단축 설정(\"적용하기 전에 항상 diff를 보여줘\")이 뒤섞여 있음.","팀원들은 Claude가 원하지도 않은 diff를 보여준다고 불평함.","내용을 어떻게 재배치해야 하는가?"],"1141031117":["쿠폰 도구의 에러가 \"안전하게 가자\"는 이유로 기본값 isRetryable: true로 잡혀 있음. 어제 로그를 보면, 고객이 쿠폰 코드를 오타로 넣었는데 에이전트가 똑같은 apply_coupon 호출을 조용히 네 번 재시도하고 나서야 사과했음. 코드를 다시 확인해 달라는 말은 한 번도 하지 않았음.","반면에 진짜 30초짜리 서비스 장애는 같은 재시도 로직으로 잘 처리됐음.","무엇을 바꿔야 하는가?"],"1144359226":["장애가 있을 때는 일부 섹션이 빠질 수 있다는 안내 문구를 모든 리포트에 넣기."],"1146079444":["Claude Code에 레거시 날짜 처리 유틸리티를 새 라이브러리로 전환해 달라고 요청함.","산문으로 쓴 명세는 꽤 자세했는데도 시도할 때마다 \"타임존 동작 유지\"를 다르게 해석함. 어떤 시도는 UTC로 변환하고, 어떤 시도는 로컬 오프셋을 그대로 둠.","가장 빨리 수렴시키는 방법은 무엇인가?"],"1147921291":["저장소에서 가장 큰 소스 파일을 열어서 처음부터 끝까지 읽고 코드 스타일 감을 잡기."],"1148931194":["180페이지짜리 재보험 계약서(reinsurance treaty)를 60개 필드로 만들어야 함.","문서 전체를 한 번의 호출로 처리하면 다섯 번 중 한 번 꼴로 엉뚱한 조항에서 값을 뽑아옴. 정의 조항(definitions article)과 청구 조항(claims article)이 거의 똑같은 문구를 쓰기 때문임.","전체 문서 묶음(corpus)에서 구조는 일정함. 항상 같은 8개 조항이 같은 순서로 나옴.","어떤 분해(decomposition) 방식이 맞는가?"],"1151181908":["거절하기. 코디네이터를 거쳐 가야 관측 가능성, 일관된 에러 처리, 통제된 정보 흐름이 유지되기 때문임. 자주 일어나는 단순 조회는 대신 종합 에이전트한테 범위를 좁힌 verify_fact 도구를 주면 됨."],"1151211810":["20명 규모 툴링 팀에 한 주 동안 요청이 세 건 들어옴. (a) 풀 리퀘스트(pull request)를 열기 전에 다들 입력하는 한 줄짜리 프롬프트: \"내가 스테이징한 변경사항을 설명으로 요약해줘.\" (b) 템플릿을 읽고, 매개변수 4개가 필요하고, 파일 약 40개를 만들어내는 9단계 서비스 스캐폴딩(service-scaffolding) 절차인데, 실행의 약 절반에서 대상 서비스 이름을 빠뜨림. (c) 생성되는 파이썬 코드는 전부 팀의 로깅 래퍼(logging wrapper)를 써야 한다는 요구사항인데, 누가 무엇을 호출했든 안 했든 매 턴마다 적용돼야 함.","어떤 배치가 맞는가?"],"1151949780":["바로 실행해서 한 줄짜리 수정을 적용하고, 이미 실패하고 있는 회귀 테스트를 돌려서 확인하기","진단은 이미 끝났고(\"스택 트레이스가 지점을 특정\") 검증 수단도 있음. 여기에 절차를 더 붙여 봐야 이미 끝난 일을 다시 하는 것일 뿐임."],"1155385176":["세그먼트 검증을 제대로 마친 뒤에 고신뢰 인보이스 추출을 자동화했음.","6개월 뒤, 새 공급업체의 인보이스 레이아웃이 자동화 구간 안에서 조용히 실패하기 시작함.","어떤 상시 안전장치가 있었으면 이 문제를 찾아냈겠는가?"],"1155593730":["리뷰어는 pull request가 바꾼 부분만 봐야 하는데, 그 발견 사항이 계속 pull request가 건드리지도 않은 파일을 인용함.","지금 prompt는 \"이 브랜치의 변경 사항을 리뷰해\"라고만 돼 있고, session에는 표준 read 도구에 더해 광범위한 shell 허용 권한도 있음.","실제로 범위를 좁혀주는 변경은 어느 것인가?"],"1159468903":["기준을 강화해서 auto-merge에 \"low\" 대신 \"very low\" 라벨을 요구하게 하되, gate로 쓰는 점수는 그대로 유지하기"],"1160687234":["세션을 fork해서 예전 수치와 새 수치를 나란히 비교할 수 있게 하고, 그 fork에서 보고하기"],"1161307372":["서비스별로 독립된 작업 다섯 개로 나누고, 각 세션이 해당 서비스에 맞는 방식을 스스로 정하게 하기"],"1162516130":["tool_choice: \"any\"로 설정해서, 모델이 텍스트로 답하지 말고 반드시 도구를 호출하게 하기"],"1165687000":["환불은 처리하고 보상 요구는 정중히 거절하기. 정의되지 않은 요청은 기본적으로 거절 처리되니까."],"1166646737":["(1) po_number를 nullable로 바꿔서 값이 없으면 null로 가게 하기. 필수 필드로 두면 모델이 없는 값을 지어내게 되기 때문임. (2) enum에 \"unclear\"를 추가하고, 상세 문자열을 받는 \"other\"도 같이 넣기. 정보가 없는 것과 범주가 안 맞는 것은 서로 다른 결함이라 처방도 다르기 때문임."],"1168162658":["assistant 턴을 예상 출력의 시작 부분으로 프리필(prefill)해서, 응답이 그 지점부터 이어지게 하고 preamble이 들어갈 자리가 아예 없게 하기. 이 모델 세대(generation)는 이 기능을 여전히 지원함."],"1168721428":["argument-hint: 인자를 물어보게 하면 출력이 초점을 유지함."],"1168949046":["(1) paths: [\"infra/**\"]를 지정한 .claude/rules/ 는 조건에 맞는 파일을 건드릴 때마다 자동으로 로드됨. (2) 온디맨드 skill은 그 작업에서 호출할 때만 로드됨.","경로 기반 스코핑으로는 같은 디렉터리 안에서 작업 종류까지 구분하지는 못함."],"1170054176":["둘 다 상급자에게 넘기기. 하나는 감정적으로 위험하고, 다른 하나는 정책에 근거가 없기 때문임."],"1170088572":["support-agent 리포지토리(repository)에서 prompts/ 폴더에 에이전트의 system-prompt 템플릿이 들어 있음.","루트 메모리 파일(root memory file)을 보면 마크다운(markdown) 줄은 전부 100자 미만이어야 하는데, 이것 때문에 프롬프트 템플릿이 망가짐.","한 메인테이너(maintainer)는 prompts/ 안에 메모리 파일을 추가하자고 제안함.","그 파일은 딱 한 가지만 빼고 팀이 원하는 걸 다 충족함.","충족하지 못하는 그 한 가지는 무엇인가?"],"1170274052":["심각도 역순으로 고쳐서 치명적인 것들이 마지막에 반영되게 하기."],"1170460595":["규칙 1은 PostToolUse에 맞음. 모델이 보기 전에 결과를 변환하는 것이기 때문임. 그런데 규칙 2는 나가는 도구 호출을 가로채는 hook이 필요함. PostToolUse가 실행될 시점엔 process_refund가 이미 실행된 뒤이기 때문임."],"1170897477":["\"서론(preamble)을 억누르려고 'Here is the summary:'를 프리필(prefill)해온 서비스라면, 그 대신 모델에게 직접 지시하거나, XML 태그 안에 출력하게 하거나, 후처리(post-processing)에서 서론을 걷어내는 쪽을 써야 함.\""],"1171340674":["원인이 무엇이든 \"no_data\"가 오면 코디네이터가 항상 한 번은 재시도하게 하기"],"1172063462":["컴플라이언스 규칙에 따르면 자동화된 리뷰 단계는 저장소를 절대 바꾸면 안 됨. 파일도, 브랜치도, 태그도 안 됨.","네 팀은 조치 네 가지를 두고 논쟁 중임.","네 가지 중 그 보장을 지켜낼 가능성이 가장 낮은 것은 어느 것인가?"],"1172697139":["주문 관련 작업 전에는 get_customer로 확인하는 게 필수라고 명시한 시스템 프롬프트."],"1173008846":["release notes 작성 절차를 project memory 파일에 넣어둬서 스프린트가 끝날 때마다 항상 바로 볼 수 있게 하기"],"1173433145":["문제가 되는 줄을 정확히 가리키는 스택 트레이스가 있는, 파일 하나짜리 버그를 고치는 일."],"1173961381":["에이전트에게 Grep을 덜 쓰고 일반적인 코드베이스에 대한 배경지식에 더 기대라고 지시하기."],"1174675330":["둘 다 고정 파이프라인(fixed pipeline)임. 각 워크로드(workload)가 시작 전에 명확한 목표를 제시하기 때문임."],"1175071696":["컴플라이언스 팀은 매일 밤 문서 20,000건을 스캔해서, 오전 9시라는 빡빡한 규제 마감까지 결과를 반드시 받아야 함.","문서는 밤 11시에 전부 도착함.","엔지니어 한 명이 비용 50% 절감을 노리고 Batches API를 제안함. \"밤 11시에 제출하면 배치는 보통 2~3시간이면 끝남.\" 재무팀은 아주 마음에 들어 함.","올바른 평가는 무엇인가?"],"1175174894":["초안 작성용 subagent에 lookup_order와 get_customer를 줘서, 글을 쓰면서 필요한 세부 정보를 뭐든 가져올 수 있게 하기."],"1177320771":["구조화된 발견마다 detected_pattern 필드를 추가해서 어떤 코드 구문이 그것을 촉발했는지 기록하기. 그다음 패턴별로 기각률을 분석하기."],"1178022966":["세 개 전부 project skill로 만들기. skill은 버전 관리(version control)가 되고, 인자(argument)를 받고, 이름으로 호출할 수 있으므로, 단일 메커니즘 하나로 모든 경우를 커버하면서 20명에게 설명할 것도 가장 적음."],"1178605548":["둘 다 만들어서, 에이전트가 가진 모든 capability가 하나의 일관된 인터페이스를 통해 제공되게 하기"],"1181786494":["(a) Glob. 파일 이름과 경로를 매칭함. (b) Grep. 파일 내용을 검색함."],"1181831102":["extractor가 추출 결과와 함께 문서 family에 대한 자체 판단도 반환하게 하고, 그 판단이 원래 전달받은 분류와 다르면 coordinator가 해당 레코드 로드를 거부하게 하기."],"1181996844":["에이전트의 판단력을 끌어올리려면 few-shot 예시는 어떤 종류의 케이스를 노려야 하는가?"],"1182039668":["두 방식을 합치기. 먼저 extended thinking 자가 검토를 돌리고, 그다음 독립 인스턴스를 돌린 뒤, 커버리지를 최대로 하려고 두 쪽 지적을 합집합으로 모으기"],"1183223140":["내용을 검색해서 74개 파일과 정확한 줄 번호를 확보하고, fixture에 있는 경우는 건너뛸 만큼 주변 텍스트를 충분히 포함한 앵커(anchor)로 한 파일씩 바꾼 다음, 마지막에 포매터(formatter)를 돌리기."],"1184151429":["확실히 커버하려고 두 계정의 가장 최근 주문 양쪽에 환불을 처리하기"],"1184157022":["결함은 없음. 파일을 읽으면 언제나 현재 내용이 나오므로 재개된 세션은 알아서 바로잡힘."],"1184428129":["빈 결과가 나오면 믿기 전에 에이전트가 무조건 세 번 재시도하게 하기."],"1187265979":["정책 조회(policy lookup)가 각 조항을 그 출처 문서와 문서의 개정일(revision date)까지 함께 반환하게 하고, 문서 두 개가 서로 다르면 두 해석을 모두 남겨 두고, 그 충돌은 에이전트가 알아서 해결하지 않고 사람 앞에 올리기."],"1190013497":["plan 모드가 아니라 직접 실행이 적절한 작업은 무엇인가?"],"1190288766":["먼저 플레이리스트를 복구해 주고, 그다음에 그래도 상담원 연결을 원하는지 물어보기."],"1191967624":["데이터베이스 스키마를 MCP resource로 노출하기. 에이전트가 탐색용 도구 호출 없이 볼 수 있는 콘텐츠 카탈로그가 됨."],"1193468248":["코멘트가 올라가기 전에 신뢰도(confidence)가 임계값(threshold) 아래인 발견 사항(finding)은 제외해서, 실제일 가능성이 높은 발견 사항만 개발자에게 전달되게 하기"],"1194000845":["\"이 레거시 시스템의 모든 엔티티에 대해 CRUD 보일러플레이트 코드를 생성할 것\"이라는 요청임. 그런데 엔티티가 여기저기 흩어져 있고, 일부는 상속 패턴을 쓰고, 몇 개는 작업 도중에야 알게 될 문서화되지 않은 상호 의존을 갖고 있음.","어떤 분해 방식이 맞는가?"],"1194097589":["러너(runner)에게 서버가 필요로 하는 인증 정보(credentials)를 주기. 노트북은 개발자 토큰(developer token)으로 인증하는데 CI에는 그 토큰이 없기 때문임."],"1194935787":["컨텍스트 창이 더 큰 모델로 바꿔서 한 번에 모든 파일에 충분히 주의가 가게 하기"],"1195995661":["기존 deny 규칙을 project settings 파일에서 managed settings로 옮기기. 그러면 어시스턴트가 시작하는 subprocess에까지 적용 범위가 넓어짐."],"1196158023":["무언가를 gate하게 두기 전에, 라벨링된 과거 pull request 세트를 채점해서 \"low\" 라벨이 실제로 무엇을 의미했는지부터 확인하기"],"1196261274":["memo의 첫 섹션 제목으로 assistant turn을 prefill해서 순서가 처음부터 고정되게 하고, 레코드는 schema 경로에 그대로 두기."],"1200805400":["같은 리서치 플랫폼에서 세션 두 개가 돌아감.","세션 A는 이미 작성된 리포트에 대한 실시간 분석가 채팅임. 6개월치 로그를 보면 어떤 답변도 약 10턴(turn) 이전에 나온 내용이 필요했던 적이 없었고, 플랫폼은 요청 경로(request path)에서 추가 모델 호출을 금지함.","세션 B는 4시간짜리 다중 소스 조사(multi-source investigation)인데, 클라이언트 제약 조건, 예산 상한(budget cap), 마감일이 첫 턴에서 정해졌고 끝까지 유지되어야 함.","맞는 배정은 어느 두 가지인가? (두 개를 선택하시오.)"],"1201486600":["이 규칙은 hook이 아니라 system prompt에 있어야 함. 그래야 모델이 제한 사항을 자기 말로 설명하고 고객에게 대안을 제시할 수 있음."],"1204579964":["리서치 한 번에 하위 작업이 다섯 개임. 독립적인 주제 검색 세 개, (4) 그 검색 결과 세 개가 전부 있어야 하는 비교, (5) 그 비교가 있어야 하는 총괄 요약임.","coordinator는 Task 호출을 어떻게 짜야 하는가?"],"1205858560":["세션을 재개하고 어떤 파일 3개가 바뀌었는지 명시적으로 알려 줘서 그 파일들만 다시 읽게 한 다음 이어서 진행하기. 어제 분석한 내용 대부분은 아직 유효하기 때문임."],"1206597366":["티켓 전체를 끝내는 abort 신호. subagent 하나라도 실패하고 있는 동안에는 잘못된 답이 고객에게 가지 않도록 하는 것임."],"1207020481":["값 누락(missing-value) 케이스 세 가지를 따로 유지하고, 각각에 회귀 테스트(regression test)를 추가해서 실패가 다시 생기면 바로 잡히게 하기."],"1211534115":["리뷰어(reviewer)가 각 발견 내용에 신뢰도 수치(confidence number)를 붙이게 하고, merge bot이 임계값(threshold) 아래의 스타일 관련 발견은 걸러내게 하기"],"1212409486":["max_tokens에 별도 분기를 주어(한도를 올려서 재시도하거나, 부분 출력을 의도적으로 받아들이거나), 그냥 평범한 턴으로 흘러가게 두지 않기."],"1214178398":["skill로 패키징은 하되 개인 스코프(personal scope)에 남겨두기. 팀 전체로 봐도 한 달에 두 번이면 트래픽이 적은 편이고, 개인 스코프로 두면 팀 공유 폴더에서 리뷰 부담도 피할 수 있음."],"1215005651":["에이전트가 연달아 나온 동일한 결과를 비교하게 하고, 시도 사이에 아무 변화가 없으면 재시도를 멈추게 하기."],"1215115795":["둘 다 architect의 단일 엔진을 쓰기. 처음부터 작성된 subtask 목록이 있으면 두 작업 모두 감사 가능(auditable)하고 실행 간 비교도 가능해지기 때문임."],"1215737697":["개발자에게 세 질문을 서로 다른 날 세 번에 나눠서 따로 요청하라고 하기"],"1218328031":["제품을 진입점이 분리된 두 개의 시스템으로 나누고, 사용자가 어느 쪽에 묻는 건지 직접 고르게 하기."],"1218507693":["모델이 도구를 안정적으로 고르는 데 가장 도움이 되는 도구 설명은 무엇인가?"],"1218843950":["Call 2는 네 개의 섹션 제목을 나열한 enum 필드를 쓰는데, 이는 그것들의 존재와 순서를 둘 다 보장함."],"1219646093":["네 에이전트가 12개 파일짜리 service scaffold를 생성한 다음, 같은 대화 안에서 자기가 방금 쓴 걸 리뷰함.","두 달치 데이터를 보면, 이 리뷰는 자기 결과물의 97%를 승인하고, 실제 production까지 가는 결함은 파일 하나짜리 로직 실수와, 한 파일의 schema가 다른 파일과 어긋나는 불일치(mismatch)로 나뉨.","이 문제를 해결하는 변경 사항 두 가지는 무엇인가? (두 가지를 선택할 것)"],"1219883591":["그 팀원 말이 맞음: 스키마가 표현할 수 없는 제약은 필드 설명에 넣는 것이므로, 패딩 규칙도 거기 넣고 모델이 완성된 줄을 만들어내게 하면 됨."],"1220317745":["보고서마다 끝에 참고한 출처 전체의 목록을 붙이기."],"1220628376":["리뷰 프롬프트에 \"매우 확신하는 finding만 보고할 것\"을 추가하기"],"1221898979":["추출을 믿을 수 없으니까 모든 계약서를 사람 검토로 보내기."],"1222378191":["세 문장 이상으로 목적, 예시 질의를 곁들인 기대 입력 형식, 엣지 케이스, 그리고 이웃 도구와의 명시적 경계(\"가이드는 search_docs를 쓰고, 제품 데이터는 이걸 쓸 것\")까지 담기"],"1223471657":["점진적 요약(progressive summarization): 30분마다 각 에이전트의 발견 내용을 계속 이어지는 서술형 digest에 접어 넣고, digest는 2K 토큰 밑으로 유지하기."],"1224101635":["모든 리뷰의 프롬프트와 응답 전체를 로그로 남겨서 사람이 직접 살펴보기"],"1226777461":["이 workflow에는 터미널이 연결되어 있지 않다고 CLI에 알려주는 headless 환경 변수(environment variable)가 빠져 있음. workflow 파일에 그것을 설정하기"],"1227427215":["두 문서 다 손상됨으로 표시하고 파이프라인에서 빼기"],"1229885562":["PR #812 리뷰를 원본 프롬프트에 후속 내용을 덧붙여서 처음부터 다시 실행하기. 리뷰는 재현하는 데 비용이 적게 들고, 이렇게 하면 식별자(identifier)를 따로 관리할 필요도 없기 때문임."],"1230381875":["인보이스 날짜가 결제 기한(payment due date)보다 늦지 않은지 확인하고 늦은 경우에는 그 레코드를 검토(review)로 돌리기."],"1230775847":["과거 사례에서 검증을 먼저 하는 행동을 보여주는 few-shot 예시."],"1230949141":["픽스처(fixture) 파일 세 개를 먼저 바꿔서 남은 부분은 전부 안전하게 일괄 치환(global replace)할 수 있게 하기"],"1234573375":["둘 다 PostToolUse로. 무슨 일이 있었는지 살펴보고 나중에 한곳에서 전부 바로잡는 방식임."],"1235259064":["페이지 참조가 들어 있는 메모는 원문 그대로(verbatim) 유지하는 선택적 보존(selective retention) 방식."],"1236441858":["max_tokens를 늘려서 모델이 잘리지 않고 레이블을 끝까지 완성할 수 있는 여유를 주기"],"1237680920":["둘 다 사내에서 만들기. 팀이 직접 짠 서버는 이 팀이 쓰는 필드와 워크플로에 딱 맞게 만들 수 있기 때문임."],"1238928041":["밤새 쌓인 search subagent 로그는 세 줄인데 전부 똑같음. isError는 true, 메시지는 \"Source fetch failed\"임.","실제 원인은 셋이었는데, 30초짜리 gateway timeout, 시스템이 갖고 있지 않은 credential을 요구하는 paywall, subagent 스스로 만든 잘못된 형식의 query string이었음.","coordinator는 셋 다 같은 횟수만큼 재시도했고, 그 과정에서 18분을 날렸음.","옳은 변경은 무엇인가?"],"1239494875":["실패가 반복되면 MCP 연결이 리셋되게 만들기"],"1239504683":["프롬프트 체이닝(prompt chaining)임. 집중된 패스를 순차로 세 번 돌리는데 보안, 의존성, API 호환성 순서이며, 각 패스마다 자체 기준과 출력 스키마를 둠."],"1240057235":["팀 스킬 안에 사용자 이름을 기준으로 갈라지는 if 분기를 넣기"],"1241651950":["정해진 세 사이클이 끝나면 남은 빈틈은 종합 에이전트가 자기 일반 지식으로 채우게 하기"],"1241660526":["폐기 예정인 formatCurrency 함수가 실질적으로 쓰이는 곳을 하나도 빠짐없이 찾아야 함.","여기엔 주의할 점이 있음. 래퍼 모듈 3개가 그 함수를 각기 다른 이름(formatMoney, toCurrencyString, fmtC)으로 다시 export하고 있음.","올바른 추적 전략은 무엇인가?"],"1243302285":["포스트모템(postmortem) 후속 조치 항목: 결제 게이트웨이 클라이언트에서 재시도 백오프(retry backoff)가 작동하는 방식을 바꾸는 것임.","설계안은 두 가지가 다 말이 되는데(클라이언트 내부의 지터(jitter) 방식 대 큐 계층의 정책 방식), 이 변경은 두 서비스에 걸쳐 파일 9개에 영향을 주며, 결제 그룹은 코드가 반영되기 전에 승인된 접근 방식을 공식 기록으로 남길 것을 요구함. 이 단계를 건너뛴 지난번 변경은 고객 1,400명에게 중복 청구를 일으켰음.","어떤 실행 방식이 맞는가?"],"1245807577":["payments/를 건드리는 변경은 라벨과 상관없이 전부 사람 리뷰어에게 보내고, 문제없이 잘 돌아가는 영역은 자동화 상태로 두기."],"1246257395":["팀에 MCP 연동이 두 개 필요함. (a) 표준적인 Jira 이슈 트래킹, 그리고 (b) 회사 자체 내부 배포 승인 시스템임.","각각 어디서 가져오는 것이 권장되는 선택인가?"],"1247308990":["송장(invoice) 처리 에이전트는 벤더 송장을 처음부터 끝까지 자동으로 승인함.","컴플라이언스 부서는 이제 세금 ID(tax-ID) 필드가 있는 모든 송장은 사람이 검토하도록 요구함. 이는 최선을 다하는 정도가 아니라 반드시 지켜야 하는 보장이며, 세금 ID 필드가 없는 송장은 계속 완전 자동으로 처리됨.","tax_id 필드의 추출 신뢰도(confidence)는 현재 평균 0.94임.","두 요건을 모두 만족하는 구현은 어느 것인가?"],"1247559609":["계속 재개(resume)하면서, 서로 충돌하는 레코드 두 개를 보면 항상 더 최신 것을 우선하라는 상시 지시(standing instruction)를 추가하기"],"1253765931":["이 threshold(임계값)는 이 비즈니스에 비해 너무 공격적임. $2,000로 올리면 대부분의 환불은 여전히 자동으로 처리되고, dead end는 자릿수 하나만큼 줄어듦."],"1253942564":["인보이스 파이프라인 하나에 추출 결함이 둘 있음. (1) 어떤 인보이스에는 PO 번호가 없는데 모델이 그것을 지어냄. (2) product-type 필드에 어느 카테고리에도 안 맞는 문서가 들어올 때가 있는데, 모델이 가장 가까운 enum 값을 억지로 고름.","각각에 맞는 해결책은 무엇인가?"],"1254048442":["tool_choice: \"any\". 모델이 도구 중 하나는 반드시 호출해야 하고, 눈앞의 문서에 맞는 스키마를 고를 수 있음."],"1254922325":["팀에서 일부러 버그를 심어둔 코드 변경 50건으로 실험을 돌림.","같은 세션에서 스스로 리뷰한 경우는 14%를 찾아냈고, extended thinking을 켠 같은 세션은 18%, diff와 리뷰 기준만 받은 새 인스턴스는 71%를 찾아냄.","시니어 엔지니어는 extended thinking 수치를 두고 \"자기 리뷰 프롬프트만 더 다듬으면 된다는 증거이고, 모델이 깊이 추론할 수 있는 것은 분명하다\"고 주장함. 이 데이터를 어떻게 읽어야 하는가?"],"1257313208":["대화는 하나로 유지하되, 요약을 작성할 때마다 가장 최근의 parse_resume 결과만 쓰라고 에이전트에게 지시하기"],"1258252857":["세션이 시작된 이후 나온 모든 경고(alert) 유형을 담아두는 구조화된 상태 객체(structured state object)를 쓰기. 이것이 컨텍스트(context) 증가를 억제함."],"1260261001":["이중 결제부터 해결하고, 배송 문제와 적립 문제는 고객에게 별도 티켓으로 올려달라고 요청하기"],"1261951511":["네 사용자 스코프에 똑같이 /commit 이름으로 두면, 너한테만 팀 버전을 깔끔하게 덮어쓰기"],"1262044633":["팀 표준은 프로젝트 수준에 그대로 두고, 개인 취향은 그 개발자의 ~/.claude/CLAUDE.md로 옮기기. 덩치 큰 주제 영역은 .claude/rules/ 파일로 쪼개는 것도 고려해 보기"],"1264203202":["tool choice를 \"any\"로 설정해서, subagent가 텍스트로 답하는 대신 반드시 도구를 호출하게 하기"],"1264847279":["frontmatter가 컨텍스트를 분기(fork)하는 skill로 실행해서, 메인 대화에는 요약만 돌아오게 하기"],"1265852797":["소스 5개짜리 리서치 실행에서, 자체 재시도를 했는데도 소스 두 개가 실패했음. 하나는 유료 장벽(paywall)이었고 하나는 타임아웃임.","그래도 종합(synthesis) 결과물은 나가야 함.","올바른 출력 설계는 무엇인가?"],"1267696937":["재시도 프롬프트가 모델에 단서를 하나도 주지 않고 있음. 원본 문서, 실패한 추출 결과, 구체적인 검증 에러를 같이 넣어주기. 그런 피드백이 있으면 형식 수준의 실패는 보통 재시도 한 번에 풀리므로 6번씩 시도할 필요가 없음."],"1268839578":[".tsx 파일을 편집할 때는 트리 어디에 있든 접근성(accessibility) 규칙을 로드하는 방식임."],"1269606301":["인용(citation)마다 레코드 하나씩 있는 구조화된 state object: 출처(source), 페이지(page), 인용된 구간(quoted span)."],"1273030390":["CI 플랫폼이 실행이 멈추기 전에 비용이 커질 수 없도록 정해둔 wall-clock limit(실제 시간 제한)에서 job을 강제 종료하게 하기."],"1275450912":["개발자가 이렇게 물음: \"체크아웃 플로우는 feature flag를 어디서 읽고, audit log는 어디에 쓰고, billing adapter는 뭘 의존하나요?\" 이 세 질문은 서로 의존하지 않음.","네 에이전트는 메인 대화에서 이 질문들을 하나씩 순서대로 답하는데, 세 번째 답을 할 때쯤이면 앞의 두 개는 이미 놓친 상태임.","어떤 변경 두 가지가 맞는가? (두 개 선택)"],"1276709779":["finding은 전부 유지하되 severity 라벨을 붙여서, 개발자가 중요한 것만 걸러볼 수 있게 하기"],"1278198688":["고객 요청이 정책 공백에 걸린 것임. 이 특정 사례에 대해서는 정책에 아무 언급이 없기 때문임."],"1278300537":["그 규칙들은 원래 개발자들의 사용자 레벨 ~/.claude/CLAUDE.md 파일에 들어 있음(오래전에 각자 따로 추가한 것임). 저장소의 프로젝트 레벨 CLAUDE.md로 옮겨서, clone만 하면 앞으로 들어올 사람까지 모두에게 전달되게 하기"],"1278662914":["coordinator의 분해 방식을 손봐서 리서치 범위를 겹치지 않는 뚜렷한 하위 주제와 소스 유형으로 나누기(예: EU / 미국 / 중국 / 국제 표준). 중복은 최소화하면서 주제 전체를 다 덮게 하는 것임."],"1279419842":["tax_id 신뢰도 점수가 0.90 밑으로 떨어지면 그 송장은 사람 검토로 보내기. 신뢰할 수 없는 필드가 바로 컴플라이언스 리스크를 만들기 때문임."],"1279842754":["메시지를 별개의 이슈 세 개로 쪼개고, 공유된 고객 컨텍스트를 써서 병렬로 조사한 다음, 세 개를 모두 다루는 통합 해결책 하나로 종합하기."],"1284436845":["종합 지표는 언제나 학습 데이터로 계산되기 때문임."],"1285644333":["두 설계 다 각각 다른 브랜치에 구현해서 결제(payments) 담당자가 서명하기 전에 실제 동작하는 코드를 비교할 수 있게 하기. 그런 다음 채택되지 않은 브랜치는 삭제하기."],"1285834411":["모델은 순차적으로 읽고 가장 최근 텍스트를 제일 잘 기억하므로 맨 끝에만."],"1286764862":["라우팅이 안정될 때까지 analyze_document를 잠시 꺼 두기."],"1290164358":["코드의 특정 영역만 가리키지 말고, 위임하는 질문 하나하나를 검증 가능한 답이 나올 만큼 구체적으로 만들기. 뭘 묻는 건지, main 에이전트가 그 답을 가지고 뭘 할 건지를 명시해서."],"1290174010":["출력 후 필터를 둘 다에 적용하기. 한 곳에서 정책 위반과 톤 문제를 함께 찾아낼 수 있기 때문임."],"1290193732":["리포트 생성기는 subagent 다섯 개가 모아온 결과를 하나의 긴 입력으로 받음.","QA를 해보니 가운데인 2~4번 섹션의 결론이 최종 리포트에서 늘 빠지고, 1번과 5번 섹션은 잘 반영됨.","가장 좋은 완화책은 무엇인가?"],"1291379967":["모든 required field(필수 필드)가 존재하는지, 그리고 각 값이 선언된 타입을 갖고 있는지 확인하는 것임."],"1291445291":["사전 승인 목록 밖의 것은 전부 거부하는 모드로 세션을 시작하고, read와 diff 명령만 사전 승인하기"],"1291904621":["네 생산성 에이전트(productivity agent)는 도구 19개를 갖고 있음.","텔레메트리(telemetry)를 보면, 턴(turn)의 23%에서 잘못된 도구를 고름. 목적에 맞게 만들어진 도구 4개가 이미 커버하는 일을 범용 run_shell 도구로 처리하려는 경우가 가장 많고, \"어떤 파일이 바뀌었어?\"라는 질문에는 아무것도 호출하지 않고 그냥 글로만 답할 때도 있음.","어떤 두 가지 변경이 맞는가? (두 개를 선택할 것.)"],"1292720546":["새 개발자의 MCP 캐시가 오래됐기 때문임. Claude Code를 다시 설치하고 저장소를 새로 clone하기"],"1292953522":["인터뷰 패턴을 쓰기. 구현 전에 Claude가 먼저 명확히 하는 질문을 던지게 해서, 무효화 전략이나 실패 모드 같은 고려사항을 앞단에서 끄집어내기"],"1293263684":["문서 전체에 대해 한 번만 호출하되, 각 값이 어느 조항에서 나왔는지 잘 살피라는 지시를 담는 방식임."],"1294160236":["(1)과 (2)는 프로그램적 통제로 걸기. 선행 조건 게이트와 도구 호출을 가로채는 hook임. 위반하면 금전적, 보안적 피해가 생기기 때문임. (3)과 (4)는 가끔 놓쳐도 괜찮으니 프롬프트 지침으로 두기."],"1294259143":["\"batch 안에서의 usage는 표준 가격의 절반으로 청구되는데, 이것이 바로 아무도 기다리지 않는 워크로드를 옮기는 이유 전부임.\""],"1297083251":["\"최솟값이나 최댓값 같은 숫자 범위는 structured-output 경로가 대신 강제해 주는 것이 아님. 그 제약은 필드의 description에 적어 두고, 우리 자체 validation 코드에서 확인해야 함.\""],"1298821947":["배치를 매시간 제출하기. 자주 제출하면 처리 시간 창이 12시간 아래로 압축됨."],"1298837512":["각 서브에이전트의 프롬프트에, 섹션을 쓸 때 \"found nothing\"과 \"could not run\"을 신경 써서 구분하도록 지시하기"],"1299740189":["보안 검사는 즉시 결과가 필요한 블로킹 작업이니 동기 API에 그대로 두고, 야간 테스트 생성은 50% 절감을 노려 Message Batches API로 옮긴 다음 결과는 custom_id로 맞추기."],"1301032861":["(a)는 프로젝트 공유 명령 폴더(command folder)에 짧은 저장된 프롬프트로 두고, (b)는 기대하는 인자(argument)를 선언하는 project skill로 둬서 서비스 이름이 빠지면 추측하지 않고 요청하게 하고, (c)는 저장소 메모리 파일로 두기. 아무것도 호출되지 않고 매 턴마다 유지돼야 하기 때문임."],"1307087605":["세 번째 시도, 네 시간째임.","세션이 컨텍스트 한도(context limit)에 가까워지고 있어서, 팀은 실행이 계속되는 동안 무엇을 버릴지 정해야 함.","브리핑에 나온 제약 조건에 맞는 전략은 어느 것인가?"],"1308746838":["(1) any. 아니면 특정 추출 도구를 강제하기. (2) none. (3) auto."],"1309183556":["스킬은 하나로 두되 프롬프트에 지시를 하나 넣기. \"데이터베이스에 적용하기 전에 항상 사용자에게 확인받아.\""],"1309945928":["어떤 고객 지원 에이전트의 루프는 응답에 텍스트 블록이 하나라도 있으면 종료됨. 게다가 \"컨텍스트를 깔끔하게 유지하려고\" 실패한 도구 결과(tool result)를 조용히 버림. 실제 결함을 고치는 변경 두 가지는 무엇인가? (두 개 선택.)"],"1310511741":["지원(support) 에이전트의 환불 승인율이 화요일에 31%에서 68%로 뛰었음.","에이전트에는 코드, 프롬프트, 모델 변경 중 아무것도 배포되지 않았음.","월요일 밤 정책팀이 에이전트의 system prompt가 그대로(verbatim) 가져오는 환불 자격(refund-eligibility) 페이지를 수정했음.","재무팀은 금요일 감사(audit) 전까지 설명을 원함.","가장 효과적인 첫 단계는 무엇인가?"],"1310983680":["보안 리뷰어 프롬프트에는 \"위험한 코드를 표시할 것\"이라고만 적혀 있음. 1차 시도에선 테스트 픽스처와 TODO 주석까지 찾아내며 PR을 발견 항목으로 도배함.","2차 시도에선 \"보수적으로 판단하고 확신하는 이슈만 보고할 것\"을 덧붙였음. 노이즈는 줄었지만, 전에 찾아냈던 진짜 SQL 인젝션까지 같이 놓침.","팀은 프롬프트 엔지니어링이 \"노이즈를 놓침과 맞바꿀 뿐\"이라고 결론 내림. 두 번의 시도에서 실제로 잘못된 것은 무엇인가?"],"1311877679":["합의 사항이 원문 그대로 더 오래 남도록 요약 빈도를 줄이기."],"1312052357":["한 팀이 \"계정을 변경하기 전에는 반드시 신원을 확인해야 함\"이라는 규칙을 어디서 강제할지 정하고 있음. 아래 네 문장 중 세 개는 이것을 system-prompt 지시가 아니라 PreToolUse hook으로 강제해야 하는 타당한 이유임.","정확하지 않은 것은 어느 것인가?"],"1312431638":["동료가 짠 루프 구현임. (a) 응답에 텍스트 블록이 하나라도 있거나 (b) 반복이 25회에 도달하면 종료하고, HTTP 상태 200인 도구 결과만 대화에 추가하고 200이 아닌 결과는 조용히 버림.","운영에서 증상이 두 가지 나타남. 작업이 마무리되지 않은 채 끝나는 일이 잦고, 에이전트가 가끔 똑같은 인자로 lookup_order를 반복해서 호출함.","어떤 진단이 맞는가?"],"1312570408":["분석 도중에 파일을 반복해서 요청하는 코드 리뷰 워크플로(도구 루프)."],"1313183389":["유연하게 가려고 enum을 없애고 자유 텍스트 카테고리를 받기"],"1313377687":["전문 서브에이전트 세 개를 검색·분석·종합을 프롬프트(prompt) 하나에서 다 처리하는 범용 서브에이전트 하나로 합치기. 그러면 요청마다 위임(delegation)이 한 번만 있으면 됨."],"1314196680":["majority voting(다수결 투표)은 여러 번의 review pass(리뷰 실행)를 통합하는 표준적인 방법임. 독립된 instance(인스턴스)들 사이의 합의가 있어야 그 발견 사항을 믿을 수 있기 때문임."],"1315165345":["other 값 하나를 free-text detail 필드와 함께 추가하고, downstream 규칙이 그 텍스트를 읽어서 두 경우를 구분하게 하기."],"1316164131":["시작 모드는 그대로 두고 job timeout을 3시간으로 늘리기. 그래야 승인 요청에 당직자가 답할 시간이 생기기 때문임."],"1320032629":["\"대화 앞부분에 나오는 어시스턴트(assistant) 메시지도 제거해야 함. 이 제한이 요청 안의 모든 어시스턴트 메시지에 적용되기 때문임.\""],"1320324708":["대안 구현(implementation) 세 개를 만들고, 테스트 케이스를 가장 많이 통과하는 것을 골라 남기기."],"1323097110":["경로 범위(path-scoped) 규칙은 유지하되 패턴을 services/*/로 좁혀서 관련 작업에 더 가깝게 발동하게 하고 새 서비스에서 처음 실행할 때를 대비한 대체 수단으로 아홉 단계를 저장소 메모리 파일(repository memory file)에 추가하기."],"1325513198":["subagent가 주장과 출처를 짝지은 구조화된 매핑을 내놓게 하고, 종합 에이전트가 그것을 보존한 채 합치게 하기. 주장마다 URL, 문서, 발췌가 묶여 있어야 함. 출처 표시는 산문이 아니라 구조로 되어 있을 때만 압축을 견뎌내기 때문임."],"1327159281":["애매한 사례들. 그럴듯한 다른 선택지를 제치고 왜 그 행동을 골랐는지 이유까지 붙이기."],"1327486536":["억제 동작은 그대로 두고, 대신 코디네이터(coordinator)가 종합된 리포트를 내보내기 전에 수상하게 비어 있는 섹션이 없는지 훑게 하기."],"1327710779":["acceptance criteria를 repository의 project memory 파일에 써놓으면, 리뷰어가 항상 그것을 로드한 상태로 있음."],"1327941935":["(1) PreToolUse. 실행되기 전에 호출을 가로채서 정책을 강제함. (2) PostToolUse. 실행된 뒤 결과가 모델 컨텍스트에 들어가기 전에 결과를 변환함."],"1328647334":["하지 말아야 할 것을 에이전트에게 가르치기 위한 실패 사례만임."],"1328838206":["모델이 스스로 보고한 신뢰도가 60% 아래로 떨어질 때임."],"1329772927":["few-shot. 실패 양상이 예측 가능한 한 가지 모양이므로 여러 사안이 섞인 메시지에 대해 추론과 도구 호출 순서를 통째로 보여주는 예시 2~3개면 그 패턴을 바로 가르칠 수 있음."],"1331628515":["두 설명을 다시 써서, 각 도구의 동작 방식, 이상적인 입력, 예시 질의, 그리고 다른 쪽 대신 이것을 골라야 할 때가 언제인지를 밝히기"],"1331657792":["동적 분해(dynamic decomposition): 고정된 규칙보다 모델이 페이지를 더 잘 읽으니까, 첫 번째 pass가 문서를 읽고 각 필드를 어느 섹션에서 가져올지 결정하게 하기"],"1331703796":["깔끔한 프로덕션 핸들러(production handler) 예시를 여러 개 추가해서, 모델이 만들어야 할 패턴을 학습하게 하기"],"1332529095":["검색을 병렬로 돌리고, 비교 에이전트가 공유 세션 메모리에서 검색 결과를 읽게 하기."],"1332636472":["같은 장비, 같은 프로젝트인데도 Claude가 어떤 세션에서는 테스트 컨벤션을 지키고 어떤 세션에서는 지키지 않음.","원인을 짚어내기에 가장 좋은 진단 단계는 무엇인가?"],"1332835321":["파일 경로와 티켓 식별자를 정확히 쓰라고 모델에 요청하는 문구를 프롬프트에 추가하기"],"1334294292":["B의 경우, 전체 트리에서 파일 내용 안을 뒤져 심볼(symbol)을 찾기"],"1335517364":["모든 필드를 자유 형식 문자열로 바꿔서 모델이 잘못된 구조로 끌려 들어가는 일이 절대 없게 하기."],"1339394060":["tool_choice는 설정하지 말고, 항상 도구를 쓰라는 프롬프트 지시에 의존하기"],"1340101490":["validator 출력을 덧붙여서 셋 다 최대 세 번까지 재시도하기. self-correction이 대부분의 실패를 처리하기 때문임."],"1342078436":["여러 기능을 합친 lookup_all 도구를 만들기. 호출 한 번이 세 번보다 원래 더 안정적이기 때문임."],"1342298717":["요청을 처리하는 도중에 도구를 실행하는 멀티턴 에이전트."],"1342688068":["프롬프트로 주는 지침은 확률적이라 준수를 보장할 수 없음. 영수증 확인이 끝나기 전까지는 100달러를 넘는 process_refund를 막는 프로그램적 선행 조건을 구현하기"],"1343092855":["모델이 보안 쪽 깊이가 부족한 것임. PR을 보안 특화 모델로 보내고 지금 프롬프트는 그대로 두기."],"1344478637":["신뢰도와 상관없이 금액이 가장 큰 문서 60건을 검토하기."],"1345177264":["subagent(하위 에이전트)가 각 출처에 숫자로 된 신뢰도 점수(credibility score)를 붙이게 하고, 분석가가 조정하는 임계값(threshold) 아래는 전부 걸러내기"],"1345313091":["둘 다 Batches API로 옮기고 공격적으로 폴링해서, 보안 검사가 오래 기다리는 일이 거의 없게 하기"],"1345632687":["지시 사항을 system prompt 맨 앞으로 옮기고 끝에도 한 번 더 넣어서 모델이 두 번 보게 하기"],"1349001471":["get_customer로 시작하는 대화와 lookup_order로 시작하는 대화 사이에서 intake 단계가 달라지던 현상이 더 이상 없어짐."],"1349079816":["코디네이터가 들어온 요청이 실제로 뭘 필요로 하는지 파악해서 필요한 subagent(하위 에이전트)만 호출하게 하기. 단순 조회(lookup)는 검색만 하고 바로 돌아오고, 브리프(brief)는 여전히 전체 파이프라인을 거치는 식임."],"1349649523":["(1)은 프로그램적으로 강제해야 함. 검증 상태가 설정되기 전까지 process_refund를 막는 선행 조건 게이트(예: PreToolUse hook)가 필요함. (2)는 스타일 취향이므로 프롬프트 지시와 예시로 처리하면 됨.","한 가지 메커니즘으로 둘 다 감당할 수는 없음."],"1351130315":["self-check 지시를 세션 시작 부분으로 옮겨서, 에이전트가 리뷰받을 걸 알고 작업하게 하기."],"1352537018":["둘 다 enum을 넓히는 쪽. 그래야 모델이 언제든 솔직하게 고를 선택지가 생기기 때문임."],"1355172049":["지금 resolver가 들어 있는 폴더마다 CLAUDE.md 파일을 하나씩 두기"],"1356089101":["(b)와 (c)는 planning을 거침. (c)는 flaky 테스트가 원인이 불명확하기 때문이고, (a)는 바로 실행함."],"1357702428":["subagent의 구조화된 출력에 발표·수집 날짜와 방법론 맥락(모집단, 범위)을 반드시 넣게 하기. 그래야 synthesis 단계가 수치들이 서로 비교 가능하지 않다는 것을 알아챌 수 있음."],"1358170670":["시스템 프롬프트에 \"항상 내장 도구보다 MCP 도구를 우선할 것\"이라는 규칙을 추가하기"],"1358736197":["둘 다 시스템 프롬프트에서 처리하기. \"항상 신원을 먼저 확인하고, 일관된 어조를 유지해\"라고 적는 것임."],"1359268082":["커버리지가 완전해 보이게, 종합 담당 에이전트가 자기 일반 지식으로 빈 곳을 채우게 하기."],"1361835668":["다섯 개 소스가 전부 성공할 때까지 보고서를 미루기. 부분적인 종합은 독자를 오도하니까."],"1362065924":["JSON 문법 오류는 없애 주지만, 품목 합계가 명시된 총액과 맞지 않는 것과 같은 의미상의 오류는 막아 주지 못함."],"1362485959":["둘 다 아님. 먼저 구조를 파악하고 영향이 큰 영역을 짚은 다음 우선순위를 매긴 계획을 세우기. 계획은 고정하지 않고 의존 관계가 드러날 때마다 계속 고쳐 나가기"],"1364641731":["두 출처가 충돌할 때마다 종합 에이전트가 더 신뢰할 만한 쪽을 고르게 하기."],"1365887354":["이 중복은 표현(presentation)의 문제일 뿐임. 이슈 하나가 세 번 보고돼도 여전히 이슈 하나고, 위치와 정체성(identity) 기준으로 findings를 병합하면 아무것도 빠뜨리지 않고 해결됨."],"1367015996":["피드백으로 전달할 이슈가 5개임. 3개는 서로 독립적인 이름 변경이나 오타고, 2개는 서로 얽혀 있음(캐시 무효화 수정이 TTL 변경에 의존함).","피드백을 어떻게 구성하는가?"],"1367783363":["코드베이스 전체에서 MAX_RETRY_DELAY를 Grep해서 정의와 이를 읽는 모든 지점을 찾고, 그다음 핵심 파일을 Read해서 사용 맥락을 파악하기."],"1369060768":["isError 플래그가 설정되는 것을 막아 줌."],"1370707314":["temperature를 0으로 낮추고, 그렇게 해서 일관되게 나오는 형식이면 무엇이든 받아들이기"],"1371211451":["정책은 이러함. 어떤 환불이든 그 전에 반드시 신원 확인이 이루어져야 하고, 위반은 하나도 허용되지 않음.","결정론적 보장을 제공하는 구현 두 가지는 무엇인가? (2개 선택)"],"1371485224":["8개 슬롯을 보고서 섹션들에 고르게 돌아가면서 배정해서, 매 분기 모든 섹션이 파트너의 관심을 받게 하기."],"1371555499":["네 가지 전부 프로그래밍 방식 hook으로 처리하기. 일관성은 어디서나 중요하고, hook이 쓸 수 있는 것 중 제일 믿음직하며, 똑같이 강제하면 추측할 여지가 사라지기 때문임."],"1372109872":["프로젝트 CLAUDE.md에 \"개인 취향은 무시해\"라는 더 강한 지시를 추가하기"],"1372728671":["그 엔지니어 말이 맞음. extended thinking이 결과를 4포인트 올렸으니, 자기 리뷰 프롬프트를 계속 다듬으면 남은 격차도 메울 수 있음."],"1373649471":["상위 에이전트들이 장황한 내용과 추론 사슬 대신 핵심 사실, 인용, 관련도 점수 같은 형태의 구조화된 데이터를 돌려주도록 고치기"],"1375866717":["팀에 요구사항이 세 개 있음. (1) 모든 개발자가 필요할 때 직접 실행할 \"머지된 PR로 릴리스 노트 생성\" 워크플로, (2) 커밋 메시지를 네 취향대로 다시 포맷하는 너만의 개인 단축 명령, (3) 생성되는 모든 코드에 항상, 모두에게 적용되어야 하는 API 에러 처리 표준임.","어떻게 배치하는 것이 맞는가?"],"1376178461":["저장소를 처음부터 다시 clone하기. 네 작업 사본의 CLAUDE.md가 손상됐을 가능성이 큼."],"1383545647":["validate_receipt를 코드 경로(code path)상의 프로그램적 전제조건으로 만들어서 검증이 끝나기 전까지는 submit_report가 실행되지 못하게 하기"],"1386152454":["세션 시작 때 모든 고객 데이터를 시스템 프롬프트에 미리 넣어서 조회가 아예 필요 없게 하기"],"1386803418":["네 리뷰어가 발견 사항을 critical/major/minor로 분류하는데, 똑같은 이슈인데도 실행할 때마다 심각도가 달라짐. SQL 인젝션이 한 번은 \"minor\", 두 번은 \"critical\"로 나왔음.","프롬프트에는 각 등급이 이미 한 문장씩 정의되어 있음(\"critical: 심각한 문제...\").","어떻게 하면 분류를 일관되게 만들 수 있는가?"],"1387395482":["어떤 수정도 다른 수정에 영향을 주지 않게 이슈마다 새 세션을 열기"],"1388990952":["히스토리에 들어가기 전에 파일을 읽을 때마다 실제로 논의된 범위만큼만 잘라내기."],"1389016137":["coverage instrumentation을 켜고 테스트 스위트(test suite)를 실행한 다음, 리포트를 읽고 어떤 테스트가 retry 코드를 건드리는지 확인하기"],"1389788730":["네 시간짜리 멀티 에이전트 코드베이스 감사가 70% 지점에서 죽었는데, 지금 설계로는 처음부터 다시 시작해야 함.","어떻게 하면 이어서 재개할 수 있게 만들 수 있는가?"],"1391002613":["팀이 공유하는 format-commit skill은 잘 작동하는데, 너는 개인적으로 커밋 메시지 규칙이 다른 변형을 쓰고 싶음. 팀원들한테는 영향을 주지 않으면서 말임.","올바른 접근은 무엇인가?"],"1392546673":["/memory를 실행해서 현재 세션에 실제로 어떤 메모리 파일이 로드됐는지 확인하고, 세션끼리 비교하기."],"1394054731":["옮기긴 하되, 네 시간 안에 배치 결과가 오지 않은 PR은 자동으로 머지하기"],"1394612754":["리뷰를 세 번 돌려서 심각도를 평균 내 편차를 부드럽게 만들기."],"1396818466":["enum은 그대로 두고, 프롬프트에 \"choose the closest category\"(가장 가까운 범주를 고르라)는 지시만 덧붙이기."],"1397794519":["내장 도구를 알맞은 작업에 연결해 볼 것.","올바른 짝은 어느 둘인가? (2개 선택)"],"1398573050":["OCR 단계가 텍스트와 함께 품질 신호(quality signal, 예: 페이지별 신뢰도(confidence)나 미인식 문자 비율(unrecognized-character rate))도 내보내게 하고, 다음 단계는 반환된 텍스트를 무조건 쓸 수 있다고 취급하지 말고 임계값(threshold) 아래는 입력을 거부하게 하기"],"1399940378":["각 에이전트가 작업하면서 정해진 위치에 구조화된 상태를 내보내게 하기. 재개할 때는 coordinator가 그 내보낸 것들의 manifest를 읽어서 각 에이전트 프롬프트에 상태를 주입하기."],"1401344460":["코드베이스 분석 에이전트를 일주일 굴리는 동안 사고가 세 건 났음. (a) 세 시간쯤 지나면 첫 시간에 분석했던 CacheManager 클래스를 인용하는 대신 \"repositories typically handle caching like...\" 같은 일반론으로 답함. (b) 새 질문이 들어올 때마다 Grep/Read가 쏟아져서 원본 출력이 대화를 뒤덮음. (c) 어젯밤 여섯 시간짜리 실행이 새벽 2시에 죽었고, 오늘은 아무것도 없는 상태에서 다시 시작했음.","대응책을 어떻게 짝지어야 맞는가?"],"1402131757":["추출 작업에서는 정확도 지표를 계산할 수 없음."],"1402900829":["네이밍 규칙을 어긴 커밋을 거부하는 CI 검사를 추가해서, 어쨌든 관례가 강제되게 하기"],"1405397560":["signing_date는 nullable로 바꾸기. jurisdiction은 enum에 \"other\"를 추가하고 상세 문자열을 함께 두기."],"1405536051":["텍스트 블록 검사는 유지하되, 루프가 종료되기 전에 텍스트에 \"Final report:\" 같은 완료 마커(completion marker)가 포함되도록 요구하기"],"1405942310":["서버 설정은 프로젝트 .mcp.json에 두되 값은 ${JIRA_TOKEN}으로 참조하기. 실제 값은 개발자마다 자기 환경에 설정하고, 유출된 토큰은 새로 교체하기.","설정은 공유하고, 비밀 값은 개인 것으로 남겨 두기."],"1406058868":["세션에 주어지는 내장 도구(built-in tools) 목록을 좁혀서 편집·쓰기 도구가 포함되지 않게 하기."],"1406151549":["subagent 보고서 다섯 개(약 90K 토큰)를 종합 입력 하나로 합치는 중임.","핵심 발견 요약은 어디에 놓아야 하고, 그 이유는 무엇인가?"],"1406936872":["네 문서 에이전트에는 analyze_document 도구가 딱 하나 있음(설명은 “문서를 분석해서 유용한 정보를 반환”).","로그를 보면 실패 패턴이 세 가지임. 추출 요청에는 요약이 돌아오고, 요약 요청에는 원본 데이터 표가 돌아오고, 사실 확인 요청에는 두루뭉술한 분석이 돌아옴.","팀은 세 가지 용도 모두에서 동작이 안정적이길 원함.","가장 좋은 재설계는 무엇인가?"],"1407518610":["네 분석가들은 \"deep source scan\"을 손으로 직접 돌림. 주제 브리프(topic brief)를 읽고, 아카이브 네 곳에 질의한 다음, 누구도 한 줄 읽기 전에 원본 검색 결과(raw hits) 약 30,000토큰을 쏟아냄.","메인 세션(main session) 안에서 실행하면, 뒤따르는 논의를 위한 공간이 남지 않음.","파일은 절대 쓰면 안 됨.","그리고 필수 인자를 하나 받는데, 바로 주제(topic)임. 분석가들이 이걸 절반 정도는 깜빡함.","어떤 패키징이 맞는가?"],"1409578562":["어떤 지적이 잘못됐다고 느꼈는지 매달 개발자 설문을 돌리기."],"1411719047":["각 백엔드 서비스 쪽에, 담당 팀들에게 API를 표준화해 달라고 요청하기"],"1411813242":["SQL 마이그레이션 규칙은 db/migrations/, scripts/migrations/, 그리고 services/billing/migrations/ 같은 서비스별 폴더 여러 곳에 들어 있는 마이그레이션 파일 전부에 적용돼야 함.","마이그레이션 파일은 전부 .sql로 끝남.","이걸 한꺼번에 커버하는 단일 rule 설정은 무엇인가?"],"1412546160":["모델은 언제나 미리 작성된 코드보다 나은 판단을 하므로, 순서를 하드코딩하면 절대 안 됨."],"1413886967":["종합 에이전트가 자기 일반 지식을 써서 부실한 섹션을 채우게 하기"],"1414670998":["실행을 사용 가능한 컨텍스트 창(context window)이 가장 큰 모델로 옮기고 원본 출력을 대화에 그대로 두기. 창이 커지면 뭘 잘라낼 필요가 없어지기 때문임."],"1414801426":["레거시 코드베이스에 테스트를 촘촘하게 추가하는 작업인데, 작업 도중에 상호 의존성이 튀어나오는 경우임."],"1414861893":["A. 중복 제거가 구현하기 더 간단하고, 최종 보고서에 반복이 없다는 것을 보장해 주기 때문임."],"1415518980":["tool_choice: {\"type\": \"tool\", \"name\": \"extract_invoice\"}로 가장 흔한 타입을 강제하기."],"1416274273":["파이프라인 단계는 Claude로 코드 패치를 만든 다음, 같은 세션 안에서 \"머지하기 전에 네 패치에 버그가 없는지 꼼꼼히 리뷰해 줘\"를 덧붙임. 그런데 머지 후 결함률이 리뷰를 아예 안 한 것과 별 차이가 없음.","구조적인 원인과 해결책은 무엇인가?"],"1416402993":["지출(expense) 에이전트가 가끔 해당 지출에 대해 validate_receipt가 실행되기도 전에 리포트를 제출해서, 신청이 반려되는 경우가 생김.","재무팀이 원하는 건 개선이 아니라 보장임.","이걸 보장해주는 변경 사항 두 가지는 무엇인가? (두 개를 선택할 것.)"],"1416779502":["escalation 시점에 그 자체로 완결된 기록을 남기기. 그 literal(리터럴 값)이 있는 파일과 revision, 주변 근거, 리뷰어가 왜 그것을 credential이라고 판단했는지, 그리고 권장 조치까지 포함해야 함. 그 기록을 받는 엔지니어는 이 발견 사항이 나온 대화에 접근할 수 없기 때문임."],"1416884683":["freeze 날짜, 보호 대상 서비스 세 개, rollback 규칙은 structured state object에 담아서 모든 prompt에 그대로(verbatim) 다시 넣고, 그 주변의 탐색 서술은 일반적인 요약(summarization)이 압축하게 두기"],"1417592268":["법무팀(Legal)이 답변 200건을 검토하다가 에이전트가 고객에게 \"저희 정책상 30일 이내 반품이 가능해요\"라고 말하는 것을 발견함. 정책 페이지는 1월 개정 이후로 14일이라고 되어 있음.","에이전트의 답변은 여전히 30이라는 숫자가 남아 있는 요약된 헬프센터 문서(help-centre article)에서 나온 것이었음. 그 문서 자체도 지난주에 서식 때문에 수정된 것이었음.","내부 문서 두 개가 서로 다른 내용을 담고 있는데, 요약은 그중 하나만 반영했음.","해결책은 무엇인가?"],"1417940603":["(a) 어림짐작으로 고르지 말고 고객에게 추가 식별자(이메일이나 주문 번호)를 물어보기. (b) 사람에게 넘기기. 정책이 경쟁사 가격 매칭에 대해 아무 말도 안 하고 있기 때문임."],"1418376999":["정중히 거절하기. 정책에 없는 건 애초에 제공하지 않는 것이기 때문임."],"1419891575":["팀은 이제 세 번째 시도를 위해 탐색 계획을 다시 짜고 있는데, 앞선 실행에서 드러난 두 가지 실패를 모두 겨냥하고 있음.","이 브리핑에 가장 잘 맞는 계획은 무엇인가?"],"1420118074":["시스템 프롬프트에서 모델한테 \"think carefully before selecting tools\"(도구를 고르기 전에 신중히 생각하라)라고 부탁하기"],"1420241349":["월요일 세션 \"billing-refactor\"에서 파일 60개를 분석했음.","수요일 상황은 다음과 같음. (a) 다른 팀이 그 파일 중 4개를 변경했고, (b) 같은 분석 기준선에서 출발해 경쟁하는 리팩터링 설계 두 개를 비교하고 싶은 상황임.","가장 좋은 세션 전략은 무엇인가?"],"1421052970":["파일 이름이 CLAUDE.md이기만 하면 위치는 어디든 상관없음."],"1422176069":["tool_choice: \"any\". 모델이 도구를 반드시 하나 호출해야 하지만, 어떤 것을 고를지는 모델이 정함."],"1423000062":["봇 이름을 바꾸고 동작은 똑같이 둔 채로 다시 출시해서 신뢰를 초기화하기."],"1423301655":["파이프라인이 좁게 사전 승인된 버전 관리 명령으로 변경된 파일 목록을 계산해서 그 목록을 프롬프트에 넘기고, 리뷰어는 그 경로들만 읽게 하기. 어떤 파일 검색 도구도 리비전이 뭘 바꿨는지는 알 수 없기 때문임."],"1424228804":[".claude/commands/ 안에 슬래시 커맨드로 두기"],"1427614081":["첫 메시지는 \"배송지 주소 바꿔줘. 그리고 봇 말고 사람 상담원 연결해줘\"임. 주소 변경은 이 에이전트가 가장 안정적으로 처리하는 작업임.","에이전트는 \"바로 처리해드릴게요!\"라고 답하고 그대로 진행함.","이 동작을 평가할 것."],"1428266297":["예시를 프로젝트 메모리 파일로 옮겨서 리뷰 프롬프트(review prompt) 안에서만이 아니라 매 실행마다 로드되게 하기."],"1431145556":["#799는 이전 findings를 구조화된 요약으로 만들어서 새 세션을 시작하기. 그 실행이 추론에 썼던 도구 결과(tool result)들이 더는 지금 브랜치 상태를 설명하지 못하기 때문임."],"1432236254":["동적 분해로 가기. 먼저 엔티티 구조를 파악하고, 그룹과 의존성을 식별하고, 우선순위를 매긴 계획을 세운 다음, 상호 의존성이 드러날 때마다 계획을 고쳐 나가기"],"1432253661":["특정 추출 도구 하나를 강제로 선택하게 하기."],"1435241940":["\"batch 요청은 synchronous(동기) 트래픽보다 우선 처리되므로, 같은 양이라도 일반 경로를 거칠 때보다 더 빨리 돌아옴.\""],"1435412855":["자동 리뷰 프롬프트에서 정밀도(precision)를 가장 크게 끌어올리는 지시 방식은 무엇인가?"],"1435880361":["너희 항공사의 수하물 클레임 에이전트(baggage-claim agent)는 lookup_booking, lookup_baggage_status, issue_voucher, escalate_to_agent라는 네 가지 도구(tool)를 써서 지연 보상 요청을 처음부터 끝까지 처리함.","회사 정책은 지연된 수하물에 대해 하루당 고정 요율로 보상하되 최대 5일까지만 인정함.<br><br>이번 주에 한 승객이 9일 지연된 가방에 대한 보상과, 기다리는 동안 산 웨딩 수트 비용의 환급을 요청했음.","정책은 지연 일수를 보상하고 상한을 두는 것까지만 다루고, 대체 의류에 대해서는 전혀 언급이 없음.","에이전트는 9일 치 전부를 보상하는 바우처를 발급하고 20% \"불편 보상금(inconvenience credit)\"까지 얹었음.<br><br>규제 당국이 이 바우처들을 감사함.","이런 요청은 어떻게 처리하는 게 맞는가?"],"1436459613":["요약은 구체적인 수치와 날짜를 뭉뚱그린 일반론으로 압축해 버림. 따로 지속되는 구조로 빼두지 않는 한 그렇게 됨."],"1437074473":["서로 영향을 주는 수정 두 개는 한 메시지에 자세히 같이 담아서 모델이 그 상호작용까지 따져보게 하기. 독립적인 세 개는 따로 처리하기. 구분 없이 한 묶음으로 쏟아부으면 변경이 뒤엉키고, 얽힌 두 개를 쪼개면 둘 다 망가지기 때문임."],"1440344299":["두 단계 모두 plan mode를 쓰기. 전부 가정 상태로 남겨 두면 실행이 더 안전하기 때문임."],"1440556787":["context window 때문임. 이 window는 네 개의 workstream(작업 흐름)을 한 번에 다 담지 못해서, handler prompt가 조립되기 전에 그 rename(이름 변경)을 놓쳐버렸음."],"1443004628":["호출은 그대로 두고 shell timeout으로 감싼 다음, 작업을 최대 세 번까지 재시도하기. 그러면 멈춘 실행은 종료되고 결국 하나는 게시(post)되기 때문임."],"1444324617":["풀 리퀘스트(pull request)당 심각도가 가장 높은 항목 3개만 올리고, 나머지는 필요한 사람이 찾아볼 수 있게 작업 로그(job log)에 남겨 두기"],"1444331889":["\"tool_choice \\\"any\\\"는 도구 호출(tool call)을 강제하면서도, 눈앞의 문서에 어떤 추출 스키마(extraction schema)가 맞는지는 모델이 계속 고를 수 있게 함.\""],"1444783213":["에이전트가 스스로 보고한 확신도가 0.6 아래로 떨어질 때."],"1445456370":["(a)는 창의성을 위해 temperature를 높여서 재시도를 더 하기. (b)는 계산된 합계로 조용히 자동 보정하기."],"1445975874":["개발자에게 티켓을 더 자세히 써 달라고 요청하고, 그것이 나올 때까지 작업을 멈추기"],"1447430687":["둘 다 맞지 않음. 두 곳에서 동일하게 실행돼야 하는 절차는 always-loaded project memory에 두어야 하고, 쓰기 금지 사항은 review 프롬프트에 두어야 함."],"1448412220":["같은 prompt를 공유하는 pipeline 단계 두 개로 작업을 나눠서 security와 style 발견 사항을 따로 집계하고 추적할 수 있게 하기"],"1448799183":["subagent 결과가 부실해 보이면 코디네이터가 직접 웹 검색을 실행하기."],"1449247176":["네 CI 리뷰 봇은 새 커밋이 올라올 때마다 PR을 다시 리뷰함.","개발자들은 봇이 매번 똑같은 지적을 다시 단다고 불평함. 이슈 #4521에는 \"입력 검증 누락\" 코멘트가 네 번이나 달렸고, 커밋 3에서 이미 고친 뒤에도 또 달렸음.","가장 좋은 해결책은 무엇인가?"],"1450089844":["도구는 그대로 두되, 검색보다 문서 분석을 우선하라고 에이전트에게 지시하기."],"1450639415":["(a) \"찾은 클래스를 항상 구체적으로 인용할 것\" 이라는 프롬프트 리마인더. (b) subagent 위임. (c) 매니페스트 기반 상태 복구."],"1453656264":["팀은 모든 추출(extraction) 이후에 돌아가는 semantic validation 레이어를 설계하고 있음.","추출 자체는 이미 schema가 강제되는 경로에서 돌아감.","그 레이어에 넣을 가치가 가장 적은 체크는 무엇인가?"],"1455498438":["용건이 여러 개인 메시지(\"A 주문을 환불해 주고, 주소도 바꿔 주고, 비밀번호도 초기화해 줄 것\")에서만 상담 정확도가 58%로 떨어짐. 실패 양상은 늘 같음. 에이전트가 첫 번째 용건만 답하고 나머지는 흘림.","제안은 다음과 같음. 별도의 분해 모델을 두거나, 자기 비판(self-critique) 단계를 넣거나, 분해 → 도구 순서 정하기 → 전부 처리까지 보여 주는 few-shot 예시를 넣는 것임. 하나를 고를 것."],"1456275993":["개인 취향 설정은 통째로 지우기. 제대로 둘 자리가 없기 때문임."],"1459344920":["두 설계 다 각각 다른 브랜치에 구현해서 결제(payments) 그룹이 동작하는 코드를 비교하게 하기. 그런 다음 채택되지 않은 브랜치는 버리기."],"1459496409":["handler subagent 문제도 있음. 넘겨받은 내용에 의존하지 말고 schema 파일을 직접 읽었어야 했음."],"1459886603":["자기 비평은 누락을 찾아냄(모델이 자기 초안에서 볼 수 있는 체크리스트 구멍 같은 것). 하지만 어떤 설계 결정을 이미 합리화해 놓은 생성기는 그것을 다시 읽어도 같은 맹점을 그대로 반복함. 그러니 축출(eviction) 로직은 생성 과정의 추론을 본 적 없는 새로운 독립 인스턴스에게 맡기기."],"1460013624":["고객에게 무엇이든 말하기 전에 모든 실패를 두 번씩 재시도하는 것으로 통일하기."],"1462876533":["다섯 개를 한 메시지에 다 보내기. 왕복이 줄면 컨텍스트 낭비도 줄기 때문임."],"1464422648":["모든 도구 설명을 입력 형식, 샘플 요청, 명시적 경계까지 담아 네 문장으로 다시 씀. escalate_to_human 선택 비율이 71%에서 96%로 오름.","그런데 process_refund는 \"제 환불이 아직 처리됐나요\"라고만 묻는 메시지에도 여전히 호출됨. 그런 메시지의 9%가 그러함.","system prompt는 이렇게 시작함: \"환불 관련 요청은 최우선 순위예요. 바로 처리하세요.\" 다음으로 무엇을 해야 하는가?"],"1465931037":["네 추출 파이프라인은 계약서 한 건당 타입이 지정된(typed) JSON 레코드 하나를 씀.","지난달에 나타난 한 문서 유형은 갱신 조항이 아예 없는데, 모델은 그 문서들에서 renewal_term_months를 12로 채워 넣고 있음.","이 레코드를 읽는 대시보드 세 개는 다른 팀 소유라서 이번 분기에는 바꿀 수 없음.","어떤 스키마 변경이 맞는가?"],"1466386937":["페이로드(payload)는 그대로 두고, 핸드오프(handoff)를 접수하기 전에 검증기(validator)가 대화 기록(transcript)이 뒷받침하지 않는 금액을 걸러내게 하기."],"1467905016":["리뷰의 thinking budget(사고 예산)을 늘려서 12개 파일 전부를 더 꼼꼼히 살펴보게 하기."],"1468987723":["이 pull request 리뷰 bot이 6주째 돌아가고 있음.","불만은 두 가지임. (a) 새 commit이 있을 때마다 작성자가 이미 처리한 동일한 댓글 30개를 다시 올림. (b) 이 bot이 제안하는 테스트가 기존 test suite가 이미 다루는 시나리오와 중복돼서, 리뷰어가 merge하는 시간보다 삭제하는 시간을 더 많이 씀.","이 문제들을 해결하는 변경 사항 두 가지는 무엇인가? (두 개 선택)"],"1470385243":["-p는 그대로 두고, 정규식으로 뽑아내던 부분을 --output-format json에 --json-schema를 더한 방식으로 바꿔서 기계가 파싱할 수 있는 결과를 받기. 그리고 리뷰는 생성 단계 맥락을 한 번도 본 적 없는 독립 인스턴스로 별도 단계에서 돌리기."],"1471900272":["일치 후보 중에서 어림짐작으로 고르지 말고, 고객에게 추가 식별 정보(주문 번호나 등록된 이메일)를 물어보기"],"1472040353":["산문으로 된 명세에 시간대 용어를 정의하는 절을 덧붙이기."],"1472287597":["래퍼(wrapper)들이 도입하는 export된 이름을 하나씩 가져와서 전체 트리(tree)에서 검색하기"],"1473197820":["투명성을 위해 백엔드 서비스의 내부 스택 트레이스 전체를 그대로 보여주기."],"1473380190":["CLAUDE_HEADLESS=true claude \"Review this diff for security issues\" --format json"],"1473507891":["둘을 검색 도구 하나로 합쳐서 헷갈릴 여지 자체를 없애기"],"1473944194":["검색 에이전트 쪽 실패로 진단하고 다른 검색 제공자로 갈아 끼우기."],"1474054147":["비용은 감수하기. 디스커버리 호출 덕분에 세션마다 최신 상태가 보장되기 때문임."],"1474105081":["\"tool use를 통해 제공된 JSON 스키마는 문법 오류는 없애주지만, 항목 합계가 명시된 총액과 맞지 않는 것 같은 의미상의 오류(semantic error)까지 막아주지는 않음.\""],"1476111261":["컨텍스트를 아끼려고 개발자당 세션마다 질문을 세 개로 제한하기."],"1476247533":["schema는 슬롯의 형태만 정할 뿐 어떤 값이 거기 들어가야 하는지는 전혀 알려주지 않으므로, 페이지 위 어느 label 아래 있는지, 보통 어디 나오는지, 주소가 하나만 찍혀 있을 때는 어떻게 할지처럼 두 값을 구분하는 방법을 각 필드의 description에 적기"],"1479622957":["exponential backoff를 추가하고 실패한 페이지마다 최대 5번까지 재시도하기. 그러면 일시적인 503 오류가 빈 페이지를 만들어내는 일이 멈춤."],"1480244733":["웨어하우스(warehouse)에 적재하는 22개 필드짜리 레코드 말고도, 추출 서비스는 한 페이지짜리 검토자 메모(reviewer memo)도 만들어야 함: 고정된 섹션 순서, 리스크마다 쉬운 말로 쓴 문단 하나, 그리고 완곡한 표현(hedged statements)에 대해 클라이언트가 정한 문구까지 지켜야 함.","한 엔지니어는 추출 도구의 스키마(schema)에 memo 문자열 필드를 추가해서, 한 번의 호출로 두 결과물 모두 검증된 형태로 돌아오게 하자고 제안함. 평가해 볼 것."],"1480526885":["지난달에 4,000건짜리 인보이스(invoice) 야간 작업이 동기 호출(synchronous call) 방식에서 Message Batches API로 옮겨갔음.","재무팀은 이제 하룻밤에 약 30건의 레코드가 다른 공급업체 데이터를 담고 있다고 보고함. 한 인보이스의 공급업체명이 다른 인보이스의 금액과 뒤섞이는 식임.","파이프라인(pipeline)은 반환된 결과를 입력 리스트와 위치 기준으로 짝짓고 있음.","비용은 절반으로 줄었고, 아무도 그걸 포기하고 싶어 하지 않음.","어떻게 고쳐야 하는가?"],"1480538991":["그냥 영구히 꺼 두기. 스타일 지적은 원래 가치가 낮기 때문임."],"1481211337":["각 엔지니어가 온보딩할 때 그 컨벤션을 자기 개인 메모리 파일(personal memory file)에 붙여넣게 하고, 바뀔 때마다 팀 채널에 업데이트를 올리게 하기"],"1481299690":["목요일 세션을 branch해서 merge된 변경사항을 분리하고, 두 가지 rewrite는 원래 세션에서 차례로 탐색하기"],"1481778490":["실패하는 레이아웃만 정확히 다루는 예시 몇 개를 추가하기. 합계가 footer에 있는 송장 하나, 주소 블록 배치가 다른 각 벤더별로 하나씩임. 그리고 페이지에서 어느 블록이 billing이고 어느 블록이 shipping인지 prompt에 명시하기"],"1481881405":["팀원이 검증 재시도 루프를 이렇게 짰음. Pydantic 검증에 실패하면 “이전 출력에 검증 오류가 있었음.","고쳐서 다시 시도할 것.”이라는 말만 넣어서 다시 프롬프트를 보냄. 재시도 성공률은 12%임.","그 팀원은 “시도할 때마다 기회가 한 번 더 생기니까”라며 최대 재시도를 2에서 6으로 올리자고 제안함. 올바른 진단은 무엇인가?"],"1481905881":["schema는 memo 문자열이 존재하고 타입이 맞는지는 보장할 수 있지만, 섹션 순서나 문단 구조, 문구 표현에 대해서는 아무것도 보장하지 못함. 이런 것은 JSON Schema가 표현하는 범위 밖에 있음.","레코드는 schema-constrained 경로에 그대로 두고, memo는 명시적인 형식 지시와 check-and-retry 루프로 만들기"],"1483506489":["추출 단계를 tool_choice: \"auto\"로 돌리면서 프롬프트에는 \"항상 추출 도구를 호출해서 응답하라\"고 강하게 못 박아 두었음. 명확한 문서에서는 잘 따르는데, 애매한 문서에서는 가끔 산문으로 답함. \"이 문서는 영수증으로 보이지만 완전히 확신하지는 못하겠어요...\" 같은 식이라 뒤쪽 JSON 파서가 죽음.","전체 실행의 약 4%에서 이런 일이 생김.","올바른 해결책은 무엇인가?"],"1484884010":["SCENARIO: CI 작업이 모든 풀 리퀘스트마다 Claude Code를 실행하고 리뷰 코멘트를 남김.<br>SITUATION: TTY가 없는 컨테이너 안에서 돌아감.","이 작업은 CLI를 호출하고 기다렸다가 돌아오는 텍스트를 그대로 게시함.<br>SYMPTOMS: 실행의 3분의 2는 CLI가 여전히 대화형 프롬프트(interactive prompt)에 멈춰 있고 코멘트 본문은 비어 있는 채로 끝남.","제대로 끝나는 실행들은 자유 형식 산문을 게시하는데, 코멘트 파서는 이걸 조용히 버림.<br>CONSTRAINT: 이 파서는 다른 팀 소유이고, 엄격한(strict) JSON만 받아들이며, 이번 분기엔 바뀌지 않음.<br>QUESTION: 두 증상을 한꺼번에 해결하는 단 하나의 변경은 무엇인가?"],"1485165200":["일반적인 지시문을, 포함 여부를 실제로 가르는 조건들(누가 게재했는지, 방법론이 명시됐는지, 자금 출처가 공개됐는지, 수치를 확인할 수 있는지)로 바꾸고, 각 조건마다 채택·기각 예시를 하나씩 실제로 붙이기."],"1485900475":["새 세션(clean session)을 열고 출력 형태와 견고성 요구사항을 훨씬 더 자세히 문서로 써서 1~3라운드에서의 혼란이 전혀 넘어오지 않게 하기."],"1486771376":["파일을 반복해서 요청하는 코드 리뷰 워크플로(파일 요청 → 수신 → 분석 계속)가 Batches API 요청 하나 안에서는 왜 돌아갈 수 없는가?"],"1487463658":["실행 한 번에 처리하는 package 수를 줄여서, crash 한 번이 나도 다시 해야 할 작업이 줄어들게 하기"],"1487572001":["두 파일이 함께 로드되면서 사용자 수준의 개인 규칙이 간섭하고 있음. 시니어 개발자가 충돌하는 개인 포매팅 규칙을 지워서, 팀 코드는 공유된 프로젝트 표준이 지배하게 해야 함."],"1491591226":["매번 Claude가 자기 해석을 제안하게 하고, 논의를 거치며 반복해서 다듬기."],"1492053782":["파싱 가능한 출력이 우연히 나올 때까지 실패한 실행을 계속 재시도하기"],"1492767354":["Team A는 동적 분해(dynamic decomposition)를 써서 각 계약서에서 나온 발견 사항이 다음 계약서에 적용할 검사를 바꿀 수 있게 하고, Team B는 비용 분석 런북(runbook)을 그대로 따르는 고정 파이프라인(fixed pipeline)을 쓰기"],"1494416822":["금액이 가장 큰 이슈를 고르고, 나머지는 후속 티켓으로 미루기."],"1495958823":["아무것도 하지 않기. 97%는 업계 기준선인 95%를 넘으므로, 검토 인력은 다른 곳에 쓰는 것이 나음."],"1496335599":["그룹 A는 원본 문서와 실패한 추출 결과, 그리고 구체적인 검증 오류를 함께 붙여서 재시도함. 그 피드백이 교정을 이끌어 주기 때문임.","그룹 B는 재시도하지 않음. 정보가 원본에 아예 없으므로 부속 문서(annex)를 가져오거나 해당 필드를 null로 표시함."],"1499848342":["unknown 값을 추가하고 모델에게 두 경우 다 이것을 쓰라고 지시한 다음, follow-up 큐를 처리할 때 reviewer가 나눠서 분류하게 하기."],"1502414613":["Min-jun: stop_reason 로직은 그대로 두되, 에러 노이즈가 모델 추론을 흐리지 않도록 실패한 도구 결과는 대화에서 빼기"],"1502446301":["리포트 에이전트에 컨텍스트 창을 더 크게 할당하고, 앞단 출력은 그대로 두기."],"1502652645":["페이지가 하나라도 실패하면 작업을 중단하고 아무것도 발행하지 않게 해서, 재무팀(finance)이 불완전한 데이터로 만들어진 보고서를 절대 받지 않게 하기"],"1503373186":["모델이 더 창의적으로 탐색하도록 temperature를 높여서 89건을 재시도하기"],"1504160435":["중간 요약 각각의 토큰 수."],"1505381938":["실제 데이터에서만 통과할 수 있는 검사를 추가하기. 예상 패턴과 맞는 invoice number, line item과 합이 맞는 total 같은 것임. 그러면 noise로 만들어진 레코드는 그냥 통과하지 않고 validation에서 걸림."],"1505890422":["고객이 경쟁사 가격 매칭을 요구함.","그런데 정책 문서에는 가격 매칭 얘기가 전혀 없음.","에이전트는 이렇게 해야 함:"],"1506322566":["재리뷰 때마다 봇이 이전 코멘트를 전부 지우게 해서, 중복이 절대 같이 남지 않게 하기"],"1507054853":["세 개 다 바로 실행으로 가기. 숙련된 팀에게는 plan mode가 필요 없기 때문임."],"1508422297":["개선될 때까지 소스 검증(source vetting)은 꺼두고 분석가가 모든 소스를 직접 검증하게 하기."],"1508561104":["9시간짜리 리서치 run이 흐트러지고 있는데, 2시간째에는 정확히 인용했던 수치를 6시간째가 되면 coordinator가 대충 바꿔 말함.","끝까지 남아 있어야 하는 것은 나중에 중요해지는 정보임. 8시간째에 애널리스트가 규정 조항의 정확한 문구, 벤더의 인원수, 신고 날짜 같은 것을 물어볼 수도 있고, 질문이 실행 중에 클라이언트에게서 오기 때문에 아무도 미리 그 목록을 정할 수 없음.","모델 호출(model call)이 추가로 드는 것은 괜찮음.","어떤 context 전략이 가장 잘 맞는가?"],"1510690593":["먼저 고객의 감정 점수를 확인하고, 불만이 높을 때만 상급자에게 넘기기"],"1510986615":["모든 관심사에 자리가 생기게 토큰 예산을 3배로 잡고 한 번에 처리하기"],"1512401142":["API 에러 처리 컨벤션이 담긴 규칙(rule) 파일이 paths: [\"src/api/**/*.ts\"]를 선언함.","리뷰어는 자기가 컨벤션을 어기는 코드를 쓰는 동안 그게 발동되지 않았다고 불평함.","그 규칙은 아래 파일 전부에 로드되는데, 하나만 예외임.","그 예외는 무엇인가?"],"1512458624":["coordinator의 context 한도를 올려서 네 subagent가 나눠 쓸 여유가 생기게 하기"],"1514223318":["네 개의 subagent를 도구를 전부 가진 에이전트 하나로 합쳐서, 티켓 하나에 실행 한 번만 들게 하기"],"1516029086":["제한되는 요청 하나와 허용되는 요청 하나를 다루는 입출력 예시를 두세 개 제시하기."],"1516036495":["YAML frontmatter는 paths 키의 대소문자를 구분하며, Paths처럼 첫 글자를 대문자로 써야 함."],"1517217968":["필요한 것은 두 가지임. (i) Claude Code가 자기가 생성한 TODO에서 트래커(tracker) 티켓을 열어야 함. 이는 널리 쓰이는 트래커와의 표준 통합(standard integration)임. (ii) 스캐폴딩(scaffolding)하기 전에, 내부 서비스 템플릿(internal service templates) 340개 중 어떤 것이 존재하는지 알아야 함.","한 엔지니어는 둘 다 사내에서(in-house) 직접 만들자고 제안함: 트래커용 서버 하나, 그리고 어떤 것이 있는지 확인하려고 에이전트가 호출하는 도구로 템플릿 목록을 노출하는 서버 하나임.","더 나은 형태는 무엇인가?"],"1518305261":["순서를 하드코딩하면 API가 stop_reason 값을 돌려주지 못해서 루프 종료가 깨짐."],"1518995887":["변경된 파일마다 파일 단위 국소 분석을 한 번씩 돌리고, 그다음에 변경된 서비스들 사이의 파일 간 데이터 흐름을 살피는 통합 분석을 따로 한 번 돌리기(예: billing-api ↔ shared/utils 호출 지점)."],"1519958367":["반복 개선 루프를 돌리기. 빈 부분을 겨냥한 질의를 검색·분석 에이전트에게 다시 위임하고, 커버리지가 충분해질 때까지 종합을 다시 호출하는 방식임."],"1520014692":["각 subagent가 필드와 타입을 선언하는 tool schema를 통해 발견 사항을 반환하게 하기. 그러면 형태를 강제로 지키게 되고, 산문에서 다시 파싱해낼 필요가 없음."],"1521015478":["Glob으로 **/*.yaml과 **/*.ts를 찾고, 걸린 파일을 하나씩 열어서 발견되는 것을 이름 바꾸기. 설정이 있을 수 있는 위치는 이 확장자들이 정해 주기 때문임."],"1521580477":["다른 결제(payment) 도구로 폴백(fallback)하기. 이 도구는 요청을 완전히 거부했기 때문임."],"1522801022":["검색은 허용하되, 검색 에이전트의 품질 필터 프롬프트를 그대로 복사해 쓰도록 요구하기."],"1523772002":["credential이 항상 최신 상태를 유지하도록 모든 엔지니어가 세션을 시작할 때마다 연결 명령(connection command)을 다시 실행하게 하기."],"1523818880":["해결된 대화는 전부 정책을 올바르게 적용했는지 같은 방식으로 세션 평가를 받으며 끝남.","이 자체 평가에서는 98%가 맞다고 나옴.","그런데 대화 900건을 사람이 감사해보니 12%는 정책이 잘못 적용됐음.","이 격차를 좁힐 가능성이 가장 낮은 조치는 무엇인가?"],"1523931899":["도구의 응답 형태를 타임아웃은 구조화된 에러(errorCategory: transient, isRetryable: true)로, 레코드 없음은 빈 배열을 담은 성공으로 나누기","이 구분을 에이전트에게 주면 한쪽은 재시도하고 다른 쪽은 그대로 보고할 수 있음."],"1524265408":["환불 케이스에서는 요약을 끄고 대화 이력 전체를 그대로 유지하기."],"1525781873":["출력 뒤에 붙는 필터로 응답을 훑어서, 검증 언급이 빠진 환불 확정 문구를 지우기"],"1526191974":["아홉 단계를 저장소 메모리 파일(repository memory file)에 넣어서 모든 세션이 이미 절차를 알게 하고, 파라미터 목록은 맨 위에 주석으로 추가해서 서비스 이름을 아무도 잊지 않게 하기"],"1526525802":["(a) 추가 식별자를 물어보기. (b) 가장 비슷한 규칙으로 자사 사이트 가격 인하 정책을 적용하기"],"1527968675":["Claude가 무언가를 쓰기 전에 먼저 열려 있는 질문들(clock jump(시간 점프)가 일어나면 어떻게 해야 하는지, 제한된 client가 무엇을 받는지, 그 limit이 무엇을 기준으로 걸리는지)을 너에게 묻게 하고, 그 답을 준 다음에 구현하게 하기"],"1529638892":["계속 제출하되, 배치가 보통 2~3시간 안에 끝난다는 점에 의존하기"],"1530305001":["직접 만들지 말고 tracker용으로 관리되고 있는 커뮤니티 server를 채택하고, 템플릿 카탈로그를 resource로 공개해서 에이전트가 물어보는 데 호출을 쓰지 않고도 무엇이 있는지 볼 수 있게 하기"],"1531051625":["간단한 질의 전용으로 더 빠른 subagent들을 묶은 두 번째 경량 파이프라인을 만들고, 심층 리서치 보고서용 전체 파이프라인은 그대로 두기."],"1531253739":["종합 에이전트 프롬프트에 \"출처 URL은 항상 유지할 것\" 을 추가하기"],"1531812385":["레거시 서비스(legacy-service) 감사 세 시간째임.","에이전트는 첫 시간에 찾아낸 RetryPolicy 클래스를 짚어 말하는 대신 \"이런 서비스는 보통 미들웨어 계층(middleware layer)에서 재시도를 처리함\"이라는 식으로 답하기 시작했고, 이번 시간 답변 중 두 개는 서로 모순됨.","네 시간이 남았고, 남은 질문마다 처음부터 다시 검색해야 함.","여기서 맞는 대응은 무엇인가?"],"1532843849":["설계된 대로라면 거절하기. 밤 11시부터 아침 9시까지는 10시간인데, 배치 처리는 지연 SLA도 없이 최대 24시간까지 걸릴 수 있음. \"보통 2~3시간\" 같은 것은 빡빡한 규제 마감을 받쳐 주지 못함.","동기 처리를 그대로 유지하든가, 배치에 손대기 전에 마감 기한부터 다시 협의하기."],"1534151677":["두 번의 시도 모두 판단 기준선을 정하지 않았음. 모호한 지시 두 개를 범주별 기준으로 갈아치우고, 인젝션·인가 우회·시크릿 노출은 보고하고 테스트 픽스처와 TODO, 스타일은 넘어가는 식으로 하며, 범주마다 코드 예시를 하나씩 붙이기."],"1534195734":["코디네이터의 작업 분해에 문제가 있음. 풍력, 수력, 지열, 정책 하위 주제를 아예 배정하지 않아서, 아래쪽 에이전트 중 누구도 그것을 다룰 수가 없었음."],"1535147204":["뭐든 어딘가에는 들어가도록 enum을 세분화된 카테고리 40개로 늘리기"],"1535269510":["허점은, 재개한 세션은 파일을 아예 다시 읽지 못하고 새로 시작한 세션만 파일에 접근할 수 있다는 점임."],"1536246991":["분석 도중에 문서 subagent가 같은 도입률 지표를 두고 40%와 12%로 다르게 말하는 신뢰할 만한 출처 두 개를 발견함. 결론을 좌우할 만큼 중요한 차이임.","불확실성 처리 모범 사례대로면 subagent는 이렇게 해야 함:"],"1537138119":["(a)와 (c)는 바로 실행으로 가기. 범위가 확정돼 있고 변경도 국소적이기 때문임. (b)는 먼저 계획 단계를 거치기. 45개 파일에 실행 가능한 방법이 두 가지 있는 상황이야말로 일찍 확정했다가 다시 작업하게 되는 전형적인 경우이기 때문임."],"1537767550":["어떤 세션이든 무엇을 실행하기 전에 반드시 필요한, repo의 build·test 명령어."],"1538307467":["두 설명을 다시 써서 각각이 기대하는 입력, 고객 질문 예시 두세 개, 대신 써야 할 짝 도구(sibling tool)를 지목하는 문장 하나를 담게 하기. 모델이 둘을 구분할 다른 단서가 전혀 없기 때문임."],"1539406528":["subagent 내부에서 재시도하는 걸 멈추고, 실패가 처음 발생하는 즉시 전부 coordinator로 escalate하기."],"1539809524":["(B). 다수결 투표가 실행 간의 불일치를 상쇄해 주기 때문임."],"1543128653":["문서화된 표준은 평소 세션이 이미 읽어 들이는 위치에 그대로 둬서 무인 실행도 함께 읽게 하고, checks-off 설정은 버리고 사전 승인 목록 밖의 모든 것을 거부하면서 읽기와 diff 명령만 허용하는 모드로 바꾸고, 이 단계가 스키마 검증(schema-validated)된 구조화된 출력을 반환하게 해서 대시보드가 문장이 아니라 필드를 소비하게 하기"],"1543956730":["도구 설명임. 모델이 도구를 고를 때 근거로 삼는 주된 단서이기 때문임."],"1544051170":["결정 전에 모든 실패를 낱낱이 볼 수 있도록 coordinator에게 더 많은 세부사항을 보내기."],"1544196814":["매 요청마다 전체 대화 기록(conversation history)을 전달해서 에이전트가 방향을 잃지 않게 하는 방식임."],"1544657228":["파이프라인은 Claude의 리뷰 출력을 파싱해 PR에 인라인 코멘트를 다는 방식임.","실행의 약 15%가 파싱에 실패함. 모델이 “제가 찾은 문제는 다음과 같습니다...” 같은 산문 도입부를 붙이거나, 필드 이름이 들쭉날쭉하거나, 따옴표 없는 문자열을 내놓기 때문임.","-p는 이미 쓰고 있음.","설정을 완성하려면 무엇을 더 해야 하는가?"],"1544767926":["개선한 프롬프트가 과거 PR로 만든 라벨링된 테스트셋에서 납득할 만한 오탐률을 보여준 다음에 다시 켜기."],"1545102665":["(1)은 루트 CLAUDE.md에, (2)는 rules 파일로. 규칙은 CLAUDE.md에, 예시는 rules에 두는 것임."],"1546531617":["데이터베이스 조회 도구를 추가해서, 에이전트가 잊어버린 수치를 언제든 다시 가져올 수 있게 하기"],"1547105473":["결과 내용과 그 출처(어떤 도구, 어떤 레코드, 어떤 타임스탬프)를 분리된 부분으로 유지하는 구조화된 형태로 결과를 넘기기. 그래야 초안 답변에서도 어떤 수치가 어디서 나왔는지 가리킬 수 있음."],"1548133550":["네 CI는 Claude 워크로드를 두 개 돌림. (1) 머지 전에 반드시 통과해야 하는 보안 검사, (2) 어제 머지된 코드용 테스트 케이스 후보 생성인데 이건 개발자들이 매일 아침 검토함.","비용이 많이 나감.","어떤 아키텍처가 맞는가?"],"1548521911":["프리필(prefill)은 그대로 두고, 정규식(regex)으로 닫는 중괄호 이후의 내용을 전부 제거한 다음, 작업을 4.6 이전 모델(pre-4.6 model)로 고정하기"],"1549750869":["올바른 JSON의 few-shot 예시를 추가하고 파싱 실패 시 재시도하는 루프를 붙이기."],"1550278948":["들어오는 메시지마다 라벨을 붙이고 그 라벨에 맞는 도구(tool)만 넘겨주는 분류기(classifier)를 모델 앞단에 두기"],"1550568455":["archive의 컬렉션 카탈로그를 MCP resource로 공개해서, 에이전트가 탐색에 호출을 쓰지 않고도 볼 수 있게 하기."],"1550720044":["모든 것을 매칭하는 패턴은 조건부 메커니즘이 무조건적인 일을 하고 있는 셈임.","이 요구사항은 모든 실행에 적용되므로 항상 로드되는 project memory에 있어야 함. path-scoped rule 파일은 관련 없을 때 컨텍스트에서 컨벤션을 빼두려고 존재하는 것임."],"1550828767":["준비된 한 줄짜리 수정을 적용하고 실패한 단계만 다시 실행하기"],"1551249733":["셋 다 제거하고, 여전히 필요한 것이 무엇인지는 테스트 스위트가 드러내게 하기"],"1551877862":["코드로 강제하는 방식은 그대로 두고, 게이트 로직만 고치기. 세션 동안 고객 인증 상태를 추적하고, 첫 인증이 성공하기 전까지만 게이트가 걸린 도구를 막기."],"1552271742":["coordinator가 티켓을 조사하고 나서 답장 초안을 쓰는 subagent를 새로 띄움.","이번 달 감사(audit)에서 나온 문제 두 가지: (1) 초안이 B-4471, $312.40 대신 \"your recent order\", \"the amount discussed\" 같은 식으로 나오는데, coordinator가 drafter한테 조사 결과를 두 줄짜리 요약으로만 넘기기 때문임. (2) 고객이 금액에 이의를 제기하면 그 숫자가 어느 기록에서 나왔는지 아무도 알 수 없음. 초안에 그 흔적이 전혀 없음.","이 문제를 터지는 지점에서 바로 잡는 변화 두 가지는 무엇인가? (두 개 선택)"],"1555923246":["문서 형태별로 하나씩, prompt 세 개로 나누고, layout(레이아웃)으로 학습된 classifier(분류기)로 문서를 각 prompt에 라우팅하기"],"1556372292":["R1과 R3는 저장소의 메모리 파일(memory file)에 넣고, R2는 프런트매터(frontmatter)가 호출 가능한 도구를 제한하는 스킬(skill)에 넣어서, 그 제약이 인프라를 건드리는 워크플로와 함께 다니게 하기"],"1556657112":["시스템 레벨, 즉 /etc/claude/CLAUDE.md."],"1556863849":["(i)부터 (iii)까지는 root 메모리 파일에 넣어서 단일 진실 공급원(single source of truth)을 유지하고, (iv)는 diff가 vendored/를 건드리는 빌드를 실패시키는 파이프라인 체크(pipeline check)로 넣기"],"1557245736":["리포지토리를 포크(fork)해서 그 사람 버전의 skill이 장기 브랜치(long-running branch)에 남아 있게 하기."],"1557884473":["바로 resume해서 이어가기. 그 파일들을 다음에 건드릴 때 세션이 동료의 변경을 알아챌 것이기 때문임."],"1558364596":["즉시 멈추고 코디네이터에게 에스컬레이션하기. 이 정도로 중대한 충돌이면 이후 분석은 의미가 없어짐."],"1559402426":["규칙은 설계상 한 디렉터리 깊이까지만 파일을 매칭할 수 있음. 중첩된 관례는 디렉터리마다 CLAUDE.md 파일이 따로 필요함."],"1560737943":["웹 검색 에이전트임. 질의가 너무 좁았기 때문임."],"1565540976":["\"Operation failed\" 같은 획일적인 에러 응답은 왜 에이전트 신뢰성을 떨어뜨리는가?"],"1565576238":["리서치 코디네이터(coordinator)가 subagent들을 조율하면서 자체적인 agentic loop를 돌림.","어젯밤 실행은 배정된 subtopic 9개 중 4개짜리 보고서만 쓰고 나서 \"completed\"라고 기록했음.","팀은 이 loop의 제어 로직(control logic)을 감사(audit)하는 중임.","다음 중 그 loop에 대한 건전한 제어 규칙이 아닌 것은 무엇인가?"],"1565930239":["3단계가 대화 히스토리에서 1단계 결과를 다시 읽게 하기."],"1566323041":["(a) 한 줄짜리(one-liner)니까 개인 커맨드(personal command)로 두고, (b) 프로젝트 스킬(project skill)로 두고, (c) Python 파일에만 적용되는 룰 파일(rule file)로 필터링해서 다른 작업에서 컨텍스트를 낭비하지 않게 하기"],"1566461723":["커밋된 deny 규칙이 리뷰어의 파일 도구가 infra/secrets/에 접근하지 못하게 막고 있음.","그런데도 감사(audit)에서 리뷰 transcript 안에 그 디렉터리 내용이 나온 것이 발견됐음. 리뷰어가 짧은 Python 명령을 직접 실행해서 파일을 열었던 것임.","별개로, 팀은 리뷰어가 실행하는 모든 shell 명령이 실행되기 전에 내부 도메인 allowlist와 대조 검사되길 원함.","이 두 문제를 올바르게 해결하는 조치 두 가지는 무엇인가? (두 개 선택)"],"1567749449":["재시도가 성공할 가능성이 있는지를 에이전트에게 알려 주는 isRetryable 불리언 값."],"1567874468":["선택적 보존(selective retention)을 쓰기. 날짜, 서비스 이름, 파일 경로 중 하나라도 언급된 턴은 그대로 남기고, 나머지는 전부 버리기."],"1573173927":["세 개 다 프로젝트 범위의 skill로 만들기. skill이 가장 기능이 많은 포장 방식이고, 방식을 하나로 통일하면 유지보수도 간단해짐."],"1573317150":["코디네이터는 allowedTools: [\"WebSearch\", \"Read\"]로 설정돼 있고, 세 개의 subagent에게 어떻게 위임할지 아주 자세히 적어 둔 시스템 프롬프트도 갖고 있음.","그런데 실제 운영에서는 subagent를 단 하나도 띄우지 않음. 그냥 웹 검색만 써서 전부 혼자 답함.","무엇이 문제인가?"],"1573668994":["재시도할 때는 더 강한 모델 등급을 쓰기. 검증 실패는 기본 모델이 능력 한계에 도달했다는 신호이기 때문임."],"1574062247":["assistant 턴을 여는 중괄호(opening brace)로 프리필(prefill)해서 응답이 객체(object) 안쪽에서 시작하게 하기"],"1575787940":["paths: [\"db/migrations/*.sql\"]. 다른 폴더는 문제가 생기면 나중에 추가하기."],"1577426862":["고객과 주고받는 실시간 지원 대화임."],"1578279629":["편집은 보류한 채로 조사해서 접근 방식을 확정하고, 그 작성된 접근 방식을 결제 담당자한테 승인받으러 넘긴 다음, 그 이후에야 일반 실행 모드로 전환해서 합의된 설계를 구현하기"],"1578974420":["출력이 장황한 탐색 단계는 간결한 요약만 돌려주는 Explore subagent에 맡기고, 메인 대화는 설계와 구현에 집중하게 하기"],"1579200002":["배치를 신청 10건씩 여섯 번 실행으로 나누고, 나중에 결과 파일 여섯 개를 합치기."],"1579658620":["/memory를 실행해서 이번 세션에 실제로 로드된 메모리 파일이 무엇인지 확인하기. 프로젝트 파일과 나란히 로드되는 사용자 레벨 ~/.claude/CLAUDE.md에 그 규칙의 오래된 사본이 남아 있을 가능성이 큼."],"1580151723":["둘 다 프로젝트 메모리 파일(project memory file)에 넣기, 하나는 컨벤션(convention)으로 하나는 단호한 문구의 금지 사항으로. 그러면 리뷰어를 처음부터 끝까지 관장하는 파일이 하나로 통일됨."],"1582665624":["먼저 Grep으로 모든 파일 내용에서 LEGACY_TIMEOUT을 찾아 코드, YAML, 문자열까지 전부 나열하고 각각의 주변 문맥을 Read로 확인한 다음 한 건씩 Edit으로 고치기. 똑같은 조각이 여러 개라 Edit의 고유 일치가 안 먹히는 곳은 Read + Write로 대신하기."],"1583094546":["stop_reason이 \"end_turn\"일 때 멈추기."],"1583112437":["그것이 항상 통하니까, 74개 파일을 하나하나 전체를 읽고 변경 사항을 적용해서 다시 쓰기"],"1583489655":["편집이 전혀 일어나지 않는 상태에서 먼저 접근 방식을 확정하고, 그 작성된 접근 방식을 결제 그룹이 서명할 것으로 앞에 내놓은 다음, 합의된 설계를 일반 작업 세션에서 실행하기"],"1583513184":["반복 상한(iteration cap)을 40에서 12로 낮춰서, 폭주하는 실행이 토큰 소모가 눈에 띄기 훨씬 전에 끊기게 하기"],"1584374402":["일반 호출을 --output-format json으로 바꾸기. 이 플래그 하나로 비대화형(non-interactive) 실행과 구조화된 출력을 둘 다 처리할 수 있음."],"1585156354":["분석 에이전트의 도구 집합을 제 역할인 문서 처리로 제한하기. 빈틈을 발견하면 코디네이터한테 보고하게 하고, 코디네이터가 추가 검색을 검색 에이전트한테 위임하는 것임."],"1587105990":["빠뜨리는 게 없도록 결제 서비스(payment services) 아래의 모든 파일을 미리 다 읽어 두고, 이후 질문에는 이미 대화에 있는 내용만으로 답하기"],"1588296377":["고객이 이렇게 씀. \"주문 #A-1042가 이중 결제됐고, 다른 주문 #A-1038은 12일째 배송이 안 됐고, 지난달 적립금도 안 들어왔어요.\" 그런데 에이전트는 이중 결제만 환불해 주고 대화를 끝내버림.","올바른 처리 패턴은 무엇인가?"],"1588693811":["채워 넣은 전후(before-and-after) 예시 두세 개를 건네줘서 형태를 더 이상 문장에서 추론하지 않아도 되게 하고, \"더 견고하게(more robust)\"라는 표현은 실패했던 정확한 입력과 실제로 돌아온 결과, 그리고 원래 나왔어야 할 결과로 바꾸고, 값 누락(missing-value) 케이스 세 개는 같은 헬퍼(helper) 안에서 서로 만나므로 하나로 묶어서 전달하기"],"1588969629":["\"저장소에 커밋되어 있는가?\"가 그 기준임. 프로젝트 수준 파일(루트 CLAUDE.md, .claude/rules/, .claude/settings.json, .mcp.json)은 clone이나 pull을 따라 모두에게 전달되지만 ~/ 아래에 있는 것은 그 컴퓨터 한 대에만 남음."],"1593192602":["큰 리뷰는 파일별 집중 패스로 쪼개고, 파일 간 통합 패스를 따로 하나 두기"],"1594176425":["지난 화요일에 빌링 플랫폼(billing platform)이 40분 동안 다운됐음.","그 시간대에 처리된 티켓 63건 전부에서 빌링 subagent가 빈 청구 목록을 반환했고, 코디네이터(coordinator)는 고객들에게 \"고객님 계정에는 청구 내역이 안 보이네요\"라고 안내함. 그중 두 명은 해지했음.","subagent는 대신 무엇을 반환해야 하고, 설계에는 또 무엇이 필요한가?"],"1594221297":["hook은 도구 호출(tool call) 자체를 막을 수 있어서, 위반 사항이 account-change tool까지 절대 도달하지 않음."],"1594807856":["메시지 전체를 사람 상담원에게 넘기기. 여러 건이 섞인 요청은 에이전트 하나가 감당할 범위를 넘기 때문임."],"1595243534":["형제 subagent들 사이에 공유 메모리(shared memory)가 빠져 있었다는 것임. 그게 있었다면 handler가 schema subagent의 결정이 내려지는 순간 바로 그걸 볼 수 있었을 것임."],"1596010937":["둘 다 맞음. 그 필드에 read 도구만 명시하면, skill이 활성화되어 있는 동안은 나머지 도구들이 세션에서 빠지게 되는데, 이게 바로 compliance가 요구했던 보장임."],"1596180331":["wrapper 파일 두 개를 열어서 무엇을 어떤 이름으로 re-export하는지 확인하기"],"1596863583":["오탐이 가장 많은 카테고리는 프롬프트가 나아질 때까지 일시적으로 꺼두기"],"1597365973":["시스템 프롬프트 규칙 하나. “환불을 처리하기 전에 항상 신원을 확인할 것.”"],"1597890548":["과거 세션에서 각 도구가 성공한 빈도."],"1597902737":["시스템 프롬프트에 \"'blocked by policy'가 보이면 그 케이스는 사람 상담원에게 넘길 것\"이라는 규칙을 추가하기"],"1600235242":["차단(blocking)을 아예 그만두고 권고성 댓글과 팀이 이미 하고 있는 사람 코드 리뷰에 맡기기."],"1600661988":["작성기(composer)가 말하려는 금액과 환불 도구 결과(tool result)에서 가져온 금액을 각각 별도 필드로 써내게 하고, 둘을 비교했을 때 일치하지 않으면 메시지를 보류하게 하기."],"1600674726":["이 섹션에 대한 에이전트 자체 신뢰도 점수(confidence score)가 설정된 임계값(threshold) 아래로 떨어지는 것을 트리거로 삼아 에스컬레이션(escalate)하기"],"1601037824":["어시스턴트 턴을 \"Label: \"로 프리필(prefill)해서 라벨이 가장 먼저 나오게 하는 것임."],"1602226770":["매시간 점진적으로 요약해서 아홉 시간 전체가 압축된 형태로 계속 남아 있게 하기"],"1602576846":["너의 송장 에이전트(invoice agent)는 공급업체 송장을 처음부터 끝까지 자동으로 승인함.","컴플라이언스(compliance) 팀은 이제 tax-ID 필드가 있는 모든 송장이 사람 검토로 가야 한다고 요구하는데, 이건 최선을 다하는 정도가 아니라 반드시 지켜야 하는 보장임. 반면 그 필드가 없는 송장은 계속 완전 자동으로 처리됨.","tax_id 필드의 추출 신뢰도(extraction confidence)는 현재 평균 0.94임.","두 요구사항을 다 만족하는 구현은 어느 것인가?"],"1605872388":["요약하는 서브에이전트를 병렬 wave 밖으로 빼기. 그것은 나머지 세 개의 결과를 소비하므로, coordinator에게 그 결과들이 다 돌아온 다음에야 실행할 수 있음."],"1606200552":["작업이 안 끝나는 것은 text 블록이 나왔을 때 루프를 빠져나오기 때문임. text는 \"tool_use\"와 함께 올 수 있음. 호출이 반복되는 것은 200이 아닌 결과를 버려서 모델이 그 호출이 실패했다는 것을 끝내 모르기 때문임.","루프 종료는 stop_reason으로 판정하고, 에러 결과도 구조화된 도구 결과(tool result)로 대화에 추가하기"],"1606219400":["처음 두 번은 validator(검증기)의 출력을 그대로 붙여서 retry하기. 모델이 스스로 고칠 수 있게 하기 위함임. 세 번째에서는 멈추기. 빠진 owner(담당자)는 다시 추측하지 말고 직접 채워 넣어야 함."],"1607098063":["미리 정해 둔 순서는 요청에 다른 도구 조합이나 순서가 필요할 때 적응하지 못함. 매 턴마다 모델이 다음 호출을 스스로 판단하게 하는 것, 그게 바로 그때그때 달라지는 요청에 대해 agentic loop가 주는 이점임."],"1609191875":["구조화된 요약을 들고 새 세션을 시작하기. 파일이 하나라도 바뀌면 예전 세션의 도구 결과는 낡은 게 됨."],"1610585838":["에이전트가 파일 800개짜리 낯선 코드베이스를 수정하기 전에, 인증이 어떻게 동작하는지부터 파악해야 함.","모범 사례에 맞는 탐색 전략은 무엇인가?"],"1612789760":["검증 토큰을 process_refund 도구 자체의 필수 파라미터로 만들어서, 검증 안 된 호출은 스키마 검증에서 실패하게 하기"],"1612902390":["단일 패스(pass)는 유지하되, 진행하면서 파일 간 참조(cross-file reference) 목록을 계속 갱신하라고 지시하기"],"1614758255":["(a) 핵심 발견을 나오는 대로 적어 두는 스크래치패드 파일을 만들고, 이후 프롬프트에서 그 파일을 참조하기. (b) 탐색은 요약만 돌려주는 subagent에게 위임하기. (c) 구조화된 상태를 정해진 위치로 내보내고, 재개할 때 코디네이터가 읽을 매니페스트도 같이 두기"],"1617299314":["세 가지 전부 저장소의 메모리 파일(memory file)에 넣기. 항상 로드되는 단일한 정보 소스(source of truth) 하나가 기여자들이 최신 상태로 유지하기 훨씬 쉽고, (2)는 지금보다 더 강하게 명시하기만 하면 됨."],"1618278823":["평소대로 실행하되 파일을 쓸 때마다 확인 프롬프트를 띄우게 해서, 결제 담당자가 변경이 일어날 때마다 파일 단위로 승인하게 하기"],"1619508361":["그 서버는 팀 리드의 user scope에 설정되어 있어서 리드 컴퓨터 밖으로 나가지 않음. 정의를 프로젝트의 .mcp.json으로 옮기고 ${GITHUB_TOKEN} 환경 변수 확장을 사용하기. 그러면 설정은 공유되면서 각자의 토큰은 로컬에 남음."],"1621383946":["절충안으로, 디렉터리 순서를 따라 모듈별로 테스트를 생성하기. 이러면 탐색도 계획도 필요 없음."],"1623652351":["종합이 끝난 뒤 코디네이터가 보니, 보고서에 규제와 시장 규모는 다뤄져 있는데 자기가 배정한 \"인재 이동\" 하위 주제는 아무 얘기도 없음.","그 하위 주제를 맡은 검색 에이전트의 결과물이 부실했기 때문임.","코디네이터는 어떻게 하는 것이 맞는가?"],"1626118079":["일관성과 완전한 통제를 위해 둘 다 직접 만들기"],"1628830419":["diff에 나타나는 파일에만 코멘트를 달라는 프롬프트 문구를 한 줄 추가하기. 이것은 비용도 안 들고 파이프라인 변경도 필요 없음."],"1629418915":["오탐률 80%였던 style 카테고리를 껐다가 프롬프트를 개선했음. 이제 언제 다시 켤지 정해야 함.","재활성화 기준으로 가장 타당한 것은 무엇인가?"],"1632979013":["납세자 번호 필드가 들어 있는 문서는 신뢰도 점수와 상관없이 전부 사람 검토로 보내기."],"1633773257":["배치 요청에는 도구 정의를 넣을 수 없기 때문임."],"1633907720":["R1은 저장소의 항상 로드되는 메모리 파일(memory file)에 넣고, R2는 프로젝트 설정(project settings)에 커밋된 deny 규칙으로 넣기. 모델이 무엇을 의도하든 클라이언트가 그 호출 자체를 거부하게 하려는 것임. R3는 frontmatter에 매칭되는 경로를 명시한 규칙 파일(rule file)에 넣어서, 해당 파일들이 열려 있을 때만 런북이 컨텍스트(context)에 들어오게 하기"],"1636272973":["세 가지 검사를 각각 독립된 기준과 출력 필드를 가진, 초점이 분리된 세 번의 패스로 나눠서 실행하기"],"1638169965":["Bash로 git 이력을 통째로 뽑아서 커밋 메시지로 아키텍처를 추론하기."],"1638294105":["import 규칙을 skill로 만들어서, 코드 생성 작업 전마다 호출되게 하기. 그러면 딱 필요한 순간에만 로드됨."],"1638725559":["코디네이터가 네 조각을 서로 독립적인 것처럼 위임했던 것이 문제임. 핸들러(handler)와 테스트는 스키마에 의존하므로, 그 단계가 먼저 끝나야 하고 그 결과가 나중 프롬프트로 실행되기 전에 전달되어야 함."],"1640452850":[".claude/rules/ 파일에 YAML frontmatter로 paths: [\"**/*.resolver.ts\"]를 지정해서, 일치하는 파일을 편집할 때만 로드되게 하기."],"1641809081":["MCP 도구의 설명을 보강해서 기능과 출력을 상세히 적기. 심볼 인식 검색, 콜 그래프 탐색, 예시 질의까지 넣어서 에이전트가 언제 이 도구가 Grep보다 나은지 알아볼 수 있게 하기."],"1643604135":["개발 생산성 에이전트는 엔지니어 한 명당 하루에 세션 하나를 유지함.","결함 두 가지가 드러났음. (1) 엔지니어가 09:10에 말한 제약 조건인 \"payments 모듈은 절대 건드리지 마\"가 16:40에 지켜지지 않았고, (2) 파일을 읽을 때마다 전체 내용이 그대로 유지되는 바람에 세션당 토큰 사용량이 5배로 늘었음.","팀은 이미 한 시간마다 요약을 하고 있음.","실제 결함을 고치는 변경 두 가지는 무엇인가? (두 개 선택.)"],"1645641294":["시점이 섞이지 않도록 리서치를 한 해 자료로만 제한하기."],"1650344921":["머지 타이밍이 문제임. 같은 세션 리뷰를 시차를 두고 두 번 돌리기"],"1651880991":["stop_reason이 \"tool_use\"인 동안은 계속 루프를 돌면서, 다음 요청 전에 각 subagent의 결과를 대화에 추가하기."],"1655662290":["실행되기 전에 hook으로 셸 호출(shell call)을 가로채서 force-push 형태와 일치하는 명령은 거부하게 하기. 그래야 이 규칙이 세션의 판단에 의존하지 않게 됨."],"1656958989":["최근 40턴에 대한 슬라이딩 윈도우(sliding window)로 전환하기. 그러면 남겨두는 텍스트가 한 글자도 틀리지 않고(byte-for-byte) 정확하게 유지됨."],"1667090667":["Session B는 가장 최근 turn들만 보는 window를 갖게 하기. 4시간짜리 session을 감당할 수 있는 비용으로 유지하는 가장 싼 방법이기 때문임."],"1669100884":["root 파일을 가장 중요한 200줄로 줄이고, 나머지는 engineering wiki로 옮긴 다음 그 파일에서 링크로 연결하기."],"1669163387":["도구가 18개인 고객지원 에이전트에서 도구 선택 품질이 떨어지고 있음.","분석해 보니 반품 워크플로가 트래픽의 90%를 도구 4개로 처리하고, 나머지 14개는 어쩌다 한 번 있는 관리 작업용임.","가장 좋은 재구성 방법은 무엇인가?"],"1669397153":["지시문을 한 번 더 고쳐 쓰기. 이번에는 effective date를 법률 용어로 정식으로 정의해서, 모든 형태가 정의 하나로 다 커버되게 하기"],"1673468599":["사내에서 만든 payment wrapper는 버리고 유지 관리되는 커뮤니티 서버를 쓰고, custom server 개발 노력은 이 팀만의 환불 승인 워크플로에 쓰기"],"1675203986":["자기 비평(evaluator-optimizer) 단계를 추가하기. 모델이 자기 초안을 완결성 체크리스트(우려 사항 전부? 정책? 일정? 다음 단계?)에 대조해 보고 고치는 것임. 그때그때 달라지는 누락은 고정된 예시를 더 넣어서는 안 되고 사례별 평가가 필요함."],"1677317249":["같은 빈 리스트를 반환하되 경고 문자열을 붙여서, 코디네이터가 답하기 전에 뭔가 잘못됐음을 알 수 있게 하기"],"1678919280":["이 에이전트는 tool_choice를 \"any\"로 설정해서 모델이 즉흥적으로 답하지 않고 항상 도구를 쓰게 함."],"1679621442":["다시 돌릴 때 이전 리뷰 지적을 컨텍스트에 같이 넣고, 최신 코드에서 새로 생긴 문제나 아직 해결 안 된 문제만 보고하라고 Claude에게 지시하기"],"1680150624":["당장 다시 켜되, 스타일 관련 지적은 \"beta\"로 표시해서 개발자들이 감안해서 보게 하기"],"1680837150":["Raj의 방식이 맞음. 이렇게 오래된 코드베이스에서는 처음에 완전한 계획을 세워 두는 게 바로 헛수고를 막아 줌."],"1680849219":["답변 생성 후에 잘라내서(truncate) 60단어로 제한하는 방식으로, 이러면 지나치게 긴 사과가 구조적으로 아예 나올 수 없게 됨."],"1681742912":["보고서 생성을 섹션마다 하나씩, 별개의 실행 5개로 쪼개기"],"1682903590":["PR #812에서 나온 발견 사항 요약을 완전히 새로운 실행에 붙여넣고, 이걸 각 시정 경로(remediation path)마다 반복해서 세 개 모두 동일한 조건에서 시작하게 하기."],"1684160568":["system prompt에 한 줄을 추가하기. 메시지에서 배송, 배달, 추적이 언급되면 언제든 track_shipment를 호출하라는 내용임."],"1684727744":["두 가지 작업(workload)이 있음. (i) 새로 게시되는 모든 헬프 센터 문서마다 동일한 세 가지 품질 검사를 실행하는 야간 작업, (ii) 지난 목요일 특정 고객 한 명의 환불이 조용히 실패한 이유를 알아내는 일회성 작업임.","분해(decomposition) 전략의 짝을 어떻게 맞추는 것이 맞는가?"],"1685315063":["대화 턴(conversational turns)에는 슬라이딩 윈도우(sliding window)를 쓰고, 여기에 매 프롬프트마다 다시 주입되는 추가 전용(append-only) 인용(citations) 블록을 결합하기"],"1686107250":["확보한 결과만으로 종합을 끝내되, 커버리지를 같이 표시하기. 어떤 결론이 근거가 탄탄한지, 그리고 구하지 못한 출처 때문에 어떤 주제 영역에 공백이 생겼는지 적기."],"1686424164":["CI 플랫폼이 정해진 실제 경과 시간(wall-clock) 제한에 도달하면 프로세스를 강제 종료하게 하고, 디스크에 남은 부분 출력을 그대로 파싱하기"],"1686653652":["프로젝트 루트에 둔 CLAUDE.md. 저장소에 커밋해서 관리하기."],"1687740493":["A의 경우, 프로젝트의 설정 파일(configuration file)을 열어서 거기서 참조하는 경로들을 따라가기"],"1688034161":["문서화된 기준(standards)은 일반 세션이 이미 읽어 들이는 위치에 그대로 두고 unattended(무인) 실행도 그것을 읽게 하기; checks-off 설정은 사전 승인 목록 밖의 모든 것을 거부하는 모드로 바꾸고 read와 diff 커맨드만 사전 승인하기; 스키마 검증된(schema-validated) 구조화된 출력을 반환해서 대시보드가 문장이 아니라 필드를 읽게 하기"],"1688580657":["전: 전체 정확도 기준을 99%로 올리기","후: 후속 팀들이 이상 징후를 보고해 올 때까지 기다리기"],"1689403705":["보정된 신뢰도 점수가 낮은 추출 결과와, 출처가 모호하거나 서로 어긋나는 문서를 먼저 사람 검토로 보내기"],"1690936826":["모델에게 제공되지 않은 외부 문서에만 존재하는 정보."],"1690962895":["모델이 문서를 더 꼼꼼히 훑을 여유가 생기게 max_tokens를 올리기."],"1691071833":["수치가 없을 때 모델이 \"not discussed\"라고 쓸 수 있도록 amount를 string 필드로 만들기"],"1692467447":["압축 예산(compaction budget)을 500에서 2,000 토큰으로 늘려서 매번 압축할 때 손실되는 세부 정보를 줄이기."],"1692619717":["심각도 등급을 없애고 지적이 하나라도 나오면 머지를 막기"],"1693011884":["둘 다 팀이 세션 시작마다 실행하는 slash command 하나에 넣기."],"1693177541":["사용 중단된(deprecated) auth/ 디렉터리를 고르기. \"deprecated\"라는 표시가 \"old\"의 의미를 가장 강하게 알려주는 신호이기 때문임."],"1693697455":["루트 파일의 100자 규칙이 prompts/ 안에서 작업하는 사람에게는 더 이상 적용되지 않는다는 보장임."],"1694260349":["shell tool에 대해 OS 수준 샌드박싱(OS-level sandboxing)을 켜야 함. 파일 거부 규칙(file deny rule)은 어시스턴트 자체의 파일 도구와 Claude Code가 인식하는 파일 명령어만 커버하지, 스스로 파일을 여는 임의의 subprocess는 커버하지 못함."],"1695493227":["출력을 정규식으로 후처리해서 산문을 걷어내고 필드명을 정규화하기."],"1697386350":["컨벤션을 저장소의 always-loaded project memory로 옮겨서 모든 실행(run)이 그걸 읽게 하고, lockfile 금지 사항은 커밋된 deny rule로 표현하기. 문서화된 컨벤션은 리뷰어가 뭘 시도할지를 정할 뿐이고, 실제로 뭘 할 수 있는지를 결정하는 건 rule뿐임."],"1699235758":["claude -p \"Review this diff for security issues\" --output-format json --json-schema review-schema.json"],"1700033302":["두 규칙 모두 PostToolUse에 넣기. 도구 결과(tool result) 안의 금액을 살펴보고 위반을 발견하면 거부할 수 있기 때문임."],"1700049738":["모델이 발견 하나하나에 신뢰도 점수를 같이 보고하게 하고 라벨이 붙은 검증 세트로 그 점수를 보정한 다음 신뢰도가 낮은 발견은 사람 검토로 보내기."],"1700371746":["크기 문제를 고친 뒤에 5,000건짜리 배치 전체를 다시 제출하기"],"1700709096":["저장소 전체를 도는 야간 리뷰가 보안, 의존성 관리 상태, API 호환성을 한꺼번에 점검함.","한 번에 몰아서 훑다 보니 결과가 얕고 들쭉날쭉함.","세 관심사는 서로 독립적이고 범위도 뚜렷함.","어떻게 재구성하는 것이 맞는가?"],"1703772090":["테스트 대상 코드 옆에 있는 .spec.ts로 끝나는 파일을 편집할 때 fixture 컨벤션을 로드하는 것임."],"1704275165":["(a) Grep, 파일 시스템을 훑어서 일치하는 파일을 찾아주기 때문임. (b) Glob, 글롭 패턴은 코드를 포함해 어떤 문자열이든 매칭할 수 있기 때문임."],"1706784387":["파일 전체를 Read로 읽고 메모리에서 변경을 적용한 다음 Write로 다시 쓰기. 원하면 Grep으로 확인까지 해도 좋음."],"1706993971":["프로젝트의 CLAUDE.md에 이 절차를 설명하는 섹션을 넣어서 언제나 참고할 수 있게 하는 방식임."],"1707654409":["네 CI 리뷰어가 러너 이미지 세 개에서 다르게 동작함: 한 호스트에는 MCP server가 설정돼 있고, 다른 하나에는 누군가 6개월 전에 설치한 plugin이 남아 있고, 세 번째는 둘 다 없음.","팀원 한 명이 세 개가 다 똑같이 시작하도록 모든 호출에 minimal-startup 플래그를 추가하자고 제안함.","그 플래그를 추가하면 아래 항목이 전부 달성되지만, 다음 하나는 예외임:"],"1707949625":["필드 하나라도 이상해 보이면 전체 조합(composition)을 최대 세 번까지 다시 시도하기. retry 비용은 거의 들지 않기 때문임."],"1708658980":["어떤 변경도 하기 전에 plan mode로 전환해서 모듈을 살펴보기."],"1714633105":["12개 표준을 전부 루트 CLAUDE.md에 붙여 넣어서 모든 패키지가 전부 상속받게 하기."],"1716747995":["파이프라인은 OCR, 추출(extraction), 검증(validation), 적재(load) 순서로 돌아감.","지난달 스캐너가 재보정됐는데 그 출력 품질이 떨어졌음. OCR이 대략 12자 중 1자꼴로 틀린 텍스트를 반환하기 시작했는데, 그런데도 매번 성공이라고 보고했음.","추출(extraction)은 이 노이즈에서도 스키마상 유효한 레코드를 만들어냈고, 검증(validation)은 타입이 맞다는 이유로 통과시켰고, 아무도 눈치채기 전에 2,100건의 레코드가 적재됐음.","이걸 막을 수 있었을 변경 두 가지는 무엇인가? (두 개를 선택할 것.)"],"1717268920":["에이전트가 검색된 위키 페이지를 항상 인용하고 일반 지식으로는 절대 답하지 않도록 하는 시스템 프롬프트(system-prompt) 지시를 추가하기"],"1717797481":["\"배치(batch)는 최대 24시간까지 걸릴 수 있고, 그때까지 안 끝난 것은 만료되는데, 여기서는 결과를 일주일 뒤에 읽으니까 문제없음.\""],"1720481247":["먼저 Grep으로 진입점(예: \"login\", \"verifyToken\")을 찾고, 그 파일들을 Read로 읽은 다음 import를 따라가며 흐름을 추적하기. 이해를 조금씩 쌓아 올리는 방식임."],"1720710495":["Glob임. 이름 패턴으로 파일을 매칭해 주기 때문임."],"1722507034":["파서를 try/catch로 감싸서 산문 형태 응답을 감지하고, 도구 호출이 돌아올 때까지 요청을 다시 보내기"],"1723058488":["각 줄의 처음 40칸을 어시스턴트 턴(assistant turn)에 미리 채워 넣어서(prefill), 모델이 금액을 쓰기 전에 시작 위치가 고정되게 하기."],"1724210840":["각 실행에 대해 JSON payload에 기록된 식별자(identifier)를 읽어서, 후속 질문을 보낼 때 그 식별자로 PR #812의 대화를 지정하고, 재개(resume) 시 새 식별자를 발급하는 옵션으로 실험을 분기해서 원본 트랜스크립트(transcript)는 그대로 보존하기"],"1724461246":["deployment manifest를 처음부터 끝까지 읽기. production에 반영되는 스위치는 전부 거기 선언되어 있어야 하기 때문임."],"1727184745":["예산에 맞추려고 가장 느린 subagent의 결과를 빼기."],"1728328866":["coordinator를 다시 설계해서 쿼리마다 요구사항을 분석하고 어떤 subagent를 호출할지 동적으로 고르게 하기. 그리고 독립적인 Task 호출을 한 응답에 함께 내보내서 선택된 에이전트들이 병렬로 돌게 하기"],"1728971486":["잘못된 것은 없음.","catch-all 패턴은 rule 파일을 무조건 적용되게 만드는 방법이고, 모든 컨벤션(convention)을 rule 파일 안에 두는 것이 두 메커니즘으로 나누는 것보다 감사(audit)하기 쉬움."],"1730038556":["재시도 상한을 네 번에서 두 번으로 낮춰서, 잘못된 입력 루프가 사과에 이르기까지 호출을 덜 태우게 하기."],"1730140299":["Claude에게 캐시 구현을 맡기고, 놓친 고려사항이 없는지 코드는 네가 직접 리뷰하기."],"1730630289":["12%는 그대로 받아들이고, 날짜가 하나보다 많이 적힌 모든 계약서는 사람 리뷰로 보내기"],"1730710440":["리뷰 세션으로 가는 링크. 엔지니어가 그 대화를 다시 이어받아서 리뷰어에게 무슨 뜻이었는지 직접 물어볼 수 있게."],"1731396772":["Read. 모든 파일을 불러와서 직접 훑어보기."],"1733587256":["에이전트가 틀린 답을 단정하는 일이 절대 없도록, 두 경우 모두 \"unknown\" 문자열을 돌려주기"],"1733693261":["subagent는 코디네이터의 대화 기록을 물려받지 않음. 그래서 문서 목록은 subagent를 띄우는 프롬프트에 명시적으로 넣어 줘야 함."],"1733919298":["메인 대화(conversation)의 토큰 한도(token limit)를 올려서 원본 검색 결과(raw search output) 세 세트가 다 들어가게 하기."],"1734522296":["종합 결과가 이렇게 나왔음. (a) 독립된 출처 5곳이 뒷받침하는 주장, (b) 신뢰할 만한 출처 2곳이 정면으로 엇갈리는 주장, (c) 유일한 출처가 유료 장벽에 막혀 있어서 확인할 수 없었던 하위 주제.","최종 보고서는 이것들을 어떻게 제시해야 하는가?"],"1737034968":["상한이 있는 5일짜리 바우처는 발급하고 의류 환급은 거절하기. 정책에 나와 있지 않은 것은 기본적으로 전부 거부되기 때문임."],"1737716599":["세 가지 전부 plan mode로. 계획을 세워서 손해 볼 일은 없기 때문임."],"1738955788":["둘 다 paths를 붙인 .claude/rules/로. api/ 디렉터리 패턴 덕분에 예시가 딱 필요한 순간에 로드됨."],"1742079620":["반드시 도구 호출로 끝나야 하는 턴에서는, 모델이 대화체로 답하는 대신 무조건 어떤 도구든 호출하도록 tool choice를 설정하기"],"1742193103":["모델이 어떤 것도 비워 두지 않도록 모든 필드를 required로 표시하기"],"1742457433":["월요일에 티켓 세 개가 들어옴. (a) 스택 트레이스가 한 줄을 가리키는데, 날짜 파서가 빈 문자열에서 에러를 던지는 것이라 수정은 가드 하나만 추가하면 됨. (b) 팀은 45개 파일에서 쓰이는 로깅 라이브러리에서 벗어나야 하는데, 방법은 두 가지임. 호출부를 그대로 두는 shim을 쓰거나, 지금 바로 호출부를 다시 쓰는 것임. (c) 불안정한 테스트(flaky test) 하나는 타임아웃 값을 한 줄만 늘리면 됨.","올바른 배분은 무엇인가?"],"1742791140":["공유 라이브러리(shared-library) 방식으로 바로 구현을 시작하고, 사이드카(sidecar)가 더 나은 선택으로 드러나면 그때 plan mode로 전환하기."],"1743467483":["너의 research coordinator는 실행(run)을 일시정지하고 요청한 analyst한테 질문을 던질 수 있음.","아래 상황들은 하나만 빼고 전부 일시정지해서 물어볼 근거가 됨. 어느 것이 아닌가?"],"1744331443":["컨벤션은 위키에 그대로 두고 리뷰어가 실행 시작할 때마다 그 페이지를 가져오게 하고, lockfile 스크립트는 리뷰 프롬프트 맨 위에 한 줄 추가해서 금지하기."],"1744816406":["밤새 돌리던 멀티 에이전트 코드베이스 분석(코디네이터 1개에 탐색 에이전트 4개)이 시작 6시간 만인 새벽 3시에 죽었음.","지금 구조에서는 한 번 죽으면 처음부터 다시 시작해야 함.","이미 끝낸 작업을 다시 하지 않고 복구하려면 어떤 설계가 필요한가?"],"1744958634":["Task 도구 호출이 대화 컨텍스트 플래그를 붙이지 못한 경우."],"1745085754":["코디네이터(coordinator)가 티켓에 실제로 무엇이 필요한지 읽고 그 요구사항에 맞는 subagent만 생성하게 하고, 진짜로 빌링과 배송(delivery)에 걸쳐 있는 티켓에 대해서만 전체 팬아웃(fan-out)을 유지하기."],"1745569108":["보고되는 카테고리(bugs, security, data loss)와 건너뛰는 카테고리를 명시하기. 건너뛰는 카테고리에는 formatting, naming, 그리고 이 프로젝트에만 해당하는 패턴이 포함됨."],"1746412298":["모든 요청에 대해 세 전문 담당자(specialist)를 전부 유지하되, 각각의 지시문과 출력 길이를 줄여서 전체 체인이 더 빨리 끝나게 하기."],"1746501871":["장황한 도구 출력은 컨텍스트에 들어가기 전에 판단에 필요한 몇 개 필드만 남기고 쳐내기"],"1747337436":["종합(synthesis) 에이전트 쪽임. 빠진 에너지 유형을 알아채지 못했음."],"1747382577":["범위 안에 회사가 소스 접근 권한이 전혀 없는 관할권이 포함돼 있어서, 배정된 subtopic 하나는 아예 조사가 불가능함."],"1748650311":["analyze_document에 필수 \"mode\" 파라미터(extract | summarize | verify)를 추가하고, 시스템 프롬프트에서 모델한테 그 값을 제대로 넣으라고 지시하기"],"1748840606":["규약을 .claude/rules/ 파일들로 쪼개고 경로 범위를 지정하기. 예를 들어 Terraform은 paths: [\"terraform/**/*\"], React는 [\"src/**/*.tsx\"] 이런 식으로. 그러면 조건에 맞는 파일을 편집할 때만 각각 로드됨."],"1749563614":["모든 지원 케이스마다 고객 프로필, 주문 이력, 배송 상태가 필요함. 서로 독립적인 조회 세 개인데 지금은 순차로 돌아서 지연이 3배임.","팀원 한 명이 셋을 합친 lookup_all 도구를 만들자고 제안함.","더 나은 첫 수는 무엇인가?"],"1751877569":["매주 수동으로 list_tables 결과를 시스템 프롬프트에 캐싱해 두기"],"1753083366":["수정을 작성한 세션이 리뷰를 다시 돌리게 하기. 무엇을 손봤는지 이미 알고 있기 때문임."],"1753942261":["이전 리뷰 지적을 리뷰 컨텍스트에 넣고, 새로 생겼거나 아직 해결 안 된 문제만 보고하라고 모델에게 지시하기. 모델은 의미로 판단하기 때문임. 반면 줄 시그니처로 억제하는 방식은 취약함. 코드를 손보면 줄 번호가 밀리고, 같은 위치에서 진짜 회귀가 생겨도 조용히 가려질 수 있음."],"1754366066":["generated/ 디렉터리는 빌드 단계(build step)가 소유하는 곳이고 지난달 한 계약직 작업자가 두 번이나 덮어썼는데, 여기에 대한 어떤 쓰기(write)도 막기."],"1754919086":["(b)가 해결되고 (c)의 출처를 구할 수 있게 될 때까지 리포트를 붙들고 있기."],"1755271251":["주장(claim)마다 레코드 하나씩 담는 구조화된 상태 객체(structured state object). 주장, 이를 뒷받침하는 문장, 출처 URL, 수집 시각이 담김."],"1756040407":["관련 표준 문서 내용을 각 패키지의 CLAUDE.md에 복사해서 넣기."],"1757170979":["버그 상황임. 고객 주소가 null이면 결제(checkout)가 죽음.","스택 트레이스가 정확한 줄을 짚어주고, 실패하는 회귀 테스트도 이미 있고, 수정은 한 줄짜리 가드 절이면 끝남.","팀원들 제안은 이러함. plan mode 먼저 쓰기 / 후보 수정안 두 개를 fork하기 / Explore subagent로 모듈 구조 파악하기.","너라면 어떻게 하겠는가?"],"1757607668":["저장소(repo)의 모든 코드가 따라야 하는 네이밍(naming)과 에러 처리(error-handling) 컨벤션임."],"1758212172":["고객이 사람 상담원을 명시적으로 요구할 때."],"1760400246":["생산성 에이전트에 내부 문서를 가져오는 범용 fetch_url 도구가 하나 붙어 있음.","로그를 보면 가끔 코드 주석 안에 적힌 외부 URL을 아무거나 가져오고 있고, 한 번은 만료돼서 지금은 스팸을 뿌리는 도메인에서 콘텐츠를 끌어온 적도 있음.","가장 좋은 해결책은 무엇인가?"],"1761490378":["검색을 시작하기 전에 src/payments/ 아래 파일을 전부 통째로 먼저 읽어서 모듈을 이해하기."],"1761971783":["root 파일의 규칙을 대체하는 게 아니라 그 위에 얹히는 convention."],"1762589070":["리뷰 단계(review step)의 structured output이 실행의 약 6%에서 schema validation을 통과하지 못함.","파이프라인(pipeline)은 동일한 프롬프트로 전체 단계를 최대 다섯 번까지 재시도하는데, 대부분의 실패는 다섯 번 다 그대로 실패하고, 이 단계의 비용은 세 배로 늘었음.","살펴보면 두 가지 뚜렷한 패턴이 있음. severity 값이 허용된 집합 밖에 있는 findings, 그리고 이 단계에 주어진 diff에는 없는 파일 경로를 언급하는 findings임.","올바른 처리 방법은 무엇인가?"],"1764932041":["모든 failure path(실패 경로)가 팀이 관리하는 고정된 문구 세트 하나로 표준화돼 있는 한, 이 문장으로 충분함."],"1766526067":["정확한 한 문장. 설명이 길면 요청마다 컨텍스트 토큰을 낭비함."],"1766805225":["같은 Edit을 다시 시도하기 전에 Glob으로 맞는 파일을 먼저 찾기"],"1767660117":["모든 원본 문서의 전체 텍스트."],"1769095850":["배치 처리는 비용을 대략 50% 절약해 줌."],"1769662952":["변경 이후에도 자동 종료된 티켓을 오늘과 같은 비율로 무작위 샘플링(sampling)해서 계속 확인하기."],"1770222307":["입력 스키마(input schema)에서 라벨을 네 값짜리 enum으로 선언한 도구(tool)를, 그 도구를 강제하는 tool_choice로 호출하기."],"1773131663":["에이전트를 뭐라도 바꾸기 전에, 월요일 밤 정책 수정본을 이전 버전과 diff해서 정확히 어떤 자격 조건이 완화됐는지 짚어내기"],"1774370667":["팀원 네 명이 각자 네 지원 에이전트용 에이전트 루프(agentic loop)를 구현했음.","누구의 구현이 맞는가?"],"1775694929":["직접 실행 모드를 유지하고 20개쯤 되는 파일을 지금 전부 고치기. Claude가 이미 근본 원인을 찾아냈고 흐름을 이어가는 것이 중요하기 때문임."],"1777396534":["페어 프로그래밍(pair-programming) 어시스턴트가 에디터에서 지금 열려 있는 파일에 대한 질문에 답함.","6개월치 트랜스크립트(transcript)를 보면 8턴보다 더 전에 나온 내용에 의존한 답변은 한 번도 없었고, 팀은 요청 경로(request path)에서 모델을 추가로 호출하지 않는다는 규칙을 엄격히 지키고 있음. 어떤 컨텍스트(context) 전략이 가장 잘 맞고, 그 이유는 무엇인가?"],"1777639039":["추론 대부분이 여전히 유효하므로 재개(resume)가 여전히 맞는 출발점이지만, 어떤 문서 6개가 바뀌었는지 세션에 정확히 알려줘서 그것만 다시 읽고 나머지 5개 분석은 그대로 두게 해야 함."],"1778568662":["둘 다 → 고정 파이프라인(fixed pipeline)임. Team A의 조항들은 항목별로 나열되어 있고 Team B에는 따라야 할 런북(runbook)이 문서로 있기 때문임."],"1779251828":["코드를 만든 세션한테 \"네 코드가 틀렸다고 가정할 것\"이라고 지시해서 스스로 검토하게 하기"],"1779593964":["Claude는 작업을 텍스트로 끝내므로, 응답에 text 블록이 하나라도 들어 있으면 곧바로 멈춤."],"1780429829":["Message Batches API에 대한 설명 중 틀린 것은 무엇인가?"],"1782026104":["모든 범주를 켜 둔 채로, 봇이 나아지는 동안 좀 참아 달라는 배너만 개발자들한테 띄우기."],"1782836625":["합산된 수치만 보지 말고 accuracy 수치를 ticket 언어와 issue 유형별로 쪼개서, 4.6 안에 숨어 있는 구간들이 드러나게 하기"],"1783711129":["네 문서 서비스는 고객에게 업로드 후 30시간 이내 결과를 약속하고 있음.","업로드된 문서는 Batches API로 일괄 처리함. 배치 하나당 최대 24시간이 걸림.","일부 문서는 첫 번째 처리에서 실패해서 재제출이 필요함. 크기가 너무 큰 문서가 컨텍스트 한도를 넘기기 때문임.","어떤 운영 설계가 SLA를 지킬 수 있는가?"],"1783781406":["매핑된 세션을 독립된 두 갈래로 분기해서 각 재작성(rewrite)을 같은 기준선(baseline)에서 서로 오염 없이 탐색하게 하고, 목요일에는 그 매핑된 세션을 재개하면서 그 30개 커밋이 건드린 파일들을 짚어 주기"],"1784166404":["schema validation을 없애고, merge bot이 파싱하지 못하는 finding은 그냥 무시하게 하기. retry 비용이 완전히 사라짐."],"1784210570":["실패한 문서만 실시간 API로 돌리고, 나머지는 하루 단위 배치 제출을 유지하기."],"1784750272":["비용 검토 회의임. 밤마다 도는 저장소 전체 감사는 이미 Batches API로 돌아가고 있고, 그것은 괜찮음.","팀원 한 명이 \"50% 싸고, 결과도 보통 한 시간 안에 온다\"며 머지 전 PR 검사도 거기로 옮기자고 제안함. 이 판단을 가르는 기준은 무엇인가?"],"1785076095":["컨텍스트 창이 더 큰 모델로 바꿔서 아무것도 밀려나지 않게 하기."],"1786135187":["이후 턴에서는 다시 \"auto\"로 되돌려서 에이전트가 그 케이스에 실제로 필요한 것에 맞게 도구를 고르게 하기"],"1787851720":["보고서 초안을 검토하다가 \"의료 분야 AI 도입률이 22%에서 38%로 상승\"이라는 문장을 발견함. 종합 에이전트가 두 개의 발견을 합쳐 놓은 것인데, 한 수치는 2021년 미국 병원 대상 조사에서 나왔고 다른 하나는 방법론이 다른 2024년 글로벌 조사에서 나온 것임.","구조화된 발견 항목에는 날짜도 방법론 맥락도 빠져 있었음.","이런 종류의 오류를 막으려면 상류 단계에서 무엇을 바꿔야 하는가?"],"1789757024":["(A)임. 컨텍스트가 충분하면 16개 파일 전부 한 번에 충분히 살펴볼 수 있음."],"1790421418":["거의 안 쓰는 도구 14개를 mega_admin 하나로 합쳐서 개수를 줄이기."],"1791188729":["2,300개 파일짜리 저장소(repository)에 네 가지가 들어갈 자리가 필요함. (i) 마이그레이션(migration) 컨벤션: 마이그레이션 파일은 .sql로 끝나고 여섯 개 디렉터리에 흩어져 있음. (ii) billing/ 안에 있는 걸 편집하는 동안 적용되는 PCI 체크리스트, billing/은 파일 90개짜리 폴더 하나임. (iii) 아직 존재하지 않고 손으로 만들 예정인 feature-flag 파일의 네이밍(naming) 컨벤션. (iv) vendored/ 트리는 절대 편집하면 안 된다는 강한 요구 사항, 지난달 계약자가 이걸 두 번이나 덮어썼음.","어떤 매핑(mapping)이 맞는가?"],"1792189951":["틀렸음. 사람을 찾는 명시적 요청은 먼저 해결을 시도하지 말고 즉시 받아들여야 함. 에이전트가 그 일을 잘한다고 해서 고객이 밝힌 선호를 뒤집을 수는 없음."],"1793549191":["불만 하나.","40페이지짜리 결제 핸드북이 저장소의 항상 로드되는 지침 파일에 들어가 있음.","이건 services/checkout/와 pipelines/settlement/ 아래 작업에만 관련이 있고, 두 트리 모두 이미 존재하며 거의 매주 수정되고, 이 가이드는 누군가 일부러 켜는 걸 기억하지 않아도 그 파일들을 수정하는 사람에게 전달돼야 함.","모든 제약을 만족하는 위치는 어디인가?"],"1793987633":["이를 각 payments 엔지니어의 개인 지시 파일(personal instruction file)로 옮겨서, 실제로 payments 업무를 하는 사람만 비용을 부담하게 하기"],"1794219188":["발견 결과(finding)는 subagent로부터 markdown 형태로 도착하고, coordinator가 이를 정규식(regular expression)으로 파싱함.","지난주에는 실행의 4%가 인용문 안에 들어간 콜론 하나 때문에 죽었고, 한 번은 coordinator가 숫자를 기대한 confidence 필드에 \"fairly high\"라고 적힌 finding이 조용히 만들어졌음.","이 두 가지 실패를 해결하는 변경 두 가지는 무엇인가? (Select TWO.)"],"1794960487":["키워드에 민감한 그 지시문이 analyze_document와 의도치 않은 연결을 만든 것임. 도구 설명 말고 시스템 프롬프트 문구를 고치기."],"1795008965":["설명이 거의 똑같이 빈약한 도구 2개를 에이전트가 자꾸 헷갈려 함.","LLM이 여러 도구 중에서 하나를 고를 때 쓰는 주된 근거는 무엇인가?"],"1795158918":["원본에 없을 수도 있는 필드는 required 말고 nullable로 두기"],"1795652854":["엄격한 출력 스키마와 나란히 형식 정규화 규칙도 프롬프트에 명시해서 넣기. 스키마는 구조를 강제하고, 규칙은 제각각인 원본 형식이 그 구조에 어떻게 대응되는지를 정해 주기 때문임."],"1795924503":["900개 파일짜리 저장소 전체에서 설정 키 LEGACY_TIMEOUT을 REQUEST_TIMEOUT_MS로 이름 바꿔야 함.","이 키는 코드에도 있고 *.yaml 설정에도 있음. 팀 추측으로는 로깅에 쓰이는 문자열 리터럴 몇 군데에도 들어가 있음.","제안된 계획은 네 개임.","어느 게 맞는가?"],"1797578083":[".spec.ts와 .test.ts를 모두 포괄하는 패턴으로 먼저 파일 이름을 매칭하고, 매칭된 파일을 하나씩 읽어서 retry를 다루는지 확인하기"],"1797627896":["temperature를 0으로 맞춰서 적어도 해석만이라도 일관되게 하기"],"1798903411":["형식 불일치와 출력 구조 오류. 정확한 정보는 문서 안에 들어 있음."],"1799694337":["생성기에게 \"pay equal attention to all sections\"(모든 섹션에 똑같이 주의를 기울이라)고 지시하기."],"1803351435":["심각도 기준을 명시하고 등급마다 구체적인 코드 예시를 붙이기. 그래야 모델이 추상적인 형용사 대신 실제로 보여준 사례를 기준으로 삼기 때문임."],"1804597343":["세 번째 불만 사항에 집중할 것.","재무팀은 문서당 비용을 낮추고 싶어함.","설명된 두 경로 모두에 맞는 처리 방식은 무엇인가?"],"1804706352":["Session A는 가장 최근 turn들만 window로 유지하고 그 이전은 다 버리는데, 로그를 보면 그보다 오래된 건 필요 없다고 나오고, 요청 경로(request path)에 호출을 추가하지도 않음."],"1805175777":["고정된 순차 파이프라인 대신 동적 적응형 분해(dynamic adaptive decomposition)가 가장 잘 맞는 작업은 무엇인가?"],"1805437681":["\"max_tokens\"는 완료된 turn이 아니라 이어서 계속해야 하는 잘린 응답으로 취급하기"],"1807132609":["임계값을 따로따로 두지 말고, 세 신호를 가중치로 합쳐 하나의 종합 에스컬레이션 점수로 만들기."],"1809817626":["각 subagent 보고서에, 현재 어떤 subtask도 담당하지 않는 엔티티를 마주쳤다면 그것을 명시하도록 요구하기"],"1811562265":["line-item 합계를 출력하기. 항목별 내역에서 계산된 값이 헤더에 직접 입력된 값보다 더 믿을 만하기 때문임."],"1812486705":["생성된 pull request는 테스트 스위트(test suite)를 통과하고 봇이 스스로 매긴 위험도 점수가 \"low\"로 나오면 자동 병합됨. 전체의 84%가 그러함.","자동 병합된 PR로 추적된 프로덕션 회귀(regression) 6건을 사고 리뷰(incident review)했더니, 6건 전부 low risk로 표시돼 있었고 6건 전부 payments/ 아래 파일을 건드렸음.","그 리뷰 결과에서 따라 나오지 않는 조치는 무엇인가?"],"1812707928":["둘 다 에러 피드백을 주면서 재시도하기. 그러면 모델이 결국 세금 ID(tax ID)도 찾아내고 합계도 맞출 것임."],"1813609150":["도구 선택이 안정적으로 되게 하려면 도구 설명에 어떤 요소 둘이 들어가야 하는가? (2개 선택)"],"1813633653":["coordinator의 대화 기록(transcript) 전체를 drafting 프롬프트에 그대로 붙여넣어서, 세부 사항이 형식적으로는 다 들어있게 하기"],"1814516711":["루트 CLAUDE.md에 \"SQL migrations\"라는 제목의 섹션을 두고, Claude가 .sql 파일을 볼 때 적용하게 하기"],"1814708810":["A임. subagent끼리는 서로의 컨텍스트를 볼 수 없으므로 중복은 피할 수 없고, 나중에 정리하는 수밖에 없음."],"1815774364":["모델이 내놓은 확신도 점수를 손대지 않고 그대로 믿고, 0.7 미만이면 전부 넘기기."],"1815804625":["날짜는 개인 식별 정보라서 자동으로 걸러짐."],"1816435200":["네 주문 검색 도구는 창고 API를 조회함.","지금은 두 가지 상황이 똑같은 응답 {\"results\": []} 을 내놓음. (a) API가 타임아웃돼서 도구가 예외를 잡은 경우, (b) 조회는 성공했지만 일치하는 주문이 하나도 없는 경우.","에이전트는 둘 다 \"주문 없음\"으로 처리해서, 장애가 난 동안에도 고객한테 주문이 존재하지 않는다고 말해버림.","이 도구는 어떻게 동작해야 하는가?"],"1816535769":["(1)은 각 기여자의 개인 메모리 파일(memory file)에 둬서 저장소를 옮겨 다녀도 따라가게 하고, (2)는 트랜스크립트(transcript)에 파괴적인 명령이 나타나면 빌드를 실패시키는 파이프라인 체크에 넣고, (3)은 ops/runbooks/ 안에 두는 메모리 파일에 넣기"],"1817492809":["턴마다 관련성(relevance)을 판단해서 선택적으로 유지하는 방식인데, 판단 기준(judge)이 중요하다고 표시한 내용은 세션이 끝날 때까지 보존함."],"1817795689":["normaliser의 대안 구현 세 개를 요청해서, 네 테스트 케이스를 가장 많이 통과하는 걸 고르기."],"1819080174":["wave당 병렬로 실행하는 서브에이전트 수를 3개에서 9개로 늘려서, 계획이 바뀌기 전에 더 많은 부분이 끝나게 하기."],"1819080693":["봇이 커밋(commit)마다 이전 댓글을 새 요약 하나로 교체하게 해서 스레드(thread)가 길어지지 않게 하기"],"1820446729":["네 고객지원 에이전트가 지켜야 할 정책이 네 개임. (1) 어떤 계정 작업이든 하기 전에 반드시 신원을 확인해야 함. (2) 500달러를 넘는 환불은 절대 자동 실행되면 안 됨. (3) 답변에서는 고객을 이름으로 불러야 함. (4) 답변은 150단어를 넘기지 않아야 함.","강제 수단을 어떻게 배분하는 것이 맞는가?"],"1820835391":["여기서는 tool 쪽 guarantee(보장)만 도움이 됨. 응답 내용을 제한하는 방식은 산문 형식을 통제할 뿐이지, 레코드의 필드 타입을 강제할 수는 없기 때문임."],"1821840146":["두 경로 다 Batches API로 옮기기. 할인은 요청 단위로 적용되고, 웹 폼은 배치(batch)가 결과를 반환하면 그 결과를 폴링(poll)할 수 있기 때문임."],"1822734381":["모델에게는 웹 관련 질문이 extract_web_results로 가는 few-shot 예시가 필요함."],"1823080929":["container_number는 required이면서 non-nullable, broker_reference는 required지만 nullable이라 확인했지만 없는 값은 명시적인 null로 들어와, insurance_certificate_id는 optional이라 범위 밖일 때는 객체에 그 키 자체가 없음."],"1823270089":["보고서를 쓰기 전에 반복된 출처를 걸러내는 중복 제거 필터를 종합 단계에 넣기"],"1824252580":["신뢰할 만한 출처 두 곳이 같은 지표(metric)에 대해 서로 다른 수치를 제시하는데, coordinator는 어느 쪽이 맞는지 판단할 수 없음."],"1825400507":["coordinator가 실패를 통과로 잘못 읽지 않도록, 각 서브에이전트가 \"checked, found nothing\"과 \"could not check\"를 구분한 structured result를 반환하게 하기."],"1826453247":["Claude한테 먼저 모듈 전체를 리팩터링하게 하고, 그러고도 남는 버그를 다시 보고하게 하기."],"1827975428":["리포트 생성기 쪽임. 길이를 줄이려고 태양광이 아닌 섹션을 잘라냈기 때문임."],"1829006939":["매 단계마다 에이전트가 다시 계획을 세우는 하이브리드(hybrid) 방식을 채택하기. 이는 둘 중 어느 쪽보다도 확실히 더 안전함."],"1829325647":["대화 전체를 사람에게 넘기기. 요청이 뒤섞여 있으면 일부만 자동화하기에는 위험이 너무 크기 때문임."],"1829838831":["둘 다 동적 분해(dynamic decomposition)임. 에이전트는 항상 자기 다음 단계를 자유롭게 고를 수 있어야 함."],"1832277879":["모델이 도구 결과(tool result)를 아예 못 보니까, 모델 입장에서는 검색이 아직 일어나지 않은 것임. 그래서 같은 호출을 계속 요청함."],"1835014916":["파괴적인 작업이 절대 실행될 수 없게 스킬에서 데이터베이스 실행 도구를 아예 빼기"],"1835442711":["적용 전에도 후에도, 문제 있는 문서를 걸러내는 데 필드 단위 신뢰도 점수를 그대로 믿고 쓰는 방식."],"1836000030":["입력 스키마(input schemas) 쪽임. 두 시그니처(signature)가 전혀 비슷해 보이지 않을 때까지 파라미터 이름과 타입을 좁혀가면 모델이 구분을 명확히 할 수 있음."],"1838211399":["이름 붙인 세션을 매일 --resume으로 이어 쓰고, 하루를 시작할 때 어제 이후 바뀐 파일이 무엇인지 에이전트한테 알려줘서 그것만 다시 분석하게 하기"],"1838984690":["팀 리드의 ~/.claude.json을 새 개발자 컴퓨터로 복사하기. 토큰까지 같이 넘어가므로 환경을 맞추는 가장 빠른 길임."],"1840263969":["자동 리팩터링이 Edit으로 설정 상수 한 군데를 바꾸려는데, 기준이 되는 텍스트가 파일 안에 7군데나 있어서 매치가 유일하지 않다는 이유로 Edit이 계속 실패함.","워크플로는 계속 안정적이어야 함. 이제 어떻게 해야 하는가?"],"1840854907":["주문 조회 도구가 이제 isError와 함께 \"The payment provider did not respond in time.\"라는 문장을 반환하는데, 팀원 한 명은 이 정도면 충분하다고 주장함. 모델이 영어를 읽을 수 있고 문장이 무슨 일이 일어났는지 말해주니, 기계가 읽을 필드를 추가하는 건 과한 설계라는 것임.","그런데 지난달 결제 제공업체(provider)가 문구를 \"Upstream timeout while settling\"로 바꿨고, 그에 따라 에이전트의 재시도(retry) 동작도 달라졌음.","올바른 평가는 무엇인가?"],"1842158209":["원하는 출력 형식(위치, 문제, 심각도, 제안된 수정)을 그대로 보여 주는 few-shot 예시를 넣어서 모델이 보여 준 구조에 맞춰 가게 하기"],"1843970155":["handler 이름으로 서비스의 entry point를 검색해서 그 파일 하나만 읽고, 거기서 import하는 것들을 따라가기."],"1845532719":["결론을 내기 전에 전체 그림이 컨텍스트에 들어와 있도록 800개 파일을 전부 먼저 읽기."],"1846792796":["순서를 지키기 더 쉽게 작업을 더 작은 batch로 나눠서 제출하고, 각 batch 안에서는 위치 기준으로 계속 짝을 맞추기."],"1849481541":["남은 5%가 덮일 때까지 더 다양한 few-shot 예시를 계속 추가하기."],"1850175324":["각 결과를, 제출할 때 썼던 custom_id로 원래 요청과 짝짓기. batch 결과는 어떤 순서로도 돌아올 수 있어서 위치는 유효한 키가 아니기 때문임."],"1850250345":["Bash 명령 한 방으로 끝내기. grep -rl | xargs sed -i 's/LEGACY_TIMEOUT/REQUEST_TIMEOUT_MS/g' 면 900개 파일 전부가 10초 만에 처리됨."],"1856253913":["범주를 명확히 못 박은 기준을 쓰기. \"주석이 주장하는 동작이 실제 코드 동작과 어긋날 때만 표시할 것.\""],"1857450671":["왕복 횟수를 줄이려고 subagent끼리 발견한 내용을 직접 주고받게 하기"],"1857551702":["파일 안의 텍스트 찾기 → Glob. glob 패턴이 어떤 문자열이든 매칭하기 때문임."],"1860529956":["풀 리퀘스트(pull-request) 리뷰 단계가 권한 검사(permission checks)가 꺼진 채로 공유 러너에서 무인으로 실행됨.","이번 스프린트에 불만이 세 가지 나옴. 리뷰가 저장소에 문서화된 에러 처리와 로깅 표준을 무시하고, 결과를 수집하는 메트릭 대시보드는 텍스트를 패턴 매칭하는 방식이라 거의 매주 깨지고, 지난 화요일에는 이 단계가 브랜치를 푸시해버림.","세 가지를 다 해결하는 수정안은 무엇인가?"],"1861133501":["여러 단계로 요약할 때, 최종 보고서를 믿을 수 있게 하려면 무엇을 반드시 보존해야 하는가?"],"1861268101":["같은 세션에서 \"assume the eviction logic is wrong and prove it.\"(축출 로직이 틀렸다고 가정하고 증명해 봐) 같은 더 강한 프롬프트로 자체 리뷰를 다시 돌리기"],"1863148981":["transcript와 policy 텍스트는 받지만 resolving 세션의 추론 과정(reasoning)은 받지 않는 별도 세션에서 audit을 실행하기."],"1863984654":["변경을 촉발한 모듈 하나만이 아니라, 리뷰어가 실제로 다루는 모듈과 finding category 전체를 아우르도록 예시 세트를 다시 조정하기."],"1865297603":["에이전트가 무서운 에러를 아예 보지 않게, HTTP 200 상태와 빈 결과 집합을 돌려주는 방식."],"1867030924":["계속 진행은 하되, 에이전트에게 실제로 찾아낸 것만으로 답하고 일반적인 패턴으로는 절대 답하지 말라고 하기"],"1867052170":["“20년 경력의 세계 최고 수준 시니어 리뷰어처럼 행동할 것.”"],"1867153539":["Northwind Freight는 40개 서비스에 걸쳐 약 120만 줄 규모의 결제 플랫폼을 운영함.","Claude 기반 분석 에이전트(agent)가 마이그레이션 보고서 하나를 작성해 달라는 요청을 받음. 레거시 빌링 클라이언트(billing client)가 호출되는 모든 위치, 각 호출 지점이 무엇에 의존하는지, 그리고 그 클라이언트를 교체하면 무엇이 깨질지를 담아야 함.","이 작업은 약 7시간짜리 단일 연속 세션(session)으로 계획되어 있음.","첫 30분 동안 플랫폼 리드(platform lead)와의 대화에서 두 가지가 정해졌음: 동결 날짜, 절대 손대면 안 되는 서비스 세 개, 그리고 수정 중인 서비스에 적용되는 롤백 규칙임.","그 결정들은 7시간째에도 한 글자도 틀리지 않고 그대로 인용할 수 있어야 하고, 최종 보고서는 나열하는 모든 호출 지점마다 파일명과 줄 번호를 명시해야 함.","어떤 파일이 중요한지는 미리 아무도 알 수 없음. 그것을 알아내는 것이 바로 이번 실행(run)의 목적임.","앞선 두 번의 시도는 똑같은 방식으로 실패했음.","1시간째에 이루어진 Grep과 Read 호출이 파일 전체를 대화에 쏟아부었고, 3시간째가 되자 에이전트는 자신이 읽은 클래스를 인용하지 않고 대신 결제 시스템에 대한 일반 지식으로 답하고 있었음.","팀은 세 번째 시도를 시작하기 전에 계획부터 고치고 싶어함."],"1867719203":["critical로 라벨링된 발견 사항(finding)은 머지를 막음.","지난 분기 데이터를 보면, critical finding은 88%의 확률로 맞고, 이의 제기를 조정하는 엔지니어 두 명이 매주 막힌 머지 약 30건을 처리하는데, 이 중 절반의 시간이 결국 맞긴 하지만 고치기엔 사소한 finding에 들어감.","리더십은 보안 가치는 포기하지 않으면서 막힌 머지 건수는 줄이길 원함.","어떤 변경 두 가지가 맞는가? (두 개를 선택할 것.)"],"1869173632":["규칙이 언제 로드되는지. glob 패턴에 맞는 파일을 편집할 때만 로드됨."],"1871365314":["2차 반복은 방향은 맞았는데 과하게 조정됐음. 프롬프트 문구를 A/B 테스트하면서 \"위험한 코드를 표시하라\"와 \"보수적으로 판단하라\" 사이의 최적점을 찾는 게 해법임."],"1873776515":["subagent 출력들을 모으고 종합 결과에 빠진 부분이 없는지 평가한 뒤, 부실한 곳은 다시 위임하기"],"1874429492":["도구 이름을 super_search로 바꿔서 더 강력하다는 신호를 주기"],"1874832251":["hook을 쓰면 규칙 작성자가 예상하지 못한 예외 상황도 모델이 스스로 판단할 수 있는데, 이는 프롬프트 지시문으로는 할 수 없는 일임."],"1875877369":["extraction 모델의 temperature를 0으로 설정하면, 품질이 떨어진 input이 들어와도 일관되게, 그래서 감지 가능한 방식으로 실패함."],"1881816857":["repo 안에 자리를 잡아야 할 것이 두 가지 있음. (i) 스프린트마다 한 번 실행하는 12단계짜리 release-notes 절차인데, dry run에서 노트를 쓰기 전까지 대화 안에서 commit-log 분석만 약 800줄이 나왔음. (ii) 생성된 코드는 절대 internal/에서 import하면 안 된다는 한 줄짜리 규칙.","맞는 배치 두 가지는 무엇인가? (두 개 골라.)"],"1881907522":["MCP 도구(tool) 두 개, fetch_order_status와 fetch_shipment_status가 있는데, 에이전트가 호출의 약 3분의 1에서 잘못 고르고 있음.","둘 다 제대로 등록돼 있고, 파라미터 이름도 서로 다르게 잘 짜인 입력 스키마(input schema)를 갖고 있는데, 설명은 둘 다 \"상태 정보를 가져옴\"임. 팀은 어디를 손봐야 할지 논쟁 중임.","모델이 둘 중 하나를 고를 때 쓰는 가장 근본적인(PRIMARY) 메커니즘은 무엇이고, 거기서 무엇이 따라 나오는가?"],"1882449687":["코디네이터가 서로 독립적인 문서 분석 세 개를 돌려야 함.","지연 시간을 가장 줄여 주는 호출 방식은 무엇인가?"],"1882503096":["리포트 생성기(report generator)가 출처 표시(attribution)가 없는 발견 내용은 모두 버리게 해서, 등록되지 않은 문서는 절대 독자에게 도달하지 않게 하기"],"1883506637":["루프를 계속 돌리기. 반복 개선의 핵심은 커버리지가 다 찰 때까지 돌리는 것이기 때문임."],"1884330409":["verify_batch가 unreachable-target을 정상 검증(clean verification)과는 구분되는 구조화된 실패(structured failure)로 보고하도록 바꾸고, 그다음 로그에서 타임아웃난 배치 세 개를 찾아내서 그 행(row)들만 다시 마이그레이션하기"],"1885383362":["Northbay Retail는 Agent SDK로 만든 고객 지원 해결 에이전트를 운영함.","이 에이전트는 매주 약 4,000건의 대화에서 반품, 청구 분쟁, 계정 변경을 처리하며, 팀의 목표는 최초 응대 해결율(first-contact resolution) 80%임.","이 에이전트는 MCP server를 통해 내부 시스템 네 곳에 접근함. 주문 데이터베이스, 결제 서비스, 창고 배송 API, 내부 정책 위키임.","노출된 도구(tool)는 7개이며, 그중에 get_customer, lookup_order, track_shipment, process_refund, search_policy, list_policy_categories, open_policy_page가 있음.","이 중 두 도구는 한 줄짜리 설명을 달고 있음. lookup_order는 \"주문 상세 정보를 조회하며, 배송 상태도 포함함\"이라고 되어 있고, track_shipment는 \"배송 정보를 제공함\"이라고 되어 있음.","지난달 릴리스 이후로 로그에 계속 나타나는 패턴이 세 가지 있음.","첫째, \"내 물건이 어디 있는가?\" 같은 배송 관련 질문에 track_shipment가 아니라 lookup_order가 답하고 있음.","둘째, 거의 모든 대화에서 에이전트는 무엇이든 답하기 전에 처음 서너 턴을 list_policy_categories와 open_policy_page를 호출하면서 정책 위키가 어떻게 구성되어 있는지 다시 파악하는 데 씀.","셋째, process_refund가 실패하면 결제 서비스가 타임아웃됐든, 요청 금액이 주문 총액보다 컸든, 반품 기한이 이미 지났든 상관없이 항상 같은 payload를 돌려줌. isError 플래그에 \"refund failed\"(환불 실패)라는 메시지가 붙어 있음.","그 릴리스에서 도구 코드는 하나도 바뀌지 않았음."],"1885758529":["에이전트가 1시간째에 봤던 파일들을 다시 읽게 해서, 세부 내용이 context로 다시 들어오게 하기"],"1886814624":["요청 전체를 에스컬레이션하기. 정책 상한(policy cap)을 넘는 혼합 요청은 어느 부분이든 자동화하기엔 너무 위험하기 때문임."],"1890439692":["감사(audit)가 각 finding에 confidence를 붙이게 하고, 무언가를 라우팅하기 전에 사람이 감사한 샘플과 대조하게 하기"],"1891539164":["다음 중 멀티 에이전트 시스템에서 오류 전파(error propagation) 안티패턴에 해당하는 것은 무엇인가?"],"1891548867":["그 첫 문장을 다시 쓰기: 행동 지시처럼 읽히는 우선순위 표현이 모델을 환불 액션 도구(refund action tool) 쪽으로 끌어당기면서 설명에 이미 정확히 적혀 있는 경계를 무시하고 있음."],"1891846427":["너의 에이전트가 pull request에 인라인으로 남기는 댓글이 무시당하고 있음.","지난 스프린트 댓글 210건 중 138건은 저장소의 formatter가 이미 처리하는 스타일 지적(style nit)이었고, 개발자들은 이제 봇 섹션을 읽지도 않고 접어버림.","해결책 네 가지가 제안됐음.","실제 문제에 가장 도움이 안 되는 것은 어느 것인가?"],"1893727492":["strict 모드를 켜서 모든 출력이 스키마와 정확히 맞아떨어지게 하기."],"1898509272":["바로 실행하지 말고 plan mode를 써야 하는 작업 두 개는 무엇인가? (2개 선택)"],"1899381732":["스키마를 느슨하게 해서 날짜와 금액을 원본 문자열 그대로 받고, 정규화는 나중에 코드에서 하기"],"1900712955":["메인 에이전트는 트래픽이 많은 도구 4개로 범위를 좁히고, 드물게 쓰는 관리 작업은 나머지 도구를 가진 별도 경로(예: 전용 에이전트나 coordinator)로 보내기"],"1901084440":["두 세션 모두 turn 단위 selective retention을 적용하기. 이것이 가능한 선택지 중 가장 정확함."],"1901217937":["skill로 패키징한 것은 맞는데, 그 frontmatter(프런트매터) 필드는 나열된 tool들을 미리 승인해줄 뿐이지 나머지를 거둬들이는 것이 아님. read-only(읽기 전용) 속성은 permission layer(권한 계층)에서 나와야 함. 커밋된 deny 규칙이나, 미리 승인된 목록 밖의 모든 것을 거부하는 실행 방식처럼."],"1902330854":["로직은 바뀐 게 없고 의존성 결론에도 영향이 없으므로, formatting pass는 언급하지 말고 세션을 resume하기"],"1904638273":["(1) 리포지토리의 항상 로드되는(always-loaded) 메모리 파일임. 생성되는 코드를 권고 수준으로 유도하는 역할이기 때문임. (2) 프로젝트 설정과 함께 커밋된 거부 규칙(deny rule)임. 가이드 문장은 이미 한 번 실패했고, 호출을 통째로 거부할 수 있는 것은 권한 계층(permission layer)뿐이기 때문임. (3) 경로 패턴(path pattern)을 담은 규칙 파일임. 그래야 해당 파일을 건드리는 세션에서만 플레이북(playbook)이 컨텍스트(context)에 들어오기 때문임."],"1904687353":["제안된 대로 두 필드를 필수(required)로 표시해서 모든 행이 빠짐없이 도착하고 null 문제가 스키마 수준에서 사라지게 하기"],"1904892783":["renewal_term_months를 nullable로 만들고, 문서에 갱신 조항(renewal clause)이 없으면 모델이 null을 반환하도록 지시하기. 그러면 이 필드가 모든 레코드에 항상 존재하게 됨."],"1906261408":["한 번 답하고 종료하도록 호출하고, 사전 승인 목록(pre-approved list) 밖의 모든 것을 자동으로 거부하는 모드로 시작하되 read와 diff 명령만 승인해두고, 대시보드가 필드로 읽어 들이는 스키마로 검증된(schema-validated) 구조화된 출력(structured output)을 반환하게 하기"],"1906482950":["둘을 평균 내서 46.5억 달러로 적고 두 출처를 각주로 달기. 정확성과 결단력을 한 번에 챙기는 것임."],"1911882497":["셋 다 optional이면서 nullable로 둬서 키가 없을 때 무슨 뜻인지는 loader가 판단하게 하기. 비즈니스 규칙은 schema에 넣을 것이 아니기 때문임."],"1912007057":["어제 세션을 resume하고 \"뭔가 바뀌었을 수도 있다\"라고 한마디 덧붙이기"],"1912412232":["subagent를 하나 띄우고 그 subagent가 다시 subagent 세 개를 띄우게 하기."],"1914056811":["tracker에는 MCP를 쓰지 말고, Claude Code가 shell을 통해 tracker의 command-line client를 호출하게 하기"],"1915645527":["에이전트에서 process_refund를 아예 제거하기."],"1916787347":["첫 번째만 재시도하기. 나머지 둘은 생성된 파일 밖의 정보에 좌우되기 때문임."],"1917529532":["감사(audit)를 대화별 정책 매칭(policy-match) 단계와, 같은 오적용이 여러 대화에서 반복되는지 살펴보는 두 번째 단계로 나누기"],"1919973376":["--output-format json에 지적 사항 구조를 정의한 --json-schema를 같이 붙이기. 그러면 출력이 자유 형식 텍스트 대신 기계가 파싱할 수 있고 스키마도 지키는 형태로 나옴."],"1920721839":["팀원이 만든 새 CI 리뷰 단계는 다음과 같음. (i) claude -p \"Review this diff...\" 를 실행하는데 이건 잘 돌아감. (ii) 산문 형태 출력에서 /(?:issue|bug):\\s*(.+)/i 같은 정규식으로 지적 사항을 뽑아내는데, 이게 매주 깨짐. (iii) \"컨텍스트 토큰을 아끼자\"면서 같은 잡(job)에서 앞서 코드 수정을 만들어 낸 파이프라인 세션을 그대로 재사용함. 그러다 보니 리뷰가 생성된 코드의 뻔한 문제를 놓침.","실제 결함을 제대로 짚는 수정안은 어떤 것인가?"],"1921492240":["312건은 에러 피드백을 붙여 재시도하기. 형식 오류는 원본에서 고칠 수 있기 때문임. 89건은 재시도하지 않기. 정보 자체가 없으니 레지스트리 조회로 보내거나 null을 그대로 받아들이기. 23건은 계산값 대 명시값 비교 필드로 표시해서 검토로 넘기기. 원본 데이터 자체가 서로 어긋날 수 있기 때문임."],"1921687336":["신뢰도와 상관없이 금액이 가장 큰 인보이스만 검토하기."],"1921758754":["지원 에이전트 하나에 결함이 둘임. (1) 신원 확인 전에 환불을 내주는 경우가 가끔 있어서 컴플라이언스 위반이고, (2) 환불 안내 메시지의 어조가 들쭉날쭉해서 어색함.","팀원 한 명은 둘 다 엄격한 출력 필터 하나로 잡자고 함.","올바른 분리 방식은 무엇인가?"],"1926258487":["점진적 요약(progressive summarization). 모든 턴의 흔적을 남기기 때문에 그 무엇도 완전히 사라지지는 않음."],"1927069521":["한 엔지니어가 데이터 추출(data-extraction) 서비스의 내부 설계 리뷰(design review)에서 \"출력 강제(output enforcement)\" 섹션을 작성함.","리뷰어가 정확하지 않다고 쳐내야 할 문장은 무엇인가?"],"1930894526":["counterparty_signatory를 nullable로 바꿔서 초안에서는 null이 나오게 하고, 뒷단 시스템이 그 이유를 알 수 있게 document_status 필드(enum: signed/draft/unclear)를 추가하기."],"1930897086":["종합 에이전트에게 리포트에 넣기 전에 모든 인용을 웹에 대조해서 다시 검증하라고 지시하기."],"1931031551":["둘 다 hook으로 처리하기. 승인된 템플릿에서 어조가 벗어난 환불 출력은 전부 막기"],"1932231050":["search_policy도 리소스(resource)로 노출하기. 에이전트가 위키에서 읽는 것은 전부 같은 방식으로 제공되어야 함."],"1932681359":["각 수정 사항과 그것을 촉발한 발견(finding)을 같이 기록하는 running plan 문서를 계속 유지하기"],"1933844893":["실패 유형, 시도했던 쿼리, 확보한 부분 데이터, 대안 제안까지 담은 구조화된 실패(structured failure). 여기에 짧은 장애는 coordinator까지 아예 올라오지 않고 subagent 자체 instructions에 적힌 retry 규칙으로 그 아래서 해결되게 하는 것까지 포함하기."],"1935235109":["모델이 가져가도록 각 PR 설명에 링크해둔 위키 페이지."],"1935924173":["이어지는 부분은 오전 세션을 resume하고, 두 가지 프레이밍(framing)은 각각 완전히 새로운 세션으로 새로 시작해서, 어느 쪽 비교 갈래도 오전 컨텍스트(context)에 오염되지 않게 하기."],"1936223552":["저장소의 아키텍처 요약(architectural summary)을 요청하고, 거기서 가장 가능성 높은 모듈 세 개를 골라서 그 모듈들을 전부 다 읽기"],"1936369524":["옮기기. 보통 한 시간 정도 걸리는 처리 시간이면 대부분의 PR에는 괜찮고, 절감액도 계속 쌓이기 때문임."],"1936714650":["네 모노레포에는 packages/web, packages/api, packages/data-pipeline이 있고, 패키지마다 회사의 표준 문서 12개 중 필요한 부분이 서로 다름.","어떤 표준이 자신에게 해당되는지는 패키지 관리자가 제일 잘 앎.","가장 유지보수하기 좋은 구성은 무엇인가?"],"1936727626":["동적 분해(dynamic decomposition)를 채택하기. 실제 티켓에는 항상 고정된 단계 목록이 예상할 수 없는 뜻밖의 상황이 들어 있기 때문임."],"1936901365":["plan mode에서 작업하고, 호출부 매핑은 압축된 요약을 반환하는 subagent에 맡겨서, 설계가 원본 탐색 결과가 아니라 findings를 바탕으로 결정되게 하기"],"1938694832":["두 경로 모두 동기(synchronous) 방식으로 유지하고, 대신 프롬프트를 압축해서 절감 효과를 노리기(배치 처리(batch processing)는 완료 시간을 보장하지 않음)"],"1940599047":["개발자 각자의 ~/.claude/CLAUDE.md에 두고, 팀 공지로 갱신하기"],"1940971413":["올바른 도구 선택을 보여 주는 few-shot 예시를 시스템 프롬프트에 추가하기"],"1943136708":["merge 직전 마지막 commit만 리뷰해서 중간 push에서는 댓글이 아예 생기지 않게 하기."],"1943555546":["원인이 파악될 때까지 지난주 환불 금액 중앙값(median)을 넘는 process_refund를 막는 hook을 추가하기."],"1944043281":["구현을 멈추고 plan mode로 전환하기. 세 서비스의 전환 경로를 살펴보고 접근 방식을 설계하기. 이는 이제 유효한 선택지가 여러 개인 아키텍처 결정이 됐기 때문임."],"1944292509":["프로젝트 CLAUDE.md에 반대 규칙을 명시적으로 넣기. \"요청받지 않으면 JSDoc을 쓰지 말 것.\""],"1944971276":["완성된 샘플 보고서 두 개를 그 출처가 된 원본 행(row)들과 함께 제공하기"],"1945137090":["이 플랫폼은 invoice, contract, shipping manifest, lab report, 이렇게 문서 종류 4가지를 다루는데, 각각 자기만의 schema와 특이한 점이 있음.","coordinator가 들어오는 문서를 각각 분류해서 그 종류에 맞는 extractor(추출기)에 위임함.","문제는 두 가지임. extractor가 가끔 어떤 schema를 써야 하냐고 되묻는 경우가 있고, 잘못 분류된 lab report가 invoice로 추출돼서 아무도 눈치채지 못한 채 그대로 로드된 경우도 있음.","맞는 변경 사항 두 가지는 무엇인가? (두 개 선택.)"],"1945296561":["두 필드 다 신뢰할 수 없으니까 둘 다 nullable로."],"1947485809":["엔지니어링 선택으로는 필터 쪽이 나음. 모델한테 기억해 달라고 부탁하는 것보다 결정적으로 걸러내는 편이 낫기 때문임."],"1947935137":["각 서브에이전트의 프롬프트에, 섹션을 쓸 때 \"found nothing\"과 \"could not run\"을 확실히 구분하도록 지시하기"],"1948739776":["rewrite마다 그 map을 붙여넣은 새 session을 시작하고, 목요일에는 merge 얘기는 꺼내지 않고 resume만 하기. session이 이미 codebase를 알고 있기 때문임."],"1949582229":["매일 밤 어떤 항목을 확인할 만한지 그때그때 정하는 동적 분해임."],"1950011950":["감사자(auditor)가 적재된 레코드 20개를 골라서, 각 수치가 소스 문서의 어디서 나왔는지 팀에 보여달라고 요청함.","지금 웨어하우스(warehouse)에는 추출된 값만 저장돼 있음.","이 요청에 가장 도움이 안 되는 변경은 무엇인가?"],"1950241667":["리포트를 명시적인 섹션으로 나누기. (a)는 충분히 확립된 결과로, (b)는 값 두 개와 각각의 출처를 함께 적어 논쟁 중인 결과로, (c)는 출처를 구할 수 없어 생긴 커버리지 공백으로 표시하기."],"1953387304":["3주 전에 팀에서 프로젝트 CLAUDE.md의 \"모든 함수에 항상 JSDoc를 작성\" 규칙을 지웠음. 그런데 이 컴퓨터에서는 Claude가 여전히 JSDoc를 여기저기 붙이고, 동료들 세션에서는 멈췄음.","최신 코드도 받아왔고, 레포에서 그 규칙이 사라진 것도 확인했음.","올바른 진단 단계와 거기서 나올 법한 원인은 무엇인가?"],"1955367006":["skill에 tenant 디렉터리와 일치하는 path filter를 주기. 그러면 거기 있는 파일이 열려 있을 때만 로드됨."],"1958430874":["불만 세 번째.","야간 리뷰 작업(nightly review job)이 승인 프롬프트에서 밤새 멈춰버렸는데 답할 사람이 없었고, 대시보드는 텍스트를 스크래핑하다 매주 깨지고, 컴플라이언스 규정상 이 단계는 저장소에 절대 쓰기를 하면 안 됨.","이 세 가지를 모두 해결하는 실행 형태는 무엇인가?"],"1962554808":["인스턴스 하나만 짚어내고 두 개는 놓친 결과도 여전히 진짜일 수 있음. 그러니까 일치 여부는 정확성 검증이 아니라 신뢰도에 대한 근거일 뿐임."],"1964411636":["데이터베이스 스키마를 MCP resource로 노출하기. 탐색용 도구 호출 없이도 에이전트가 볼 수 있는 콘텐츠 카탈로그가 되기 때문임."],"1965519848":["생성을 세 번 돌리고, eviction 로직이 맞는지 다수결로 정하기."],"1966285475":["주간 재고 예측(inventory-forecast) 시스템은 코디네이터(coordinator) 하나와 서브에이전트(subagent) 세 개(demand_history, supplier_lead_times, promotions_calendar)를 돌림.","각자 자기 섹션을 작성하고 코디네이터가 보고서로 취합함.<br><br>지난주에는 promotions 서브에이전트의 데이터 소스에 연결할 수 없었음.","그 서브에이전트는 \"이번 기간엔 프로모션 데이터 없음\"이라는 문구만 담긴 빈 섹션을 반환했음. 그런데도 코디네이터는 보고서를 그대로 취합했고, merchandising 팀은 2주짜리 프로모션이 조용히 빠진 예측치를 근거로 발주했음.","6주치 실행 기록을 검토해 보니, 서브에이전트의 소스에 연결할 수 없었는데도 보고서가 완료 상태로 나간 밤이 네 번 더 있었음.<br><br>보고서는 매주 반드시 나와야 함. merchandising 팀은 예측치가 없는 것을 통제 실패로 간주함.","재발을 막는 데 가장 효과가 없는(LEAST effective) 변경은 무엇인가?"],"1968339456":["배치 결과는 순서가 뒤죽박죽으로 돌아오므로 루프의 단계들이 뒤섞여버림."],"1968731661":["corpus(말뭉치)의 대부분을 차지하는 single-address(주소가 하나인) invoice에서 뽑은, 제대로 채워진 invoice 예시를 prompt에 추가하기."],"1971383943":["생성 과정의 추론을 전혀 본 적 없는 새 독립 인스턴스로 리뷰하기"],"1971876203":["일시적 실패는 국소적으로 복구해 보기(예: 횟수를 제한한 재시도). 그리고 스스로 해결하지 못한 에러만 코디네이터로 올리기. 이때 뭘 시도했는지와 부분 결과도 같이 담아서 보내기."],"1972686985":["그 세션은 코드를 만들 때의 추론을 그대로 갖고 있어서 자기 결정을 진짜로 의심하지 않음. 리뷰는 별도 파이프라인 단계로 돌리고, 패치와 리뷰 기준만 받는 독립된 Claude 인스턴스한테 맡기기."],"1973425370":["Alex: \"tool_use\"면 결과를 전부 추가하면서 계속 진행하되, 비용을 묶어 두려고 12회 반복을 주된 정지 조건으로 삼기"],"1975815247":["\"필드를 optional로 선언하는 것과 nullable로 선언하는 것은 같은 개념을 다르게 표현한 것뿐이므로, 읽기 편한 쪽을 골라서 스키마 전체에 일관되게 적용하기\""],"1976040545":["네 CI 리뷰 봇이 붙이는 심각도 라벨이 머지를 통제함. critical이면 막히고 minor면 막히지 않음.","개발자들이 똑같은 하드코딩 자격증명 지적에 월요일엔 critical, 목요일엔 minor가 붙은 걸 발견했고, 이제 막힌 머지마다 전부 이의를 제기함.","프롬프트는 각 심각도를 추상적인 한 문장씩으로만 정의해 놓았음.","어떻게 고쳐야 하는가?"],"1976692613":["모노레포의 GraphQL resolver들은 packages/api/src/resolvers/, packages/admin/src/resolvers/, 그리고 여러 기능 폴더에 흩어져 있고, 전부 .resolver.ts로 끝남.","resolver 컨벤션은 그런 파일을 편집할 때만 자동으로 로드되어야 하고, 그 외에는 절대 로드되면 안 됨.","올바른 방식은 무엇인가?"],"1980236085":["실패한 추출은 두 그룹으로 나뉨. A는 의미 오류로 검증에 실패했음(\"항목 합계가 명시된 총액과 안 맞음\"). B는 참조된 계약 부속서가 제공된 문서 안에 없어서 실패했음.","재시도 전략을 어떻게 설계해야 하는가?"],"1980875030":["세 조사를 순차적으로 하지 말고 한 turn에 같이 실행되도록 한꺼번에 내보내기"],"1981843219":["거래 관련 사실을 지속되는 case-facts 블록으로 빼내서, 요약 대상에서는 제외하고 매 턴 포함되게 하기"],"1981996575":["가장 최근 N개 턴만 그대로 남기고 그보다 오래된 것은 전부 버리기. 유지하는 데 추가 비용이 들지 않음."],"1983104286":["(1) .claude/에 두는 프로젝트 범위 명령/스킬로, 버전 관리로 공유하기. (2) ~/.claude/commands/에 두는 사용자 범위 명령. (3) 프로젝트 CLAUDE.md. 모두에게 적용되는 표준은 호출될 때까지 기다리지 않고 매 세션마다 로드돼야 하기 때문임."],"1984849953":["대규모 리팩터링 세션 3시간째임. Claude가 1시간째에 분석했던 구체적인 UserRepository나 OrderService 클래스 대신 \"표준 repository 패턴\" 얘기를 점점 더 많이 꺼내고, 방금은 앞서 스스로 짚었던 제약과 충돌하는 변경을 제안했음.","어떤 조합으로 대응해야 하는가?"],"1985362151":["기준(standards)을 리뷰 프롬프트 자체에 붙여넣고, 어시스턴트에게 JSON으로만 답하게 지시하고, 이 단계에 비용 상한(dollar cap)을 걸어서 비싼 실행이 반복되지 않게 하기."],"1987569171":["12%는 재시도 루프에서 정상 범위임. 상한을 6회로 올리면 확률이 누적돼서 받아들일 만한 성공률이 나옴."],"1988858787":["형식 지침을 자세히 줬는데도 네 PR 리뷰어가 지적 사항 형식을 제멋대로 내놓음. 어떨 땐 산문 문단, 어떨 땐 불릿 목록이고 필드 이름도 실행할 때마다 달라짐.","후속 도구가 필요로 하는 것은 위치, 문제, 심각도, 제안 수정임.","스키마 강제 말고, 출력 일관성을 위해 가이드가 추천하는 프롬프트 기법은 무엇인가?"],"1991982579":["--print를 --verbose와 함께 쓰는 것."],"1992831903":["최종 리서치 보고서를 출처까지 되짚어 검증할 수 있게 지켜 주는 실천 두 가지는 무엇인가? (두 개 선택.)"],"1992874226":["세션을 fork해서 원본 분석은 그대로 유지하고, 브랜치(branch)에서 의존성 작업을 이어가기"],"1993717765":["사용자 범위인 ~/.claude.json 안에."],"1994693233":["Glob으로 \"*currency*\" 이름의 파일을 찾아서 읽기"],"1994876806":["두 증상 모두 프롬프트가 약해서 생긴 것이므로, \"응답하기 전에 항상 모든 작업을 끝내라\"는 지시를 넣기."],"1995977217":["가장 읽기 쉬운 만능 형식인 산문 문단으로 전부 바꾸기."],"1998195541":["실패마다 구조화된 메타데이터를 반환하기. errorCategory(\"transient\"/\"validation\"/\"business\"), isRetryable(타임아웃일 때만 true), 그리고 사람이 읽을 수 있는 설명을 담고, 정책 관련 건에는 고객에게 그대로 보여줄 수 있는 설명도 같이 넣기."],"2000325981":["Message Batches API에 적합한 작업은 무엇인가?"],"2001127746":["먼저 Glob과 Grep으로 범위를 좁히고 매치된 영역만 Read하고, 대량 훑기는 파일·라인 참조가 담긴 요약을 반환하는 서브에이전트(subagent)에게 맡기고, 에이전트가 확인된 호출 지점을 전부 나중에 다시 읽을 수 있는 scratchpad 파일에 append하게 하기"],"2002552019":["네 coordinator는 각 subagent의 전체 트랜스크립트를 중간 추론이랑 도구 호출 잡음까지 통째로 이어 붙여서, 하나의 마크다운 묶음으로 synthesis 에이전트에 넘기고 있음.","그러다 보니 최종 보고서가 출판 날짜를 뒤섞고, 인용문을 엉뚱한 논문에 갖다 붙임.","출처 귀속을 바로잡으려면 어떤 변경이 제일 나은가?"],"2002892625":["거래 사실(금액, 날짜, 주문 ID, 상태)을 뽑아서 계속 유지되는 case-facts 블록에 담고, 요약된 컨텍스트마다 항상 같이 딸려 가게 하기. 요약은 계속 문장을 줄여 나가지만, 사실 블록은 정확한 값을 그대로 보존함."],"2003303482":["retry 경로 고유의 식별자(그 안에서 쓰는 함수와 상수)를 트리 전체 파일 내용에서 검색하기. 파일 이름이 무엇이든 상관없이 걸리는 파일이 나오므로, 그것만 열기"],"2003991146":["에러 맥락과 함께 부분 결과도 같이 담기"],"2006995531":["독립적인 리뷰 인스턴스(review instance) 세 개가 모든 pull request마다 돌아가고, 파이프라인은 그 결과들의 합집합을 게시함.","개발자들은 같은 이슈를 표현만 다르게 해서 최대 세 번까지 보게 됐고, 이제는 대충 훑어보기 시작했음.","한 팀원은 합집합 대신 다수결(majority vote) 방식을 쓰자고 제안함. 세 개 중 최소 두 개가 보고한 결과만 남기자는 것임.","그 제안에 대한 설명 중 맞지 않는 것은 무엇인가?"],"2010063938":["파일 45개짜리 라이브러리 마이그레이션에서, 팀은 (1) 코드베이스를 조사하고 접근법을 설계한 다음 (2) 변경을 실행하려고 함.","Claude Code의 모드를 여기에 어떻게 대응시켜야 하는가?"],"2010360002":["subagent가 구조화된 출력에 발행일이나 데이터 수집일을 반드시 넣게 하기. 그래야 시점 차이를 모순이 아니라 시간에 따른 변화로 해석할 수 있음."],"2011614357":["계획 단계는 건너뛰고 바로 3단계 코드를 읽기 시작하기. 어차피 첫 번째 발견 이후에는 어떤 계획도 쓸모없어지기 때문임."],"2012125880":["리포트를 제출하기 전에 영수증을 항상 검증하라고 지시하는 문장을 시스템 프롬프트(system prompt)에 추가하기."],"2015445368":["새로 온 개발자가 팀 컨벤션을 내려받아 활성화하려면 초기화 명령을 직접 실행해야 함."],"2016736044":["리뷰 봇의 오탐(false positive) 비율이 40%임.","팀의 제약 조건은 다음과 같음. 사람이 보기 전에 발견 항목(findings)을 숨기면 안 됨.","측정해 보니 병목은 개발자가 발견 항목 하나하나를 조사하는 데 쓰는 시간임.","어떤 개선 수단이 맞는가?"],"2017619329":["팀이 저장소(repository)에 커밋해 둔 컨벤션(convention)은 여전히 리뷰어에게 전달됨. runner 이미지가 아니라 코드와 함께 이동하기 때문임."],"2018190335":["공유 서버를 저장소에 커밋되는 project-scoped 설정 파일로 옮기고 credential은 환경 변수 참조로 적어서 각 머신이 자기 값을 넣도록 하기."],"2020046147":["리더십은 CI reviewer가 댓글만 다는 것을 멈추고 직접 고치기를 원함: pull request마다 수정(remediation)을 직접 만들어내야 함.","이 작업은 의존성 버전 업(dependency bumps), 지난주 디자인 채널에서 후보 접근법 세 가지를 두고 논쟁했던 설정 마이그레이션(config migration), 가끔 있는 스키마 수정까지 포괄함.","파이프라인은 새벽 3시에 아무도 지켜보지 않는 상태로 돌아감.","한 아키텍트는 \"뭔가 수정되기 전에 접근법이 먼저 승인되도록\" 이 단계를 plan mode로 돌리자고 제안함. 평가할 것."],"2021162677":["프로젝트 context, hooks, plugins 탐색(discovery)을 건너뛰는 옵션을 추가해서 모든 runner가 동일하게 시작하게 하기. push에 대한 deny 규칙을 추가하고, 출력은 프로즈(prose) 그대로 두되 리뷰 프롬프트 문구는 고정해서 대시보드 패턴이 더 이상 흔들리지 않게 하기"],"2021548702":["원본 문서 자체 안에 있는 모순."],"2022007374":["올바른 migration 쌍의 예시를 project memory 파일에 추가해서, 모델이 만들어내야 할 형태를 직접 보게 하기"],"2022036801":["effective_date 필드가 계약서의 약 12%에서 틀리게 나옴.","틀린 사례들을 살펴보면, 어떤 문서는 서명일(signature date)과 별도의 발효 개시일(commencement date)을 함께 표기하고, 어떤 문서는 두 서명일 중 더 늦은 날짜에 계약이 발효된다고 말하고, 어떤 문서는 날짜를 바꾸는 amendment를 포함하고 있음.","팀은 3주 동안 서술형 지시문(prose instruction)을 네 번 다시 썼지만 오류율은 그대로임.","가장 빨리 수렴하는 방법은 무엇인가?"],"2022451570":["고정 목록에 없는 제품을 위해 \"other\" 값과 짝이 되는 상세 문자열 필드를 추가하고, 정말로 모호한 케이스를 위해 \"unclear\" 값도 넣기."],"2023215510":["요청에는 \"우리 주요 경쟁사\"라고만 적혀 있는데, 클라이언트 자체 자료에는 서로 다른 경쟁사 집합이 두 개나 나와 있음."],"2024112862":["코드 리뷰어가 프로젝트 고유의 정당한 패턴(예를 들면 로깅 데코레이터를 붙인 의도적인 빈 catch 블록)을 버그로 찾아냄.","진짜 빈 catch 버그는 놓치지 않으면서 오탐만 줄여야 함.","few-shot을 어떻게 설계하는 것이 가장 좋은가?"],"2025942458":["scaffolding이 실행될 때마다 Terraform stub을 추가하라고 에이전트한테 알려주는 줄을, 그녀의 개인 always-loaded memory 파일에 추가하기"],"2026518797":["막힌 merge를 판단이 필요한지 아닌지로 나누기. 기계적인 것들은 구체적인 수정안을 같이 붙여서 작성자 혼자 처리하게 하고, 이견이 있는 것만 중재자(arbitrator)한테 보내기"],"2028030837":["전부 그대로 두되 정규식 패턴을 더 촘촘하게 다듬어서 지적 문구의 다양한 표현 변형까지 커버하기"],"2031895554":["사안마다 필수 필드를 하나씩 둔 엄격한 출력 스키마 쓰기. 답이 빠지면 검증에서 걸리기 때문임."],"2032374526":["stop_reason이 \"refusal\"이면 모델이 진행을 거부한 거니까 거기서 멈추기."],"2032490159":["허용된 라벨을 enum으로 선언하는 스키마(schema)를 가진 도구(tool)를 정의하고, tool_choice로 강제하기"],"2035089706":["턴마다 중요도를 판단해서 선택적으로 보존하기. 중요한 것만 정확히 남기고 나머지는 남기지 않음."],"2035983173":["false positive를 줄이려고 팀은 리뷰 프롬프트에 예시 12개를 추가했는데, 전부 authentication 모듈에서 가져온 것임. 그곳에서 false positive가 가장 심했기 때문임.","그 이후로 auth의 false positive는 절반으로 줄었지만, payments와 reporting 모듈의 findings는 거의 0에 가깝게 떨어졌고, 리뷰어는 관련 없는 코드까지 authentication 용어로 설명하기 시작했음.","어떤 두 가지 변경이 이 문제를 해결하는가? (Select TWO.)"],"2038066038":["형식이 ISO 8601과 다른 문서는 접수 단계에서 반려하기."],"2038916270":["표준 12개를 각각 별도 파일로 두고, 각 패키지의 CLAUDE.md에서 @import로 관련 있는 것만 가져오기. 무엇을 넣을지는 그 패키지 메인테이너가 고름."],"2041075477":["description 텍스트: 모델은 description을 보고 판단하니까, 각 설명에는 그 도구가 무엇을 반환하는지, 그리고 다른 도구 대신 언제 이 도구를 써야 하는지가 명시돼 있어야 함."],"2043066707":["완성된 보고서를 캐시해 두고, 충분히 비슷한 질의가 나중에 오면 그것을 내주기. 답이 어느 정도 최신으로 유지되도록 캐시는 주 1회 주기로 갱신하기."],"2044733172":["대화가 열 턴을 넘겼음."],"2045997798":["프로젝트의 CLAUDE.md임. 주제별 세부 사항은 .claude/rules/로 나눠 두면 됨. 대화형 실행이든 비대화형 실행이든 똑같이 로드되고, 그게 관장하는 코드와 같이 버전 관리됨."],"2047813741":["셋 다 auto로 두고, 각 단계의 요구사항은 프롬프트 지시로 명시하기."],"2048116610":["(a)는 find 명령을 쓰는 Bash, (b)는 grep 명령을 쓰는 Bash임. 여기서는 내장 도구가 필요 없음."],"2048824664":["다음 중 에이전트 루프를 종료하는 방법으로 올바르지 않은 것은 무엇인가?"],"2049117029":["완성된 landscape의 짧은 예시 하나를 첨부하기. 섹션 구성, 각 섹션이 대략 얼마나 걸리는지, 채워 넣은 항목 하나까지 보여주기."],"2049203503":["그것을 skill로 패키징하는 것은 틀렸음. skill의 본문은 호출될 때만 로드되므로, CI 실행의 시작 컨텍스트가 개발자 쪽과 달라지기 때문임."],"2050074544":["스킬마다 allowed-tools를 그 일에 맞게 좁히기. 생성용에는 파일 도구만, 적용용에는 DB 실행만 주는 식으로."],"2051839252":["둘 다 스스로 해결하기. 에이전트는 첫 응대에서 끝내는 비율을 최대한 높여야 하기 때문임."],"2053471227":["나열된 경로 전부를 실제로 존재하는 파일과 대조하고, 서로 다르면 원래 지시사항, 실패한 manifest, 그리고 정확히 어디가 어긋났는지를 명시해서 manifest를 다시 요청하기"],"2053696680":["temperature(온도)를 낮춰서 에이전트가 두 호출의 순서를 더 일관되게 정하도록 하기."],"2056726019":["시스템 프롬프트의 환불 섹션을, 올바르게 거절된 환불의 퓨샷(few-shot) 예시들로 다시 쓰기."],"2057047010":["Sara: 응답에 마지막 텍스트 블록이 있으면 종료하기. Claude는 작업을 텍스트로 끝내기 때문임. 그리고 성공한 도구 결과(tool result)는 매 사이클 대화에 추가하기."],"2057315498":["subagent가 발견한 내용을 구조화해서 돌려주게 하기. 주장, 근거 발췌, 출처 URL, 문서 이름, 발행일까지 담고, 원본 대화 기록 대신 그 구조를 종합 단계로 넘기기."],"2058118992":["네 개의 레이블을 나열하고 모델에게 그중 하나를 고르라고 하는 프롬프트 한 줄임."],"2058331644":["코드베이스 전체에서 applyDiscount 함수를 호출하는 곳을 모두 찾으려면 에이전트는 어떤 내장 도구를 써야 하는가?"],"2058644141":["예시를 특정 module의 identifier, 파일 이름, domain noun(도메인 용어) 중심이 아니라 finding category(발견 사항 범주) 중심으로 다시 쓰기. 그래야 일반화되는 게 규칙이지, 특정 상황이 아니게 됨."],"2059524562":["위임하기 전에 조사 범위를 서로 겹치지 않는 하위 주제로 나눠 두기."],"2060057439":["synthesis 에이전트가 가장 중요하다고 판단한 finding을 계속 보내되 순위를 더 신중하게 매기라고 요청하기."],"2060715744":["요약을 끄고 전체 대화 기록을 그대로 유지하기."],"2063208431":["장황한 검색은 subagent한테 위임하고, 그 subagent가 결론만 돌려주게 하는 것임."],"2063833517":["맞음. 간단한 요청을 먼저 해결하고 그다음에 사람 연결을 제안하는 것이 가장 빠른 결과를 주기 때문임."],"2063907211":["(a) 직접 실행하기. (b) plan mode로 조사한 뒤 직접 실행으로 구현하기. (c) 방식을 확정하기 전에 plan mode로 두 접근을 비교하기."],"2064544004":["두 필드 다 nullable로 만들기. 불확실한 건 뭐든 null이 만능 안전값이기 때문임."],"2064751468":["(a) 결제는 중요하니까 plan mode로 가기. (b) 시간을 아끼려면 바로 실행(direct execution)으로 가기. (c) 제일 먼저 떠오르는 방법을 그대로 들고 바로 실행하기."],"2065114606":["이 요구사항은 skill에 넣는 것이 맞음. 그래야 요약 형식(summary format)이 세션 내내 context에 계속 남아있는 대신 리뷰어(reviewer)가 필요한 순간에만 로드됨."],"2067188554":["lookup_order에서 \"including delivery status\"라는 문구를 지우고, track_shipment의 설명은 그대로 두기"],"2067292482":["고정된 파이프라인. 엔티티를 알파벳순으로 나열하고 그 순서대로 각각 CRUD를 생성하기."],"2069675715":["계약 검토(contract-review) 파이프라인(pipeline)은 문서마다 정확히 네 가지 위험 라벨 중 하나만 반환해야 하고, 후속(downstream) 코드는 그 정확한 문자열(string)로 분기함.","팀은 최신 모델(current models)을 쓰고 있고 어떤 API 기능이든 사용할 수 있음.","라벨이 항상 네 가지 중 하나임을 가장 직접적으로 보장하는 방법은 무엇인가?"],"2070422803":["arbitrator(중재자)들이 막힌 merge 중 무작위 표본만 처리하게 하고, 나머지는 자동 승인하기. 그러면 팀이 정한 비율만큼 대기열이 줄어듦."],"2070499895":["사용자 레벨, 즉 ~/.claude/CLAUDE.md임."],"2071335097":["brief에 이 고객 업계에서 \"executive-ready(경영진 보고용 수준)\"가 무엇을 의미하는지 정의하는 단락을 추가하기"],"2072221709":["조사 파이프라인 전체를 분해 단계부터 다시 시작하기."],"2072989332":["코디네이터(coordinator)의 분류 신뢰도 임계값(confidence threshold)을 높여서, 불확실한 문서는 아예 위임되지 않게 하기"],"2073495451":["세션마다 에이전트는 실제 질문에 답하기 전에 처음 몇 턴을 list_schemas, list_tables, describe_table 호출에 씀. 같은 데이터베이스 구조를 매번 다시 파악하는 셈임.","그 구조는 한 달에 한 번 바뀔까 말까 함.","어떤 MCP 기능이 이를 효율적으로 해결해 주는가?"],"2073539715":["네 라우팅 에이전트 프롬프트에는 few-shot 예시가 6개 있는데, 전부 \"고객: '주문 #123 환불해줘, 깨진 채로 왔음.' → Action: process_refund. ✓\" 같은 형태임. 그런데 운영 티켓을 보면 \"생각했던 거랑은 좀 다르네요...\" 같은 메시지에서는 여전히 헤맴. 동료는 같은 스타일 예시를 12개로 두 배 늘리자고 제안함.","올바른 판단은 무엇인가?"],"2075157720":["아무것도 재시도하지 않기. 세 그룹 모두 이 문서 유형에 모델이 맞지 않는다는 신호이기 때문임."],"2075483021":["머지 전 검사는 사람을 기다리게 만드는 blocking 작업임. Batches API는 지연 시간 SLA가 없어서 최대 24시간까지 걸릴 수 있고, \"보통 한 시간\"은 그냥 관찰일 뿐 보장이 아님.","blocking 워크로드는 할인이 얼마든 상관없이 동기 API에 그대로 남겨둬야 함."],"2077627134":["\"주문을 찾을 수 없음\" 메시지마다 시스템이 다운됐을 수도 있다는 안내 문구를 붙이기."],"2078339824":["plan mode가 맞는 선택임. plan mode가 기다리는 승인은 다음 날 아침 팀이 하는 pull request 리뷰로 채워지므로, 사람이 거치는 게이트는 이미 마련돼 있는 것임."],"2078642342":["get_customer가 \"M. Park\"에 대해 레코드 두 건을 돌려줌. 하나는 이메일 도메인이 일치하고, 다른 하나는 전화 지역번호가 일치함.","에이전트는 240달러 환불을 처리해야 함.","두 후보 사이의 신뢰도 차이는 작음.","에이전트는 어떻게 해야 하는가?"],"2079594333":["에이전트마다 진행하면서 구조화된 상태(발견 매니페스트)를 정해진 위치로 내보내기. 재개할 때는 코디네이터가 그 매니페스트들을 읽어서 새 에이전트 프롬프트에 넣어 주기. 사라진 기억을 오래 남는 기록으로 대체하는 것임."],"2079614422":["발견 사항들을 심각도(severity)로 순위 매기고 각각에 근거 자료를 붙이기. 그러면 가치가 낮은 항목은 읽을 만한 항목 아래로 가라앉으면서도, 모든 발견 사항이 코멘트에 여전히 다 나타남."],"2082084905":["앞으로의 커밋에서 아무것도 새어 나가지 못하게 .mcp.json을 .gitignore에 추가하기"],"2082511510":["end_turn이 아닌 stop_reason이 나오면 언제든 루프가 동일한 요청을 그대로 재시도하게 하기."],"2083805769":["보조 완료 확인용으로 응답에서 \"all done\" 같은 문구를 훑어보기."],"2084061024":["먼저 전체 트리에서 그 리터럴(literal)로 파일 내용을 검색하기. 파일 종류에 상관없이 정확한 히트 목록(hit list)이 나옴. 그다음엔 히트가 난 위치만 열어서 주변 줄을 읽고, 히트가 모호한 곳에서만 근처 코드로 범위를 넓히기"],"2084626340":["저장소의 .claude/commands/review.md를 수정해서 더 엄격한 체크리스트를 넣고 추가 검사 항목은 선택 사항이라는 메모를 파일 안에 남기기."],"2084771721":["paths. 스킬을 특정 디렉터리로 한정하는 방식임."],"2085028081":["\"schema conformance는 값이 맞는지에 대해서는 아무것도 말해 주지 않음. 모든 type check를 통과한 line item이라도 합산하면 명시된 total과 안 맞을 수 있음.\""],"2086183558":["경로 범위(path-scoped) 규칙 파일은 아래 요구 사항 전부에 맞는 도구인데, 딱 하나만 예외임.","어느 요구 사항에서 실패하는가?"],"2086790296":["네 생산성 에이전트에는 search_code(의미 기반, 심볼 인식)와 find_text(정확한 문자열 일치)가 있음.","두 도구의 설명이 모두 \"코드베이스를 검색합니다\"임. 개발자들 말로는 에이전트가 \"authenticate와 비슷한 함수 찾기\"에는 find_text를, 정확한 에러 문자열에는 search_code를 쓴다고 함. 각 도구가 제일 약한 쪽으로 골라 쓰는 셈임.","가장 먼저 해야 할 수정은 무엇인가?"],"2087585609":["모든 섹션이 똑같이 주목받도록 입력 전체에 고르게 분산하기."],"2088450435":["프로젝트 루트의 CLAUDE.md에."],"2090370602":["tracker의 MCP server를 저장소에 커밋되는 settings 파일에 설정하기. 그래야 노트북들이 찾는 것과 같은 방식으로 runner도 그걸 찾을 수 있음."],"2091136230":["coordinator의 전체 대화 기록을 각 위임 건에 붙여서, extractor가 분류가 어떻게 나왔는지 볼 수 있게 하기"],"2091541195":["지금 방식대로 호출은 유지하고 셸 타임아웃(shell timeout)을 추가한 다음, 작업을 최대 3번까지 재시도해서 멈춘 실행은 죽이고 결국 하나는 성공하게 하기"],"2092925804":["대신 agentic-turn 상한을 추가하기. turn을 더 못 쓰는 실행은 돈도 더 못 쓰기 때문에, 두 제어는 효과 면에서 동등함."],"2093155855":["독립된 인스턴스는 생성 쪽의 추론 맥락이 없으니까, 원래 결정을 변호하려는 편향이 없음."],"2094156645":["모델이 결과를 반환하기 전에 자기 manifest를 다시 읽고 맞는지 스스로 확인하게 하기."],"2094481367":["이 실행은 interactive 모드로 시작돼서, 아무도 앉아 있지 않은 머신에서 사람이 입력하기를 마냥 기다리고 있었음. non-interactive print 플래그와 machine-readable(기계가 읽을 수 있는) 출력 형식으로 시작하면 그 단계가 끝나고 그 결과를 댓글로 바꿀 수 있음."],"2094670772":["지난 화요일에 결제 지연 시간이 두 배가 된 이유를 조사하는 상황이고, 발견되는 사실마다 다음에 뭘 볼지가 결정되는 경우."],"2095572836":["fan-out은 유지하되, 고객별로 subagent의 마지막 답변을 10분 동안 캐시해서 반복 티켓은 작업을 건너뛰게 하기"],"2096414627":["(a) 적대적인 말투니까 사람에게 넘기기. (b) 고객이 협조적이니까 자율적으로 처리하기"],"2097301626":["subagent들이 발견 사항을 주장(claim), 수치(figure), 출처(source), 발행일(publication date), 관련성(relevance)으로 구성된 구조화된 레코드로 반환하게 하고, 그 레코드는 요약하지 않고 그대로 이어가기. narrative compaction은 그 주변 대화용 뼈대(scaffolding)에만 적용하기"],"2100892948":["파일 안에서만 끝나는 이슈는 파일별로 집중해서 한 번씩 훑고, 파일 경계를 넘나드는 문제만 전담하는 별도의 pass를 따로 돌리기. 두 종류의 결함은 서로 다른 방식의 주의가 필요하기 때문임."],"2101251836":["크래시 뒤에는 세션 --resume에 맡기기. 대화 기록에 에이전트들이 알던 것이 전부 들어 있기 때문임."],"2101748254":["tool은 그대로 두고, 언제 이걸 쓰고 언제 대신 Grep을 써야 하는지 설명하는 routing 가이드를 project memory 파일에 추가하기."],"2101962809":["서로 어긋나는 통계는 전부 믿을 수 없다고 보고 리포트에서 빼기."],"2102007730":["container_number는 required로, 나머지 둘은 optional로 두기. 항상 존재하지는 않는 필드를 required로 선언하면 절대 안 되기 때문임."],"2102944757":["세션을 재개하고 교체에 대해서는 아무 말도 하지 않기. 에이전트는 필요할 때 파일을 다시 읽으므로 새 목록을 알아서 반영함. 그런 다음 그 세션에서 두 가지 프레이밍(framing)을 차례로 실행하기."],"2103028346":["두 단계 모두 바로 실행으로 가기. 팀이 합의한 뒤라면 계획 단계는 그냥 부담일 뿐임."],"2104657366":["전체 합산된 auto-merge 비율만 보지 말고, 회귀율(regression rate)을 디렉터리별·변경 유형별로 쪼개서 보기."],"2105267747":["요약 프롬프트에 \"숫자 값은 절대 잃어버리지 말 것\" 을 추가하기."],"2108092338":["subagent 보고가 끝날 때마다 코디네이터(coordinator)가 자기 서브태스크(subtask) 목록을 다시 검토하고, 그 보고서가 암시하는 서브태스크를 추가하게 하기"],"2108142896":["응답하기 전에 모델이 스스로 형식을 점검하게 하기."],"2108320013":["기준으로 삼은 텍스트가 파일 안 여러 군데에 나와서 Edit 이 계속 실패함.","어떤 도구 순서로 풀어야 하는가?"],"2109037257":["대화 40개가 runner의 시간 예산을 초과하니까, 그것을 10개씩 job 4개로 나눠서 각각 제한 시간 안에 끝나게 하기"],"2110522938":["(a)는 Glob, (b)는 저장소의 모든 .ts 파일을 Read로 열어서 내용을 손으로 훑기."],"2112340574":["파일 전체에서 패턴을 치환하는 Bash 한 줄(sed)로 바꾸기."],"2113203564":["renewal_term_months는 6, 12, 24, 36으로 이루어진 enum으로 제한하기. 그러면 모델은 계약서에 실제로 있는 기간만 낼 수 있음."],"2115331230":["전체 세션을 최근 25턴에 대한 슬라이딩 윈도우(sliding window)로 전환하기"],"2115721225":["22턴짜리 환불 케이스임. 초반 턴에서 847.50달러와 3월 15일 기한이 확정됐는데, 20번째 턴에서 에이전트는 \"앞서 논의한 환불\"이라고만 씀. 로그를 보면 주기적 요약이 그 수치들을 뭉뚱그린 문장으로 압축해버렸음.","컨텍스트가 무한정 늘어나지 않게 하면서 고칠 것."],"2116799583":["\"모든 엣지 케이스를 고려해서 신중하고 철저하게 리뷰하기\""],"2118131417":["다섯 개를 어려운 것부터 순서대로 하나씩 처리하기. 한 번에 한 문제만 다뤄야 검토와 테스트가 항상 더 깔끔하기 때문임."],"2118916073":["(i) 그 접미사(suffix)를 깊이에 상관없이 매칭하는 패턴을 가진 규칙 파일; (ii) 경계가 폴더 자체이므로 그 폴더 안에 있는 규칙 파일이나 메모리 파일(memory file) 중 하나; (iii) 아직 매칭을 촉발할 대상이 없으므로 이 중 어느 것도 아니고, 이것은 항상 존재하거나 명시적으로 호출되는 곳에 속해야 하는 문제; (iv) 컨벤션(convention) 문서는 쓰기(write)를 거부할 수 없으므로 커밋된 deny 규칙."],"2119229046":["모델이 보내기 전에 자기가 쓴 확인 문구를 다시 읽고 검증 완료로 표시하게 하기"],"2120209688":["배치 하나가 최대 24시간까지 걸릴 수 있어서 Batches API만으로는 12시간 SLA를 보장하지 못함. 이 서비스에는 동기 API를 쓰거나, 아니면 SLA를 다시 협상하기."],"2121704224":["자동화가 실패했으니 이 변경만큼은 사용자한테 직접 손으로 해 달라고 부탁하기"],"2122021092":["검색이 타임아웃된 뒤에 빈 결과 집합을 성공으로 표시해서 반환하기."],"2122394609":["stop_reason 값마다 명시적으로 분기하기. end_turn일 때만 끝난 것이고, max_tokens는 응답이 잘렸다는 뜻이라 이어 받거나 한도를 올려야 함. tool_use가 아닌 값을 전부 \"done\"으로 뭉뚱그린 것이 바로 버그임."],"2122764131":["ORM 마이그레이션은 Claude Code 세션을 매일 돌려서 2주가 걸릴 예정임.","매일 처음부터 다시 탐색하지 않고 이전 분석 위에 쌓아 올리고 싶은데, 동료들은 분석해 둔 파일 일부를 건드리는 작은 PR을 매일 머지함.","어떤 세션 전략이 맞는가?"],"2125079249":["--output xml 을 --schema 와 함께 쓰기."],"2126267585":["그 서비스는 분석하지 않았다는 커버리지 노트(coverage note)와 함께 리포트에서 빼서, 실행이 예정대로 끝나게 하기"],"2127493833":["문서 500개를 문서마다 똑같은 단계로 한 형식에서 다른 형식으로 변환하기"],"2128698404":["인프라 요구사항이 서로 다른 두 통합 방식 중에서 하나를 고르는 일."],"2129170162":["모든 프롬프트 맨 앞에 \"항상 테스트 규약을 따를 것\"을 붙이기"],"2132284627":["리뷰하기 전에 generator가 자기 reasoning을 더 자세히 설명하게 해서, 리뷰가 다룰 재료를 더 많이 갖게 하기."],"2133086090":["저장소(repository) 하나를 감사(audit)했더니 서로 무관한 불만 사항 세 건이 나왔음.","(1) 생성된 Go 코드가 일부 파일에서는 표준 라이브러리로 에러를 감싸고, 다른 파일에서는 팀이 2024년에 폐기(deprecate)한 헬퍼로 감쌈.","(2) 컨트리뷰터 가이드에 파괴적인(destructive) 데이터베이스 명령은 절대 실행하지 말라고 적혀 있는데도, 에이전트 세션이 3월에 스테이징 스키마를 삭제(drop)했음.","(3) 30페이지짜리 인시던트 플레이북(incident playbook)은 누군가 ops/runbooks/ 아래 파일을 편집할 때만 관련이 있는데도, 지난달 기록된 세션 260개 전부에 로드됐음.","각 불만 사항을 실제로 해결할 수 있는 메커니즘에 정확히 배정한 건 어느 쪽인가?"],"2133617102":["tax_id 필드가 채워진 추출 건은 신뢰도 점수(confidence score)와 상관없이 무조건 사람 검토(human review)로 보내고, 나머지 송장(invoice)은 전부 자동 경로에 남겨두는 프로그램 방식의 게이트(programmatic gate)를 쓰기."],"2135011613":["analyze_document를 목적별 도구로 쪼개고 입출력 계약을 명확히 정하기. extract_data_points, summarize_content, verify_claim_against_source로 나누고, 각각 언제 쓰는 도구인지 설명에 적기."],"2136038911":["assistant 턴을 여는 중괄호(opening brace)로 프리필(prefill)해서 서론(preamble)이 들어갈 자리 자체를 없애기. 이것이 가장 값싼 변경이고 스키마 작업도 필요 없음."],"2137561114":["지금 5개 서비스에 걸쳐 인증(auth) 미들웨어(middleware)를 교체하고 있음.","통합 방식 두 가지 다 나름 타당함. 공유 라이브러리(shared library) 방식과 사이드카(sidecar) 방식인데, 운영 비용(operational cost)이 서로 다름.","지금 호출 지점(call site)들을 매핑하는 데만 몇 시간이 걸리고 검색 결과도 수천 줄이 나오는데, 지난번 시도에서는 세션이 꽉 차서 나온 계획이 앞의 두 서비스만 다뤘음.","이 작업은 어떻게 진행해야 하는가?"],"2138018498":["get_customer가 검증된 고객 ID를 반환하기 전까지 lookup_order와 process_refund를 막아 두는 프로그래밍적 선행 조건임."],"2138820461":["Dana 쪽으로 가기. 일찍 결과물을 내면 탄력이 붙고, 코드베이스 구조는 작업하면서 자연스럽게 드러남."],"2139649357":["정말로 공통인 규칙만 root 파일에 남기고 각 패키지에는 그 패키지에 필요한 표준 문서만 끌어오는 memory file을 따로 줘서 mobile 세션은 공유 기반 위에 mobile 세트를 얹어 로드하게 하기."],"2139879656":["옮기지 않기. Batches API는 도구 정의가 들어간 요청을 받지 못하기 때문임."],"2140790829":["옆에 있는 도구와의 경계를 명시하는 것(\"가이드는 search_docs를 쓰고, 제품 데이터는 이 도구를 쓸 것\")."],"2141053831":["어제 결론을 구조화된 요약(structured summary)으로 정리해서 새 세션을 시작하기. 저장소의 모든 파일이 바뀌었으므로, 그 세션의 도구 결과(tool result)는 전부 낡은 상태이기 때문임."],"2142816916":["차단 임계값을 올려서 상한에 걸리는 환불을 줄이고, 막다른 상황이 덜 생기게 하기"],"2143123914":["prefill을 \"JSON만 출력하고 앞뒤에는 아무것도 붙이지 말 것\"이라는 강한 어조의 지시로 바꾸기. 그러면 모델 지원 문제가 완전히 사라짐."],"2145610762":["텍스트가 있는지로 판단하지 말고 stop_reason 값으로 종료를 결정하기. \"tool_use\"면 계속하고, \"end_turn\"이면 멈추기"],"2041895345":["장황한 출력은 context: fork로 격리하고, 파일을 수정하거나 삭제하는 도구는 disallowed-tools로 빼고, 넘겨야 할 대상 디렉터리는 argument-hint로 안내하기."],"1395317790":["disallowed-tools 하나만 쓰기. 도구를 빼면 출력도 격리되고 기본 인자까지 정할 수 있기 때문임."],"1510463932":["(1)은 버전 관리로 공유되는 .claude/skills/의 프로젝트 스킬. (2)는 ~/.claude/skills/의 개인 스킬. (3)은 프로젝트 CLAUDE.md. 모두에게 적용되는 표준은 호출될 때까지 기다리지 않고 매 세션마다 로드돼야 하기 때문임."],"160499298":["셋 다 프로젝트 CLAUDE.md에 넣기. 스킬을 여러 개 따로 두는 것보다 관리할 것이 적기 때문임."],"974997815":["Bash를 disallowed-tools로 빼서 셸 명령을 실행할 수 없게 하고, 엔드포인트 이름이 필요하다는 것을 argument-hint로 안내하기. 스캐폴드 출력이 작으므로 context: fork는 선택 사항임."],"1960651759":["프론트매터로 격리된 포크 컨텍스트에서 실행하고, 쓸 수 있는 도구에서 파일 쓰기 도구를 빼고, 필요한 인자를 안내 문구로 보여 주어 분석가가 주제가 필수임을 알 수 있게 한 프로젝트 스킬."],"447963559":["그 절차는 필요할 때마다 호출되므로, 프론트매터 없이 프롬프트 텍스트만 담은 프로젝트 스킬."],"837359848":["Agent 도구 호출이 대화 컨텍스트 플래그를 붙이지 못한 경우."],"710355690":["코디네이터가 요청마다 실제로 어떤 스페셜리스트가 필요한지 판단하게 하고, 독립적인 것들은 한 응답 안에서 Agent 호출로 동시에 실행시키고, 진짜로 의존 관계가 있는 단계만 다음 턴으로 남기기"],"1708163170":["코디네이터 응답 하나에 Agent 도구 호출을 세 개 담아서 subagent들이 병렬로 돌게 하기."],"493278777":["Agent 호출 5개를 한 응답에 전부 내보내기. 병렬성을 최대로 끌어올리면 전체 지연이 가장 짧아지기 때문임."],"2090715958":["검색 Agent 호출 세 개를 한 응답에 같이 내보내서 병렬로 돌리기. 그다음 턴에서 세 결과를 프롬프트에 주입해 비교 단계를 호출하고, 이어서 비교 결과를 넣어 요약 단계를 호출하기"],"869996692":["coordinator를 다시 설계해서 쿼리마다 요구사항을 분석하고 어떤 subagent를 호출할지 동적으로 고르게 하기. 그리고 독립적인 Agent 호출을 한 응답에 함께 내보내서 선택된 에이전트들이 병렬로 돌게 하기"],"1841994186":["리서치 한 번에 하위 작업이 다섯 개임. 독립적인 주제 검색 세 개, (4) 그 검색 결과 세 개가 전부 있어야 하는 비교, (5) 그 비교가 있어야 하는 총괄 요약임.","coordinator는 Agent 호출을 어떻게 짜야 하는가?"],"975230457":["코디네이터의 allowedTools에 \"Agent\"가 빠져 있음. Agent 도구가 없으면 프롬프트에서 위임을 아무리 잘 설명해도 subagent를 띄울 수단 자체가 없음."],"2108029726":["대화 턴마다 Task를 하나씩만 호출하고, 결과가 나온 다음에 그다음 것을 실행하기"],"1457465020":["저장소에는 팀 엔지니어 전원이 실행하는 공유 /review 스킬이 들어 있음.","내가 실행할 때는 /review 자체가 더 엄격한 보안 체크리스트와 다른 출력 형식을 쓰게 하고 싶고, 팀원이 /review를 실행할 때 받는 결과는 바뀌면 안 됨.","어떻게 하는가?"],"1350395242":["더 엄격한 버전을 담은 review라는 이름의 개인 스킬을 ~/.claude/skills/에 만들기. 개인 스킬과 프로젝트 스킬의 이름이 같으면 개인 스킬이 실행되고, 그 효과는 나에게만 적용됨."],"64871348":["저장소의 스킬은 그대로 두고, /review-strict 같은 다른 이름으로 개인 스킬 만들기."],"1181993476":["저장소의 .claude/skills/review/SKILL.md를 고쳐 더 엄격한 체크리스트를 넣고, 추가 검사는 선택 사항이라는 메모를 파일에 남기기."],"354324761":["더 엄격한 체크리스트를 프로젝트 CLAUDE.md에 넣어 /review가 실행될 때마다 적용되게 하기."],"1862352795":["팀 스킬은 그대로 두고 ~/.claude/skills/ 아래에 개인 스킬 만들기."],"1236717559":["저장소와 함께 버전 관리되도록 프로젝트의 .claude/skills/에 새 이름으로 변형 추가하기."],"3575375":["팀이 공유하는 /commit 스킬을 내가 실행할 때는 내 메시지 형식으로 쓰고 싶고, 다른 사람에게는 영향이 없어야 함.","내 버전은 어디에 두고, 이름이 같으면 어떻게 되는가?"],"1575493486":["개인 스킬 폴더(~/.claude/skills/)에 두기. 이름이 같은 개인 스킬은 프로젝트 스킬 대신 실행되고, 내 컴퓨터에서만 적용됨."],"1943373151":["같은 이름으로 개인 스킬 폴더에 두기. 다만 이름이 겹치면 항상 프로젝트 스킬이 우선하므로 적용되지 않음."],"1448383542":["저장소와 함께 백업되도록 프로젝트의 .claude/skills/에 새 이름으로 두기."],"1285023599":["규제를 받는 고객사가 사내 게이트웨이를 운영하며, 앞으로 두 분기 동안 현재 세대 Claude 모델로 고정돼 있음.","게이트웨이는 밖으로 나가는 모든 요청에서 tools 항목을 삭제하고 나머지 항목은 그대로 전달함.","분류기의 결함은 정확히 하나임. 응답의 약 7%가 JSON 앞에 \"Sure!","Here is the classification:\"라는 문장으로 시작해서 엄격한 파서가 실패함.","모델이나 게이트웨이 변경은 이번 분기 범위 밖임.","이들이 쓸 수 있는 가장 직접적인 해결책은 무엇인가?"],"998224227":["output_config.format에 JSON 스키마를 넣어 API가 응답 글 자체를 스키마에 맞추게 하기. 이 방식은 tools 항목이 필요 없고 서두가 들어갈 자리가 없음."],"1009363310":["assistant 턴에 여는 중괄호를 미리 적어 두어 응답이 그 지점에서 이어지게 하고 서두가 붙지 못하게 하기."],"329426768":["한 팀이 이번 주 안에 분류기를 출시해야 하며 강한 제약이 두 가지 있음. 프록시가 모든 요청에서 tools 항목을 삭제하고 나머지 항목은 그대로 전달하며, 이번 분기 동안 현재 세대 Claude 모델로 고정돼 있음.","실패 유형은 두 가지임. 라벨 앞에 붙는 서두 문장, 그리고 가끔 허용 목록 밖의 라벨이 나오는 것임.","이들이 실제로 쓸 수 있고 두 실패를 해결하는 조치 두 가지는 무엇인가? (두 개 선택)"],"285351588":["output_config.format에 JSON 스키마 넣기. tools 항목이 필요 없고 응답 글 자체가 스키마에 맞춰지며 서두가 들어갈 자리가 없음."],"1485511654":["assistant 턴에 예상 출력의 첫 부분을 미리 적어 두어 응답이 그 지점에서 이어지게 하기."],"1589542996":["배치 요청 하나 안에서는 내 애플리케이션이 실행하는 도구의 결과를 돌려보내 그 요청을 이어 가게 할 수 없음."]};
